        ["diag.inductive_missing_flyback"] = "Relay coils and motors need a flyback diode across the inductive terminals — a diode elsewhere on the canvas is not enough.",
        ["diag.dc_rc_needs_tran"] = "Capacitors need Transient analysis for charge and discharge — switch to Transient and set tStop long enough (e.g. 6 s for LED fade).",
        ["lab.title"] = "Circuit Lab",
        ["lab.fromLearn"] = "From Learn:",
        ["lab.backToLearnSteps"] = "← Back to steps",
        ["lab.intro"] = "Build a schematic, wire pins, and run DC, transient, or AC analysis.",
        ["lab.hint"] = "Drag parts from the palette onto the canvas (or click a part, then click to place). Wire pin-to-pin, then Run. When the circuit solves, green dashes on wires show current flowing. An LED is bright near 20 mA; above ~35 mA it burns out and becomes an open circuit (fire graphic) until you replace it — always use enough series resistance. Drag an empty area to box-select; drag any selected part to move the group. Ctrl/Cmd-click or Ctrl/Cmd-drag to add to the selection. Click a wire to select it, then Delete. Example circuits open in a new tab. Ctrl+D duplicate; Ctrl+C/V copy/paste. Wheel to zoom; Shift-drag to pan. Drag on the scope to scrub time.",
        ["lab.hint.challenge"] = "Build the circuit described in Learn from an empty canvas. Place parts, wire pin-to-pin, pick the right analysis mode, Run, then Check my work.",
        ["lab.hint.wire"] = "Wire mode: click a pin to start (blue preview follows the cursor), then click another pin — or click an existing wire to make a T-junction. In Select mode, drag a wire to reshape it; double-click a wire to reset auto-route. Click empty canvas to cancel.",
        ["lab.hint.probe"] = "Probe mode: click a part body to read branch current (mA), or a net/wire node for voltage (V). The value appears in the status banner. In Transient, scrub the scope — the probe and canvas follow that time.",
        ["lab.hint.led"] = "LED series: Run DC. Current flows battery → resistor → LED → ground. Try lowering the resistor until the LED burns out (~35 mA), then Replace LED and restore ~220 Ω.",
        ["lab.hint.ledFade"] = "LED fade: 1) Keep the switch Closed and Run — the capacitor charges and the LED lights. 2) Uncheck Closed. 3) Run again — the capacitor discharges through the resistor and the LED fades. After the switch opens, current only flows on the LED side (that is expected).",
        ["lab.hint.rc"] = "RC charge: Transient from 0 V. Scrub the scope to watch the capacitor voltage rise toward the supply through R. Compare τ ≈ R·C with the curve.",
        ["lab.hint.pot"] = "Potentiometer divider: Run DC, then change Wiper (0–1) in the inspector — the mid-point voltage tracks the wiper. Probe the wiper net to read it.",
        ["lab.hint.pulse"] = "Pulse into RC: Transient — the pulse source steps high then low. Scrub through the edges to see charge and discharge on the capacitor.",
        ["lab.hint.opamp"] = "Op-amp inverting amp (teaching model with ±15 V rails by default). Run DC — gain ≈ −Rf/Rin. Probe the output; try changing Rf, Rin, or rail limits in the inspector.",
        ["lab.hint.ac"] = "AC RC low-pass: set analysis to AC and pick a frequency. Below the cutoff the load sees more of the source; far above it, the capacitor shunts AC to ground. Nonlinear parts are open in AC.",
        ["lab.hint.bjt"] = "BC547 LED switch: Run DC with S1 Closed — base current turns Q1 on and the LED lights. Open S1 (uncheck Closed) and Run again — the LED goes out. Probe AM1 for collector current; try changing RB.",
        ["lab.hint.relay"] = "Relay + diode: Run DC with S1 Closed — coil energizes K1 and the LED lights through the contacts. Dfly is the flyback diode across the coil (cathode to coil+). Open S1 — contacts open and the LED goes out.",
        ["lab.hint.nmos"] = "NMOS LED switch: Run DC with S1 Closed — gate high, LED on. Open S1 (RPD pulls the gate down) and Run again — LED off. Drain overcurrent or |Vgs| ≳ 20 V burns M1 open.",
        ["lab.hint.ne555"] = "NE555 astable: Transient auto-runs — three LEDs blink from OUT right away. Watch playback or scrub OUT / CT on the scope. Too little R1–R3 or Vcc above ~18 V burns the timer open.",
        ["lab.hint.ne555Pot"] = "NE555 + pot blink: Transient auto-runs — one LED blinks from OUT. Change POT1 Wiper to change Rb and the blink rate (higher → slower).",
        ["lab.hint.christmasTree"] = "NE555 Christmas tree: Transient auto-runs — ten LEDs blink in a pyramid from OUT. Watch playback or probe any LED. Too little R1–R10 or high Vcc burns the timer open.",
        ["lab.hint.pushbutton"] = "Pushbutton LED: hold BTN1 on the canvas or the Hold to press control in the inspector — LED lights while pressed.",
        ["lab.hint.ldr"] = "LDR night-light: Run DC — with Light low the LED is on. Raise Light on LDR1 toward 1 and Run again — gate falls and the LED goes dark.",
        ["lab.hint.buzzer"] = "Buzzer + button: hold BTN1 on the canvas or in the inspector — BZ1 draws current (teaching “sound”). Release — silent.",
        ["lab.hint.motor"] = "NMOS + motor: Run DC with S1 closed — motor current flows; Dfly is the flyback diode. Open S1 — motor stops.",
        ["lab.hint.arduino"] = "Arduino LED: D2 is a teaching digital pin (Output / HIGH). Run DC — LED lights. Set Level to LOW or Mode to Input and Run again.",
        ["lab.hint.i2cOled"] = "I2C OLED: Run DC — with VCC powered, OLED1 shows “Hello” and SDA/SCL sit near 5 V via the pull-ups. Probe a bus line; remove a pull-up to see idle level collapse.",
        ["lab.hint.halfWave"] = "Half-wave rectifier: Run Transient — cycles loop on the canvas. Current flows only on positive half-cycles; the reverse half stays idle (diode blocks). Probe R1.",
        ["lab.hint.bridge"] = "Bridge rectifier: Run Transient — cycles loop. Both AC half-cycles feed the load as pulsating DC (four diodes).",
        ["lab.hint.filterCap"] = "Filter capacitor: Run Transient — cycles loop; C1 smooths the rectified peaks. Try smaller C or heavier R to see more ripple.",
        ["lab.hint.zener"] = "Zener regulator: Run DC and probe JM — voltage should sit near Vz (~5.1 V) despite a 12 V supply.",
        ["lab.hint.vreg7805"] = "7805 regulator: Run DC — OUT should be ~5 V with 12 V in. Lower Vin toward dropout to see regulation fail.",
        ["lab.hint.reversePolarity"] = "Reverse-polarity diode: Run DC — LED on. Flip the battery polarity (swap thinking) — series diode blocks reverse connection.",
        ["lab.hint.fuseProtect"] = "Fuse protection: Run DC with S1 open — safe current through RL. Close S1 and Run — F1 opens (short across RL). Replace F1 (S1 opens automatically) and Run again.",
        ["lab.hint.ripple"] = "Ripple: Run Transient and probe JT — residual AC on the filtered DC is the ripple. Smaller C / heavier load → more ripple.",
        ["lab.hint.buck"] = "Buck converter: Run Transient — PWM loops on the canvas. On: current through M1→L1; off: freewheel in Dfly. Gate wires stay idle. Probe JO; change pulse width (duty) to change the average.",
        ["lab.hint.boost"] = "Boost converter: Run Transient — PWM loops on the canvas. On: L1 charges via M1; off: diode feeds the load. Gate / VP1 wires stay idle (like buck). Probe JO; longer on-time stores more energy in L1.",
