        ["lab.modelNote.fuse"] = "Teaching fuse: low series Ron until |I| exceeds iMax, then opens until you replace it.",
        ["lab.modelNote.vreg7805"] = "Teaching 7805: OUT holds ~vOut vs GND when Vin ≥ vOut + dropout; otherwise it behaves like series Ron.",
