        ["lab.hint.opampFollower"] = "Voltage follower: Run DC — Vout ≈ Vin. Probe JO vs VIN; change VIN or RL and watch the buffer hold the voltage.",
        ["lab.hint.opampNonInv"] = "Non-inverting amp: Run DC — gain ≈ 1+Rf/Rg. Probe OUT; raise Vin until the teaching rails clamp.",
        ["lab.hint.opampComparator"] = "Comparator: Run DC and move POT1 Wiper — OUT rails high/low vs the ~2.5 V divider; LED follows.",
        ["lab.hint.opampSchmitt"] = "Schmitt trigger: Run DC and sweep POT1 slowly up and down — trip points differ (hysteresis) thanks to positive feedback.",
        ["lab.hint.opampSumming"] = "Summing amp: Run DC — Vout ≈ −(V1+V2) with equal resistors. Change V2 and confirm the sum.",
