        ["learn.project.ohmsLaw.labGoal"] = "Build a closed loop: 5 V battery → resistor → LED → ground. Pick the resistor value so the LED carries between 8 mA and 20 mA, and the node between resistor and LED sits near 2 V. Run DC and check.",
        ["learn.project.seriesParallelCircuits.labGoal"] = "Build two parallel branches across the battery, each with its own resistor and LED, both returning to ground. Run DC: both LEDs must conduct between 2 mA and 30 mA.",
        ["learn.project.fundamentalsLoop.labGoal"] = "Build the smallest complete circuit: battery + → resistor → LED → ground, with the return back to battery −. Run DC so the LED conducts.",
        ["learn.project.ohmExplore.labGoal"] = "Start from the LED loop and change only the resistor. Find a value that keeps the LED lit between 1 mA and 25 mA without burning it, then Run DC.",
        ["learn.project.led.labGoal"] = "Wire an LED with a series resistor to a battery and ground using at least four wires. Run DC: the LED must conduct and stay intact.",
        ["learn.project.diodeDirection.labGoal"] = "Build the diode example and orient the diode so current can pass (anode toward the battery +). Run DC and confirm the load conducts.",
        ["learn.project.seriesParallel.labGoal"] = "Build two LED branches in parallel, each LED with its own resistor. Run DC and confirm every LED conducts.",
        ["learn.project.seriesLeds.labGoal"] = "Put several LEDs in one series string with a single resistor on the 9 V supply. Run DC: the same current must flow through every LED.",
        ["learn.project.ledBurnLimit.labGoal"] = "Design a safe LED loop: choose the resistor so the LED stays below 25 mA and never burns out. Run DC and check.",
        ["learn.project.rc.labGoal"] = "Build battery → resistor → capacitor → ground. Switch to Transient analysis and run: the capacitor must charge to at least 0.5 V by the end.",
        ["learn.project.timeConstant.labGoal"] = "Build the RC loop, run a Transient analysis long enough for the capacitor to reach at least 2 V, and read τ off the scope at ~63 % of the rise.",
        ["learn.project.ledFade.labGoal"] = "Build the LED-fade circuit: battery and switch feeding a capacitor, with a resistor + LED returning to the capacitor. Run Transient with the switch closed to charge it.",
        ["learn.project.pulseRc.labGoal"] = "Feed a pulse source into a resistor–capacitor pair to ground. Run a Transient analysis and watch the RC round off the pulse edges.",
