        ["learn.project.voltageIntro.lesson1.title"] = "Voltage is a difference",
        ["learn.project.voltageIntro.lesson1.body"] = "Voltage is the difference in electric potential between two points — the push that moves charge. It is measured in volts, across a part, against the shared ground reference.",
        ["learn.project.voltageIntro.lesson2.title"] = "Potential, not motion",
        ["learn.project.voltageIntro.lesson2.body"] = "A battery has its full voltage even when nothing is connected. Only a closed path turns that potential into current, and around a loop the drops add up to the source.",
        ["learn.project.voltageIntro.quiz.q1.prompt"] = "Voltage is best described as…",
        ["learn.project.voltageIntro.quiz.q1.a"] = "A difference in electric potential between two points",
        ["learn.project.voltageIntro.quiz.q1.b"] = "The amount of charge stored in a wire",
        ["learn.project.voltageIntro.quiz.q1.c"] = "The speed of electrons in a circuit",
        ["learn.project.voltageIntro.quiz.q1.explain"] = "Voltage is always a comparison between two points — the push, not the flow.",
        ["learn.project.voltageIntro.quiz.q2.prompt"] = "A voltmeter is connected…",
        ["learn.project.voltageIntro.quiz.q2.a"] = "In series, inside the path",
        ["learn.project.voltageIntro.quiz.q2.b"] = "In parallel, across the two points",
        ["learn.project.voltageIntro.quiz.q2.c"] = "Only to ground",
        ["learn.project.voltageIntro.quiz.q2.explain"] = "It must see the difference between two points without becoming part of the path.",
        ["learn.project.voltageIntro.quiz.q3.prompt"] = "With the switch open, a voltmeter across the switch reads…",
        ["learn.project.voltageIntro.quiz.q3.a"] = "0 V, because nothing flows",
        ["learn.project.voltageIntro.quiz.q3.b"] = "Half the battery voltage",
        ["learn.project.voltageIntro.quiz.q3.c"] = "The full battery voltage",
        ["learn.project.voltageIntro.quiz.q3.explain"] = "No current flows, but the whole potential difference appears across the gap.",
        ["learn.project.voltageIntro.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.voltageIntro.challenge.c2.label"] = "The node between resistor and LED sits between 1.5 V and 3.5 V.",
        ["learn.project.currentIntro.lesson1.title"] = "Charge on the move",
        ["learn.project.currentIntro.lesson1.body"] = "Current is the rate at which charge passes a point, measured in amperes; small circuits live in milliamperes. Conventional current runs from + to −.",
        ["learn.project.currentIntro.lesson2.title"] = "One loop, one current",
        ["learn.project.currentIntro.lesson2.body"] = "Current needs a closed path and is the same at every point of a single loop. At a junction the incoming current equals the outgoing currents.",
        ["learn.project.currentIntro.quiz.q1.prompt"] = "One ampere means…",
        ["learn.project.currentIntro.quiz.q1.a"] = "One coulomb of charge passing per second",
        ["learn.project.currentIntro.quiz.q1.b"] = "One volt across one resistor",
        ["learn.project.currentIntro.quiz.q1.c"] = "One electron per second",
        ["learn.project.currentIntro.quiz.q1.explain"] = "Current is charge per time: 1 A = 1 C/s.",
        ["learn.project.currentIntro.quiz.q2.prompt"] = "In a single series loop the current is…",
        ["learn.project.currentIntro.quiz.q2.a"] = "Largest near the battery",
        ["learn.project.currentIntro.quiz.q2.b"] = "The same at every point",
        ["learn.project.currentIntro.quiz.q2.c"] = "Zero after the LED",
        ["learn.project.currentIntro.quiz.q2.explain"] = "There is only one path, so what leaves the battery passes every part and returns.",
        ["learn.project.currentIntro.quiz.q3.prompt"] = "An ammeter is connected…",
        ["learn.project.currentIntro.quiz.q3.a"] = "Across the battery",
        ["learn.project.currentIntro.quiz.q3.b"] = "Across the LED",
        ["learn.project.currentIntro.quiz.q3.c"] = "In series, inside the path",
        ["learn.project.currentIntro.quiz.q3.explain"] = "Current must pass through the meter; across a source it would short it.",
        ["learn.project.currentIntro.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.currentIntro.challenge.c2.label"] = "LED current between 5 mA and 30 mA.",
        ["learn.project.resistanceIntro.lesson1.title"] = "Resistance pushes back",
        ["learn.project.resistanceIntro.lesson1.body"] = "Resistance opposes current and is measured in ohms. A resistor is built to a precise value; its colour bands spell the number and it has no polarity.",
        ["learn.project.resistanceIntro.lesson2.title"] = "Ohm’s law",
        ["learn.project.resistanceIntro.lesson2.body"] = "U = I · R: for a fixed voltage, more resistance means less current. Series resistances add, and current through resistance turns into heat (P = I² · R).",
        ["learn.project.resistanceIntro.quiz.q1.prompt"] = "With the voltage fixed, doubling the resistance…",
        ["learn.project.resistanceIntro.quiz.q1.a"] = "Halves the current",
        ["learn.project.resistanceIntro.quiz.q1.b"] = "Doubles the current",
        ["learn.project.resistanceIntro.quiz.q1.c"] = "Leaves the current unchanged",
        ["learn.project.resistanceIntro.quiz.q1.explain"] = "I = U / R — current is inversely proportional to resistance.",
        ["learn.project.resistanceIntro.quiz.q2.prompt"] = "A 5 V battery, an LED that takes 2 V and a 220 Ω resistor: the LED current is about…",
        ["learn.project.resistanceIntro.quiz.q2.a"] = "23 mA",
        ["learn.project.resistanceIntro.quiz.q2.b"] = "13.6 mA",
        ["learn.project.resistanceIntro.quiz.q2.c"] = "2.3 mA",
        ["learn.project.resistanceIntro.quiz.q2.explain"] = "The resistor sees 5 − 2 = 3 V; 3 V / 220 Ω ≈ 13.6 mA.",
        ["learn.project.resistanceIntro.quiz.q3.prompt"] = "Two 220 Ω resistors in series behave like…",
        ["learn.project.resistanceIntro.quiz.q3.a"] = "110 Ω",
        ["learn.project.resistanceIntro.quiz.q3.b"] = "220 Ω",
        ["learn.project.resistanceIntro.quiz.q3.c"] = "440 Ω",
        ["learn.project.resistanceIntro.quiz.q3.explain"] = "Series resistances add: 220 + 220 = 440 Ω.",
        ["learn.project.resistanceIntro.challenge.c1.label"] = "At least one resistor limits the LED.",
        ["learn.project.resistanceIntro.challenge.c2.label"] = "LED current between 8 mA and 20 mA.",
        ["learn.project.ohmsLaw.lesson1.title"] = "One law, three forms",
        ["learn.project.ohmsLaw.lesson1.body"] = "U = I · R, I = U / R and R = U / I are the same statement. Ohmic parts draw a straight I–U line; LEDs and diodes curve, which is why they need a resistor in series.",
        ["learn.project.ohmsLaw.lesson2.title"] = "Sizing and power",
        ["learn.project.ohmsLaw.lesson2.body"] = "Size an LED resistor from R = (U_supply − U_LED) / I and round up to a standard value; then check the power P = U · I = I² · R against the resistor’s rating.",
        ["learn.project.ohmsLaw.quiz.q1.prompt"] = "A 5 V supply, an LED taking 2 V, target 15 mA — the resistor should be about…",
        ["learn.project.ohmsLaw.quiz.q1.a"] = "200 Ω (use 220 Ω)",
        ["learn.project.ohmsLaw.quiz.q1.b"] = "333 Ω",
        ["learn.project.ohmsLaw.quiz.q1.c"] = "75 Ω",
        ["learn.project.ohmsLaw.quiz.q1.explain"] = "R = (5 − 2) V / 0.015 A = 200 Ω; the next standard value up is 220 Ω.",
        ["learn.project.ohmsLaw.quiz.q2.prompt"] = "3 V across a part and 6.4 mA through it means R is about…",
        ["learn.project.ohmsLaw.quiz.q2.a"] = "19 Ω",
        ["learn.project.ohmsLaw.quiz.q2.b"] = "470 Ω",
        ["learn.project.ohmsLaw.quiz.q2.c"] = "2.1 kΩ",
        ["learn.project.ohmsLaw.quiz.q2.explain"] = "R = U / I = 3 / 0.0064 ≈ 470 Ω.",
        ["learn.project.ohmsLaw.quiz.q3.prompt"] = "3 V divided by 2.2 kΩ is…",
        ["learn.project.ohmsLaw.quiz.q3.a"] = "1.36 A",
        ["learn.project.ohmsLaw.quiz.q3.b"] = "0.68 mA",
        ["learn.project.ohmsLaw.quiz.q3.c"] = "1.36 mA",
        ["learn.project.ohmsLaw.quiz.q3.explain"] = "Volts divided by kilo-ohms gives milliamperes: 3 / 2.2 = 1.36 mA.",
        ["learn.project.ohmsLaw.challenge.c1.label"] = "A resistor limits the LED.",
        ["learn.project.ohmsLaw.challenge.c2.label"] = "LED current between 8 mA and 20 mA with the LED node near 2 V.",
        ["learn.project.circuitElements.lesson1.title"] = "Four roles",
        ["learn.project.circuitElements.lesson1.body"] = "Every circuit has a source, a load, a closed path and usually a control. Sources are batteries, AC and pulse sources; passives are resistors, capacitors and inductors.",
        ["learn.project.circuitElements.lesson2.title"] = "Reading the symbols",
        ["learn.project.circuitElements.lesson2.body"] = "Diodes and LEDs are one-way arrows, transistors are controllable valves, switches and fuses control and protect. Dots connect wires, crossings do not, and every ground symbol is one node.",
        ["learn.project.circuitElements.quiz.q1.prompt"] = "On the battery symbol the long line marks…",
        ["learn.project.circuitElements.quiz.q1.a"] = "The + terminal",
        ["learn.project.circuitElements.quiz.q1.b"] = "The − terminal",
        ["learn.project.circuitElements.quiz.q1.c"] = "Ground",
        ["learn.project.circuitElements.quiz.q1.explain"] = "Long line +, short thick line −.",
        ["learn.project.circuitElements.quiz.q2.prompt"] = "A capacitor…",
        ["learn.project.circuitElements.quiz.q2.a"] = "Adds energy to the circuit",
        ["learn.project.circuitElements.quiz.q2.b"] = "Stores charge and blocks steady DC",
        ["learn.project.circuitElements.quiz.q2.c"] = "Only limits current",
        ["learn.project.circuitElements.quiz.q2.explain"] = "It passes changing signals and blocks DC — smoothing, timing and filtering.",
        ["learn.project.circuitElements.quiz.q3.prompt"] = "Two schematic lines cross without a dot. They are…",
        ["learn.project.circuitElements.quiz.q3.a"] = "Connected",
        ["learn.project.circuitElements.quiz.q3.b"] = "Connected only if both are wires",
        ["learn.project.circuitElements.quiz.q3.c"] = "Not connected",
        ["learn.project.circuitElements.quiz.q3.explain"] = "Only a junction dot means an electrical connection.",
        ["learn.project.circuitElements.challenge.c1.label"] = "Battery, resistor, LED and ground are all present with a closed loop.",
        ["learn.project.circuitElements.challenge.c2.label"] = "The LED lights and does not burn.",
        ["learn.project.seriesParallelCircuits.lesson1.title"] = "Series: one path",
        ["learn.project.seriesParallelCircuits.lesson1.body"] = "In series the same current flows through every part, the voltage drops add up to the source, and resistances add. One broken part stops everything.",
        ["learn.project.seriesParallelCircuits.lesson2.title"] = "Parallel: shared nodes",
        ["learn.project.seriesParallelCircuits.lesson2.body"] = "In parallel every branch sees the same voltage, the branch currents add at the supply, and the total resistance is smaller than any branch. Branches fail independently.",
        ["learn.project.seriesParallelCircuits.quiz.q1.prompt"] = "Two 220 Ω resistors in series draw a straight…",
        ["learn.project.seriesParallelCircuits.quiz.q1.a"] = "440 Ω total",
        ["learn.project.seriesParallelCircuits.quiz.q1.b"] = "110 Ω total",
        ["learn.project.seriesParallelCircuits.quiz.q1.c"] = "220 Ω total",
        ["learn.project.seriesParallelCircuits.quiz.q1.explain"] = "Series resistances add: 220 + 220 = 440 Ω.",
        ["learn.project.seriesParallelCircuits.quiz.q2.prompt"] = "Two equal LEDs in parallel on a 5 V rail: each branch sees…",
        ["learn.project.seriesParallelCircuits.quiz.q2.a"] = "2.5 V",
        ["learn.project.seriesParallelCircuits.quiz.q2.b"] = "5 V",
        ["learn.project.seriesParallelCircuits.quiz.q2.c"] = "10 V",
        ["learn.project.seriesParallelCircuits.quiz.q2.explain"] = "Parallel branches share the same two nodes, so each sees the full voltage.",
        ["learn.project.seriesParallelCircuits.quiz.q3.prompt"] = "One LED in a parallel pair burns out. The other…",
        ["learn.project.seriesParallelCircuits.quiz.q3.a"] = "Goes dark too",
        ["learn.project.seriesParallelCircuits.quiz.q3.b"] = "Gets twice the voltage",
        ["learn.project.seriesParallelCircuits.quiz.q3.c"] = "Keeps lighting as before",
        ["learn.project.seriesParallelCircuits.quiz.q3.explain"] = "Each branch is its own loop; the battery simply supplies less total current.",
        ["learn.project.seriesParallelCircuits.challenge.c1.label"] = "Two LED branches, each with a resistor.",
        ["learn.project.seriesParallelCircuits.challenge.c2.label"] = "Both LEDs conduct between 2 mA and 30 mA.",
        ["learn.project.acDc.lesson1.title"] = "Steady or alternating",
        ["learn.project.acDc.lesson1.body"] = "DC flows one way at a steady value and has polarity. AC reverses in a sine wave; one cycle lasts the period T and the frequency is f = 1 / T — 50 or 60 Hz for mains.",
        ["learn.project.acDc.lesson2.title"] = "Describing and converting AC",
        ["learn.project.acDc.lesson2.body"] = "AC size is given as peak, peak-to-peak or RMS (U_RMS = Û / √2 for a sine). Transformers only work with AC, electronics need DC, so chargers rectify with diodes and smooth with capacitors.",
        ["learn.project.acDc.quiz.q1.prompt"] = "A 50 Hz mains cycle lasts…",
        ["learn.project.acDc.quiz.q1.a"] = "20 ms",
        ["learn.project.acDc.quiz.q1.b"] = "50 ms",
        ["learn.project.acDc.quiz.q1.c"] = "2 ms",
        ["learn.project.acDc.quiz.q1.explain"] = "T = 1 / f = 1 / 50 Hz = 0.02 s = 20 ms.",
        ["learn.project.acDc.quiz.q2.prompt"] = "“230 V mains” is the…",
        ["learn.project.acDc.quiz.q2.a"] = "Peak value",
        ["learn.project.acDc.quiz.q2.b"] = "RMS value",
        ["learn.project.acDc.quiz.q2.c"] = "Peak-to-peak value",
        ["learn.project.acDc.quiz.q2.explain"] = "RMS is the heating-equivalent DC value; the peak is about 325 V.",
        ["learn.project.acDc.quiz.q3.prompt"] = "Under AC a capacitor…",
        ["learn.project.acDc.quiz.q3.a"] = "Blocks everything",
        ["learn.project.acDc.quiz.q3.b"] = "Passes DC and blocks AC",
        ["learn.project.acDc.quiz.q3.c"] = "Passes AC and blocks DC",
        ["learn.project.acDc.quiz.q3.explain"] = "Only a changing voltage moves charge on and off the plates — the basis of filters.",
        ["learn.project.acDc.challenge.c1.label"] = "AC analysis runs on the RC example.",
        ["learn.project.acDc.challenge.c2.label"] = "The capacitor node magnitude is a fraction of the source.",
        ["learn.project.basicsFinal.lesson1.title"] = "What this group covered",
        ["learn.project.basicsFinal.lesson1.body"] = "Voltage pushes, current flows, resistance limits. Ohm’s law ties them together. Series shares one current, parallel shares one voltage. DC is steady, AC swings.",
        ["learn.project.basicsFinal.lesson2.title"] = "How the final works",
        ["learn.project.basicsFinal.lesson2.body"] = "Ten questions, mixed across the group. Eight correct passes. Wrong answers show the reason, and you can retry as often as you like.",
        ["learn.project.basicsFinal.challenge.c1.label"] = "No lab for the final quiz.",
        ["learn.project.basicsFinal.challenge.c2.label"] = "No lab for the final quiz.",
        ["learn.project.voltageIntro.slide1.title"] = "Something has to push the charge",
        ["learn.project.voltageIntro.slide1.p1"] = "Electric charge does not start moving on its own. Before it can flow through a wire, something has to push it, and that push is what we call voltage.",
        ["learn.project.voltageIntro.slide1.p2"] = "Water is the easiest picture. Join two tanks with a pipe and, as long as the levels are equal, nothing happens. Lift one tank and water starts flowing into the lower one. The difference in level is what drives the water, and voltage plays exactly the same role in a circuit.",
        ["learn.project.voltageIntro.slide1.p3"] = "Notice that voltage by itself does not say how much water flows. It only describes how hard the water is being pushed. The actual amount depends on the pipe as well, on how easily water can get through it. That is what the next two lessons, on current and on resistance, are about.",
        ["learn.project.voltageIntro.slide1.caption"] = "Equal levels, no flow. A difference in level sets the water moving. Voltage is that difference.",
        ["learn.project.voltageIntro.slide2.title"] = "Voltage is always between two points",
        ["learn.project.voltageIntro.slide2.p1"] = "A single point in a circuit does not \"have\" 5 volts. Voltage is always a comparison of two places, the difference between them. That is why a voltmeter has to touch two points at once.",
        ["learn.project.voltageIntro.slide2.p2"] = "A 5 V battery keeps its positive terminal 5 volts above its negative terminal, no matter what you connect to it. The unit of voltage is the volt, written V. In formulas voltage is written as U.",
        ["learn.project.voltageIntro.slide2.p3"] = "When someone says that \"this node is at 3 V\", they mean 3 volts relative to ground. The second point is simply left unsaid because everyone assumes it. It is always there, though.",
        ["learn.project.voltageIntro.slide2.caption"] = "A voltmeter connects between two points and shows the difference in their voltage.",
        ["learn.project.voltageIntro.slide2.callout"] = "Voltage is measured across a part, between its terminals. Current flows through the part.",
        ["learn.project.voltageIntro.slide3.title"] = "Where voltage comes from",
        ["learn.project.voltageIntro.slide3.p1"] = "Inside a battery a chemical reaction separates charge. One terminal collects a surplus of electrons, the other is left short of them. This stored imbalance is the source of the push that later drives charge around the circuit.",
        ["learn.project.voltageIntro.slide3.p2"] = "Sources differ a lot in size. An AA cell gives 1.5 V, a USB port 5 V and a car battery 12 V. A wall socket carries 230 V, which is a voltage these lessons will never work with.",
        ["learn.project.voltageIntro.slide3.p3"] = "Chemistry is not the only option. A solar cell makes voltage from light, a generator from motion, and a USB charger derives it from the mains through a transformer. The result is the same every time: a difference in potential that a circuit can put to use.",
        ["learn.project.voltageIntro.slide3.caption"] = "Typical voltages, from a single cell to the wall socket.",
        ["learn.project.voltageIntro.slide3.callout"] = "Everything in these lessons stays below 24 V. Never experiment with mains voltage.",
        ["learn.project.voltageIntro.slide4.title"] = "Ground is the shared zero",
        ["learn.project.voltageIntro.slide4.p1"] = "To talk about the voltage \"at a node\" we need a common reference point that all voltages are measured from. That point is called ground, and by agreement its voltage is 0 V.",
        ["learn.project.voltageIntro.slide4.p2"] = "Every voltage label you see next to a node in the Lab is measured against ground. Ground is usually the negative terminal of the battery. Nothing special happens there; it is just the place we measure from.",
        ["learn.project.voltageIntro.slide4.p3"] = "We could just as well pick any other node as the zero. Every difference between parts would stay exactly the same, only the numbers on the labels would shift. Ground is a convention that makes the values in a circuit easy to compare.",
        ["learn.project.voltageIntro.slide4.caption"] = "Think of voltages as heights on a ladder. Ground is the rung we call zero.",
        ["learn.project.voltageIntro.slide5.title"] = "Voltage can exist without current",
        ["learn.project.voltageIntro.slide5.p1"] = "Open the switch and the current stops everywhere in the circuit. The battery voltage does not go anywhere, though. Put a voltmeter across the open switch and it reads the full 5 V.",
        ["learn.project.voltageIntro.slide5.p2"] = "So voltage is a readiness to push, not the pushing itself. Only a closed path through the circuit lets that readiness turn into moving charge, which is current.",
        ["learn.project.voltageIntro.slide5.p3"] = "This example deserves a moment of thought. No charge is moving, and yet the whole battery voltage sits between the contacts of the open switch. The push is waiting there for the moment a path appears.",
        ["learn.project.voltageIntro.slide5.caption"] = "Open switch: no current anywhere, but 5 V across the switch contacts.",
        ["learn.project.voltageIntro.slide6.title"] = "Voltage is shared out around the loop",
        ["learn.project.voltageIntro.slide6.p1"] = "Close the switch and the battery's 5 V gets divided between the parts. About 2.75 V appears across the resistor and 2.25 V across the LED. Add the two together and you are back at 5 V.",
        ["learn.project.voltageIntro.slide6.p2"] = "This always holds: the voltage drops across the parts in a closed loop add up to the voltage of the source. Whatever the LED does not take falls on the resistor, and the other way round.",
        ["learn.project.voltageIntro.slide6.p3"] = "The rule is known as Kirchhoff's voltage law, and it is the main tool for reasoning about series circuits. Know the source voltage and one drop, and you can work out the other.",
        ["learn.project.voltageIntro.slide6.caption"] = "2.75 V + 2.25 V = 5 V.",
        ["learn.project.voltageIntro.slide6.callout"] = "U_battery = U_resistor + U_LED",
        ["learn.project.voltageIntro.slide7.title"] = "Voltage: what to take away",
        ["learn.project.voltageIntro.slide7.p1"] = "Everything that follows rests on these four points.",
        ["learn.project.voltageIntro.slide7.fact1"] = "Voltage is the difference in potential between two points. It is the \"push\" that drives charge.",
        ["learn.project.voltageIntro.slide7.fact2"] = "It is measured in volts, across a part, with a voltmeter connected in parallel.",
        ["learn.project.voltageIntro.slide7.fact3"] = "Ground is the agreed zero. Node voltages are given relative to it.",
        ["learn.project.voltageIntro.slide7.fact4"] = "A source has voltage even when no current flows. Around a closed loop the drops add up to the source voltage.",
        ["learn.project.currentIntro.slide1.title"] = "Charge on the move",
        ["learn.project.currentIntro.slide1.p1"] = "Metals are full of electrons that are free to move. Apply a voltage to a wire and they all start shifting in one direction. This orderly movement of charge is what we call electric current.",
        ["learn.project.currentIntro.slide1.p2"] = "Current tells you how much charge passes a given point every second. The unit is the ampere (A): a current of one ampere means one coulomb of charge passes the point each second. In formulas current is written as I.",
        ["learn.project.currentIntro.slide1.p3"] = "The electrons themselves move surprisingly slowly, well under a millimetre per second. What travels fast is the push that drives them. That is why, when you close a switch, electrons along the whole length of the wire start moving almost at once.",
        ["learn.project.currentIntro.slide1.caption"] = "Count how much charge passes the gate each second and you have the current.",
        ["learn.project.currentIntro.slide1.callout"] = "I = Q / t",
        ["learn.project.currentIntro.slide2.title"] = "Which way current flows",
        ["learn.project.currentIntro.slide2.p1"] = "Schematics use what is called conventional current: from the positive terminal of the source, through the circuit, to the negative terminal. Arrows in diagrams, diode symbols and the moving dashes on the Lab wires all follow this direction.",
        ["learn.project.currentIntro.slide2.p2"] = "Electrons actually drift the other way, from negative to positive. For calculations and for understanding a circuit this makes no difference, both views give the same results. So the old convention stayed, and you should read every arrow as conventional current.",
        ["learn.project.currentIntro.slide2.p3"] = "The convention is older than the electron. Benjamin Franklin decided which charge would be called positive long before anyone knew what actually carried charge in a wire. By the time electrons were discovered, the arrows were already in every textbook.",
        ["learn.project.currentIntro.slide2.caption"] = "Conventional current (top) runs from + to −. Electrons (bottom) move the other way.",
        ["learn.project.currentIntro.slide3.title"] = "How much is one ampere",
        ["learn.project.currentIntro.slide3.p1"] = "For small electronics one ampere is a lot. Most values you will meet are in milliamperes: 1 A = 1000 mA.",
        ["learn.project.currentIntro.slide3.p2"] = "A sensor input draws only microamperes, an LED needs 10 to 20 mA, a phone charger delivers up to 2 A, and an electric kettle takes around 10 A.",
        ["learn.project.currentIntro.slide3.p3"] = "To get a sense of scale: a phone battery holds about 3000 mAh. That means it can deliver 3 A for one hour, or 15 mA for 200 hours. A single LED would run on it for more than a week.",
        ["learn.project.currentIntro.slide3.caption"] = "From sensors to heating elements.",
        ["learn.project.currentIntro.slide4.title"] = "Current needs a closed circuit",
        ["learn.project.currentIntro.slide4.p1"] = "Charge cannot pile up anywhere or get lost. For a current to flow it needs a complete path: out of the source, through every part, and back into the source again.",
        ["learn.project.currentIntro.slide4.p2"] = "Break the circuit in one single place and the current drops to zero everywhere, not just at the break. The battery still has its voltage, it simply has nowhere to push.",
        ["learn.project.currentIntro.slide4.p3"] = "This is exactly why a bird can sit safely on a high-voltage line. It touches only one wire, so there is no closed path through its body and no current flows through it.",
        ["learn.project.currentIntro.slide4.caption"] = "Battery + → resistor → LED → ground → battery −.",
        ["learn.project.currentIntro.slide5.title"] = "One loop, one current",
        ["learn.project.currentIntro.slide5.p1"] = "In a simple loop there is only one current. Whatever leaves the battery passes through the resistor, the LED and the return wire, because there is nowhere else for it to go. You will therefore see the same value on every part.",
        ["learn.project.currentIntro.slide5.p2"] = "Where a wire splits, the current divides between the branches. But the total flowing into a junction always equals the total flowing out. That is the basic rule for every junction in a circuit.",
        ["learn.project.currentIntro.slide5.p3"] = "This rule is called Kirchhoff's current law. Together with the voltage law from the previous lesson it is enough to solve every circuit you will meet in this course.",
        ["learn.project.currentIntro.slide5.caption"] = "30 mA flows into the junction, 18 + 12 mA flow out.",
        ["learn.project.currentIntro.slide5.callout"] = "I_in = I_out1 + I_out2",
        ["learn.project.currentIntro.slide6.title"] = "How current is measured",
        ["learn.project.currentIntro.slide6.p1"] = "An ammeter is connected in series, directly in the path of the current, so that the current it measures flows through it. Connected in parallel with a battery it would short the battery out.",
        ["learn.project.currentIntro.slide6.p2"] = "In the Lab you rarely need an ammeter. After a run the current of every branch is listed, and the speed of the dashes on a wire follows its current.",
        ["learn.project.currentIntro.slide6.p3"] = "With a real meter it takes more work: you have to break the circuit and insert the meter into the gap. That is one reason voltage is measured far more often than current in practice. Measuring a voltage needs no rewiring at all.",
        ["learn.project.currentIntro.slide6.caption"] = "An ammeter connected in series in the top wire.",
        ["learn.project.currentIntro.slide7.title"] = "When there is too much current",
        ["learn.project.currentIntro.slide7.p1"] = "Current passing through resistance produces heat. A little is harmless, but too much melts insulation, burns resistors and destroys LEDs.",
        ["learn.project.currentIntro.slide7.p2"] = "A Lab LED comfortably handles about 20 mA and burns out at roughly 35 mA. Limiting the current to a safe value is precisely the job of the resistor connected in series with the LED.",
        ["learn.project.currentIntro.slide7.p3"] = "Wires have limits too. A thin wire carrying too much current heats up. A fuse is built on exactly this: it is a deliberately weak piece of wire that is meant to melt first.",
        ["learn.project.currentIntro.slide7.caption"] = "LED current zones in the Lab.",
        ["learn.project.currentIntro.slide7.callout"] = "Never connect an LED straight to a battery without a resistor.",
        ["learn.project.currentIntro.slide8.title"] = "Current: what to take away",
        ["learn.project.currentIntro.slide8.p1"] = "Keep these five points close.",
        ["learn.project.currentIntro.slide8.fact1"] = "Current is the amount of charge per second and is measured in amperes. Small circuits work in milliamperes.",
        ["learn.project.currentIntro.slide8.fact2"] = "Conventional current runs from + to −. Arrows and LED symbols follow it.",
        ["learn.project.currentIntro.slide8.fact3"] = "Current needs a closed circuit. Break it anywhere and it stops everywhere.",
        ["learn.project.currentIntro.slide8.fact4"] = "In a single loop there is one current. At a junction, what flows in equals what flows out.",
        ["learn.project.currentIntro.slide8.fact5"] = "It is measured in series. Too much current means heat and destroyed parts.",
        ["learn.project.resistanceIntro.slide1.title"] = "Resistance stands in the way of current",
        ["learn.project.resistanceIntro.slide1.p1"] = "Water flows easily through a wide pipe. Through a narrow one, far less gets through at the same pressure. Electrical resistance is exactly this \"narrowness\" of the path the current has to take.",
        ["learn.project.resistanceIntro.slide1.p2"] = "Copper wire puts up almost no resistance. Carbon or a thin metal film puts up a great deal. The unit of resistance is the ohm, written Ω.",
        ["learn.project.resistanceIntro.slide1.p3"] = "Resistance depends on the material, the length and the thickness of a conductor. A longer wire has more resistance, a thicker one less. That is why a thick cable feeds a cooker while a thin wire is enough for a doorbell.",
        ["learn.project.resistanceIntro.slide1.caption"] = "Same pressure, different pipes. A narrow pipe means high resistance.",
        ["learn.project.resistanceIntro.slide2.title"] = "The resistor",
        ["learn.project.resistanceIntro.slide2.p1"] = "A resistor is a part made to have a precise value of resistance. Coloured bands on its body spell out that value. A resistor has no polarity, so it does not matter which way round you connect it.",
        ["learn.project.resistanceIntro.slide2.p2"] = "The bands are read as digits. Red, red and brown mean 2, 2 and a multiplier of 10, so 220 Ω. A gold band means a tolerance of 5 %.",
        ["learn.project.resistanceIntro.slide2.p3"] = "You do not have to memorise the colour code. The Lab shows the value right next to the symbol, and a multimeter will measure it for you. Still, it is nice to recognise a 220 Ω resistor at a glance.",
        ["learn.project.resistanceIntro.slide2.caption"] = "A resistor with a resistance of 220 Ω.",
        ["learn.project.resistanceIntro.slide3.title"] = "Ohm's law",
        ["learn.project.resistanceIntro.slide3.p1"] = "For a resistor the current is proportional to the voltage. The constant of proportionality is the resistance, and the relation between them is written U = I · R.",
        ["learn.project.resistanceIntro.slide3.p2"] = "An example: the supply is 5 V and the LED takes 2 V of it, leaving 3 V for the resistor. With 220 Ω the current through the resistor, and so through the whole loop, is 3 / 220 ≈ 13.6 mA.",
        ["learn.project.resistanceIntro.slide3.p3"] = "It helps to say the units out loud while you calculate: volts across the part, amperes through it, ohms in between. If a result looks absurd, say 3000 A through an LED, a prefix has certainly gone missing somewhere.",
        ["learn.project.resistanceIntro.slide3.caption"] = "Cover the quantity you are looking for. The other two show how to calculate it.",
        ["learn.project.resistanceIntro.slide3.callout"] = "U = I · R\nI = U / R\nR = U / I",
        ["learn.project.resistanceIntro.slide4.title"] = "More resistance, less current",
        ["learn.project.resistanceIntro.slide4.p1"] = "Keep the voltage the same and change only the resistor. From 3 V, a 100 Ω resistor passes 30 mA, a 220 Ω resistor only 13.6 mA, and 1 kΩ a mere 3 mA.",
        ["learn.project.resistanceIntro.slide4.p2"] = "This is exactly why a resistor works as a current limiter. By choosing the resistance R you are also choosing the current I that will flow through the circuit.",
        ["learn.project.resistanceIntro.slide4.p3"] = "This table is really the whole design method for a simple circuit. Decide how much current the load should get, and Ohm's law tells you which resistor you need.",
        ["learn.project.resistanceIntro.slide4.caption"] = "Current from 3 V for four different resistors.",
        ["learn.project.resistanceIntro.slide5.title"] = "Resistors in series add up",
        ["learn.project.resistanceIntro.slide5.p1"] = "Connect two resistors one after the other and the current has to squeeze through both. Their resistances therefore add: 220 + 220 = 440 Ω.",
        ["learn.project.resistanceIntro.slide5.p2"] = "A parallel connection works the other way round. A second \"pipe\" next to the first lowers the total resistance, because the current has more paths. The lesson on series and parallel circuits covers this in detail.",
        ["learn.project.resistanceIntro.slide5.p3"] = "Adding comes in handy when you do not have the value you need. No 440 Ω resistor in the drawer? Two 220 Ω resistors in a row do the same job.",
        ["learn.project.resistanceIntro.slide5.caption"] = "Resistances in series add.",
        ["learn.project.resistanceIntro.slide5.callout"] = "R_series = R1 + R2",
        ["learn.project.resistanceIntro.slide6.title"] = "Everything has resistance",
        ["learn.project.resistanceIntro.slide6.p1"] = "A short wire has a resistance of only a few milliohms, which is why the Lab treats wires as perfect. Human skin has tens of kilo-ohms or more, and that is precisely why small voltages are harmless.",
        ["learn.project.resistanceIntro.slide6.p2"] = "Some parts change their resistance on purpose: a potentiometer when you turn it, a light-dependent resistor with the amount of light, and a thermistor with temperature.",
        ["learn.project.resistanceIntro.slide6.p3"] = "Long thin wires are the exception. A 100 m extension cord has a few ohms, and a motor drawing 10 A loses several volts along it. That is why power tools run weaker at the far end of a long cord.",
        ["learn.project.resistanceIntro.slide6.caption"] = "From copper wire to glass insulation.",
        ["learn.project.resistanceIntro.slide7.title"] = "Resistance produces heat",
        ["learn.project.resistanceIntro.slide7.p1"] = "Pushing charge through resistance costs energy, and that energy turns into heat. The power lost in a part is P = U · I, or equally I² · R.",
        ["learn.project.resistanceIntro.slide7.p2"] = "Our 220 Ω resistor at 13.6 mA gives off about 0.04 W, no problem at all for an ordinary quarter-watt resistor. Force 100 mA through it, though, and it would dissipate 2.2 W and start to burn.",
        ["learn.project.resistanceIntro.slide7.p3"] = "Sometimes heat is the whole point. A kettle, a toaster and an old-fashioned light bulb are essentially resistors designed to run hot. In every other case it is waste, and it limits how much power a small part can take.",
        ["learn.project.resistanceIntro.slide7.caption"] = "Stay below the power rating of the part.",
        ["learn.project.resistanceIntro.slide7.callout"] = "P = U · I = I² · R",
        ["learn.project.resistanceIntro.slide8.title"] = "Resistance: what to take away",
        ["learn.project.resistanceIntro.slide8.p1"] = "The third side of the triangle.",
        ["learn.project.resistanceIntro.slide8.fact1"] = "Resistance opposes the flow of current and is measured in ohms. Wires have almost none, insulators an enormous amount.",
        ["learn.project.resistanceIntro.slide8.fact2"] = "U = I · R. At a fixed voltage, more resistance means less current.",
        ["learn.project.resistanceIntro.slide8.fact3"] = "A resistor limits current and has no polarity. Coloured bands give its value.",
        ["learn.project.resistanceIntro.slide8.fact4"] = "Resistances in series add. A parallel connection lowers the total.",
        ["learn.project.resistanceIntro.slide8.fact5"] = "Current through resistance produces heat: P = I² · R.",
        ["learn.project.ohmsLaw.slide1.title"] = "One law, three quantities",
        ["learn.project.ohmsLaw.slide1.p1"] = "Voltage pushes, current flows and resistance holds it back. Ohm's law ties the three together in a single line: U = I · R.",
        ["learn.project.ohmsLaw.slide1.p2"] = "As soon as you know two of the quantities, the third is fixed. The triangle in the picture is a memory aid: cover the quantity you want and the remaining two show whether to multiply or divide.",
        ["learn.project.ohmsLaw.slide1.p3"] = "The law works for any single ohmic part, and for a whole chain of them as long as you use the total voltage and the total resistance. The only trick is to keep track of which voltage belongs to which resistance.",
        ["learn.project.ohmsLaw.slide1.caption"] = "U on top, I and R underneath.",
        ["learn.project.ohmsLaw.slide1.callout"] = "U = I · R",
        ["learn.project.ohmsLaw.slide2.title"] = "A straight line",
        ["learn.project.ohmsLaw.slide2.p1"] = "Plot the current through a resistor against the voltage across it and you get a straight line through the origin. Double the voltage and the current doubles as well.",
        ["learn.project.ohmsLaw.slide2.p2"] = "A larger resistance gives a flatter line, because the same voltage produces less current. Parts whose graph is a straight line like this are called ohmic.",
        ["learn.project.ohmsLaw.slide2.p3"] = "The slope of the line is 1 / R. Take any two points on it and you can read off the resistance. A multimeter does the same thing on its ohms range: it pushes a known current through the part and measures the voltage.",
        ["learn.project.ohmsLaw.slide2.caption"] = "A steeper line means a smaller resistance.",
        ["learn.project.ohmsLaw.slide3.title"] = "Worked example: choosing a resistor for an LED",
        ["learn.project.ohmsLaw.slide3.p1"] = "The supply is 5 V, the red LED needs 2 V and we want about 15 mA through it. The resistor has to take the rest of the voltage, 5 − 2 = 3 V.",
        ["learn.project.ohmsLaw.slide3.p2"] = "From Ohm's law, R = U / I = 3 V / 0.015 A = 200 Ω. Resistors only come in standard values, so we round up to 220 Ω. A quick check: 3 / 220 ≈ 13.6 mA, which is fine.",
        ["learn.project.ohmsLaw.slide3.p3"] = "Rounding up is deliberate. A slightly larger resistor gives slightly less current, which is on the safe side. Rounding down would push the LED harder than planned.",
        ["learn.project.ohmsLaw.slide3.caption"] = "R1 takes whatever voltage the LED does not need.",
        ["learn.project.ohmsLaw.slide3.callout"] = "R = (U_supply − U_LED) / I\n= 3 V / 0.015 A = 200 Ω → 220 Ω",
        ["learn.project.ohmsLaw.slide4.title"] = "Worked example: finding an unknown resistor",
        ["learn.project.ohmsLaw.slide4.p1"] = "Measure the voltage across the resistor and the current through it, and Ohm's law gives you the resistance: R = U / I.",
        ["learn.project.ohmsLaw.slide4.p2"] = "If you read 3.0 V across the part and 6.4 mA through it, the resistance is 3.0 / 0.0064 ≈ 470 Ω. A multimeter on its ohms range does exactly this calculation for you.",
        ["learn.project.ohmsLaw.slide4.p3"] = "The method works for anything that behaves like a resistor: a heating element, a long cable, a light bulb at a fixed brightness. Two readings and one division.",
        ["learn.project.ohmsLaw.slide4.caption"] = "Ammeter in series, voltmeter across. Two readings, one division.",
        ["learn.project.ohmsLaw.slide5.title"] = "Prefixes",
        ["learn.project.ohmsLaw.slide5.p1"] = "The prefix k means ×1000, M means ×1 000 000, m means ÷1000 and µ means ÷1 000 000. Most mistakes with Ohm's law are really mistakes with prefixes.",
        ["learn.project.ohmsLaw.slide5.p2"] = "The safest habit is to convert everything to base units first. For example, 3 V / 2.2 kΩ = 3 / 2200 = 0.00136 A, which is 1.36 mA.",
        ["learn.project.ohmsLaw.slide5.p3"] = "A quick sanity check helps too. LED currents are milliamperes, resistors range from hundreds of ohms to kilo-ohms, and hobby voltages are single digits. If your answer lands far outside that, look for the slipped prefix.",
        ["learn.project.ohmsLaw.slide5.caption"] = "Each step is a factor of 1000.",
        ["learn.project.ohmsLaw.slide5.callout"] = "V ÷ kΩ = mA\nV ÷ MΩ = µA\nmA × kΩ = V",
        ["learn.project.ohmsLaw.slide6.title"] = "Where the law stops working",
        ["learn.project.ohmsLaw.slide6.p1"] = "An LED does not draw a straight line. Almost nothing flows below about 2 V, and then the current climbs steeply. Its \"resistance\" changes with the voltage, so a single number cannot describe it.",
        ["learn.project.ohmsLaw.slide6.p2"] = "That is exactly why an LED needs a resistor. The resistor is the ohmic part that sets the current; the LED simply takes its 2 V and lets the rest of the loop do the arithmetic.",
        ["learn.project.ohmsLaw.slide6.p3"] = "Many parts curve like this: diodes, transistors, a filament bulb as it heats up. Ohm's law still holds at any one operating point, it is just not a fixed value. Datasheets give a curve instead of a number.",
        ["learn.project.ohmsLaw.slide6.caption"] = "Resistor: a straight line. LED: a curve.",
        ["learn.project.ohmsLaw.slide7.title"] = "Power",
        ["learn.project.ohmsLaw.slide7.p1"] = "Power is voltage times current, P = U · I. Combined with Ohm's law it can also be written as I² · R or U² / R.",
        ["learn.project.ohmsLaw.slide7.p2"] = "The LED resistor from the example dissipates 2.75 V × 13.6 mA ≈ 0.037 W, which is nothing for a quarter-watt part. A 10 Ω resistor connected straight across 5 V, on the other hand, would have to handle 2.5 W and would burn.",
        ["learn.project.ohmsLaw.slide7.p3"] = "The three power formulas are one law rearranged. Use whichever pair of quantities you already know. For a resistor that is usually R together with either U or I.",
        ["learn.project.ohmsLaw.slide7.caption"] = "Always ask two questions: how many ohms, and how many watts.",
        ["learn.project.ohmsLaw.slide7.callout"] = "P = U · I = I² · R = U² / R",
        ["learn.project.ohmsLaw.slide8.title"] = "Ohm's law: what to take away",
        ["learn.project.ohmsLaw.slide8.p1"] = "The working rules.",
        ["learn.project.ohmsLaw.slide8.fact1"] = "U = I · R holds for any ohmic part.",
        ["learn.project.ohmsLaw.slide8.fact2"] = "LED resistor: R = (U_supply − U_LED) / I, then round up to a standard value.",
        ["learn.project.ohmsLaw.slide8.fact3"] = "Unknown resistor: R = U / I from two readings.",
        ["learn.project.ohmsLaw.slide8.fact4"] = "Convert prefixes first. V ÷ kΩ gives mA.",
        ["learn.project.ohmsLaw.slide8.fact5"] = "LEDs are not ohmic, so they need a resistor. Check the watts as well as the ohms.",
        ["learn.project.circuitElements.slide1.title"] = "Four roles",
        ["learn.project.circuitElements.slide1.p1"] = "Every circuit is built from the same four roles: a source that pushes, a load that uses the energy, wires that close the loop, and usually a control that decides when the circuit runs.",
        ["learn.project.circuitElements.slide1.p2"] = "In the LED example the battery is the source, the LED with its resistor is the load, the wires and ground close the loop, and the switch is the control.",
        ["learn.project.circuitElements.slide1.p3"] = "When a circuit does not work, check the roles in this order. Is there a source? Is the loop closed? Is the control letting current through? Only then start looking at the load itself.",
        ["learn.project.circuitElements.slide1.caption"] = "Source V1, control S1, load R1 + D1, return through ground.",
        ["learn.project.circuitElements.slide2.title"] = "Sources",
        ["learn.project.circuitElements.slide2.p1"] = "A battery gives a steady direct voltage; the longer line on its symbol marks the positive terminal. An AC source swings back and forth like the mains. A pulse source jumps between two levels, like the output pin of a microcontroller.",
        ["learn.project.circuitElements.slide2.p2"] = "Every source has two terminals. Whatever current leaves through one of them has to come back in through the other.",
        ["learn.project.circuitElements.slide2.p3"] = "A real source has its limits. A battery cannot deliver unlimited current, and its voltage sags under a heavy load. The Lab battery has an internal resistance setting for exactly this effect.",
        ["learn.project.circuitElements.slide2.caption"] = "The three sources available in the Lab.",
        ["learn.project.circuitElements.slide2.fig.l1"] = "Battery",
        ["learn.project.circuitElements.slide2.fig.l2"] = "AC source",
        ["learn.project.circuitElements.slide2.fig.l3"] = "Pulse source",
        ["learn.project.circuitElements.slide3.title"] = "Passive parts",
        ["learn.project.circuitElements.slide3.p1"] = "A resistor limits current. A capacitor stores charge and blocks steady direct current. An inductor stores energy in a magnetic field and resists any change in current.",
        ["learn.project.circuitElements.slide3.p2"] = "None of these parts add energy to the circuit. They only shape how the energy from the source is used.",
        ["learn.project.circuitElements.slide3.p3"] = "Capacitors and inductors only matter when something changes. In a steady DC circuit a capacitor behaves like an open gap and an inductor like a plain wire. Their real role appears in the RC and AC lessons.",
        ["learn.project.circuitElements.slide3.caption"] = "Ohms, farads and henries.",
        ["learn.project.circuitElements.slide3.fig.l1"] = "Resistor",
        ["learn.project.circuitElements.slide3.fig.l2"] = "Capacitor",
        ["learn.project.circuitElements.slide3.fig.l3"] = "Inductor",
        ["learn.project.circuitElements.slide4.title"] = "Semiconductors",
        ["learn.project.circuitElements.slide4.p1"] = "A diode is a one-way valve. Current flows from the anode to the cathode, the side with the bar, and the diode costs about 0.7 V to keep open. An LED is a diode that emits light and drops about 2 V.",
        ["learn.project.circuitElements.slide4.p2"] = "Transistors are controllable valves. A small signal at one pin switches a much larger current between the other two. You will meet the BJT and the MOSFET later in the course.",
        ["learn.project.circuitElements.slide4.p3"] = "The transistor is the reason electronics exists at all. Every chip in a phone contains billions of them, each working as a tiny switch. Here you start with a single one driving an LED.",
        ["learn.project.circuitElements.slide4.caption"] = "One-way parts and electronic switches.",
        ["learn.project.circuitElements.slide4.fig.l1"] = "Diode",
        ["learn.project.circuitElements.slide4.fig.l2"] = "LED",
        ["learn.project.circuitElements.slide4.fig.l3"] = "NPN transistor",
        ["learn.project.circuitElements.slide4.fig.l4"] = "N-MOSFET",
        ["learn.project.circuitElements.slide4.callout"] = "Diode and LED symbols are arrows. Current flows in the direction the arrow points.",
        ["learn.project.circuitElements.slide5.title"] = "Controls and protection",
        ["learn.project.circuitElements.slide5.p1"] = "A switch opens or closes the path. A pushbutton does the same, but only while it is held down. In the Lab you toggle a switch by clicking it.",
        ["learn.project.circuitElements.slide5.p2"] = "A potentiometer is a resistor with a sliding tap, so its resistance can be adjusted. A fuse is a deliberately weak link that melts when the current gets too high.",
        ["learn.project.circuitElements.slide5.p3"] = "A relay is a switch operated by a coil, which lets a small circuit turn a much bigger one on and off. Later lessons use it, and the transistor does the same job with no moving parts.",
        ["learn.project.circuitElements.slide5.caption"] = "Deciding when current flows, and how much.",
        ["learn.project.circuitElements.slide5.fig.l1"] = "Switch",
        ["learn.project.circuitElements.slide5.fig.l2"] = "Pushbutton",
        ["learn.project.circuitElements.slide5.fig.l3"] = "Potentiometer",
        ["learn.project.circuitElements.slide5.fig.l4"] = "Fuse",
        ["learn.project.circuitElements.slide6.title"] = "Wires, dots, ground and meters",
        ["learn.project.circuitElements.slide6.p1"] = "In the Lab, wires are perfect conductors. A dot where lines meet means a connection. Lines that cross without a dot are not connected.",
        ["learn.project.circuitElements.slide6.p2"] = "The ground symbol marks 0 V, and every ground symbol in a drawing is the same node. A voltmeter is connected across two points, an ammeter is inserted into the path.",
        ["learn.project.circuitElements.slide6.p3"] = "Two ground symbols on opposite sides of a drawing are connected even though no wire is drawn between them. This keeps schematics tidy, but it trips up beginners. Remember: every ground is one and the same node.",
        ["learn.project.circuitElements.slide6.caption"] = "The glue of a schematic, plus the two meters.",
        ["learn.project.circuitElements.slide6.fig.l1"] = "Junction",
        ["learn.project.circuitElements.slide6.fig.l2"] = "Ground",
        ["learn.project.circuitElements.slide6.fig.l3"] = "Voltmeter",
        ["learn.project.circuitElements.slide6.fig.l4"] = "Ammeter",
        ["learn.project.circuitElements.slide7.title"] = "Reading a schematic",
        ["learn.project.circuitElements.slide7.p1"] = "A schematic is a map of connections, not a picture of a circuit board. The only thing that matters is which pin is joined to which.",
        ["learn.project.circuitElements.slide7.p2"] = "Parts get names such as R1, D1 or C1, with their values written next to them. Read the drawing the way the current does: start at the positive terminal, follow the path, and make sure you arrive back at the negative one.",
        ["learn.project.circuitElements.slide7.p3"] = "A good habit: before you run anything, trace the loop with your finger. If you cannot get from + back to − without lifting it, the circuit will not work either.",
        ["learn.project.circuitElements.slide7.caption"] = "Names and values sit next to the symbols.",
        ["learn.project.circuitElements.slide8.title"] = "Elements: what to take away",
        ["learn.project.circuitElements.slide8.p1"] = "Your vocabulary of parts.",
        ["learn.project.circuitElements.slide8.fact1"] = "Every circuit has a source, a load, a closed path and usually a control.",
        ["learn.project.circuitElements.slide8.fact2"] = "Sources: battery, AC source, pulse source. The long line on the battery is +.",
        ["learn.project.circuitElements.slide8.fact3"] = "A resistor limits, a capacitor stores charge and blocks DC, an inductor resists change.",
        ["learn.project.circuitElements.slide8.fact4"] = "Diodes and LEDs are arrows. Transistors are controlled valves.",
        ["learn.project.circuitElements.slide8.fact5"] = "Dots connect, crossings do not. All grounds are one node.",
        ["learn.project.seriesParallelCircuits.slide1.title"] = "Two ways to connect parts",
        ["learn.project.seriesParallelCircuits.slide1.p1"] = "Put two parts one after the other and the current has only one path through both of them. That is a series connection.",
        ["learn.project.seriesParallelCircuits.slide1.p2"] = "Give each part its own path from + to − and the current can choose. That is a parallel connection. Most real circuits mix the two.",
        ["learn.project.seriesParallelCircuits.slide1.p3"] = "The words describe how parts are connected, not where they sit on the page. Two resistors drawn side by side are still in series if the current has no choice but to pass through both.",
        ["learn.project.seriesParallelCircuits.slide1.caption"] = "Series: one path, one current.",
        ["learn.project.seriesParallelCircuits.slide2.title"] = "The rules for series",
        ["learn.project.seriesParallelCircuits.slide2.p1"] = "In a series circuit one current flows through everything. The voltage is shared between the parts, and the drops add up to the source voltage. Resistances add.",
        ["learn.project.seriesParallelCircuits.slide2.p2"] = "Two 220 Ω resistors in series behave like a single 440 Ω resistor, so the current is half of what one resistor would allow.",
        ["learn.project.seriesParallelCircuits.slide2.p3"] = "The voltage splits in proportion to the resistances: the larger resistor takes the larger share. A 220 Ω and a 440 Ω resistor in series across 6 V get 2 V and 4 V respectively.",
        ["learn.project.seriesParallelCircuits.slide2.caption"] = "Two equal resistors each take half of the voltage.",
        ["learn.project.seriesParallelCircuits.slide2.callout"] = "R_series = R1 + R2\nU_source = U1 + U2\nthe same I everywhere",
        ["learn.project.seriesParallelCircuits.slide3.title"] = "The rules for parallel",
        ["learn.project.seriesParallelCircuits.slide3.p1"] = "In a parallel circuit every branch sees the full source voltage. Each branch draws its own current, and the source has to supply the sum of them.",
        ["learn.project.seriesParallelCircuits.slide3.p2"] = "The total resistance is lower than that of any single branch. Two equal resistors in parallel give half the resistance of one.",
        ["learn.project.seriesParallelCircuits.slide3.p3"] = "Adding a branch never reduces the current drawn from the source, it only adds to it. That is why plugging too many heaters into one socket trips the breaker: each heater is another parallel path.",
        ["learn.project.seriesParallelCircuits.slide3.caption"] = "The same voltage on each branch; the currents add up.",
        ["learn.project.seriesParallelCircuits.slide3.callout"] = "1 / R_parallel = 1 / R1 + 1 / R2\nI_source = I1 + I2\nthe same U on each branch",
        ["learn.project.seriesParallelCircuits.slide4.title"] = "What happens when a part fails",
        ["learn.project.seriesParallelCircuits.slide4.p1"] = "In a series circuit a single dead part breaks the only path, and everything stops. Old strings of Christmas lights went dark all at once for exactly this reason.",
        ["learn.project.seriesParallelCircuits.slide4.p2"] = "In a parallel circuit each branch is a loop of its own. One LED can fail and the other keeps shining as if nothing had happened.",
        ["learn.project.seriesParallelCircuits.slide4.p3"] = "This is why the wiring in a house is parallel. Every lamp and every socket gets the full 230 V and works independently of the others. Modern LED strings use parallel groups for the same reason.",
        ["learn.project.seriesParallelCircuits.slide4.caption"] = "Parallel LEDs light independently of each other.",
        ["learn.project.seriesParallelCircuits.slide5.title"] = "Mixing both",
        ["learn.project.seriesParallelCircuits.slide5.p1"] = "The Lab example puts a resistor in series with each LED, and then connects the two pairs in parallel.",
        ["learn.project.seriesParallelCircuits.slide5.p2"] = "Inside a branch you use the series rules, between the branches the parallel rules. Simplify a mixed circuit from the inside out.",
        ["learn.project.seriesParallelCircuits.slide5.p3"] = "Each branch here draws about 13 mA, so the battery supplies about 26 mA. Add a third identical branch and the total becomes 39 mA. The LEDs do not notice each other; the battery certainly does.",
        ["learn.project.seriesParallelCircuits.slide5.caption"] = "Each branch is a series pair.",
        ["learn.project.seriesParallelCircuits.slide6.title"] = "A quick test",
        ["learn.project.seriesParallelCircuits.slide6.p1"] = "Series: the only way from one part to the other is a single wire with nothing else attached to it.",
        ["learn.project.seriesParallelCircuits.slide6.p2"] = "Parallel: both ends of both parts sit on the same two nodes. A junction dot is the tell-tale sign.",
        ["learn.project.seriesParallelCircuits.slide6.p3"] = "When in doubt, follow the current from + and ask at every point: does it have a choice? No choice means series. A choice means parallel branches begin here.",
        ["learn.project.seriesParallelCircuits.slide6.caption"] = "A junction means branches.",
        ["learn.project.seriesParallelCircuits.slide6.callout"] = "Same current: series. Same voltage: parallel.",
        ["learn.project.seriesParallelCircuits.slide7.title"] = "Series and parallel: what to take away",
        ["learn.project.seriesParallelCircuits.slide7.p1"] = "The two sets of rules.",
        ["learn.project.seriesParallelCircuits.slide7.fact1"] = "Series: the same current, voltages add, resistances add.",
        ["learn.project.seriesParallelCircuits.slide7.fact2"] = "Parallel: the same voltage, currents add, total resistance goes down.",
        ["learn.project.seriesParallelCircuits.slide7.fact3"] = "A broken part in series stops everything. Parallel branches are independent.",
        ["learn.project.seriesParallelCircuits.slide7.fact4"] = "Mixed circuits: simplify from the inside out.",
        ["learn.project.acDc.slide1.title"] = "Two kinds of current",
        ["learn.project.acDc.slide1.p1"] = "Direct current, DC for short, always flows in the same direction at a steady value. Batteries, USB ports and solar cells all supply DC.",
        ["learn.project.acDc.slide1.p2"] = "Alternating current, AC, reverses its direction many times every second, following a sine wave. This is what comes out of a wall socket.",
        ["learn.project.acDc.slide1.p3"] = "Both kinds carry energy equally well. The difference is in what you can connect to them: LEDs and chips need DC, heaters and many motors accept either, and transformers work only with AC.",
        ["learn.project.acDc.slide1.caption"] = "DC is a flat line. AC crosses zero twice in every cycle.",
        ["learn.project.acDc.slide2.title"] = "Direct current",
        ["learn.project.acDc.slide2.p1"] = "DC has polarity. Turn the battery round and the LED goes dark and a motor spins the other way. Which terminal is which matters.",
        ["learn.project.acDc.slide2.p2"] = "The DC analysis in the Lab assumes that everything has settled down. It gives you one voltage for every node and one current for every part, with nothing changing in time.",
        ["learn.project.acDc.slide2.p3"] = "Even DC is rarely perfectly flat. The output of a charger carries a little ripple, and a battery's voltage sinks as it runs down. DC means that the direction never flips, not that the value never moves.",
        ["learn.project.acDc.slide2.caption"] = "A 5 V supply, the same at every instant.",
        ["learn.project.acDc.slide3.title"] = "Alternating current",
        ["learn.project.acDc.slide3.p1"] = "One complete swing of the wave is a cycle, and its duration is the period T. The number of cycles per second is the frequency f = 1 / T, measured in hertz.",
        ["learn.project.acDc.slide3.p2"] = "The European mains runs at 50 Hz, so one period lasts 20 ms. Audio signals cover roughly 20 Hz to 20 kHz.",
        ["learn.project.acDc.slide3.p3"] = "Frequency is what your ear hears as pitch and what a radio tunes to. The hum you sometimes hear from a transformer or a cheap amplifier is the 50 Hz of the mains.",
        ["learn.project.acDc.slide3.caption"] = "Period T and amplitude Û.",
        ["learn.project.acDc.slide3.callout"] = "f = 1 / T\n50 Hz → T = 20 ms",
        ["learn.project.acDc.slide4.title"] = "Peak value and RMS",
        ["learn.project.acDc.slide4.p1"] = "The peak value Û is the top of the wave. The peak-to-peak value is the whole swing from bottom to top, twice as much.",
        ["learn.project.acDc.slide4.p2"] = "The RMS value is the DC voltage that would heat a resistor by the same amount. For a sine wave U_RMS = Û / √2. When we say \"230 V\" we mean the RMS value; the peak is about 325 V.",
        ["learn.project.acDc.slide4.p3"] = "RMS is the number that matters for power and for safety. A rating of \"12 V AC\" is an RMS value, and the peak is about 17 V. Parts have to survive the peak, not just the RMS value.",
        ["learn.project.acDc.slide4.caption"] = "Peak, RMS at 0.707 of the peak, and the full swing.",
        ["learn.project.acDc.slide4.callout"] = "U_RMS = Û / √2",
        ["learn.project.acDc.slide5.title"] = "Why the grid is AC and gadgets run on DC",
        ["learn.project.acDc.slide5.p1"] = "A transformer can step an AC voltage up or down with almost no loss, but it works only with a changing current. That is why electricity travels across the country at very high voltage and comes down to 230 V in your street.",
        ["learn.project.acDc.slide5.p2"] = "Chips and LEDs need steady DC, so every charger and power supply has to convert the AC from the socket into DC.",
        ["learn.project.acDc.slide5.p3"] = "The power lost in a cable is I² · R. Ten times the voltage means a tenth of the current for the same power, and therefore a hundredth of the loss. That is the whole argument for high-voltage transmission lines.",
        ["learn.project.acDc.slide5.caption"] = "AC for transport, DC at the load.",
        ["learn.project.acDc.slide6.title"] = "From AC to DC",
        ["learn.project.acDc.slide6.p1"] = "A diode lets through only one half of each cycle. Four diodes arranged as a bridge flip the negative halves upward as well. This is called rectification.",
        ["learn.project.acDc.slide6.p2"] = "The result is still bumpy. A capacitor fills in the gaps between the bumps and leaves a much smoother voltage with a small ripple. A regulator then holds the output at a fixed value, for example 5 V.",
        ["learn.project.acDc.slide6.p3"] = "Open any USB charger and you will find exactly these stages: a rectifier, a capacitor and a regulator, usually a switching one. The power module of this course builds each of them.",
        ["learn.project.acDc.slide6.caption"] = "Rectified bumps and the smoothed output.",
        ["learn.project.acDc.slide7.title"] = "AC in the Lab",
        ["learn.project.acDc.slide7.p1"] = "Place an AC source, set its frequency and run the AC analysis. Every node then gets a magnitude and a phase instead of a single voltage.",
        ["learn.project.acDc.slide7.p2"] = "Capacitors block DC but let AC through, and the higher the frequency, the more easily. Filters are built on exactly this behaviour, and the filters module takes it further.",
        ["learn.project.acDc.slide7.p3"] = "The AC analysis assumes a pure sine wave at one frequency and reports how the circuit responds to it. To see the actual shape of the wave over time, use the Transient analysis instead.",
        ["learn.project.acDc.slide7.caption"] = "The AC RC example.",
        ["learn.project.acDc.slide7.fig.l1"] = "AC source",
        ["learn.project.acDc.slide7.fig.l2"] = "Resistor",
        ["learn.project.acDc.slide7.fig.l3"] = "Capacitor",
        ["learn.project.acDc.slide7.fig.l4"] = "Ground",
        ["learn.project.acDc.slide8.title"] = "AC and DC: what to take away",
        ["learn.project.acDc.slide8.p1"] = "The essentials.",
        ["learn.project.acDc.slide8.fact1"] = "DC flows in one direction at a steady value and has polarity.",
        ["learn.project.acDc.slide8.fact2"] = "AC is a sine wave. f = 1 / T. The mains is 50 or 60 Hz.",
        ["learn.project.acDc.slide8.fact3"] = "AC is described by its peak or its RMS value. U_RMS = Û / √2, and \"230 V\" is RMS.",
        ["learn.project.acDc.slide8.fact4"] = "The grid uses AC because of transformers. Electronics runs on DC.",
        ["learn.project.acDc.slide8.fact5"] = "Diodes rectify, capacitors smooth, regulators hold the value.",
        ["learn.project.fundamentalsLoop.slide1.title"] = "One path out, one path back",
        ["learn.project.fundamentalsLoop.slide1.p1"] = "This is the smallest useful circuit: a battery, a resistor, an LED and a return to ground. Current leaves the positive terminal, passes through every part in turn and comes back to the negative terminal.",
        ["learn.project.fundamentalsLoop.slide1.p2"] = "Every part sits on that single path. Take any one of them out and there is no circuit any more.",
        ["learn.project.fundamentalsLoop.slide1.p3"] = "The order of the parts along the path does not matter for the current. Put the resistor before the LED or after it, the same 12.5 mA flows either way.",
        ["learn.project.fundamentalsLoop.slide1.caption"] = "The moving dashes show the single current going round the loop.",
        ["learn.project.fundamentalsLoop.slide2.title"] = "Break it anywhere",
        ["learn.project.fundamentalsLoop.slide2.p1"] = "Open the switch, pull out a wire or burn the LED, and the current stops everywhere at the same moment, not just at the break.",
        ["learn.project.fundamentalsLoop.slide2.p2"] = "Ground is part of the loop too. Without the return wire nothing lights up, even though the battery is still in place.",
        ["learn.project.fundamentalsLoop.slide2.p3"] = "A break is simply a very large resistance. Ohm's law with an enormous R gives a current of practically zero, and that is exactly what you see on every wire.",
        ["learn.project.fundamentalsLoop.slide2.caption"] = "One gap, zero current.",
        ["learn.project.fundamentalsLoop.slide3.title"] = "Reading the labels",
        ["learn.project.fundamentalsLoop.slide3.p1"] = "After you run the DC analysis, every node shows its voltage relative to ground and every part shows the current flowing through it.",
        ["learn.project.fundamentalsLoop.slide3.p2"] = "The battery, the resistor and the LED all show the same current, because there is only one path. The node voltages step down from 5 V to 0 V as you go round the loop.",
        ["learn.project.fundamentalsLoop.slide3.p3"] = "The voltage labels only make sense relative to ground. If the ground symbol is missing, the Lab has no zero to measure from, and it will tell you so.",
        ["learn.project.fundamentalsLoop.slide3.caption"] = "5 V in, 2.75 V across R1, 2.25 V across D1, 0 V at ground.",
        ["learn.project.fundamentalsLoop.slide4.title"] = "Now build it",
        ["learn.project.fundamentalsLoop.slide4.p1"] = "In the Lab:",
        ["learn.project.fundamentalsLoop.slide4.fact1"] = "Place a battery, a resistor, an LED and a ground symbol. Wire + → R → LED → ground, and ground back to −.",
        ["learn.project.fundamentalsLoop.slide4.fact2"] = "Run the DC analysis. The LED should light and show about 12.5 mA.",
        ["learn.project.fundamentalsLoop.slide4.fact3"] = "Probe the node between the resistor and the LED. It sits near 2.25 V.",
        ["learn.project.fundamentalsLoop.slide4.fact4"] = "Delete one wire and run again. Everything stops.",
        ["learn.project.led.slide1.title"] = "Why the resistor?",
        ["learn.project.led.slide1.p1"] = "An LED connected straight across a battery has nothing to limit the current. It draws far more than it can handle and burns out within moments.",
        ["learn.project.led.slide1.p2"] = "A resistor in series turns a fixed voltage into a safe and predictable current. That is its only job here, and it is an essential one.",
        ["learn.project.led.slide1.p3"] = "Think of the LED as the part that fixes the voltage and the resistor as the part that fixes the current. Neither of them can do the other's job.",
        ["learn.project.led.slide1.caption"] = "Too little resistance: 40 mA and a dead LED.",
        ["learn.project.led.slide1.callout"] = "Never connect an LED straight across a supply.",
        ["learn.project.led.slide2.title"] = "The LED takes 2 V",
        ["learn.project.led.slide2.p1"] = "A lit LED holds roughly 2 V across itself almost regardless of the current. The resistor takes whatever is left of the supply voltage.",
        ["learn.project.led.slide2.p2"] = "With a 5 V supply that leaves 3 V for the resistor. Those 3 V together with the resistance R set the current.",
        ["learn.project.led.slide2.p3"] = "The exact LED voltage depends on the colour. Red sits around 1.8 to 2 V, green and blue around 3 V. A blue LED on 5 V leaves only 2 V for the resistor, so it needs a smaller resistor for the same current.",
        ["learn.project.led.slide2.caption"] = "About 2 V across the LED, the rest across R1.",
        ["learn.project.led.slide3.title"] = "Choosing the value",
        ["learn.project.led.slide3.p1"] = "Pick a current, say 15 mA. Then R = (5 − 2) V / 0.015 A = 200 Ω. Round up to the standard value of 220 Ω.",
        ["learn.project.led.slide3.p2"] = "A smaller resistor gives a brighter LED, right up to the point where the LED cooks. A larger one gives a dimmer LED and a longer life.",
        ["learn.project.led.slide3.p3"] = "Resistors come in standard steps: 100, 150, 220, 330, 470, 680 Ω and so on. Pick the nearest value above the one you calculated.",
        ["learn.project.led.slide3.caption"] = "R = U / I, using the resistor's share of the voltage.",
        ["learn.project.led.slide3.callout"] = "R = (U_supply − U_LED) / I",
        ["learn.project.led.slide4.title"] = "Build it",
        ["learn.project.led.slide4.p1"] = "In the Lab:",
        ["learn.project.led.slide4.fact1"] = "Battery, resistor, LED, ground. At least four wires.",
        ["learn.project.led.slide4.fact2"] = "Run the DC analysis. The LED conducts and stays healthy.",
        ["learn.project.led.slide4.fact3"] = "Lower R1 step by step. Watch the brightness rise, then the burn-out at about 35 mA.",
        ["learn.project.led.slide4.fact4"] = "Replace the LED and set R1 back to 220 Ω.",
        ["learn.project.diodeDirection.slide1.title"] = "A one-way valve",
        ["learn.project.diodeDirection.slide1.p1"] = "A diode lets current through in one direction and blocks it in the other. Its symbol is an arrow: current flows the way the arrow points, from the anode to the cathode, which is the side with the bar.",
        ["learn.project.diodeDirection.slide1.p2"] = "An LED is a diode too, so its orientation matters just as much.",
        ["learn.project.diodeDirection.slide1.p3"] = "On a real part the cathode is marked: a stripe on a diode, the shorter leg or a flat edge on an LED. In the Lab, rotate the symbol until the bar points to where the current should end up.",
        ["learn.project.diodeDirection.slide1.caption"] = "Anode on the flat side, cathode at the bar.",
        ["learn.project.diodeDirection.slide1.fig.l1"] = "Diode",
        ["learn.project.diodeDirection.slide1.fig.l2"] = "LED",
        ["learn.project.diodeDirection.slide2.title"] = "Forward: the diode conducts",
        ["learn.project.diodeDirection.slide2.p1"] = "With the anode towards the positive side the diode opens. Keeping it open costs about 0.7 V for an ordinary diode and about 2 V for an LED.",
        ["learn.project.diodeDirection.slide2.p2"] = "The rest of the loop behaves as usual and the LED lights.",
        ["learn.project.diodeDirection.slide2.p3"] = "Those 0.7 V or 2 V are lost as heat inside the part. It is not much, but it has to be subtracted from the supply before you work out the resistor.",
        ["learn.project.diodeDirection.slide2.caption"] = "Forward biased. Current flows and the LED is on.",
        ["learn.project.diodeDirection.slide3.title"] = "Reverse: the diode blocks",
        ["learn.project.diodeDirection.slide3.p1"] = "Turn the diode round and almost nothing flows. The whole supply voltage now sits across the diode and the LED stays dark.",
        ["learn.project.diodeDirection.slide3.p2"] = "This is not a fault. It is the diode doing exactly what it is for.",
        ["learn.project.diodeDirection.slide3.p3"] = "Reverse bias has a limit. Push a real diode far enough backwards and it breaks down. Small signal diodes withstand tens of volts, and nothing in this course comes close to that.",
        ["learn.project.diodeDirection.slide3.caption"] = "Reverse biased. No current anywhere.",
        ["learn.project.diodeDirection.slide4.title"] = "Try both ways",
        ["learn.project.diodeDirection.slide4.p1"] = "In the Lab:",
        ["learn.project.diodeDirection.slide4.fact1"] = "Run the diode example as given. The LED lights.",
        ["learn.project.diodeDirection.slide4.fact2"] = "Select D1 and rotate it twice (180°). Run again. Dark.",
        ["learn.project.diodeDirection.slide4.fact3"] = "Probe the node before the diode: the full voltage is waiting there.",
        ["learn.project.diodeDirection.slide4.fact4"] = "Rotate it back. It works again.",
        ["learn.project.seriesLeds.slide1.title"] = "One string",
        ["learn.project.seriesLeds.slide1.p1"] = "Two LEDs and a resistor in a single line. There is one path, so one and the same current runs through everything.",
        ["learn.project.seriesLeds.slide1.p2"] = "The same current means the LEDs share the same brightness.",
        ["learn.project.seriesLeds.slide1.p3"] = "A series string is the usual way to run several LEDs from one resistor. One resistor, one current, and every LED in the string is equally bright.",
        ["learn.project.seriesLeds.slide1.caption"] = "LEDs in series: one current.",
        ["learn.project.seriesLeds.slide2.title"] = "The drops add up",
        ["learn.project.seriesLeds.slide2.p1"] = "Each LED takes about 2 V. Two of them take 4 V before the resistor gets anything at all.",
        ["learn.project.seriesLeds.slide2.p2"] = "That is why this example uses a 9 V battery. With 5 V there would be only 1 V left for the resistor and very little current would flow.",
        ["learn.project.seriesLeds.slide2.p3"] = "The supply has to exceed the sum of the LED voltages with some room to spare for the resistor. Three 2 V LEDs want at least about 8 V to leave a comfortable margin.",
        ["learn.project.seriesLeds.slide2.caption"] = "9 V = 2 V + 2 V + the resistor's 5 V.",
        ["learn.project.seriesLeds.slide2.callout"] = "I = (9 − 2 − 2) V / 470 Ω ≈ 10.6 mA",
        ["learn.project.seriesLeds.slide3.title"] = "Try it",
        ["learn.project.seriesLeds.slide3.p1"] = "In the Lab:",
        ["learn.project.seriesLeds.slide3.fact1"] = "Run the series LEDs example. Both LEDs show the same current.",
        ["learn.project.seriesLeds.slide3.fact2"] = "Change the battery to 5 V and run again. Watch the current collapse.",
        ["learn.project.seriesLeds.slide3.fact3"] = "Back to 9 V. Add a third LED and see the current drop again.",
        ["learn.project.ledBurnLimit.slide1.title"] = "What \"too much\" means",
        ["learn.project.ledBurnLimit.slide1.p1"] = "Up to about 20 mA a Lab LED is bright and perfectly happy. Above that it is overloaded. Above roughly 35 mA it burns out and stays dead until you replace it.",
        ["learn.project.ledBurnLimit.slide1.p2"] = "Real LEDs behave the same way, just a little less dramatically.",
        ["learn.project.ledBurnLimit.slide1.p3"] = "Datasheets call the safe value the continuous forward current, usually 20 mA for small LEDs. The absolute maximum listed above it is meant for short pulses, not for everyday use.",
        ["learn.project.ledBurnLimit.slide1.caption"] = "Green is comfortable, red is gone.",
        ["learn.project.ledBurnLimit.slide2.title"] = "What 40 mA looks like",
        ["learn.project.ledBurnLimit.slide2.p1"] = "With too small a resistor the LED flares briefly and then fails open. The whole loop goes dead along with it.",
        ["learn.project.ledBurnLimit.slide2.p2"] = "In the Lab the part turns into a burnt symbol. Use Replace LED to get a fresh one.",
        ["learn.project.ledBurnLimit.slide2.p3"] = "A burnt LED fails open, so the entire series loop dies with it. That is the one upside of the failure: the resistor and the battery are left unharmed.",
        ["learn.project.ledBurnLimit.slide2.caption"] = "An overdriven LED at 40 mA.",
        ["learn.project.ledBurnLimit.slide3.title"] = "Heat is the killer",
        ["learn.project.ledBurnLimit.slide3.p1"] = "Power is voltage times current. Double the current and the heat produced inside the LED chip roughly doubles as well.",
        ["learn.project.ledBurnLimit.slide3.p2"] = "A safe design keeps the LED at 10 to 20 mA and leaves the resistor well below its power rating.",
        ["learn.project.ledBurnLimit.slide3.p3"] = "LEDs also age faster when they run hot. A lamp designed for 15 mA lasts far longer than the same LED pushed to 25 mA, even though both work fine on the first day.",
        ["learn.project.ledBurnLimit.slide3.caption"] = "Keep both the LED and the resistor cool.",
        ["learn.project.ledBurnLimit.slide4.title"] = "Try it, then fix it",
        ["learn.project.ledBurnLimit.slide4.p1"] = "In the Lab:",
        ["learn.project.ledBurnLimit.slide4.fact1"] = "Lower R1 until the LED burns. Note the current at which it happens.",
        ["learn.project.ledBurnLimit.slide4.fact2"] = "Replace the LED.",
        ["learn.project.ledBurnLimit.slide4.fact3"] = "Pick a resistor that keeps the current below 25 mA and run again.",
        ["learn.project.rc.slide1.title"] = "A capacitor stores charge",
        ["learn.project.rc.slide1.p1"] = "A capacitor is two plates with a gap between them. Apply a voltage and charge piles up on the plates. The more charge they hold, the higher the voltage across them.",
        ["learn.project.rc.slide1.p2"] = "Capacitance, measured in farads, says how much charge the capacitor stores per volt. A value of 1 µF is typical for small circuits.",
        ["learn.project.rc.slide1.p3"] = "Capacitors range from picofarads in radios to thousands of microfarads in power supplies. A larger value means more charge at the same voltage, and more time to fill it through the same resistor.",
        ["learn.project.rc.slide1.caption"] = "The parts of the RC example.",
        ["learn.project.rc.slide1.fig.l1"] = "Battery",
        ["learn.project.rc.slide1.fig.l2"] = "Resistor",
        ["learn.project.rc.slide1.fig.l3"] = "Capacitor",
        ["learn.project.rc.slide2.title"] = "Charging through a resistor",
        ["learn.project.rc.slide2.p1"] = "Connect the battery through a resistor and the capacitor starts to fill up. At first the current is large. As the capacitor voltage rises, less voltage is left for the resistor, and so the current shrinks.",
        ["learn.project.rc.slide2.p2"] = "The filling therefore slows down as it goes. The last part of the climb takes much longer than the first.",
        ["learn.project.rc.slide2.p3"] = "The current is not one fixed number here. It starts at U / R, as if the capacitor were a short circuit, and fades towards zero as the capacitor voltage approaches the battery voltage.",
        ["learn.project.rc.slide2.caption"] = "Current flows only while the capacitor is still charging.",
        ["learn.project.rc.slide3.title"] = "The time constant",
        ["learn.project.rc.slide3.p1"] = "The time constant is τ = R · C. With 1 kΩ and 1 µF, τ = 1 ms. After one τ the capacitor has reached 63 % of its final voltage, and after 5τ it is practically full.",
        ["learn.project.rc.slide3.p2"] = "A bigger resistor or a bigger capacitor means slower charging, because either one stretches τ.",
        ["learn.project.rc.slide3.p3"] = "τ is a rule of thumb you can use without a calculator. Double R or double C and the whole curve stretches to twice the width. It governs every RC delay, filter and timer in the later lessons.",
        ["learn.project.rc.slide3.caption"] = "The charging curve. 63 % at τ, done by 5τ.",
        ["learn.project.rc.slide3.callout"] = "τ = R · C\n1 kΩ · 1 µF = 1 ms",
        ["learn.project.rc.slide4.title"] = "Reading τ off the scope",
        ["learn.project.rc.slide4.p1"] = "Find the point where the capacitor voltage reaches 63 % of its final value. The time it took to get there is one τ. For a 5 V supply that point is at 3.15 V.",
        ["learn.project.rc.slide4.p2"] = "After 3τ the voltage is at 95 %, after 5τ at 99 %. Engineers call 5τ fully charged.",
        ["learn.project.rc.slide4.p3"] = "Discharging follows the same rule in reverse. After one τ the capacitor has lost 63 % of its voltage and still holds 37 %. The shape is the mirror image of the charging curve.",
        ["learn.project.rc.slide4.caption"] = "Each τ closes 63 % of the remaining gap.",
        ["learn.project.rc.slide4.callout"] = "1τ → 63 %\n3τ → 95 %\n5τ → 99 %",
        ["learn.project.rc.slide5.title"] = "Watch it happen",
        ["learn.project.rc.slide5.p1"] = "In the Lab:",
        ["learn.project.rc.slide5.fact1"] = "First work out τ = R · C from the part values.",
        ["learn.project.rc.slide5.fact2"] = "Open the RC example. Switch to Transient and run.",
        ["learn.project.rc.slide5.fact3"] = "Hover over the scope near 63 % of the final voltage and compare the time with your estimate.",
        ["learn.project.rc.slide5.fact4"] = "Change C to 10 µF and run again. Ten times slower.",
        ["learn.project.ledFade.slide1.title"] = "Store first",
        ["learn.project.ledFade.slide1.p1"] = "With the switch closed, the battery charges a large capacitor. The LED lights from the same supply at the same time.",
        ["learn.project.ledFade.slide1.p2"] = "Once charged, the capacitor is a small reservoir of energy sitting next to the LED.",
        ["learn.project.ledFade.slide1.p3"] = "A capacitor of a few hundred microfarads holds a noticeable amount of energy at 5 V. Enough to keep an LED glowing for a moment, not enough to run anything for long.",
        ["learn.project.ledFade.slide1.caption"] = "Charging: the capacitor fills while the switch is closed.",
        ["learn.project.ledFade.slide2.title"] = "Then release",
        ["learn.project.ledFade.slide2.p1"] = "Open the switch. The battery is out of the picture, but the capacitor still holds its voltage and keeps pushing current through the resistor and the LED.",
        ["learn.project.ledFade.slide2.p2"] = "Its voltage falls along a discharge curve with the same time constant τ = R · C as before.",
        ["learn.project.ledFade.slide2.p3"] = "The discharge resistor here is the LED resistor. A smaller R drains the capacitor faster and the fade gets shorter; a bigger R stretches it out.",
        ["learn.project.ledFade.slide2.caption"] = "Discharge: down to 37 % after one τ.",
        ["learn.project.ledFade.slide3.title"] = "Why it fades",
        ["learn.project.ledFade.slide3.p1"] = "The LED current follows the capacitor voltage minus the LED's 2 V. As the voltage sinks, the current shrinks and the LED grows dimmer.",
        ["learn.project.ledFade.slide3.p2"] = "Once the capacitor drops below about 2 V the LED goes out completely, even though some charge is still left in it.",
        ["learn.project.ledFade.slide3.p3"] = "This is why the LEDs in some devices linger for a moment after you switch them off. A capacitor somewhere inside is still emptying through them.",
        ["learn.project.ledFade.slide3.caption"] = "The current slides down the scale as the capacitor empties.",
        ["learn.project.ledFade.slide4.title"] = "Try it",
        ["learn.project.ledFade.slide4.p1"] = "In the Lab:",
        ["learn.project.ledFade.slide4.fact1"] = "Run with the switch closed. The capacitor charges.",
        ["learn.project.ledFade.slide4.fact2"] = "Untick Closed and run again. Watch the LED fade.",
        ["learn.project.ledFade.slide4.fact3"] = "Change C to 470 µF. The fade gets much shorter.",
        ["learn.project.pulseRc.slide1.title"] = "Edges get rounded off",
        ["learn.project.pulseRc.slide1.p1"] = "A pulse source jumps between 0 and 5 V. Feed that into a resistor and a capacitor and the output cannot jump with it. It charges up and drains down along RC curves instead.",
        ["learn.project.pulseRc.slide1.p2"] = "Sharp edges go in, rounded edges come out.",
        ["learn.project.pulseRc.slide1.p3"] = "The output follows the same τ = R · C as in the DC RC example. The only difference is that the input keeps changing before the capacitor has finished.",
        ["learn.project.pulseRc.slide1.caption"] = "A square pulse in, a rounded response out.",
        ["learn.project.pulseRc.slide2.title"] = "Pulse width against τ",
        ["learn.project.pulseRc.slide2.p1"] = "If the pulse lasts much longer than τ, the output reaches the top before the pulse ends. If the pulse is shorter than τ, the output never gets there.",
        ["learn.project.pulseRc.slide2.p2"] = "That is the whole idea behind RC delays and simple filters.",
        ["learn.project.pulseRc.slide2.p3"] = "Filters work on exactly this principle. A signal that changes much faster than τ barely gets through, while a slow one passes almost untouched.",
        ["learn.project.pulseRc.slide2.caption"] = "A 4 ms pulse with τ = 1 ms gets to about 98 %.",
        ["learn.project.pulseRc.slide2.callout"] = "τ = 1 kΩ · 1 µF = 1 ms",
        ["learn.project.pulseRc.slide3.title"] = "Try it",
        ["learn.project.pulseRc.slide3.p1"] = "In the Lab:",
        ["learn.project.pulseRc.slide3.fact1"] = "Run the pulse example in Transient. Compare the input and output traces.",
        ["learn.project.pulseRc.slide3.fact2"] = "Shorten the pulse width to 0.5 ms and run again. The output stays low.",
        ["learn.project.pulseRc.slide3.fact3"] = "Change C to 0.1 µF. The edges get sharp again.",
        ["learn.project.basicsFinal.slide1.title"] = "What this group covered",
        ["learn.project.basicsFinal.slide1.p1"] = "A quick recap before the questions.",
        ["learn.project.basicsFinal.slide1.fact1"] = "Voltage is the push, measured between two points. Ground is 0 V.",
        ["learn.project.basicsFinal.slide1.fact2"] = "Current is the flow, measured in the path. It needs a closed loop.",
        ["learn.project.basicsFinal.slide1.fact3"] = "Resistance limits the current. U = I · R.",
        ["learn.project.basicsFinal.slide1.fact4"] = "Series: one current, the drops add up. Parallel: one voltage, the currents add up.",
        ["learn.project.basicsFinal.slide1.fact5"] = "DC is steady and has polarity. AC swings, and \"230 V\" is an RMS value.",
        ["learn.project.basicsFinal.slide1.fact6"] = "An LED takes about 2 V and needs a resistor. An RC circuit charges with τ = R · C.",
        ["learn.project.basicsFinal.slide2.title"] = "How the final quiz works",
        ["learn.project.basicsFinal.slide2.p1"] = "Ten questions drawn from everything above. You need eight correct answers to pass.",
        ["learn.project.basicsFinal.slide2.p2"] = "After every attempt you see which answers were wrong and why. You can retry as often as you like.",
        ["learn.project.basicsFinal.slide2.callout"] = "Stuck on a question? Go back to that lesson. The slides are short.",
        ["learn.project.basicsFinal.quiz.q1.prompt"] = "A 9 V battery is on the shelf with nothing connected. What is true?",
        ["learn.project.basicsFinal.quiz.q1.a"] = "There is current but no voltage.",
        ["learn.project.basicsFinal.quiz.q1.b"] = "There is voltage but no current.",
        ["learn.project.basicsFinal.quiz.q1.c"] = "There is neither.",
        ["learn.project.basicsFinal.quiz.q1.explain"] = "Voltage is a potential difference between the terminals. Current needs a closed path.",
        ["learn.project.basicsFinal.quiz.q2.prompt"] = "What does an ammeter measure, and how is it connected?",
        ["learn.project.basicsFinal.quiz.q2.a"] = "Voltage, in parallel.",
        ["learn.project.basicsFinal.quiz.q2.b"] = "Resistance, across the part.",
        ["learn.project.basicsFinal.quiz.q2.c"] = "Current, in series with the path.",
        ["learn.project.basicsFinal.quiz.q2.explain"] = "Current has to pass through the meter, so it sits in the path.",
        ["learn.project.basicsFinal.quiz.q3.prompt"] = "5 V supply, an LED that takes 2 V, and a 220 Ω resistor. Roughly what current flows?",
        ["learn.project.basicsFinal.quiz.q3.a"] = "About 14 mA",
        ["learn.project.basicsFinal.quiz.q3.b"] = "About 23 mA",
        ["learn.project.basicsFinal.quiz.q3.c"] = "About 2 mA",
        ["learn.project.basicsFinal.quiz.q3.explain"] = "The resistor sees 3 V. 3 V / 220 Ω ≈ 13.6 mA.",
        ["learn.project.basicsFinal.quiz.q4.prompt"] = "You double the resistance and keep the voltage. The current…",
        ["learn.project.basicsFinal.quiz.q4.a"] = "doubles.",
        ["learn.project.basicsFinal.quiz.q4.b"] = "halves.",
        ["learn.project.basicsFinal.quiz.q4.c"] = "stays the same.",
        ["learn.project.basicsFinal.quiz.q4.explain"] = "I = U / R. Twice the R, half the I.",
        ["learn.project.basicsFinal.quiz.q5.prompt"] = "Two 470 Ω resistors in series act like…",
        ["learn.project.basicsFinal.quiz.q5.a"] = "235 Ω",
        ["learn.project.basicsFinal.quiz.q5.b"] = "470 Ω",
        ["learn.project.basicsFinal.quiz.q5.c"] = "940 Ω",
        ["learn.project.basicsFinal.quiz.q5.explain"] = "Series resistances add.",
        ["learn.project.basicsFinal.quiz.q6.prompt"] = "Two LEDs sit in parallel on a 5 V rail. One burns out. The other…",
        ["learn.project.basicsFinal.quiz.q6.a"] = "keeps shining as before.",
        ["learn.project.basicsFinal.quiz.q6.b"] = "goes dark too.",
        ["learn.project.basicsFinal.quiz.q6.c"] = "gets brighter.",
        ["learn.project.basicsFinal.quiz.q6.explain"] = "Each parallel branch is its own loop with the same 5 V across it.",
        ["learn.project.basicsFinal.quiz.q7.prompt"] = "Which statement about ground is right?",
        ["learn.project.basicsFinal.quiz.q7.a"] = "Ground is where current disappears.",
        ["learn.project.basicsFinal.quiz.q7.b"] = "Ground is the agreed 0 V reference point.",
        ["learn.project.basicsFinal.quiz.q7.c"] = "Ground always carries the most current.",
        ["learn.project.basicsFinal.quiz.q7.explain"] = "All node voltages are measured against ground. It is a reference, nothing more.",
        ["learn.project.basicsFinal.quiz.q8.prompt"] = "Mains in Europe is \"230 V, 50 Hz\". The 230 V is…",
        ["learn.project.basicsFinal.quiz.q8.a"] = "an RMS value.",
        ["learn.project.basicsFinal.quiz.q8.b"] = "the peak value.",
        ["learn.project.basicsFinal.quiz.q8.c"] = "the peak-to-peak value.",
        ["learn.project.basicsFinal.quiz.q8.explain"] = "RMS is the heating-equivalent DC value. The peak is about 325 V.",
        ["learn.project.basicsFinal.quiz.q9.prompt"] = "On a schematic, two lines cross without a dot. They are…",
        ["learn.project.basicsFinal.quiz.q9.a"] = "connected.",
        ["learn.project.basicsFinal.quiz.q9.b"] = "connected if both are wires.",
        ["learn.project.basicsFinal.quiz.q9.c"] = "not connected.",
        ["learn.project.basicsFinal.quiz.q9.explain"] = "Only a junction dot means a connection.",
        ["learn.project.basicsFinal.quiz.q10.prompt"] = "An LED in the Lab is running at 40 mA. What happens?",
        ["learn.project.basicsFinal.quiz.q10.a"] = "It dims slightly.",
        ["learn.project.basicsFinal.quiz.q10.b"] = "It overheats and burns out.",
        ["learn.project.basicsFinal.quiz.q10.c"] = "Nothing, LEDs have no limit.",
        ["learn.project.basicsFinal.quiz.q10.explain"] = "Lab LEDs are healthy up to about 20 mA and burn above roughly 35 mA.",
        ["learn.project.led.lesson1.title"] = "Why a resistor?",
        ["learn.project.led.lesson1.body"] = "An LED needs a current-limiting resistor in series. Without it, too much current flows and the teaching model may show burnout.",
        ["learn.project.led.lesson2.title"] = "Brightness vs current",
        ["learn.project.led.lesson2.body"] = "Lower series resistance → more current → brighter LED (until overload). This is Ohm’s law in a one-loop circuit.",
        ["learn.project.led.quiz.q1.prompt"] = "What does the series resistor mainly do?",
        ["learn.project.led.quiz.q1.a"] = "Limits LED current",
        ["learn.project.led.quiz.q1.b"] = "Stores charge",
        ["learn.project.led.quiz.q1.c"] = "Boosts voltage",
        ["learn.project.led.quiz.q1.explain"] = "It drops voltage so only a safe current reaches the LED.",
        ["learn.project.led.quiz.q2.prompt"] = "You decrease R1. What usually happens to LED current?",
        ["learn.project.led.quiz.q2.a"] = "It falls",
        ["learn.project.led.quiz.q2.b"] = "It rises",
        ["learn.project.led.quiz.q2.c"] = "It stays exactly the same",
        ["learn.project.led.quiz.q2.explain"] = "Less resistance in series allows more current for the same supply.",
        ["learn.project.led.quiz.q3.prompt"] = "Before running in Lab, you should…",
        ["learn.project.led.quiz.q3.a"] = "Skip ground",
        ["learn.project.led.quiz.q3.b"] = "Ignore polarity",
        ["learn.project.led.quiz.q3.c"] = "Confirm supply and return path",
        ["learn.project.led.quiz.q3.explain"] = "Every loop needs a clear return to ground in the teaching model.",
        ["learn.project.led.challenge.c1.label"] = "Run DC with no simulation errors.",
        ["learn.project.led.challenge.c2.label"] = "LED D1 conducts (current above ~1 mA).",
        ["learn.project.rc.lesson1.title"] = "Capacitors charge gradually",
        ["learn.project.rc.lesson1.body"] = "A capacitor cannot jump instantly to the supply voltage. Current through R charges C — the voltage curve is exponential.",
        ["learn.project.rc.lesson2.title"] = "Time constant τ",
        ["learn.project.rc.lesson2.body"] = "τ ≈ R × C sets how fast the curve rises. Double C or R → roughly double the charge time.",
        ["learn.project.rc.quiz.q1.prompt"] = "Larger capacitance usually means…",
        ["learn.project.rc.quiz.q1.a"] = "Slower charging",
        ["learn.project.rc.quiz.q1.b"] = "Faster charging",
        ["learn.project.rc.quiz.q1.c"] = "No change",
        ["learn.project.rc.quiz.q1.explain"] = "More charge to move → longer rise time for the same R.",
        ["learn.project.rc.quiz.q2.prompt"] = "Which analysis shows the charge curve?",
        ["learn.project.rc.quiz.q2.a"] = "DC only",
        ["learn.project.rc.quiz.q2.b"] = "Transient",
        ["learn.project.rc.quiz.q2.c"] = "AC small-signal",
        ["learn.project.rc.quiz.q2.explain"] = "Use Transient to watch voltage vs time.",
        ["learn.project.rc.quiz.q3.prompt"] = "τ doubles when…",
        ["learn.project.rc.quiz.q3.a"] = "R and C both halve",
        ["learn.project.rc.quiz.q3.b"] = "R doubles (C fixed)",
        ["learn.project.rc.quiz.q3.c"] = "Supply doubles",
        ["learn.project.rc.quiz.q3.explain"] = "τ = R×C — scale R or C to stretch time.",
        ["learn.project.rc.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.rc.challenge.c2.label"] = "Use Transient analysis for this unit.",
        ["learn.project.ledFade.lesson1.title"] = "Store and release",
        ["learn.project.ledFade.lesson1.body"] = "The capacitor was charged earlier; now it discharges through a resistor while the LED dims.",
        ["learn.project.ledFade.lesson2.title"] = "Same RC idea",
        ["learn.project.ledFade.lesson2.body"] = "Fade time is still governed by R×C — only the load (LED) changes how you observe it.",
        ["learn.project.ledFade.quiz.q1.prompt"] = "You see the LED dim over seconds because…",
        ["learn.project.ledFade.quiz.q1.a"] = "C discharges through R",
        ["learn.project.ledFade.quiz.q1.b"] = "Battery runs out instantly",
        ["learn.project.ledFade.quiz.q1.c"] = "LED polarity flips",
        ["learn.project.ledFade.quiz.q1.explain"] = "Stored charge leaks through the discharge path.",
        ["learn.project.ledFade.quiz.q2.prompt"] = "To fade slower, you would usually…",
        ["learn.project.ledFade.quiz.q2.a"] = "Shrink C a lot",
        ["learn.project.ledFade.quiz.q2.b"] = "Increase C or discharge R",
        ["learn.project.ledFade.quiz.q2.c"] = "Remove ground",
        ["learn.project.ledFade.quiz.q2.explain"] = "Larger τ → slower voltage fall.",
        ["learn.project.ledFade.quiz.q3.prompt"] = "Best analysis mode here is…",
        ["learn.project.ledFade.quiz.q3.a"] = "DC",
        ["learn.project.ledFade.quiz.q3.b"] = "Transient",
        ["learn.project.ledFade.quiz.q3.c"] = "AC",
        ["learn.project.ledFade.quiz.q3.explain"] = "Watch voltage/current vs time.",
        ["learn.project.ledFade.challenge.c1.label"] = "Run completes cleanly.",
        ["learn.project.ledFade.challenge.c2.label"] = "Use Transient analysis.",
        ["learn.project.bc547.lesson1.title"] = "Transistor as switch",
        ["learn.project.bc547.lesson1.body"] = "A small base current can allow a larger collector current — the BJT routes LED current when driven on.",
        ["learn.project.bc547.lesson2.title"] = "Open vs driven",
        ["learn.project.bc547.lesson2.body"] = "Open base (switch off) → LED off. Driven base with series RB → LED on if the transistor is in saturation.",
        ["learn.project.bc547.quiz.q1.prompt"] = "With S1 open, the LED should be…",
        ["learn.project.bc547.quiz.q1.a"] = "On brightly",
        ["learn.project.bc547.quiz.q1.b"] = "Off",
        ["learn.project.bc547.quiz.q1.c"] = "Random",
        ["learn.project.bc547.quiz.q1.explain"] = "No base drive → transistor off → LED dark.",
        ["learn.project.bc547.quiz.q2.prompt"] = "RB is for…",
        ["learn.project.bc547.quiz.q2.a"] = "Limiting base current",
        ["learn.project.bc547.quiz.q2.b"] = "Boosting supply voltage",
        ["learn.project.bc547.quiz.q2.c"] = "Timing the LED",
        ["learn.project.bc547.quiz.q2.explain"] = "Protects the teaching BJT from excessive base current.",
        ["learn.project.bc547.quiz.q3.prompt"] = "Too little RB can…",
        ["learn.project.bc547.quiz.q3.a"] = "Burn the transistor open",
        ["learn.project.bc547.quiz.q3.b"] = "Charge the capacitor faster only",
        ["learn.project.bc547.quiz.q3.c"] = "Nothing in this model",
        ["learn.project.bc547.quiz.q3.explain"] = "Excessive base current is a teaching failure mode.",
        ["learn.project.bc547.challenge.c1.label"] = "DC simulation succeeds.",
        ["learn.project.bc547.challenge.c2.label"] = "Switch S1 closed (LED on path).",
        ["learn.project.relay.lesson1.title"] = "Coil + contacts",
        ["learn.project.relay.lesson1.body"] = "Energizing the coil pulls contacts closed to switch a separate load (here, an LED).",
        ["learn.project.relay.lesson2.title"] = "Flyback diode",
        ["learn.project.relay.lesson2.body"] = "The diode gives coil current a safe path when the switch opens — inductive kick otherwise spikes voltage.",
        ["learn.project.relay.quiz.q1.prompt"] = "Flyback diode orientation…",
        ["learn.project.relay.quiz.q1.a"] = "Conducts when coil field collapses",
        ["learn.project.relay.quiz.q1.b"] = "Blocks all DC forever",
        ["learn.project.relay.quiz.q1.c"] = "Replaces the coil",
        ["learn.project.relay.quiz.q1.explain"] = "It must conduct reverse energy away from the switch node.",
        ["learn.project.relay.quiz.q2.prompt"] = "With S1 open, the contact LED should be…",
        ["learn.project.relay.quiz.q2.a"] = "On",
        ["learn.project.relay.quiz.q2.b"] = "Off",
        ["learn.project.relay.quiz.q2.c"] = "Always blinking",
        ["learn.project.relay.quiz.q2.explain"] = "No coil current → contacts open.",
        ["learn.project.relay.quiz.q3.prompt"] = "Relay coil is driven from…",
        ["learn.project.relay.quiz.q3.a"] = "The same switch path as in the preset",
        ["learn.project.relay.quiz.q3.b"] = "Only AC analysis",
        ["learn.project.relay.quiz.q3.c"] = "Scope probe",
        ["learn.project.relay.quiz.q3.explain"] = "Follow the preset wiring in Lab.",
        ["learn.project.relay.challenge.c1.label"] = "DC run is clean.",
        ["learn.project.relay.challenge.c2.label"] = "Switch S1 closed so the coil energizes.",
        ["learn.project.nmos.lesson1.title"] = "Gate controls channel",
        ["learn.project.nmos.lesson1.body"] = "NMOS turns on when gate voltage is high enough vs source — here a switch + pull-down set the gate.",
        ["learn.project.nmos.lesson2.title"] = "Pull-down",
        ["learn.project.nmos.lesson2.body"] = "When the switch opens, RPD holds the gate low so the LED turns off reliably.",
        ["learn.project.nmos.quiz.q1.prompt"] = "With S1 open, gate is pulled…",
        ["learn.project.nmos.quiz.q1.a"] = "Low by RPD",
        ["learn.project.nmos.quiz.q1.b"] = "High automatically",
