        ["learn.project.fuseProtect.lesson1.title"] = "Trip on overcurrent",
        ["learn.project.fuseProtect.lesson1.body"] = "The teaching fuse stays low-Ron until |I| exceeds iMax, then opens like a burned-open part.",
        ["learn.project.fuseProtect.lesson2.title"] = "After a trip",
        ["learn.project.fuseProtect.lesson2.body"] = "Replace the fuse — Lab opens closed switches so the new fuse is not instantly overloaded. Fix the fault before closing the short again.",
        ["learn.project.fuseProtect.quiz.q1.prompt"] = "A fuse opens when…",
