        ["learn.project.fuseProtect.quiz.q1.explain"] = "Overcurrent trip.",
        ["learn.project.fuseProtect.quiz.q2.prompt"] = "After burnout you should…",
        ["learn.project.fuseProtect.quiz.q2.a"] = "Replace the fuse",
        ["learn.project.fuseProtect.quiz.q2.b"] = "Wire around it forever",
        ["learn.project.fuseProtect.quiz.q2.c"] = "Remove ground",
