        ["learn.project.fuseProtect.challenge.c2.label"] = "Wiring passes circuit checks.",
        ["learn.project.ripple.lesson1.title"] = "What ripple is",
        ["learn.project.ripple.lesson1.body"] = "Residual AC riding on filtered DC — the droop between rectifier peaks.",
        ["learn.project.ripple.lesson2.title"] = "How to see it",
        ["learn.project.ripple.lesson2.body"] = "Transient + probe on the filter node. Smaller C or heavier load makes ripple easier to spot.",
        ["learn.project.ripple.quiz.q1.prompt"] = "Ripple is…",
        ["learn.project.ripple.quiz.q1.a"] = "AC leftover on DC",
        ["learn.project.ripple.quiz.q1.b"] = "Only DC offset",
        ["learn.project.ripple.quiz.q1.c"] = "Gate threshold",
        ["learn.project.ripple.quiz.q1.explain"] = "Peak-to-peak residual.",
        ["learn.project.ripple.quiz.q2.prompt"] = "Heavier load usually…",
        ["learn.project.ripple.quiz.q2.a"] = "Increases ripple",
        ["learn.project.ripple.quiz.q2.b"] = "Removes diodes",
        ["learn.project.ripple.quiz.q2.c"] = "Stops AC forever",
        ["learn.project.ripple.quiz.q2.explain"] = "Faster discharge between peaks.",
        ["learn.project.ripple.quiz.q3.prompt"] = "Use…",
        ["learn.project.ripple.quiz.q3.a"] = "Transient analysis",
        ["learn.project.ripple.quiz.q3.b"] = "DC only forever",
        ["learn.project.ripple.quiz.q3.c"] = "No probe ever",
        ["learn.project.ripple.quiz.q3.explain"] = "Time-domain view.",
        ["learn.project.ripple.challenge.c1.label"] = "Simulation succeeds.",
        ["learn.project.ripple.challenge.c2.label"] = "Transient analysis is selected.",
        ["learn.project.buck.lesson1.title"] = "Step-down idea",
        ["learn.project.buck.lesson1.body"] = "A high-side switch chops Vin; L and C average the pulses into a lower DC.",
        ["learn.project.buck.lesson2.title"] = "Duty cycle",
        ["learn.project.buck.lesson2.body"] = "Longer on-time (higher duty) raises the average output toward Vin.",
        ["learn.project.buck.quiz.q1.prompt"] = "A buck converter ideally…",
        ["learn.project.buck.quiz.q1.a"] = "Steps voltage down",
        ["learn.project.buck.quiz.q1.b"] = "Always boosts",
        ["learn.project.buck.quiz.q1.c"] = "Removes inductors",
        ["learn.project.buck.quiz.q1.explain"] = "Vout < Vin typically.",
        ["learn.project.buck.quiz.q2.prompt"] = "Higher duty cycle tends to…",
        ["learn.project.buck.quiz.q2.a"] = "Raise average Vout",
        ["learn.project.buck.quiz.q2.b"] = "Guarantee zero current",
        ["learn.project.buck.quiz.q2.c"] = "Open the diode forever",
        ["learn.project.buck.quiz.q2.explain"] = "More on-time → higher average.",
        ["learn.project.buck.quiz.q3.prompt"] = "This sample needs…",
        ["learn.project.buck.quiz.q3.a"] = "Transient (PWM)",
        ["learn.project.buck.quiz.q3.b"] = "DC only",
        ["learn.project.buck.quiz.q3.c"] = "AC phasor only",
        ["learn.project.buck.quiz.q3.explain"] = "Switching is time-domain.",
        ["learn.project.buck.challenge.c1.label"] = "Simulation succeeds.",
        ["learn.project.buck.challenge.c2.label"] = "Transient analysis is selected.",
        ["learn.project.boost.lesson1.title"] = "Step-up idea",
        ["learn.project.boost.lesson1.body"] = "Low-side switch stores energy in L, then the diode delivers it to a higher Vout capacitor.",
        ["learn.project.boost.lesson2.title"] = "Energy per cycle",
        ["learn.project.boost.lesson2.body"] = "Longer on-time stores more inductor energy — Vout can rise above Vin.",
        ["learn.project.boost.quiz.q1.prompt"] = "A boost converter ideally…",
        ["learn.project.boost.quiz.q1.a"] = "Steps voltage up",
        ["learn.project.boost.quiz.q1.b"] = "Always bucks",
        ["learn.project.boost.quiz.q1.c"] = "Needs no diode",
        ["learn.project.boost.quiz.q1.explain"] = "Vout > Vin typically.",
        ["learn.project.boost.quiz.q2.prompt"] = "Inductor energy is stored mainly when…",
        ["learn.project.boost.quiz.q2.a"] = "The switch is on",
        ["learn.project.boost.quiz.q2.b"] = "The fuse opens",
        ["learn.project.boost.quiz.q2.c"] = "Ground floats",
        ["learn.project.boost.quiz.q2.explain"] = "L charges to ground.",
        ["learn.project.boost.quiz.q3.prompt"] = "Analysis mode?",
        ["learn.project.boost.quiz.q3.a"] = "Transient",
        ["learn.project.boost.quiz.q3.b"] = "DC only",
        ["learn.project.boost.quiz.q3.c"] = "AC small-signal only",
        ["learn.project.boost.quiz.q3.explain"] = "PWM needs time.",
        ["learn.project.boost.challenge.c1.label"] = "Simulation succeeds.",
        ["learn.project.boost.challenge.c2.label"] = "Transient analysis is selected.",
        ["learn.project.rcLowPass.lesson1.body"] = "At low f the capacitor is open so Vout ≈ Vin. Above fc ≈ 1/(2πRC) the shunt C shorts AC to ground and |Vout| rolls off ~20 dB/decade.",
        ["learn.project.rcLowPass.lesson2.body"] = "Sensor smoothing, anti-aliasing before ADCs, and simple tone control all start from this topology.",
        ["learn.project.rcLowPass.quiz.q1.prompt"] = "An RC low-pass puts the capacitor…",
        ["learn.project.rcLowPass.quiz.q1.a"] = "Across the output (shunt to return)",
        ["learn.project.rcLowPass.quiz.q1.b"] = "Only in series with the source",
        ["learn.project.rcLowPass.quiz.q1.c"] = "Floating with no ground",
        ["learn.project.rcLowPass.quiz.q1.explain"] = "Series R + shunt C is the classic LPF.",
        ["learn.project.rcLowPass.quiz.q2.prompt"] = "Cutoff frequency scales as…",
        ["learn.project.rcLowPass.quiz.q2.a"] = "RC",
        ["learn.project.rcLowPass.quiz.q2.b"] = "1 / (2πRC)",
        ["learn.project.rcLowPass.quiz.q2.c"] = "2πRC",
        ["learn.project.rcLowPass.quiz.q2.explain"] = "fc = 1/(2πRC) for the first-order RC LPF.",
        ["learn.project.rcLowPass.quiz.q3.prompt"] = "Well above cutoff, |Vout|…",
        ["learn.project.rcLowPass.quiz.q3.a"] = "Equals Vin",
        ["learn.project.rcLowPass.quiz.q3.b"] = "Grows without bound",
        ["learn.project.rcLowPass.quiz.q3.c"] = "Falls as frequency rises",
        ["learn.project.rcLowPass.quiz.q3.explain"] = "The shunt C steals more AC current as f increases.",
        ["learn.project.rcLowPass.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.rcLowPass.challenge.c2.label"] = "Analysis mode is AC.",
        ["learn.project.rcHighPass.lesson1.body"] = "At high f the capacitor is a short so Vout ≈ Vin across R. Near DC the C blocks and |Vout| falls toward zero.",
        ["learn.project.rcHighPass.lesson2.body"] = "AC coupling between stages, removing DC offsets, and simple treble-pass networks.",
        ["learn.project.rcHighPass.quiz.q1.prompt"] = "An RC high-pass puts the capacitor…",
        ["learn.project.rcHighPass.quiz.q1.a"] = "In series with the signal path",
        ["learn.project.rcHighPass.quiz.q1.b"] = "Only as a shunt to ground",
        ["learn.project.rcHighPass.quiz.q1.c"] = "Across the battery",
        ["learn.project.rcHighPass.quiz.q1.explain"] = "Series C + shunt R is the classic HPF.",
        ["learn.project.rcHighPass.quiz.q2.prompt"] = "Near DC, ideal HPF output…",
        ["learn.project.rcHighPass.quiz.q2.a"] = "Equals Vin",
        ["learn.project.rcHighPass.quiz.q2.b"] = "Approaches zero",
        ["learn.project.rcHighPass.quiz.q2.c"] = "Oscillates",
        ["learn.project.rcHighPass.quiz.q2.explain"] = "The series C blocks DC.",
        ["learn.project.rcHighPass.quiz.q3.prompt"] = "Raising C (same R) moves fc…",
        ["learn.project.rcHighPass.quiz.q3.a"] = "Higher",
        ["learn.project.rcHighPass.quiz.q3.b"] = "Nowhere",
        ["learn.project.rcHighPass.quiz.q3.c"] = "Lower",
        ["learn.project.rcHighPass.quiz.q3.explain"] = "fc = 1/(2πRC) — larger C lowers the knee.",
        ["learn.project.rcHighPass.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.rcHighPass.challenge.c2.label"] = "Analysis mode is AC.",
        ["learn.project.rlcSeries.lesson1.body"] = "At fr the inductive and capacitive reactances cancel. Series impedance is near R, so current is largest for a given drive.",
        ["learn.project.rlcSeries.lesson2.body"] = "Filters and tuned tanks are just RLC with different pick-off points — start by feeling the resonance peak.",
        ["learn.project.rlcSeries.quiz.q1.prompt"] = "Series resonance occurs when…",
        ["learn.project.rlcSeries.quiz.q1.a"] = "XL ≈ XC",
        ["learn.project.rlcSeries.quiz.q1.b"] = "R = 0 only",
        ["learn.project.rlcSeries.quiz.q1.c"] = "L = C numerically",
        ["learn.project.rlcSeries.quiz.q1.explain"] = "Reactances cancel; impedance ≈ R.",
        ["learn.project.rlcSeries.quiz.q2.prompt"] = "Resonant frequency scales as…",
        ["learn.project.rlcSeries.quiz.q2.a"] = "LC",
        ["learn.project.rlcSeries.quiz.q2.b"] = "1 / (2π√(LC))",
        ["learn.project.rlcSeries.quiz.q2.c"] = "2πLC",
        ["learn.project.rlcSeries.quiz.q2.explain"] = "fr = 1/(2π√(LC)).",
        ["learn.project.rlcSeries.quiz.q3.prompt"] = "At resonance, series impedance is closest to…",
        ["learn.project.rlcSeries.quiz.q3.a"] = "∞",
        ["learn.project.rlcSeries.quiz.q3.b"] = "jωL only",
        ["learn.project.rlcSeries.quiz.q3.c"] = "R",
        ["learn.project.rlcSeries.quiz.q3.explain"] = "L and C cancel; R remains.",
        ["learn.project.rlcSeries.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.rlcSeries.challenge.c2.label"] = "Analysis mode is AC.",
        ["learn.project.bandPass.lesson1.body"] = "Around resonance the network transfers signal; far off-resonance reactive mismatch attenuates. Bandwidth depends on Q (R vs √(L/C)).",
        ["learn.project.bandPass.lesson2.body"] = "A band-pass needs both a high-side and low-side roll-off — RLC (or cascaded RC) gives that shape.",
        ["learn.project.bandPass.quiz.q1.prompt"] = "A band-pass ideally…",
        ["learn.project.bandPass.quiz.q1.a"] = "Passes a mid band, attenuates ends",
        ["learn.project.bandPass.quiz.q1.b"] = "Only blocks DC",
        ["learn.project.bandPass.quiz.q1.c"] = "Amplifies all frequencies equally",
        ["learn.project.bandPass.quiz.q1.explain"] = "That is the definition of band-pass.",
        ["learn.project.bandPass.quiz.q2.prompt"] = "Center frequency is set mainly by…",
        ["learn.project.bandPass.quiz.q2.a"] = "Only R",
        ["learn.project.bandPass.quiz.q2.b"] = "L and C (resonance)",
        ["learn.project.bandPass.quiz.q2.c"] = "Wire length alone",
        ["learn.project.bandPass.quiz.q2.explain"] = "fr follows the LC product.",
        ["learn.project.bandPass.quiz.q3.prompt"] = "Higher Q usually means…",
        ["learn.project.bandPass.quiz.q3.a"] = "Wider pass band",
        ["learn.project.bandPass.quiz.q3.b"] = "No resonance",
        ["learn.project.bandPass.quiz.q3.c"] = "Narrower peak around fr",
        ["learn.project.bandPass.quiz.q3.explain"] = "Q sharpens the resonance peak.",
        ["learn.project.bandPass.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.bandPass.challenge.c2.label"] = "Analysis mode is AC.",
        ["learn.project.notchFilter.lesson1.body"] = "At the notch frequency the network presents a path that cancels transfer to the load — |Vout| plunges in a narrow band.",
        ["learn.project.notchFilter.lesson2.body"] = "Killing mains hum, removing a whistle, or scrubbing one interferer before amplification.",
        ["learn.project.notchFilter.quiz.q1.prompt"] = "A notch filter…",
        ["learn.project.notchFilter.quiz.q1.a"] = "Rejects a narrow band",
        ["learn.project.notchFilter.quiz.q1.b"] = "Only passes DC",
        ["learn.project.notchFilter.quiz.q1.c"] = "Always amplifies",
        ["learn.project.notchFilter.quiz.q1.explain"] = "Notch = band-stop around one frequency.",
        ["learn.project.notchFilter.quiz.q2.prompt"] = "Far from the notch frequency, |Vout|…",
        ["learn.project.notchFilter.quiz.q2.a"] = "Is always zero",
        ["learn.project.notchFilter.quiz.q2.b"] = "Recovers toward the pass level",
        ["learn.project.notchFilter.quiz.q2.c"] = "Must oscillate",
        ["learn.project.notchFilter.quiz.q2.explain"] = "Rejection is local to the notch.",
        ["learn.project.notchFilter.quiz.q3.prompt"] = "Tuning the notch mainly means changing…",
        ["learn.project.notchFilter.quiz.q3.a"] = "Only the battery ESR",
        ["learn.project.notchFilter.quiz.q3.b"] = "Wire color",
        ["learn.project.notchFilter.quiz.q3.c"] = "L and/or C",
        ["learn.project.notchFilter.quiz.q3.explain"] = "The reject frequency tracks the LC resonance.",
        ["learn.project.notchFilter.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.notchFilter.challenge.c2.label"] = "Analysis mode is AC.",
        ["learn.project.voltageDivider.lesson1.body"] = "With no load, Vmid = Vsource · Rbottom / (Rtop + Rbottom). Current is V / (R1+R2).",
        ["learn.project.voltageDivider.lesson2.body"] = "Anything attached to the mid node is another parallel path — it lowers effective Rbottom and drops Vmid.",
        ["learn.project.voltageDivider.quiz.q1.prompt"] = "Unloaded divider mid voltage is…",
        ["learn.project.voltageDivider.quiz.q1.a"] = "V · R2 / (R1 + R2)",
        ["learn.project.voltageDivider.quiz.q1.b"] = "V · R1 only",
        ["learn.project.voltageDivider.quiz.q1.c"] = "Always V/2 regardless of R",
        ["learn.project.voltageDivider.quiz.q1.explain"] = "Ohm’s law on the series string.",
        ["learn.project.voltageDivider.quiz.q2.prompt"] = "Equal resistors give…",
        ["learn.project.voltageDivider.quiz.q2.a"] = "Zero volts",
        ["learn.project.voltageDivider.quiz.q2.b"] = "Half the source (ideal)",
        ["learn.project.voltageDivider.quiz.q2.c"] = "Twice the source",
        ["learn.project.voltageDivider.quiz.q2.explain"] = "R2/(R1+R2) = 1/2.",
        ["learn.project.voltageDivider.quiz.q3.prompt"] = "A heavy load on the mid node…",
        ["learn.project.voltageDivider.quiz.q3.a"] = "Raises Vmid",
        ["learn.project.voltageDivider.quiz.q3.b"] = "Does nothing",
        ["learn.project.voltageDivider.quiz.q3.c"] = "Pulls Vmid down",
        ["learn.project.voltageDivider.quiz.q3.explain"] = "Load parallels Rbottom.",
        ["learn.project.voltageDivider.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.voltageDivider.challenge.c2.label"] = "Mid-node voltage is near half supply.",
        ["learn.project.dividerDesign.lesson1.title"] = "Design the ratio",
        ["learn.project.dividerDesign.lesson1.body"] = "Pick R1 and R2 so Vmid lands where you need it. Equal resistors → half supply; larger Rbottom → higher mid.",
        ["learn.project.dividerDesign.lesson2.title"] = "Check with a probe",
        ["learn.project.dividerDesign.lesson2.body"] = "After you set values, Run DC and probe the mid node — prediction first, measurement second.",
        ["learn.project.dividerDesign.quiz.q1.prompt"] = "To raise unloaded Vmid you can…",
        ["learn.project.dividerDesign.quiz.q1.a"] = "Increase Rbottom relative to Rtop",
        ["learn.project.dividerDesign.quiz.q1.b"] = "Only remove ground",
        ["learn.project.dividerDesign.quiz.q1.c"] = "Always lower both R to zero",
        ["learn.project.dividerDesign.quiz.q1.explain"] = "Larger bottom share raises the tap.",
        ["learn.project.dividerDesign.quiz.q2.prompt"] = "Best design habit…",
        ["learn.project.dividerDesign.quiz.q2.a"] = "Guess forever without probing",
        ["learn.project.dividerDesign.quiz.q2.b"] = "Predict, then probe Vmid",
        ["learn.project.dividerDesign.quiz.q2.c"] = "Delete the battery first",
        ["learn.project.dividerDesign.quiz.q2.explain"] = "Close the loop between math and Lab.",
        ["learn.project.dividerDesign.quiz.q3.prompt"] = "Equal 10 kΩ on 5 V should give about…",
        ["learn.project.dividerDesign.quiz.q3.a"] = "0 V",
        ["learn.project.dividerDesign.quiz.q3.b"] = "5 V",
        ["learn.project.dividerDesign.quiz.q3.c"] = "2.5 V",
        ["learn.project.dividerDesign.quiz.q3.explain"] = "Half the source when R1 = R2.",
        ["learn.project.dividerDesign.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.dividerDesign.challenge.c2.label"] = "Mid voltage is near half of 5 V.",
        ["learn.project.potDivider.lesson1.body"] = "A potentiometer is two resistors in series whose ratio tracks the mechanical (or slider) position.",
        ["learn.project.potDivider.lesson2.body"] = "Vwiper ≈ V · pos when unloaded. Volume controls and setpoint knobs are this idea in hardware.",
        ["learn.project.potDivider.quiz.q1.prompt"] = "A pot used as a divider…",
        ["learn.project.potDivider.quiz.q1.a"] = "Takes a tap between two end terminals",
        ["learn.project.potDivider.quiz.q1.b"] = "Must be floating with one pin",
        ["learn.project.potDivider.quiz.q1.c"] = "Only works with AC",
        ["learn.project.potDivider.quiz.q1.explain"] = "Ends on the rail; wiper is the mid.",
        ["learn.project.potDivider.quiz.q2.prompt"] = "Moving the wiper toward ground…",
        ["learn.project.potDivider.quiz.q2.a"] = "Raises Vwiper to Vcc",
        ["learn.project.potDivider.quiz.q2.b"] = "Lowers Vwiper toward 0",
        ["learn.project.potDivider.quiz.q2.c"] = "Disconnects the circuit",
        ["learn.project.potDivider.quiz.q2.explain"] = "More resistance above the tap → lower ratio.",
        ["learn.project.potDivider.quiz.q3.prompt"] = "Heavy load on the wiper…",
        ["learn.project.potDivider.quiz.q3.a"] = "Never matters",
        ["learn.project.potDivider.quiz.q3.b"] = "Increases supply voltage",
        ["learn.project.potDivider.quiz.q3.c"] = "Distorts the expected linear sweep",
        ["learn.project.potDivider.quiz.q3.explain"] = "Loading parallels the lower arm.",
        ["learn.project.potDivider.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.potDivider.challenge.c2.label"] = "Circuit includes a potentiometer.",
        ["learn.project.measureAc.lesson1.body"] = "AC mode reports phasor magnitude/phase at the analysis frequency — think “how big is this tone here?”",
        ["learn.project.measureAc.lesson2.body"] = "Pick one frequency, probe one node, change one parameter — that is how you build intuition without drowning in plots.",
        ["learn.project.measureAc.quiz.q1.prompt"] = "AC analysis in this Lab is best for…",
        ["learn.project.measureAc.quiz.q1.a"] = "Tone magnitude at a frequency",
        ["learn.project.measureAc.quiz.q1.b"] = "Only DC battery ESR",
        ["learn.project.measureAc.quiz.q1.c"] = "Mechanical switch bounce",
        ["learn.project.measureAc.quiz.q1.explain"] = "AC solves the linear network at f.",
        ["learn.project.measureAc.quiz.q2.prompt"] = "Doubling source mag (linear network)…",
        ["learn.project.measureAc.quiz.q2.a"] = "Zeros the output",
        ["learn.project.measureAc.quiz.q2.b"] = "Roughly doubles probed mag",
        ["learn.project.measureAc.quiz.q2.c"] = "Inverts DC only",
        ["learn.project.measureAc.quiz.q2.explain"] = "Linear scaling.",
        ["learn.project.measureAc.quiz.q3.prompt"] = "Good measurement discipline is…",
        ["learn.project.measureAc.quiz.q3.a"] = "Change everything at once",
        ["learn.project.measureAc.quiz.q3.b"] = "Never use a voltmeter",
        ["learn.project.measureAc.quiz.q3.c"] = "Change one thing and re-probe",
        ["learn.project.measureAc.quiz.q3.explain"] = "Isolation builds understanding.",
        ["learn.project.measureAc.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.measureAc.challenge.c2.label"] = "Analysis mode is AC.",
        ["learn.project.bodeIntuition.lesson1.title"] = "Magnitude vs frequency",
        ["learn.project.bodeIntuition.lesson1.body"] = "Change the AC analysis frequency and probe the same node — that is the seed of Bode thinking without a full plot yet.",
        ["learn.project.bodeIntuition.lesson2.title"] = "One knob at a time",
        ["learn.project.bodeIntuition.lesson2.body"] = "Hold amplitude fixed, sweep frequency in your head (or step it), and watch magnitude fall or rise depending on the network.",
        ["learn.project.bodeIntuition.quiz.q1.prompt"] = "Bode intuition starts with…",
