        ["learn.project.bodeIntuition.challenge.c2.label"] = "Use AC analysis.",
        ["learn.project.motorMosfet.lesson1.body"] = "NMOS between motor (−) and ground lets a logic-level gate control a higher-current path from the supply through the motor.",
        ["learn.project.motorMosfet.lesson2.body"] = "Motors are inductive — when the FET opens, current needs a freewheel path (flyback diode).",
        ["learn.project.motorMosfet.quiz.q1.prompt"] = "Low-side NMOS motor drive puts the FET…",
        ["learn.project.motorMosfet.quiz.q1.a"] = "Between motor return and ground",
        ["learn.project.motorMosfet.quiz.q1.b"] = "Only across the battery",
        ["learn.project.motorMosfet.quiz.q1.c"] = "In series with nothing",
        ["learn.project.motorMosfet.quiz.q1.explain"] = "Classic low-side switch.",
        ["learn.project.motorMosfet.quiz.q2.prompt"] = "Gate high (above threshold)…",
        ["learn.project.motorMosfet.quiz.q2.a"] = "Always burns the motor",
        ["learn.project.motorMosfet.quiz.q2.b"] = "Allows drain–source current",
        ["learn.project.motorMosfet.quiz.q2.c"] = "Opens the channel forever",
        ["learn.project.motorMosfet.quiz.q2.explain"] = "Enhancement NMOS conducts when Vgs is high enough.",
        ["learn.project.motorMosfet.quiz.q3.prompt"] = "Flyback diode orientation…",
        ["learn.project.motorMosfet.quiz.q3.a"] = "Anode to +V",
        ["learn.project.motorMosfet.quiz.q3.b"] = "Optional decoration",
        ["learn.project.motorMosfet.quiz.q3.c"] = "Cathode toward +V across the motor",
        ["learn.project.motorMosfet.quiz.q3.explain"] = "It freewheels inductive current when the switch opens.",
        ["learn.project.motorMosfet.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.motorMosfet.challenge.c2.label"] = "Circuit has no structural errors.",
        ["learn.project.motorPwm.lesson1.body"] = "PWM switches fully on/off. The motor inductance/mechanics average the pulses — higher duty ≈ higher effective voltage.",
        ["learn.project.motorPwm.lesson2.body"] = "Switching keeps the FET in low-loss on/off states instead of dissipating as a series rheostat.",
        ["learn.project.motorPwm.quiz.q1.prompt"] = "PWM motor control mainly varies…",
        ["learn.project.motorPwm.quiz.q1.a"] = "Duty cycle (on-time fraction)",
        ["learn.project.motorPwm.quiz.q1.b"] = "Wire color",
        ["learn.project.motorPwm.quiz.q1.c"] = "Only diode Vf forever",
        ["learn.project.motorPwm.quiz.q1.explain"] = "Duty sets average voltage.",
        ["learn.project.motorPwm.quiz.q2.prompt"] = "During the off interval, inductive current…",
        ["learn.project.motorPwm.quiz.q2.a"] = "Needs a freewheel path",
        ["learn.project.motorPwm.quiz.q2.b"] = "Instantly becomes zero safely always",
        ["learn.project.motorPwm.quiz.q2.c"] = "Charges the gate only",
        ["learn.project.motorPwm.quiz.q2.explain"] = "Flyback diode (or sync path) matters.",
        ["learn.project.motorPwm.quiz.q3.prompt"] = "Higher duty cycle tends to…",
        ["learn.project.motorPwm.quiz.q3.a"] = "Stop the motor always",
        ["learn.project.motorPwm.quiz.q3.b"] = "Lower average voltage",
        ["learn.project.motorPwm.quiz.q3.c"] = "Raise average motor voltage",
        ["learn.project.motorPwm.quiz.q3.explain"] = "More on-time → more average V.",
        ["learn.project.motorPwm.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.motorPwm.challenge.c2.label"] = "Analysis mode is transient.",
        ["learn.project.motorSpeed.lesson1.title"] = "Speed ≈ average voltage",
        ["learn.project.motorSpeed.lesson1.body"] = "In the teaching model, raising PWM duty raises the average voltage across the motor — it spins harder.",
        ["learn.project.motorSpeed.lesson2.title"] = "Tune carefully",
        ["learn.project.motorSpeed.lesson2.body"] = "Change pulse width (duty), Run Transient, and watch motor current / animation. Keep the flyback path intact.",
        ["learn.project.motorSpeed.quiz.q1.prompt"] = "To spin faster you usually…",
        ["learn.project.motorSpeed.quiz.q1.a"] = "Increase PWM duty cycle",
        ["learn.project.motorSpeed.quiz.q1.b"] = "Remove the flyback diode",
        ["learn.project.motorSpeed.quiz.q1.c"] = "Delete ground",
        ["learn.project.motorSpeed.quiz.q1.explain"] = "More on-time raises average voltage.",
        ["learn.project.motorSpeed.quiz.q2.prompt"] = "Best analysis mode to see PWM…",
        ["learn.project.motorSpeed.quiz.q2.a"] = "Import JSON only",
        ["learn.project.motorSpeed.quiz.q2.b"] = "Transient",
        ["learn.project.motorSpeed.quiz.q2.c"] = "SEO mode",
        ["learn.project.motorSpeed.quiz.q2.explain"] = "Need time to see the pulses.",
        ["learn.project.motorSpeed.quiz.q3.prompt"] = "Lowering duty cycle tends to…",
        ["learn.project.motorSpeed.quiz.q3.a"] = "Always burn the FET",
        ["learn.project.motorSpeed.quiz.q3.b"] = "Raise speed forever",
        ["learn.project.motorSpeed.quiz.q3.c"] = "Reduce average motor voltage",
        ["learn.project.motorSpeed.quiz.q3.explain"] = "Less on-time → slower / weaker drive.",
        ["learn.project.motorSpeed.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.motorSpeed.challenge.c2.label"] = "Use Transient analysis.",
        ["learn.project.motorFlyback.lesson1.body"] = "Current in an inductor cannot stop instantly. Without a path, voltage spikes and can avalanche the transistor.",
        ["learn.project.motorFlyback.lesson2.body"] = "Diode anti-parallel to the inductive load: cathode to the more positive motor terminal (toward +V on a low-side switch).",
        ["learn.project.motorFlyback.quiz.q1.prompt"] = "Flyback diodes protect against…",
        ["learn.project.motorFlyback.quiz.q1.a"] = "Inductive voltage spikes at turn-off",
        ["learn.project.motorFlyback.quiz.q1.b"] = "Only LED color",
        ["learn.project.motorFlyback.quiz.q1.c"] = "USB enumeration",
        ["learn.project.motorFlyback.quiz.q1.explain"] = "They freewheel L·di/dt energy.",
        ["learn.project.motorFlyback.quiz.q2.prompt"] = "On a low-side motor switch, cathode faces…",
        ["learn.project.motorFlyback.quiz.q2.a"] = "Ground only",
        ["learn.project.motorFlyback.quiz.q2.b"] = "Toward +V (across the motor)",
        ["learn.project.motorFlyback.quiz.q2.c"] = "The gate resistor",
        ["learn.project.motorFlyback.quiz.q2.explain"] = "Standard freewheel orientation.",
        ["learn.project.motorFlyback.quiz.q3.prompt"] = "Omitting the diode when switching a motor…",
        ["learn.project.motorFlyback.quiz.q3.a"] = "Is always fine",
        ["learn.project.motorFlyback.quiz.q3.b"] = "Speeds PWM forever",
        ["learn.project.motorFlyback.quiz.q3.c"] = "Risks killing the transistor",
        ["learn.project.motorFlyback.quiz.q3.explain"] = "Spike energy has nowhere safe to go.",
        ["learn.project.motorFlyback.challenge.c1.label"] = "Include a flyback diode across the motor (cathode toward +V on a low-side switch).",
        ["learn.project.motorFlyback.challenge.c2.label"] = "Close the gate switch and run DC so the motor conducts.",
        ["learn.project.hBridge.lesson1.body"] = "Forward: top-left + bottom-right. Reverse: the other diagonal. Both highs or both lows on one side shorts the supply.",
        ["learn.project.hBridge.lesson2.body"] = "Ideal switches stand in for MOSFET half-bridges — focus on current path, not gate-drive ICs yet.",
        ["learn.project.hBridge.quiz.q1.prompt"] = "Forward H-bridge conduction uses…",
        ["learn.project.hBridge.quiz.q1.a"] = "One diagonal pair of switches",
        ["learn.project.hBridge.quiz.q1.b"] = "All four switches closed",
        ["learn.project.hBridge.quiz.q1.c"] = "Only the flyback LEDs",
        ["learn.project.hBridge.quiz.q1.explain"] = "Diagonal path through the motor.",
        ["learn.project.hBridge.quiz.q2.prompt"] = "Closing both switches on one leg…",
        ["learn.project.hBridge.quiz.q2.a"] = "Is required",
        ["learn.project.hBridge.quiz.q2.b"] = "Shoot-through / shorts the rail",
        ["learn.project.hBridge.quiz.q2.c"] = "Charges the motor safely",
        ["learn.project.hBridge.quiz.q2.explain"] = "High and low both on = supply short.",
        ["learn.project.hBridge.quiz.q3.prompt"] = "Reversing the motor means…",
        ["learn.project.hBridge.quiz.q3.a"] = "Removing ground",
        ["learn.project.hBridge.quiz.q3.b"] = "Changing wire color only",
        ["learn.project.hBridge.quiz.q3.c"] = "Closing the other diagonal pair",
        ["learn.project.hBridge.quiz.q3.explain"] = "Current through the motor flips.",
        ["learn.project.hBridge.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.hBridge.challenge.c2.label"] = "Circuit has no structural errors.",
        ["learn.project.motorDirection.lesson1.body"] = "Reversing is not a second motor — it is the other pair of switches so current enters the opposite motor terminal.",
        ["learn.project.motorDirection.lesson2.body"] = "Real drivers insert dead time so both FETs on a leg are never on together.",
        ["learn.project.motorDirection.quiz.q1.prompt"] = "To reverse with an H-bridge…",
        ["learn.project.motorDirection.quiz.q1.a"] = "Close the opposite diagonal",
        ["learn.project.motorDirection.quiz.q1.b"] = "Short both rails",
        ["learn.project.motorDirection.quiz.q1.c"] = "Remove the motor",
        ["learn.project.motorDirection.quiz.q1.explain"] = "Other diagonal flips current.",
        ["learn.project.motorDirection.quiz.q2.prompt"] = "Forward and reverse diagonals should be…",
        ["learn.project.motorDirection.quiz.q2.a"] = "Closed at the same time",
        ["learn.project.motorDirection.quiz.q2.b"] = "Mutually exclusive",
        ["learn.project.motorDirection.quiz.q2.c"] = "Irrelevant",
        ["learn.project.motorDirection.quiz.q2.explain"] = "Overlap causes shoot-through.",
        ["learn.project.motorDirection.quiz.q3.prompt"] = "Dead time is…",
        ["learn.project.motorDirection.quiz.q3.a"] = "Extra LED brightness",
        ["learn.project.motorDirection.quiz.q3.b"] = "USB delay only",
        ["learn.project.motorDirection.quiz.q3.c"] = "A brief both-off gap when changing direction",
        ["learn.project.motorDirection.quiz.q3.explain"] = "Prevents leg shoot-through.",
        ["learn.project.motorDirection.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.motorDirection.challenge.c2.label"] = "Circuit has no structural errors.",
        ["learn.project.pullUpDown.lesson1.body"] = "Inputs must not float. A pull-up weakly holds HIGH until the switch (or open-drain) strongly pulls LOW.",
        ["learn.project.pullUpDown.lesson2.body"] = "The switch wins when closed; the resistor wins when open. Choose R so leakage and speed still work.",
        ["learn.project.pullUpDown.quiz.q1.prompt"] = "A pull-up resistor…",
        ["learn.project.pullUpDown.quiz.q1.a"] = "Holds the node high when the switch is open",
        ["learn.project.pullUpDown.quiz.q1.b"] = "Always shorts VCC to ground",
        ["learn.project.pullUpDown.quiz.q1.c"] = "Replaces the battery",
        ["learn.project.pullUpDown.quiz.q1.explain"] = "Weak HIGH idle.",
        ["learn.project.pullUpDown.quiz.q2.prompt"] = "Closing a switch to ground on a pull-up input…",
        ["learn.project.pullUpDown.quiz.q2.a"] = "Leaves the node floating",
        ["learn.project.pullUpDown.quiz.q2.b"] = "Drives the node low",
        ["learn.project.pullUpDown.quiz.q2.c"] = "Raises VCC",
        ["learn.project.pullUpDown.quiz.q2.explain"] = "Strong low overrides the weak pull-up.",
        ["learn.project.pullUpDown.quiz.q3.prompt"] = "Floating inputs are bad because…",
        ["learn.project.pullUpDown.quiz.q3.a"] = "They are always 5.000 V",
        ["learn.project.pullUpDown.quiz.q3.b"] = "LEDs become brighter",
        ["learn.project.pullUpDown.quiz.q3.c"] = "Noise can randomly trip logic",
        ["learn.project.pullUpDown.quiz.q3.explain"] = "Undefined voltage = unreliable reads.",
        ["learn.project.pullUpDown.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.pullUpDown.challenge.c2.label"] = "Circuit has no structural errors.",
        ["learn.project.debounce.lesson1.body"] = "Mechanical contacts chatter for milliseconds. Logic that samples raw edges may see many false transitions.",
        ["learn.project.debounce.lesson2.body"] = "A capacitor to ground (with pull-up) low-pass filters the switch node. Firmware debounce is the digital twin of this idea.",
        ["learn.project.debounce.quiz.q1.prompt"] = "Switch bounce causes…",
        ["learn.project.debounce.quiz.q1.a"] = "Multiple edges from one press",
        ["learn.project.debounce.quiz.q1.b"] = "Higher battery voltage",
        ["learn.project.debounce.quiz.q1.c"] = "Perfect single edges always",
        ["learn.project.debounce.quiz.q1.explain"] = "Contacts chatter.",
        ["learn.project.debounce.quiz.q2.prompt"] = "An RC on the switch node…",
        ["learn.project.debounce.quiz.q2.a"] = "Removes the need for ground",
        ["learn.project.debounce.quiz.q2.b"] = "Slows/filters fast chatter",
        ["learn.project.debounce.quiz.q2.c"] = "Increases bounce",
        ["learn.project.debounce.quiz.q2.explain"] = "Low-pass softens edges.",
        ["learn.project.debounce.quiz.q3.prompt"] = "Debounce belongs with…",
        ["learn.project.debounce.quiz.q3.a"] = "Only RF antennas",
        ["learn.project.debounce.quiz.q3.b"] = "Only transformers",
        ["learn.project.debounce.quiz.q3.c"] = "Buttons, limit switches, and noisy contacts",
        ["learn.project.debounce.quiz.q3.explain"] = "Any mechanical contact benefits.",
        ["learn.project.debounce.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.debounce.challenge.c2.label"] = "Circuit has no structural errors.",
        ["learn.project.debounceIdea.lesson1.title"] = "Why debounce exists",
        ["learn.project.debounceIdea.lesson1.body"] = "One physical press is not one clean edge — contacts bounce. Logic and MCU inputs need a quiet decision.",
        ["learn.project.debounceIdea.lesson2.title"] = "Hardware vs firmware",
        ["learn.project.debounceIdea.lesson2.body"] = "An RC filter is the analog version; waiting a few milliseconds in code is the digital twin. Same problem, two tools.",
        ["learn.project.debounceIdea.quiz.q1.prompt"] = "Debounce solves…",
        ["learn.project.debounceIdea.quiz.q1.a"] = "False multiple edges from one press",
        ["learn.project.debounceIdea.quiz.q1.b"] = "Battery voltage doubling",
        ["learn.project.debounceIdea.quiz.q1.c"] = "Missing ground symbols only",
        ["learn.project.debounceIdea.quiz.q1.explain"] = "Bounce creates chatter edges.",
        ["learn.project.debounceIdea.quiz.q2.prompt"] = "Firmware debounce usually…",
        ["learn.project.debounceIdea.quiz.q2.a"] = "Ignores edges for a short settle time",
        ["learn.project.debounceIdea.quiz.q2.b"] = "Deletes the switch",
        ["learn.project.debounceIdea.quiz.q2.c"] = "Raises supply to 100 V",
        ["learn.project.debounceIdea.quiz.q2.explain"] = "Wait until the contact is stable.",
        ["learn.project.debounceIdea.quiz.q3.prompt"] = "RC debounce and code debounce…",
        ["learn.project.debounceIdea.quiz.q3.a"] = "Are unrelated forever",
        ["learn.project.debounceIdea.quiz.q3.b"] = "Only work on motors",
        ["learn.project.debounceIdea.quiz.q3.c"] = "Attack the same bounce problem differently",
        ["learn.project.debounceIdea.quiz.q3.explain"] = "Hardware filters; software waits — same goal.",
        ["learn.project.debounceIdea.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.debounceIdea.challenge.c2.label"] = "Circuit has no structural errors.",
        ["learn.project.sensorLdr.lesson1.title"] = "Resistance to voltage",
        ["learn.project.sensorLdr.lesson1.body"] = "Most sensors do not output a clean volt by themselves. An LDR is a variable R; a fixed resistor completes a divider so you get a voltage that tracks light.",
        ["learn.project.sensorLdr.lesson2.title"] = "Usable signal",
        ["learn.project.sensorLdr.lesson2.body"] = "That mid-node voltage can drive a FET, a comparator, or (later) an ADC pin. Same idea for many resistive sensors.",
        ["learn.project.sensorLdr.quiz.q1.prompt"] = "An LDR mainly changes…",
        ["learn.project.sensorLdr.quiz.q1.a"] = "Resistance with light",
        ["learn.project.sensorLdr.quiz.q1.b"] = "Only battery ESR",
        ["learn.project.sensorLdr.quiz.q1.c"] = "Wire color",
        ["learn.project.sensorLdr.quiz.q1.explain"] = "Photoresistance varies with illumination.",
        ["learn.project.sensorLdr.quiz.q2.prompt"] = "A series resistor with the LDR makes…",
        ["learn.project.sensorLdr.quiz.q2.a"] = "A short across VCC",
        ["learn.project.sensorLdr.quiz.q2.b"] = "A voltage divider (usable signal)",
        ["learn.project.sensorLdr.quiz.q2.c"] = "An antenna",
        ["learn.project.sensorLdr.quiz.q2.explain"] = "Divider mid-node is the sensor voltage.",
        ["learn.project.sensorLdr.quiz.q3.prompt"] = "Raising light (lower LDR R to ground) tends to…",
        ["learn.project.sensorLdr.quiz.q3.a"] = "Raise the mid node forever",
        ["learn.project.sensorLdr.quiz.q3.b"] = "Disconnect ground",
        ["learn.project.sensorLdr.quiz.q3.c"] = "Pull the mid node toward ground",
        ["learn.project.sensorLdr.quiz.q3.explain"] = "Lower bottom R drops the divider ratio.",
        ["learn.project.sensorLdr.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.sensorLdr.challenge.c2.label"] = "Circuit has no structural errors.",
        ["learn.project.sensorPot.lesson1.title"] = "Position → voltage",
        ["learn.project.sensorPot.lesson1.body"] = "Mechanical travel changes the divider ratio. The wiper is already a usable analog signal.",
        ["learn.project.sensorPot.lesson2.title"] = "Loading",
        ["learn.project.sensorPot.lesson2.body"] = "Whatever you attach to the wiper (ADC, amp, FET) must not drag the voltage if you need accuracy — buffer or high impedance helps.",
        ["learn.project.sensorPot.quiz.q1.prompt"] = "A pot used as a sensor outputs…",
        ["learn.project.sensorPot.quiz.q1.a"] = "A tap voltage between the rails",
        ["learn.project.sensorPot.quiz.q1.b"] = "Only digital pulses",
        ["learn.project.sensorPot.quiz.q1.c"] = "RF only",
        ["learn.project.sensorPot.quiz.q1.explain"] = "Wiper is the analog signal.",
        ["learn.project.sensorPot.quiz.q2.prompt"] = "Moving the wiper changes…",
        ["learn.project.sensorPot.quiz.q2.a"] = "Nothing electrical",
        ["learn.project.sensorPot.quiz.q2.b"] = "The divider ratio (and Vwiper)",
        ["learn.project.sensorPot.quiz.q2.c"] = "Only LED color",
        ["learn.project.sensorPot.quiz.q2.explain"] = "Position sets the resistive split.",
        ["learn.project.sensorPot.quiz.q3.prompt"] = "Heavy load on the wiper…",
        ["learn.project.sensorPot.quiz.q3.a"] = "Never matters",
        ["learn.project.sensorPot.quiz.q3.b"] = "Raises VCC",
        ["learn.project.sensorPot.quiz.q3.c"] = "Can distort the expected voltage",
        ["learn.project.sensorPot.quiz.q3.explain"] = "Loading parallels the lower arm.",
        ["learn.project.sensorPot.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.sensorPot.challenge.c2.label"] = "Circuit has no structural errors.",
        ["learn.project.ntcDivider.lesson1.title"] = "Thermistor idea",
        ["learn.project.ntcDivider.lesson1.body"] = "NTCs drop resistance as they warm. In a divider that moves the mid voltage — that is your temperature signal.",
        ["learn.project.ntcDivider.lesson2.title"] = "Why a stand-in",
        ["learn.project.ntcDivider.lesson2.body"] = "Lab v1 has no dedicated NTC model yet. A pot lets you feel the divider math before a future sensor ADR.",
        ["learn.project.ntcDivider.quiz.q1.prompt"] = "An NTC in a divider mainly gives…",
        ["learn.project.ntcDivider.quiz.q1.a"] = "A voltage that tracks temperature",
        ["learn.project.ntcDivider.quiz.q1.b"] = "Only PWM",
        ["learn.project.ntcDivider.quiz.q1.c"] = "Galvanic isolation",
        ["learn.project.ntcDivider.quiz.q1.explain"] = "R(T) → Vmid.",
        ["learn.project.ntcDivider.quiz.q2.prompt"] = "If NTC resistance falls (warmer) on the bottom arm…",
        ["learn.project.ntcDivider.quiz.q2.a"] = "Vmid usually falls",
        ["learn.project.ntcDivider.quiz.q2.b"] = "Vmid must rise to VCC",
        ["learn.project.ntcDivider.quiz.q2.c"] = "The battery shorts",
        ["learn.project.ntcDivider.quiz.q2.explain"] = "Lower bottom R lowers the ratio.",
        ["learn.project.ntcDivider.quiz.q3.prompt"] = "This sample uses a pot because…",
        ["learn.project.ntcDivider.quiz.q3.a"] = "Pots are NTCs",
        ["learn.project.ntcDivider.quiz.q3.b"] = "It is a teaching stand-in for variable R",
        ["learn.project.ntcDivider.quiz.q3.c"] = "AC analysis requires it",
        ["learn.project.ntcDivider.quiz.q3.explain"] = "Interactive R without a dedicated NTC model.",
        ["learn.project.ntcDivider.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.ntcDivider.challenge.c2.label"] = "Circuit has no structural errors.",
        ["learn.project.sensorThreshold.lesson1.title"] = "Threshold decision",
        ["learn.project.sensorThreshold.lesson1.body"] = "Many sensor apps need a trip point, not a continuous number. A comparator (or MCU digital read after conditioning) turns analog into on/off.",
        ["learn.project.sensorThreshold.lesson2.title"] = "Hysteresis next",
        ["learn.project.sensorThreshold.lesson2.body"] = "Real systems add Schmitt feedback so noise does not chatter at the trip point — see the Schmitt unit.",
        ["learn.project.sensorThreshold.quiz.q1.prompt"] = "A comparator on a sensor voltage…",
        ["learn.project.sensorThreshold.quiz.q1.a"] = "Compares it to a threshold",
        ["learn.project.sensorThreshold.quiz.q1.b"] = "Always integrates",
        ["learn.project.sensorThreshold.quiz.q1.c"] = "Removes the need for ground",
