        ["learn.project.commsI2c.lesson1.title"] = "Open-drain bus",
        ["learn.project.commsI2c.lesson1.body"] = "I²C lines idle high via pull-ups; devices only pull low. Missing pull-ups = a stuck or flaky bus.",
        ["learn.project.commsI2c.lesson2.title"] = "Why it matters",
        ["learn.project.commsI2c.lesson2.body"] = "Sensors, EEPROMs, and displays share this pattern. UART/SPI/RS-485 need their own wiring stories (later ADRs).",
        ["learn.project.commsI2c.quiz.q1.prompt"] = "I²C SDA/SCL idle state relies on…",
