        ["learn.project.adcFrontEnd.lesson1.title"] = "Sample a voltage",
        ["learn.project.adcFrontEnd.lesson1.body"] = "ADC converts Vin into an integer using Vref and bit depth. The front-end job is delivering a clean Vin in range.",
        ["learn.project.adcFrontEnd.lesson2.title"] = "Sensors → ADC",
        ["learn.project.adcFrontEnd.lesson2.body"] = "Dividers, amps, and filters condition the sensor so the MCU pin sees a friendly voltage — not raw milliamp loops.",
        ["learn.project.adcFrontEnd.quiz.q1.prompt"] = "An ADC primarily converts…",
