        ["learn.project.adcReference.lesson1.title"] = "Vref sets the ruler",
        ["learn.project.adcReference.lesson1.body"] = "Resolution is Vref / 2^N per count (ideal). A noisy or wrong Vref scales every reading.",
        ["learn.project.adcReference.lesson2.title"] = "Sampling",
        ["learn.project.adcReference.lesson2.body"] = "How often you convert (sample rate) is separate from bits — both matter for faithful reconstruction.",
