        ["learn.project.adcReference.challenge.c2.label"] = "Circuit has no structural errors.",
        ["learn.project.pwmFilter.lesson1.title"] = "Average is the “analog”",
        ["learn.project.pwmFilter.lesson1.body"] = "PWM is still digital edges. An RC (or the load’s own filtering) averages them into a DC-ish voltage.",
        ["learn.project.pwmFilter.lesson2.title"] = "Vs true DAC",
        ["learn.project.pwmFilter.lesson2.body"] = "A real DAC outputs a held level with better linearity/noise. PWM+filter is the teaching stand-in and a common MCU trick.",
        ["learn.project.pwmFilter.quiz.q1.prompt"] = "PWM as a DAC mainly varies…",
