        ["learn.project.pwmFilter.challenge.c2.label"] = "Analysis mode is transient.",
        ["learn.project.relayBjt.lesson1.title"] = "Why a driver",
        ["learn.project.relayBjt.lesson1.body"] = "Relay coils take tens of mA. A transistor (or MOSFET) lets a small base/gate current control that coil.",
        ["learn.project.relayBjt.lesson2.title"] = "Still need the diode",
        ["learn.project.relayBjt.lesson2.body"] = "Turning the coil off dumps inductive energy — Dfly protects the transistor.",
