        ["learn.project.mosfetDriver.lesson1.body"] = "Enhancement NMOS conducts when Vgs is high enough. Almost no DC gate current vs BJT base current.",
        ["learn.project.mosfetDriver.lesson2.title"] = "Industrial cousin",
