        ["learn.project.coilProtect.lesson1.title"] = "L·di/dt",
        ["learn.project.coilProtect.lesson1.body"] = "Current in a coil cannot stop instantly. Without a path, voltage rises until something breaks down.",
        ["learn.project.coilProtect.lesson2.title"] = "Orientation",
        ["learn.project.coilProtect.lesson2.body"] = "Diode cathode toward the positive coil supply so it is reverse-biased in steady on-state.",
