        ["learn.project.coilProtect.challenge.c2.label"] = "Close the coil switch so the load LED conducts.",
        ["learn.project.inductiveLoad.lesson1.title"] = "Not a resistor",
        ["learn.project.inductiveLoad.lesson1.body"] = "Inductive loads fight current change. DC motors look resistive when spinning, but turn-off still spikes.",
