        ["learn.project.ledBurnLimit.lesson2.title"] = "Replace and recover",
        ["learn.project.ledBurnLimit.lesson2.body"] = "Burnout is sticky until you replace the part and fix the overload (usually raise R).",
        ["learn.project.ledBurnLimit.quiz.q1.prompt"] = "Burnout here means…",
        ["learn.project.ledBurnLimit.quiz.q1.a"] = "Too much current for too long",
        ["learn.project.ledBurnLimit.quiz.q1.b"] = "Wrong wire color",
        ["learn.project.ledBurnLimit.quiz.q1.c"] = "AC mode only",
        ["learn.project.ledBurnLimit.quiz.q1.explain"] = "Overcurrent trips the teaching model.",
        ["learn.project.ledBurnLimit.quiz.q2.prompt"] = "After a burn you should…",
        ["learn.project.ledBurnLimit.quiz.q2.a"] = "Ignore it",
        ["learn.project.ledBurnLimit.quiz.q2.b"] = "Replace the LED and raise R",
        ["learn.project.ledBurnLimit.quiz.q2.c"] = "Delete ground",
        ["learn.project.ledBurnLimit.quiz.q2.explain"] = "Recover the part and reduce current.",
        ["learn.project.ledBurnLimit.quiz.q3.prompt"] = "Safer LED current in these labs is often…",
        ["learn.project.ledBurnLimit.quiz.q3.a"] = "Hundreds of amps",
        ["learn.project.ledBurnLimit.quiz.q3.b"] = "Zero always",
        ["learn.project.ledBurnLimit.quiz.q3.c"] = "Around 10–20 mA",
        ["learn.project.ledBurnLimit.quiz.q3.explain"] = "Typical indicator current range.",
        ["learn.project.ledBurnLimit.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.ledBurnLimit.challenge.c2.label"] = "LED stays intact below ~25 mA.",
        ["learn.project.diodeDirection.lesson1.title"] = "One-way street",
        ["learn.project.diodeDirection.lesson1.body"] = "A diode conducts when the anode is more positive than the cathode (forward). Reverse bias blocks current.",
        ["learn.project.diodeDirection.lesson2.title"] = "Orientation matters",
        ["learn.project.diodeDirection.lesson2.body"] = "Swap the diode and the LED stays dark — polarity is not optional.",
        ["learn.project.diodeDirection.quiz.q1.prompt"] = "Forward bias means…",
        ["learn.project.diodeDirection.quiz.q1.a"] = "Anode more positive than cathode",
        ["learn.project.diodeDirection.quiz.q1.b"] = "Cathode more positive always",
        ["learn.project.diodeDirection.quiz.q1.c"] = "No voltage ever",
        ["learn.project.diodeDirection.quiz.q1.explain"] = "Conventional current can flow anode→cathode when forward.",
        ["learn.project.diodeDirection.quiz.q2.prompt"] = "If you reverse the diode in this sample…",
        ["learn.project.diodeDirection.quiz.q2.a"] = "LED gets brighter",
        ["learn.project.diodeDirection.quiz.q2.b"] = "LED stays dark (blocked)",
        ["learn.project.diodeDirection.quiz.q2.c"] = "Ground disappears",
        ["learn.project.diodeDirection.quiz.q2.explain"] = "Reverse bias blocks the series path.",
        ["learn.project.diodeDirection.quiz.q3.prompt"] = "The series resistor still…",
        ["learn.project.diodeDirection.quiz.q3.a"] = "Stores charge like a capacitor",
        ["learn.project.diodeDirection.quiz.q3.b"] = "Removes the need for ground",
        ["learn.project.diodeDirection.quiz.q3.c"] = "Limits current when the diode conducts",
        ["learn.project.diodeDirection.quiz.q3.explain"] = "Protects the LED in the forward path.",
        ["learn.project.diodeDirection.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.diodeDirection.challenge.c2.label"] = "LED conducts above ~1 mA.",
        ["learn.project.seriesParallel.lesson1.title"] = "Parallel shares voltage",
        ["learn.project.seriesParallel.lesson1.body"] = "Both LED branches see the same supply voltage. Each branch has its own current set by its series R.",
        ["learn.project.seriesParallel.lesson2.title"] = "Currents add",
        ["learn.project.seriesParallel.lesson2.body"] = "Total supply current is roughly the sum of the branch currents — more branches, more load on the battery.",
        ["learn.project.seriesParallel.quiz.q1.prompt"] = "In this parallel sample, both LEDs see…",
        ["learn.project.seriesParallel.quiz.q1.a"] = "Approximately the same supply voltage",
        ["learn.project.seriesParallel.quiz.q1.b"] = "Half the voltage always",
        ["learn.project.seriesParallel.quiz.q1.c"] = "Zero voltage",
        ["learn.project.seriesParallel.quiz.q1.explain"] = "Parallel branches share the rail voltage.",
        ["learn.project.seriesParallel.quiz.q2.prompt"] = "If you open one branch…",
        ["learn.project.seriesParallel.quiz.q2.a"] = "The other branch also always dies",
        ["learn.project.seriesParallel.quiz.q2.b"] = "The other branch can still light",
        ["learn.project.seriesParallel.quiz.q2.c"] = "Ground vanishes",
        ["learn.project.seriesParallel.quiz.q2.explain"] = "Independent paths — one open does not kill the other.",
        ["learn.project.seriesParallel.quiz.q3.prompt"] = "Total battery current roughly…",
        ["learn.project.seriesParallel.quiz.q3.a"] = "Equals the smaller branch only",
        ["learn.project.seriesParallel.quiz.q3.b"] = "Is always zero",
        ["learn.project.seriesParallel.quiz.q3.c"] = "Adds the branch currents",
        ["learn.project.seriesParallel.quiz.q3.explain"] = "Parallel loads stack current at the supply.",
        ["learn.project.seriesParallel.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.seriesParallel.challenge.c2.label"] = "At least one LED conducts above ~1 mA.",
        ["learn.project.seriesLeds.lesson1.title"] = "Same current",
        ["learn.project.seriesLeds.lesson1.body"] = "In series, one current flows through R and both LEDs. There is no independent branch current.",
        ["learn.project.seriesLeds.lesson2.title"] = "Voltages add",
        ["learn.project.seriesLeds.lesson2.body"] = "Each LED drops ~Vf. Two series LEDs need more supply headroom than one — that is why this sample uses 9 V.",
        ["learn.project.seriesLeds.quiz.q1.prompt"] = "Series LEDs share…",
        ["learn.project.seriesLeds.quiz.q1.a"] = "The same current",
        ["learn.project.seriesLeds.quiz.q1.b"] = "Independent currents always",
        ["learn.project.seriesLeds.quiz.q1.c"] = "No resistor ever",
        ["learn.project.seriesLeds.quiz.q1.explain"] = "One loop current through every series part.",
        ["learn.project.seriesLeds.quiz.q2.prompt"] = "Compared with parallel branches…",
        ["learn.project.seriesLeds.quiz.q2.a"] = "Series needs more total voltage for the same Vf stack",
        ["learn.project.seriesLeds.quiz.q2.b"] = "Series always uses less voltage",
        ["learn.project.seriesLeds.quiz.q2.c"] = "Ground is optional",
        ["learn.project.seriesLeds.quiz.q2.explain"] = "Vf drops add along the string.",
        ["learn.project.seriesLeds.quiz.q3.prompt"] = "If one series LED opens…",
        ["learn.project.seriesLeds.quiz.q3.a"] = "The other still lights alone",
        ["learn.project.seriesLeds.quiz.q3.b"] = "Nothing changes",
        ["learn.project.seriesLeds.quiz.q3.c"] = "The whole string goes dark",
        ["learn.project.seriesLeds.quiz.q3.explain"] = "An open breaks the single loop.",
        ["learn.project.seriesLeds.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.seriesLeds.challenge.c2.label"] = "LED conducts above ~1 mA.",
        ["learn.project.timeConstant.lesson1.title"] = "τ ≈ R×C",
        ["learn.project.timeConstant.lesson1.body"] = "One time constant is the characteristic rise/fall scale of an RC network.",
        ["learn.project.timeConstant.lesson2.title"] = "By eye on the scope",
        ["learn.project.timeConstant.lesson2.body"] = "You do not need a calculator for intuition — stretch R or C and the curve follows.",
        ["learn.project.timeConstant.quiz.q1.prompt"] = "τ is roughly…",
        ["learn.project.timeConstant.quiz.q1.a"] = "R × C",
        ["learn.project.timeConstant.quiz.q1.b"] = "R / C",
        ["learn.project.timeConstant.quiz.q1.c"] = "C only",
        ["learn.project.timeConstant.quiz.q1.explain"] = "Product of resistance and capacitance.",
        ["learn.project.timeConstant.quiz.q2.prompt"] = "To stretch the rise, you can…",
        ["learn.project.timeConstant.quiz.q2.a"] = "Increase R or C",
        ["learn.project.timeConstant.quiz.q2.b"] = "Only decrease V",
        ["learn.project.timeConstant.quiz.q2.c"] = "Remove C",
        ["learn.project.timeConstant.quiz.q2.explain"] = "Larger τ slows the curve.",
        ["learn.project.timeConstant.quiz.q3.prompt"] = "Which mode shows τ?",
        ["learn.project.timeConstant.quiz.q3.a"] = "DC only",
        ["learn.project.timeConstant.quiz.q3.b"] = "Import JSON",
        ["learn.project.timeConstant.quiz.q3.c"] = "Transient",
        ["learn.project.timeConstant.quiz.q3.explain"] = "Watch voltage vs time.",
        ["learn.project.timeConstant.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.timeConstant.challenge.c2.label"] = "Use Transient analysis.",
        ["learn.project.pulseRc.lesson1.title"] = "Edges meet RC",
        ["learn.project.pulseRc.lesson1.body"] = "A fast pulse through R into C cannot jump instantly — the node rises and falls with τ.",
        ["learn.project.pulseRc.lesson2.title"] = "Pulse parameters",
        ["learn.project.pulseRc.lesson2.body"] = "Delay, width, and levels set the stimulus; R and C set how faithfully the node follows.",
        ["learn.project.pulseRc.quiz.q1.prompt"] = "RC on a pulse mainly…",
        ["learn.project.pulseRc.quiz.q1.a"] = "Rounds the edges",
        ["learn.project.pulseRc.quiz.q1.b"] = "Creates RF permanently",
        ["learn.project.pulseRc.quiz.q1.c"] = "Removes ground",
        ["learn.project.pulseRc.quiz.q1.explain"] = "τ filters sharp transitions.",
        ["learn.project.pulseRc.quiz.q2.prompt"] = "Best analysis here…",
        ["learn.project.pulseRc.quiz.q2.a"] = "DC only",
        ["learn.project.pulseRc.quiz.q2.b"] = "Transient",
        ["learn.project.pulseRc.quiz.q2.c"] = "Delete wires",
        ["learn.project.pulseRc.quiz.q2.explain"] = "Time-domain edges need Transient.",
        ["learn.project.pulseRc.quiz.q3.prompt"] = "Larger C with same R…",
        ["learn.project.pulseRc.quiz.q3.a"] = "Sharpens the edge",
        ["learn.project.pulseRc.quiz.q3.b"] = "Does nothing",
        ["learn.project.pulseRc.quiz.q3.c"] = "Slows the edge more",
        ["learn.project.pulseRc.quiz.q3.explain"] = "Larger τ → slower response.",
        ["learn.project.pulseRc.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.pulseRc.challenge.c2.label"] = "Use Transient analysis.",
        ["learn.project.acRcLpf.lesson1.title"] = "Low-pass idea",
        ["learn.project.acRcLpf.lesson1.body"] = "An RC low-pass passes slower changes and attenuates fast ones.",
        ["learn.project.acRcLpf.lesson2.title"] = "AC vs Transient",
        ["learn.project.acRcLpf.lesson2.body"] = "AC mode shows steady-state response at one frequency — great for intuition, not a full Bode plot yet.",
        ["learn.project.acRcLpf.quiz.q1.prompt"] = "A low-pass attenuates…",
        ["learn.project.acRcLpf.quiz.q1.a"] = "Higher frequencies more",
        ["learn.project.acRcLpf.quiz.q1.b"] = "Only DC forever",
        ["learn.project.acRcLpf.quiz.q1.c"] = "Ground only",
        ["learn.project.acRcLpf.quiz.q1.explain"] = "Fast signals see more attenuation.",
        ["learn.project.acRcLpf.quiz.q2.prompt"] = "AC analysis here means…",
        ["learn.project.acRcLpf.quiz.q2.a"] = "Deleting C",
        ["learn.project.acRcLpf.quiz.q2.b"] = "Single-frequency response",
        ["learn.project.acRcLpf.quiz.q2.c"] = "Only burnout",
        ["learn.project.acRcLpf.quiz.q2.explain"] = "Probe magnitude at the chosen Hz.",
        ["learn.project.acRcLpf.quiz.q3.prompt"] = "Raising frequency on an LPF usually…",
        ["learn.project.acRcLpf.quiz.q3.a"] = "Raises it forever",
        ["learn.project.acRcLpf.quiz.q3.b"] = "Removes R",
        ["learn.project.acRcLpf.quiz.q3.c"] = "Lowers output magnitude",
        ["learn.project.acRcLpf.quiz.q3.explain"] = "Above cutoff, attenuation grows.",
        ["learn.project.acRcLpf.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.acRcLpf.challenge.c2.label"] = "Use AC analysis.",
        ["learn.project.ne555Play.lesson1.title"] = "One timer, many loads",
        ["learn.project.ne555Play.lesson1.body"] = "The 555 still sets the period; each LED branch is just another load on the output.",
        ["learn.project.ne555Play.lesson2.title"] = "Current budget",
        ["learn.project.ne555Play.lesson2.body"] = "More LEDs share the output — keep series resistors sensible so branches stay healthy.",
        ["learn.project.ne555Play.quiz.q1.prompt"] = "Blink rate is set mainly by…",
        ["learn.project.ne555Play.quiz.q1.a"] = "RA, RB, and CT",
        ["learn.project.ne555Play.quiz.q1.b"] = "LED color only",
        ["learn.project.ne555Play.quiz.q1.c"] = "Wire thickness",
        ["learn.project.ne555Play.quiz.q1.explain"] = "Astable timing network.",
        ["learn.project.ne555Play.quiz.q2.prompt"] = "Best mode to see blinking…",
        ["learn.project.ne555Play.quiz.q2.a"] = "Import only",
        ["learn.project.ne555Play.quiz.q2.b"] = "Transient",
        ["learn.project.ne555Play.quiz.q2.c"] = "DC forever",
        ["learn.project.ne555Play.quiz.q2.explain"] = "Time animation needs Transient.",
        ["learn.project.ne555Play.quiz.q3.prompt"] = "More LED branches usually means…",
        ["learn.project.ne555Play.quiz.q3.a"] = "Zero current always",
        ["learn.project.ne555Play.quiz.q3.b"] = "No ground needed",
        ["learn.project.ne555Play.quiz.q3.c"] = "More output loading",
        ["learn.project.ne555Play.quiz.q3.explain"] = "Each branch draws current when on.",
        ["learn.project.ne555Play.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.ne555Play.challenge.c2.label"] = "Use Transient analysis.",
        ["learn.project.ne555Pot.lesson1.title"] = "Pot as timing R",
        ["learn.project.ne555Pot.lesson1.body"] = "A potentiometer can stand in for part of the RA/RB network so you can sweep period live.",
        ["learn.project.ne555Pot.lesson2.title"] = "Teaching model",
        ["learn.project.ne555Pot.lesson2.body"] = "This is still an astable 555 — the pot is just a convenient knob on τ.",
        ["learn.project.ne555Pot.quiz.q1.prompt"] = "The pot here mainly adjusts…",
        ["learn.project.ne555Pot.quiz.q1.a"] = "Blink period",
        ["learn.project.ne555Pot.quiz.q1.b"] = "Battery chemistry",
        ["learn.project.ne555Pot.quiz.q1.c"] = "Wire color",
        ["learn.project.ne555Pot.quiz.q1.explain"] = "Timing resistance changes period.",
        ["learn.project.ne555Pot.quiz.q2.prompt"] = "Analysis mode for blinking…",
        ["learn.project.ne555Pot.quiz.q2.a"] = "SEO only",
        ["learn.project.ne555Pot.quiz.q2.b"] = "Transient",
