        ["learn.project.ne555Pot.quiz.q3.b"] = "I2C address",
        ["learn.project.ne555Pot.quiz.q3.c"] = "Effective timing R",
        ["learn.project.ne555Pot.quiz.q3.explain"] = "R in the RC timing path.",
        ["learn.project.ne555Pot.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.ne555Pot.challenge.c2.label"] = "Use Transient analysis.",
        ["learn.project.pinInput.lesson1.title"] = "Outputs vs inputs",
        ["learn.project.pinInput.lesson1.body"] = "A digital output actively drives HIGH/LOW. An input only senses — it needs a defined voltage.",
        ["learn.project.pinInput.lesson2.title"] = "Floating is bad",
        ["learn.project.pinInput.lesson2.body"] = "An undriven input can read randomly; pull-ups/pull-downs fix that habit early.",
        ["learn.project.pinInput.quiz.q1.prompt"] = "A floating input is…",
        ["learn.project.pinInput.quiz.q1.a"] = "Undefined / noisy",
        ["learn.project.pinInput.quiz.q1.b"] = "Always safe HIGH",
        ["learn.project.pinInput.quiz.q1.c"] = "A battery",
        ["learn.project.pinInput.quiz.q1.explain"] = "No defined drive → unreliable level.",
        ["learn.project.pinInput.quiz.q2.prompt"] = "Pull-down resistor purpose…",
        ["learn.project.pinInput.quiz.q2.a"] = "Increase RF forever",
        ["learn.project.pinInput.quiz.q2.b"] = "Define LOW when switch open",
        ["learn.project.pinInput.quiz.q2.c"] = "Burn LEDs",
        ["learn.project.pinInput.quiz.q2.explain"] = "Holds the node at a known level.",
        ["learn.project.pinInput.quiz.q3.prompt"] = "Arduino LED sample pin is acting as…",
        ["learn.project.pinInput.quiz.q3.a"] = "An I2C clock only",
        ["learn.project.pinInput.quiz.q3.b"] = "A fuse",
        ["learn.project.pinInput.quiz.q3.c"] = "An output driver",
        ["learn.project.pinInput.quiz.q3.explain"] = "It sources/sinks the LED path.",
        ["learn.project.pinInput.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.pinInput.challenge.c2.label"] = "LED conducts above ~1 mA.",
        ["learn.project.i2cAddress.lesson1.title"] = "Shared wires",
        ["learn.project.i2cAddress.lesson1.body"] = "I²C shares SDA/SCL; the address selects which chip should listen.",
        ["learn.project.i2cAddress.lesson2.title"] = "0x3C vs 0x3D",
        ["learn.project.i2cAddress.lesson2.body"] = "Many SSD1306 modules use 0x3C; some straps select 0x3D — same idea, different ID.",
        ["learn.project.i2cAddress.quiz.q1.prompt"] = "I²C address selects…",
        ["learn.project.i2cAddress.quiz.q1.a"] = "Which device talks/listens",
        ["learn.project.i2cAddress.quiz.q1.b"] = "Wire thickness",
        ["learn.project.i2cAddress.quiz.q1.c"] = "LED color",
        ["learn.project.i2cAddress.quiz.q1.explain"] = "Multiple chips share the bus.",
        ["learn.project.i2cAddress.quiz.q2.prompt"] = "Pull-ups on SDA/SCL…",
        ["learn.project.i2cAddress.quiz.q2.a"] = "Are optional decoration",
        ["learn.project.i2cAddress.quiz.q2.b"] = "Are required for open-drain I²C",
        ["learn.project.i2cAddress.quiz.q2.c"] = "Replace ground",
        ["learn.project.i2cAddress.quiz.q2.explain"] = "Idle lines are pulled high.",
        ["learn.project.i2cAddress.quiz.q3.prompt"] = "Two OLEDs on one bus need…",
        ["learn.project.i2cAddress.quiz.q3.a"] = "Identical shorts",
        ["learn.project.i2cAddress.quiz.q3.b"] = "No VCC",
        ["learn.project.i2cAddress.quiz.q3.c"] = "Different addresses",
        ["learn.project.i2cAddress.quiz.q3.explain"] = "Unique IDs avoid collisions.",
        ["learn.project.i2cAddress.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.i2cAddress.challenge.c2.label"] = "Wiring passes circuit checks.",
        ["learn.project.spiVsI2c.lesson1.title"] = "Two common buses",
        ["learn.project.spiVsI2c.lesson1.body"] = "I²C uses two shared wires (SDA/SCL) plus addresses. SPI uses dedicated chip-select lines and usually a clock + data pair — faster, but more pins.",
        ["learn.project.spiVsI2c.lesson2.title"] = "When which",
        ["learn.project.spiVsI2c.lesson2.body"] = "I²C wins for few pins and many addressable sensors. SPI wins for higher bandwidth displays and when you can afford CS lines.",
        ["learn.project.spiVsI2c.quiz.q1.prompt"] = "I²C typically needs…",
        ["learn.project.spiVsI2c.quiz.q1.a"] = "Two shared wires plus addresses",
        ["learn.project.spiVsI2c.quiz.q1.b"] = "One CS per clock forever",
        ["learn.project.spiVsI2c.quiz.q1.c"] = "No pull-ups ever",
        ["learn.project.spiVsI2c.quiz.q1.explain"] = "SDA/SCL are shared; address selects the chip.",
        ["learn.project.spiVsI2c.quiz.q2.prompt"] = "SPI usually adds…",
        ["learn.project.spiVsI2c.quiz.q2.a"] = "Nothing beyond I²C",
        ["learn.project.spiVsI2c.quiz.q2.b"] = "A chip-select (CS) per device",
        ["learn.project.spiVsI2c.quiz.q2.c"] = "Only a single global address",
        ["learn.project.spiVsI2c.quiz.q2.explain"] = "CS picks the slave without an address field.",
        ["learn.project.spiVsI2c.quiz.q3.prompt"] = "Choose I²C when you want…",
        ["learn.project.spiVsI2c.quiz.q3.a"] = "Maximum wire count always",
        ["learn.project.spiVsI2c.quiz.q3.b"] = "No shared bus ever",
        ["learn.project.spiVsI2c.quiz.q3.c"] = "Few pins and many addressable devices",
        ["learn.project.spiVsI2c.quiz.q3.explain"] = "Addressing trades speed for wiring simplicity.",
        ["learn.project.spiVsI2c.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.spiVsI2c.challenge.c2.label"] = "Wiring passes circuit checks.",
        ["learn.project.i2cMultiSlave.lesson1.title"] = "One bus, many chips",
        ["learn.project.i2cMultiSlave.lesson1.body"] = "SDA and SCL stay shared. Each slave listens for its own 7-bit address — wiring does not fork a new bus per chip.",
        ["learn.project.i2cMultiSlave.lesson2.title"] = "Collision rules",
        ["learn.project.i2cMultiSlave.lesson2.body"] = "Two devices with the same address fight. Unique addresses (or an address translator) keep the shared wires peaceful.",
        ["learn.project.i2cMultiSlave.quiz.q1.prompt"] = "Adding a second I²C slave usually…",
        ["learn.project.i2cMultiSlave.quiz.q1.a"] = "Reuses the same SDA/SCL wires",
        ["learn.project.i2cMultiSlave.quiz.q1.b"] = "Needs a second battery ground only",
        ["learn.project.i2cMultiSlave.quiz.q1.c"] = "Removes all pull-ups",
        ["learn.project.i2cMultiSlave.quiz.q1.explain"] = "The bus is shared; addresses distinguish chips.",
        ["learn.project.i2cMultiSlave.quiz.q2.prompt"] = "Identical addresses on one bus…",
        ["learn.project.i2cMultiSlave.quiz.q2.a"] = "Are fine forever",
        ["learn.project.i2cMultiSlave.quiz.q2.b"] = "Cause collisions / unreliable replies",
        ["learn.project.i2cMultiSlave.quiz.q2.c"] = "Increase VCC automatically",
        ["learn.project.i2cMultiSlave.quiz.q2.explain"] = "Both chips may respond to the same ID.",
        ["learn.project.i2cMultiSlave.quiz.q3.prompt"] = "Pull-ups on a multi-slave bus…",
        ["learn.project.i2cMultiSlave.quiz.q3.a"] = "Are still required for open-drain lines",
        ["learn.project.i2cMultiSlave.quiz.q3.b"] = "Must be deleted",
        ["learn.project.i2cMultiSlave.quiz.q3.c"] = "Replace chip addresses",
        ["learn.project.i2cMultiSlave.quiz.q3.explain"] = "Idle SDA/SCL still need to float high.",
        ["learn.project.i2cMultiSlave.challenge.c1.label"] = "Simulation completes without errors.",
        ["learn.project.i2cMultiSlave.challenge.c2.label"] = "Wiring passes circuit checks.",
        ["learn.project.bjtVsMos.lesson1.title"] = "BJT mental model",
        ["learn.project.bjtVsMos.lesson1.body"] = "A small base current enables a larger collector current — current controlled switch.",
        ["learn.project.bjtVsMos.lesson2.title"] = "MOSFET mental model",
