    /// <summary>Czech translations (partial: UI + basics module). Missing keys fall back to English on the client.</summary>
    public static readonly IReadOnlyDictionary<string, string> Czech = new Dictionary<string, string>
    {
        ["shell.brand"] = "Electro Lab",
        ["shell.nav.lab"] = "Laboratoř",
        ["shell.nav.learn"] = "Výuka",
        ["shell.nav.account"] = "Účet",
        ["shell.language"] = "Jazyk",
        ["lab.title"] = "Laboratoř obvodů",
        ["lab.fromLearn"] = "Z výuky:",
        ["lab.backToLearnSteps"] = "← Zpět k lekci",
        ["lab.intro"] = "Nakreslete schéma, propojte vývody a spusťte DC, přechodovou nebo AC analýzu.",
        ["lab.hint"] = "Přetáhněte součástky z palety na plátno (nebo klikněte na součástku a pak na plátno). Spojte vývody vodiči a spusťte simulaci. Když obvod projde, zelené čárky na vodičích ukazují tekoucí proud. LED svítí naplno kolem 20 mA; nad ~35 mA shoří a stane se rozpojeným obvodem (grafika ohně), dokud ji nevyměníte. Vždy použijte dostatečný sériový odpor. Tažením po prázdném místě vyberete více součástek; tažením vybrané součástky posunete celou skupinu. Ctrl/Cmd-klik nebo Ctrl/Cmd-tažení přidává do výběru. Klikněte na vodič a stiskněte Delete. Příklady se otevírají v nové záložce. Ctrl+D duplikuje; Ctrl+C/V kopíruje a vkládá. Kolečkem přibližujete; Shift-tažením posouváte. Tažením po osciloskopu posouváte čas.",
        ["lab.hint.challenge"] = "Postavte obvod popsaný ve výuce z prázdného plátna. Umístěte součástky, propojte vývody, zvolte správnou analýzu, spusťte a pak klikněte na Zkontrolovat.",
        ["lab.hint.wire"] = "Režim vodičů: klikněte na vývod (modrý náhled sleduje kurzor), pak na další vývod, nebo klikněte na existující vodič a vznikne odbočka. V režimu Výběr můžete vodič tažením přetvarovat; dvojklik obnoví automatické vedení. Kliknutím na prázdné plátno akci zrušíte.",
        ["lab.hint.probe"] = "Režim sondy: klikněte na tělo součástky pro proud (mA) nebo na uzel či vodič pro napětí (V). Hodnota se zobrazí ve stavovém řádku. V přechodové analýze posouvejte čas na osciloskopu, sonda i plátno ho sledují.",
        ["lab.hint.led"] = "LED se sériovým odporem: spusťte DC. Proud teče baterie → rezistor → LED → zem. Zkuste snižovat odpor, dokud LED neshoří (~35 mA), pak ji vyměňte a vraťte ~220 Ω.",
        ["lab.hint.ledFade"] = "Pohasínání LED: 1) Nechte spínač sepnutý a spusťte. Kondenzátor se nabije a LED svítí. 2) Zrušte Sepnuto. 3) Spusťte znovu. Kondenzátor se vybíjí přes rezistor a LED pohasíná. Po rozepnutí spínače teče proud jen na straně LED (to je v pořádku).",
        ["lab.hint.rc"] = "Nabíjení RC: přechodová analýza od 0 V. Posouvejte čas na osciloskopu a sledujte, jak napětí kondenzátoru roste přes R k napájení. Porovnejte τ ≈ R·C s křivkou.",
        ["lab.hint.pot"] = "Dělič s potenciometrem: spusťte DC a měňte Jezdec (0–1) v inspektoru. Napětí středu sleduje jezdec. Odečtěte ho sondou.",
        ["lab.hint.pulse"] = "Pulz do RC: přechodová analýza. Pulzní zdroj skočí nahoru a zase dolů. Projděte hrany a sledujte nabíjení a vybíjení kondenzátoru.",
        ["lab.hint.opamp"] = "Invertující zesilovač s operačním zesilovačem (výukový model, napájení ±15 V). Spusťte DC, zisk ≈ −Rf/Rin. Změřte výstup; zkuste změnit Rf, Rin nebo meze napájení.",
        ["lab.hint.ac"] = "AC RC dolní propust: nastavte analýzu AC a zvolte frekvenci. Pod mezní frekvencí vidí zátěž větší část zdroje; vysoko nad ní kondenzátor odvádí střídavou složku do země. Nelineární součástky jsou v AC rozpojené.",
        ["lab.hint.bjt"] = "Spínač LED s BC547: spusťte DC se sepnutým S1. Proud báze sepne Q1 a LED svítí. Rozepněte S1 a spusťte znovu, LED zhasne. Změřte AM1 pro kolektorový proud; zkuste změnit RB.",
        ["lab.hint.relay"] = "Relé + dioda: spusťte DC se sepnutým S1. Cívka přitáhne K1 a LED svítí přes kontakty. Dfly je ochranná dioda přes cívku (katoda na +). Rozepněte S1: kontakty se rozpojí a LED zhasne.",
        ["lab.hint.nmos"] = "Spínač LED s NMOS: spusťte DC se sepnutým S1. Gate je nahoře, LED svítí. Rozepněte S1 (RPD stáhne gate dolů) a spusťte znovu, LED zhasne. Nadproud drainem nebo |Vgs| ≳ 20 V M1 zničí.",
        ["lab.hint.ne555"] = "NE555 astabilní: přechodová analýza běží automaticky, tři LED blikají z OUT. Sledujte přehrávání nebo OUT / CT na osciloskopu. Příliš malé R1–R3 nebo Vcc nad ~18 V časovač zničí.",
        ["lab.hint.ne555Pot"] = "NE555 + potenciometr: přechodová analýza běží automaticky, jedna LED bliká z OUT. Změňte Jezdec POT1, změní se Rb a rychlost blikání (vyšší → pomaleji).",
        ["lab.hint.christmasTree"] = "Vánoční stromek s NE555: přechodová analýza běží automaticky, deset LED bliká v pyramidě z OUT. Sledujte přehrávání nebo změřte libovolnou LED. Příliš malé R1–R10 nebo vysoké Vcc časovač zničí.",
        ["lab.hint.pushbutton"] = "LED s tlačítkem: držte BTN1 na plátně nebo ovládání Držet v inspektoru. LED svítí, dokud je stisknuto.",
        ["lab.hint.ldr"] = "Noční světlo s LDR: spusťte DC. Při nízkém Světle LED svítí. Zvyšte Světlo na LDR1 k 1 a spusťte znovu: gate klesne a LED zhasne.",
        ["lab.hint.buzzer"] = "Bzučák + tlačítko: držte BTN1 na plátně nebo v inspektoru. BZ1 odebírá proud (výukový „zvuk“). Pusťte, ticho.",
        ["lab.hint.motor"] = "NMOS + motor: spusťte DC se sepnutým S1, motorem teče proud; Dfly je ochranná dioda. Rozepněte S1, motor se zastaví.",
        ["lab.hint.arduino"] = "LED na Arduinu: D2 je výukový digitální pin (Výstup / HIGH). Spusťte DC, LED svítí. Nastavte úroveň LOW nebo režim Vstup a spusťte znovu.",
        ["lab.hint.i2cOled"] = "I2C OLED: spusťte DC. S napájeným VCC ukáže OLED1 „Hello“ a SDA/SCL sedí přes pull-upy blízko 5 V. Změřte sběrnici; odstraňte pull-up a sledujte pokles klidové úrovně.",
        ["lab.hint.halfWave"] = "Jednocestný usměrňovač: spusťte přechodovou analýzu, periody běží na plátně. Proud teče jen v kladných půlperiodách; v záporných dioda blokuje. Změřte R1.",
        ["lab.hint.bridge"] = "Můstkový usměrňovač: spusťte přechodovou analýzu, periody běží. Obě půlperiody napájejí zátěž pulzujícím stejnosměrným napětím (čtyři diody).",
        ["lab.hint.filterCap"] = "Filtrační kondenzátor: spusťte přechodovou analýzu, periody běží; C1 vyhlazuje usměrněné špičky. Zkuste menší C nebo větší zátěž a sledujte zvlnění.",
        ["lab.hint.zener"] = "Zenerův stabilizátor: spusťte DC a změřte JM. Napětí by mělo sedět u Vz (~5,1 V) i při 12 V napájení.",
        ["lab.hint.vreg7805"] = "Stabilizátor 7805: spusťte DC. OUT má být ~5 V při 12 V na vstupu. Snižte Vin k úbytku a sledujte, jak regulace selže.",
        ["lab.hint.reversePolarity"] = "Dioda proti přepólování: spusťte DC, LED svítí. Otočte polaritu baterie: sériová dioda obrácené zapojení zablokuje.",
        ["lab.hint.fuseProtect"] = "Pojistka: spusťte DC s rozepnutým S1, bezpečný proud přes RL. Sepněte S1 a spusťte, F1 se přepálí (zkrat přes RL). Vyměňte F1 (S1 se rozepne automaticky) a spusťte znovu.",
        ["lab.hint.ripple"] = "Zvlnění: spusťte přechodovou analýzu a změřte JT. Zbytková střídavá složka na filtrovaném DC je zvlnění. Menší C / větší zátěž → větší zvlnění.",
        ["lab.hint.buck"] = "Snižující měnič: spusťte přechodovou analýzu, PWM běží na plátně. Sepnuto: proud přes M1→L1; rozepnuto: proud teče přes Dfly. Vodiče gate zůstávají v klidu. Změřte JO; změnou šířky pulzu (střídy) změníte střední hodnotu.",
        ["lab.hint.boost"] = "Zvyšující měnič: spusťte přechodovou analýzu, PWM běží na plátně. Sepnuto: L1 se nabíjí přes M1; rozepnuto: dioda napájí zátěž. Vodiče gate / VP1 zůstávají v klidu. Změřte JO; delší sepnutí uloží do L1 více energie.",
        ["lab.hint.diodeDirection"] = "Směr diody: spusťte DC, LED svítí, když je D1 v propustném směru. Otočte diodu a zablokuje.",
        ["lab.hint.seriesParallel"] = "Paralelní LED: spusťte DC, obě větve svítí. Změňte jeden R; ztlumí se jen ta větev.",
        ["lab.hint.seriesLeds"] = "Sériové LED: spusťte DC, oběma teče stejný proud. Porovnejte s příkladem paralelních větví.",
        ["lab.hint.opampFollower"] = "Napěťový sledovač: spusťte DC, Vout ≈ Vin. Změřte JO a VIN; změňte VIN nebo RL a sledujte, jak buffer drží napětí.",
        ["lab.hint.opampNonInv"] = "Neinvertující zesilovač: spusťte DC, zisk ≈ 1+Rf/Rg. Změřte OUT; zvyšujte Vin, dokud výukové napájení neomezí.",
        ["lab.hint.opampComparator"] = "Komparátor: spusťte DC a pohybujte Jezdcem POT1. OUT skáče k napájení nahoru/dolů proti děliči ~2,5 V; LED ho sleduje.",
        ["lab.hint.opampSchmitt"] = "Schmittův obvod: spusťte DC a pomalu přejíždějte POT1 nahoru a dolů. Body překlopení se liší (hystereze) díky kladné zpětné vazbě.",
        ["lab.hint.opampSumming"] = "Sčítací zesilovač: spusťte DC, Vout ≈ −(V1+V2) při shodných rezistorech. Změňte V2 a ověřte součet.",
        ["lab.hint.opampIntegrator"] = "Integrátor: spusťte přechodovou analýzu (~30 ms). OUT roste, dokud je pulz nahoře. Sledujte OUT / CF na osciloskopu.",
        ["lab.hint.opampDifferentiator"] = "Derivátor: spusťte přechodovou analýzu (~30 ms). OUT vytvoří špičky na hranách pulzu. Sledujte OUT kolem náběžné a sestupné hrany.",
        ["lab.hint.opampActiveFilter"] = "Aktivní dolní propust: spusťte AC při ~100 Hz a pak ~10 kHz. Nízké frekvence projdou, vysoké klesnou. Změnou Cf/Rf posunete fc.",
