        ["lab.modelNote.op_amp"] = "Výukový model: zdroj napětí s konečným ziskem omezený na vMax/vMin (výchozí ±15 V). V AC zůstává lineární (bez omezení).",
        ["lab.modelNote.bjt_npn"] = "Výukový model: dioda báze + malý vnitřní rb + odpor kolektor–emitor v sepnutém stavu (ne SPICE). Použijte externí odpor báze; Ib nad ~25 mA tranzistor zničí.",
        ["lab.modelNote.bc547"] = "NPN typu BC547 (TO-92). Výukový spínací model: použijte odpor báze; Ib nad ~25 mA součástku zničí (není to katalogový/SPICE tranzistor).",
        ["lab.modelNote.nmos"] = "Výukový N-kanálový MOSFET spínač (Vgs ≥ vth → Ron). Nadproud drainem (~0,5 A) nebo |Vgs| ≳ 20 V ho zničí. Není to SPICE model úrovně 1.",
        ["lab.modelNote.ne555"] = "Výukový NE555: SR klopný obvod thr/trig, otevřený drain discharge, výstup totem-pole. Výstup ≳ 200 mA nebo Vcc ≳ 18 V ho zničí. Behaviorální model, ne úplný bipolární 555.",
        ["lab.modelNote.pushbutton"] = "Okamžikový kontakt (výukový). Držte tlačítko na plátně nebo v inspektoru pro sepnutí. Stejný elektrický model jako spínač.",
        ["lab.modelNote.ldr"] = "Fotorezistor: Světlo 0 → tma (rDark), 1 → světlo (rLight). Použijte v děliči pro snímání světla. Trvalý výkon nad ~¼ W ho zničí.",
        ["lab.modelNote.buzzer"] = "Výukový piezobzučák: vede, když je propustné napětí ≥ vf (jako LED). Proud znamená „zvuk“. Nad ~50 mA se zničí.",
        ["lab.modelNote.dc_motor"] = "Výukový DC motor jako zátěž: při |V| ≥ vStart odebírá proud přes ron. Použijte ochrannou diodu. Trvalý proud nad ~0,4 A ho zničí.",
        ["lab.modelNote.arduino_dio"] = "Výukový digitální pin Arduina: Výstup budí vHigh nebo 0 V přes ron; Vstup je rozpojený (přidejte pull-up/down). Není to celý mikrokontrolér.",
        ["lab.modelNote.arduino_i2c"] = "Výukový host Arduino Wire: napájení 5V proti GND; SDA/SCL jsou v klidu otevřený kolektor (vysoká impedance). Přidejte externí pull-upy, stejná lekce zapojení jako u skutečného I2C. Nesimuluje protokol na úrovni bitů.",
        ["lab.modelNote.ssd1306"] = "Výukový I2C OLED SSD1306: zátěž na VCC + SDA/SCL s vysokou impedancí. Pro lekci zvolte adresu 0x3C/0x3D; model nedekóduje I2C provoz.",
        ["lab.modelNote.resistor"] = "Výukový rezistor ¼ W. Trvalý výkon nad ~0,25 W ho zničí.",
        ["lab.modelNote.diode"] = "Výuková křemíková dioda. Proud nad ~100 mA ji zničí.",
        ["lab.modelNote.zener"] = "Výuková Zenerova dioda: v propustném směru jako dioda; v závěrném omezuje u Vz. Katoda na stabilizovaný uzel, anoda na zem.",
        ["lab.modelNote.fuse"] = "Výuková pojistka: malý sériový Ron, dokud |I| nepřekročí iMax, pak se rozpojí, dokud ji nevyměníte.",
        ["lab.modelNote.vreg7805"] = "Výukový 7805: OUT drží ~vOut proti GND, když Vin ≥ vOut + úbytek; jinak se chová jako sériový Ron.",
        ["lab.modelNote.capacitor"] = "Výukový kondenzátor. Napětí nad vmax (výchozí 16 V) ho zničí.",
        ["lab.modelNote.ammeter"] = "Sériový ampérmetr. Proud nad ~200 mA měřidlo zničí (nezapojujte přes zdroj).",
        ["lab.modelNote.relay"] = "Výukové relé SPST: odpor cívky mezi +/−; kontakty sepnou, když |Vcívky| ≥ přítah (nebo Sepnuto / časová osa).",
        ["lab.modelNote.battery"] = "Ideální stejnosměrný zdroj s volitelným sériovým ESR. Dbejte na polaritu. Zkrat p na n je hlášen jako chyba.",
        ["lab.modelNote.ac_source"] = "Fázorový střídavý zdroj pro AC analýzu (amplituda/fáze). Nastavte Frekvenci pro sinusový průběh v přechodové analýze; 0 Hz znamená jen DC.",
        ["lab.modelNote.led"] = "Výuková LED: vede, když je propustné napětí ≥ vf. Proud ji rozsvítí; trvalý proud nad ~25 mA ji zničí. Vždy použijte sériový rezistor.",
        ["lab.modelNote.switch"] = "Výukový spínač SPST. Sepnuto/rozepnuto může v přechodové analýze sledovat časy Rozepnout v / Sepnout v.",
        ["lab.modelNote.inductor"] = "Výuková cívka. Rozpojení smyčky s proudem může vyvolat napěťovou špičku. U induktivních zátěží použijte ochrannou diodu.",
        ["lab.modelNote.potentiometer"] = "Třívývodový dělič (nebo reostat se dvěma vývody). Poloha jezdce 0 → 1 jde od konce a ke konci b.",
        ["lab.modelNote.pulse_source"] = "Časovaný pulz pro přechodové úlohy: začne na V1, po Zpoždění skočí na V2 na dobu Šířky pulzu (volitelná Perioda pro opakování).",
        ["lab.modelNote.voltmeter"] = "Ideální napěťová sonda (jen ve schématu, není v netlistu). Umístěte přes uzel, který chcete číst; neodebírá proud.",
