        ["learn.project.ledFade.labGoal"] = "Postavte obvod pohasínání: baterie a spínač napájejí kondenzátor, rezistor s LED se vrací ke kondenzátoru. Spusťte přechodovou analýzu se sepnutým spínačem, aby se nabil.",
        ["learn.project.ledFade.lesson1.title"] = "Uložit a uvolnit",
        ["learn.project.ledFade.lesson1.body"] = "Kondenzátor se předtím nabil; teď se vybíjí přes rezistor a LED slábne.",
        ["learn.project.ledFade.lesson2.title"] = "Stejná myšlenka RC",
        ["learn.project.ledFade.lesson2.body"] = "Dobu pohasínání stále řídí R×C. Mění se jen zátěž (LED), na které to pozorujete.",
        ["learn.project.ledFade.quiz.q1.prompt"] = "LED slábne několik sekund, protože…",
        ["learn.project.ledFade.quiz.q1.a"] = "C se vybíjí přes R.",
        ["learn.project.ledFade.quiz.q1.b"] = "baterie se okamžitě vybije.",
        ["learn.project.ledFade.quiz.q1.c"] = "LED změní polaritu.",
        ["learn.project.ledFade.quiz.q1.explain"] = "Uložený náboj odtéká vybíjecí cestou.",
        ["learn.project.ledFade.quiz.q2.prompt"] = "Aby pohasínání trvalo déle, obvykle…",
        ["learn.project.ledFade.quiz.q2.a"] = "hodně zmenšíte C.",
        ["learn.project.ledFade.quiz.q2.b"] = "zvětšíte C nebo vybíjecí R.",
        ["learn.project.ledFade.quiz.q2.c"] = "odeberete zem.",
        ["learn.project.ledFade.quiz.q2.explain"] = "Větší τ → pomalejší pokles napětí.",
        ["learn.project.ledFade.quiz.q3.prompt"] = "Nejlepší analýza je tady…",
        ["learn.project.ledFade.quiz.q3.a"] = "DC.",
        ["learn.project.ledFade.quiz.q3.b"] = "přechodová.",
        ["learn.project.ledFade.quiz.q3.c"] = "AC.",
        ["learn.project.ledFade.quiz.q3.explain"] = "Sledujte napětí a proud v čase.",
        ["learn.project.pulseRc.title"] = "Hrany pulzu do RC",
        ["learn.project.pulseRc.summary"] = "Budte RC pulzním zdrojem a sledujte, jak se hrany zaoblují. Most mezi digitálními hranami a analogovým časováním.",
        ["learn.project.pulseRc.step1"] = "Otevřete příklad s pulzem do RC a spusťte přechodovou analýzu.",
        ["learn.project.pulseRc.step2"] = "Změřte uzel kondenzátoru. Hrany jsou oproti pulzu měkčí.",
        ["learn.project.pulseRc.step3"] = "Změňte R nebo C a porovnejte rychlost hran.",
        ["learn.project.pulseRc.step4"] = "Zkuste širší pulz a sledujte, jak se kondenzátor blíží horní úrovni.",
        ["learn.project.pulseRc.openLab"] = "Otevřít v laboratoři",
        ["learn.project.pulseRc.labGoal"] = "Přiveďte pulzní zdroj na dvojici rezistor–kondenzátor proti zemi. Spusťte přechodovou analýzu a sledujte, jak RC zaobluje hrany pulzu.",
        ["learn.project.pulseRc.lesson1.title"] = "Hrany potkají RC",
        ["learn.project.pulseRc.lesson1.body"] = "Rychlý pulz přes R do C nemůže skočit okamžitě. Uzel roste a klesá s τ.",
        ["learn.project.pulseRc.lesson2.title"] = "Parametry pulzu",
        ["learn.project.pulseRc.lesson2.body"] = "Zpoždění, šířka a úrovně určují budicí signál; R a C určují, jak věrně ho uzel sleduje.",
        ["learn.project.pulseRc.quiz.q1.prompt"] = "RC na pulzu hlavně…",
        ["learn.project.pulseRc.quiz.q1.a"] = "zaobluje hrany.",
        ["learn.project.pulseRc.quiz.q1.b"] = "trvale vytváří rádiový signál.",
        ["learn.project.pulseRc.quiz.q1.c"] = "odstraní zem.",
        ["learn.project.pulseRc.quiz.q1.explain"] = "τ filtruje ostré přechody.",
        ["learn.project.pulseRc.quiz.q2.prompt"] = "Nejlepší analýza tady…",
        ["learn.project.pulseRc.quiz.q2.a"] = "jen DC.",
        ["learn.project.pulseRc.quiz.q2.b"] = "přechodová.",
        ["learn.project.pulseRc.quiz.q2.c"] = "smazat vodiče.",
        ["learn.project.pulseRc.quiz.q2.explain"] = "Hrany v čase vyžadují přechodovou analýzu.",
        ["learn.project.pulseRc.quiz.q3.prompt"] = "Větší C při stejném R…",
        ["learn.project.pulseRc.quiz.q3.a"] = "zostří hranu.",
        ["learn.project.pulseRc.quiz.q3.b"] = "nic neudělá.",
        ["learn.project.pulseRc.quiz.q3.c"] = "hranu ještě víc zpomalí.",
        ["learn.project.pulseRc.quiz.q3.explain"] = "Větší τ → pomalejší odezva.",
        ["learn.project.basicsFinal.title"] = "Závěrečný kvíz: napětí, proud a odpor",
        ["learn.project.basicsFinal.summary"] = "Deset smíšených otázek ze všeho v této skupině. Osm správně znamená splněno a uzavírá modul.",
        ["learn.project.basicsFinal.step1"] = "Prolistujte shrnutí.",
        ["learn.project.basicsFinal.step2"] = "Odpovězte na všech deset otázek.",
        ["learn.project.basicsFinal.step3"] = "Získejte alespoň osm bodů. Případně to zopakujte.",
        ["learn.project.basicsFinal.openLab"] = "Otevřít v laboratoři",
        ["learn.project.basicsFinal.lesson1.title"] = "Co tato skupina probrala",
        ["learn.project.basicsFinal.lesson1.body"] = "Napětí tlačí, proud teče, odpor omezuje. Ohmův zákon je spojuje. Sériové zapojení sdílí jeden proud, paralelní jedno napětí. DC je stálé, AC kmitá.",
        ["learn.project.basicsFinal.lesson2.title"] = "Jak závěrečný kvíz funguje",
        ["learn.project.basicsFinal.lesson2.body"] = "Deset otázek napříč skupinou. Osm správně stačí. Špatné odpovědi ukážou důvod a můžete to zkoušet, jak často chcete.",
        ["learn.project.basicsFinal.quiz.q1.prompt"] = "Baterie 9 V leží na poličce a nic k ní není připojeno. Co platí?",
        ["learn.project.basicsFinal.quiz.q1.a"] = "Je tam proud, ale ne napětí.",
        ["learn.project.basicsFinal.quiz.q1.b"] = "Je tam napětí, ale ne proud.",
        ["learn.project.basicsFinal.quiz.q1.c"] = "Není tam ani jedno.",
        ["learn.project.basicsFinal.quiz.q1.explain"] = "Napětí je rozdíl potenciálů mezi svorkami. Proud potřebuje uzavřenou cestu.",
        ["learn.project.basicsFinal.quiz.q2.prompt"] = "Co měří ampérmetr a jak se zapojuje?",
        ["learn.project.basicsFinal.quiz.q2.a"] = "Napětí, paralelně.",
        ["learn.project.basicsFinal.quiz.q2.b"] = "Odpor, přes součástku.",
        ["learn.project.basicsFinal.quiz.q2.c"] = "Proud, do série s cestou.",
        ["learn.project.basicsFinal.quiz.q2.explain"] = "Proud musí měřidlem projít, proto sedí v cestě.",
        ["learn.project.basicsFinal.quiz.q3.prompt"] = "Zdroj 5 V, LED s úbytkem 2 V a rezistor 220 Ω. Jaký proud přibližně teče?",
        ["learn.project.basicsFinal.quiz.q3.a"] = "Asi 14 mA",
        ["learn.project.basicsFinal.quiz.q3.b"] = "Asi 23 mA",
        ["learn.project.basicsFinal.quiz.q3.c"] = "Asi 2 mA",
        ["learn.project.basicsFinal.quiz.q3.explain"] = "Na rezistoru jsou 3 V. 3 V / 220 Ω ≈ 13,6 mA.",
        ["learn.project.basicsFinal.quiz.q4.prompt"] = "Zdvojnásobíte odpor a napětí necháte. Proud…",
        ["learn.project.basicsFinal.quiz.q4.a"] = "se zdvojnásobí.",
        ["learn.project.basicsFinal.quiz.q4.b"] = "klesne na polovinu.",
        ["learn.project.basicsFinal.quiz.q4.c"] = "zůstane stejný.",
        ["learn.project.basicsFinal.quiz.q4.explain"] = "I = U / R. Dvojnásobné R, poloviční I.",
        ["learn.project.basicsFinal.quiz.q5.prompt"] = "Dva rezistory 470 Ω v sérii se chovají jako…",
        ["learn.project.basicsFinal.quiz.q5.a"] = "235 Ω",
        ["learn.project.basicsFinal.quiz.q5.b"] = "470 Ω",
        ["learn.project.basicsFinal.quiz.q5.c"] = "940 Ω",
        ["learn.project.basicsFinal.quiz.q5.explain"] = "Sériové odpory se sčítají.",
        ["learn.project.basicsFinal.quiz.q6.prompt"] = "Dvě LED jsou paralelně na 5 V. Jedna shoří. Ta druhá…",
        ["learn.project.basicsFinal.quiz.q6.a"] = "svítí dál jako předtím.",
        ["learn.project.basicsFinal.quiz.q6.b"] = "zhasne taky.",
        ["learn.project.basicsFinal.quiz.q6.c"] = "svítí víc.",
        ["learn.project.basicsFinal.quiz.q6.explain"] = "Každá paralelní větev je vlastní smyčka se stejnými 5 V.",
        ["learn.project.basicsFinal.quiz.q7.prompt"] = "Které tvrzení o zemi je správné?",
        ["learn.project.basicsFinal.quiz.q7.a"] = "Zem je místo, kde proud mizí.",
        ["learn.project.basicsFinal.quiz.q7.b"] = "Zem je dohodnutý referenční bod 0 V.",
        ["learn.project.basicsFinal.quiz.q7.c"] = "Zemí teče vždy největší proud.",
        ["learn.project.basicsFinal.quiz.q7.explain"] = "Všechna napětí uzlů se měří proti zemi. Je to reference, nic víc.",
        ["learn.project.basicsFinal.quiz.q8.prompt"] = "Síť v Evropě je „230 V, 50 Hz“. Těch 230 V je…",
        ["learn.project.basicsFinal.quiz.q8.a"] = "efektivní hodnota (RMS).",
        ["learn.project.basicsFinal.quiz.q8.b"] = "špičková hodnota.",
        ["learn.project.basicsFinal.quiz.q8.c"] = "hodnota špička–špička.",
        ["learn.project.basicsFinal.quiz.q8.explain"] = "Efektivní hodnota je stejnosměrný ekvivalent podle ohřevu. Špička je asi 325 V.",
        ["learn.project.basicsFinal.quiz.q9.prompt"] = "Ve schématu se dvě čáry kříží bez tečky. Jsou…",
        ["learn.project.basicsFinal.quiz.q9.a"] = "spojené.",
        ["learn.project.basicsFinal.quiz.q9.b"] = "spojené, pokud jsou obě vodiče.",
        ["learn.project.basicsFinal.quiz.q9.c"] = "nespojené.",
        ["learn.project.basicsFinal.quiz.q9.explain"] = "Spojení znamená jen tečka uzlu.",
        ["learn.project.basicsFinal.quiz.q10.prompt"] = "LED v laboratoři běží na 40 mA. Co se stane?",
        ["learn.project.basicsFinal.quiz.q10.a"] = "Trochu potemní.",
        ["learn.project.basicsFinal.quiz.q10.b"] = "Přehřeje se a shoří.",
        ["learn.project.basicsFinal.quiz.q10.c"] = "Nic, LED nemají mez.",
        ["learn.project.basicsFinal.quiz.q10.explain"] = "Výukové LED jsou v pořádku asi do 20 mA a shoří zhruba nad 35 mA.",
        ["learn.project.voltageIntro.lesson1.title"] = "Napětí je rozdíl",
        ["learn.project.voltageIntro.lesson1.body"] = "Napětí je rozdíl elektrického potenciálu mezi dvěma body, síla, která pohání náboj. Měří se ve voltech, přes součástku, proti společné zemi.",
        ["learn.project.voltageIntro.lesson2.title"] = "Potenciál, ne pohyb",
        ["learn.project.voltageIntro.lesson2.body"] = "Baterie má plné napětí, i když k ní nic není připojeno. Až uzavřená cesta udělá z potenciálu proud a ve smyčce se úbytky sečtou na napětí zdroje.",
        ["learn.project.voltageIntro.quiz.q1.prompt"] = "Napětí je nejlépe popsat jako…",
        ["learn.project.voltageIntro.quiz.q1.a"] = "rozdíl elektrického potenciálu mezi dvěma body.",
        ["learn.project.voltageIntro.quiz.q1.b"] = "množství náboje uloženého ve vodiči.",
        ["learn.project.voltageIntro.quiz.q1.c"] = "rychlost elektronů v obvodu.",
        ["learn.project.voltageIntro.quiz.q1.explain"] = "Napětí je vždy srovnání dvou bodů: tlak, ne tok.",
        ["learn.project.voltageIntro.quiz.q2.prompt"] = "Voltmetr se zapojuje…",
        ["learn.project.voltageIntro.quiz.q2.a"] = "do série, uvnitř cesty.",
        ["learn.project.voltageIntro.quiz.q2.b"] = "paralelně, přes dva body.",
        ["learn.project.voltageIntro.quiz.q2.c"] = "jen na zem.",
        ["learn.project.voltageIntro.quiz.q2.explain"] = "Musí vidět rozdíl mezi dvěma body, aniž by se stal součástí cesty.",
        ["learn.project.voltageIntro.quiz.q3.prompt"] = "Při rozepnutém spínači ukáže voltmetr přes spínač…",
        ["learn.project.voltageIntro.quiz.q3.a"] = "0 V, protože nic neteče.",
        ["learn.project.voltageIntro.quiz.q3.b"] = "polovinu napětí baterie.",
        ["learn.project.voltageIntro.quiz.q3.c"] = "plné napětí baterie.",
        ["learn.project.voltageIntro.quiz.q3.explain"] = "Proud neteče, ale celý rozdíl potenciálů se objeví přes mezeru.",
        ["learn.project.currentIntro.lesson1.title"] = "Náboj v pohybu",
        ["learn.project.currentIntro.lesson1.body"] = "Proud je rychlost, jakou náboj prochází bodem, měří se v ampérech; malé obvody žijí v miliampérech. Dohodnutý směr proudu je od + k −.",
        ["learn.project.currentIntro.lesson2.title"] = "Jedna smyčka, jeden proud",
        ["learn.project.currentIntro.lesson2.body"] = "Proud potřebuje uzavřenou cestu a v jedné smyčce je v každém místě stejný. V uzlu se přítoky rovnají odtokům.",
        ["learn.project.currentIntro.quiz.q1.prompt"] = "Jeden ampér znamená…",
        ["learn.project.currentIntro.quiz.q1.a"] = "jeden coulomb náboje za sekundu.",
        ["learn.project.currentIntro.quiz.q1.b"] = "jeden volt na jednom rezistoru.",
        ["learn.project.currentIntro.quiz.q1.c"] = "jeden elektron za sekundu.",
        ["learn.project.currentIntro.quiz.q1.explain"] = "Proud je náboj za čas: 1 A = 1 C/s.",
        ["learn.project.currentIntro.quiz.q2.prompt"] = "V jedné sériové smyčce je proud…",
        ["learn.project.currentIntro.quiz.q2.a"] = "největší u baterie.",
        ["learn.project.currentIntro.quiz.q2.b"] = "v každém místě stejný.",
        ["learn.project.currentIntro.quiz.q2.c"] = "za LED nulový.",
        ["learn.project.currentIntro.quiz.q2.explain"] = "Je jen jedna cesta, takže co odejde z baterie, projde každou součástkou a vrátí se.",
        ["learn.project.currentIntro.quiz.q3.prompt"] = "Ampérmetr se zapojuje…",
        ["learn.project.currentIntro.quiz.q3.a"] = "přes baterii.",
        ["learn.project.currentIntro.quiz.q3.b"] = "přes LED.",
        ["learn.project.currentIntro.quiz.q3.c"] = "do série, uvnitř cesty.",
        ["learn.project.currentIntro.quiz.q3.explain"] = "Proud musí měřidlem projít; přes zdroj by ho zkratoval.",
        ["learn.project.resistanceIntro.lesson1.title"] = "Odpor brzdí",
        ["learn.project.resistanceIntro.lesson1.body"] = "Odpor brání proudu a měří se v ohmech. Rezistor je vyrobený na přesnou hodnotu; barevné proužky ji říkají a nemá polaritu.",
        ["learn.project.resistanceIntro.lesson2.title"] = "Ohmův zákon",
        ["learn.project.resistanceIntro.lesson2.body"] = "U = I · R: při stálém napětí znamená větší odpor menší proud. Sériové odpory se sčítají a proud v odporu se mění v teplo (P = I² · R).",
        ["learn.project.resistanceIntro.quiz.q1.prompt"] = "Při stálém napětí zdvojnásobení odporu…",
        ["learn.project.resistanceIntro.quiz.q1.a"] = "sníží proud na polovinu.",
        ["learn.project.resistanceIntro.quiz.q1.b"] = "zdvojnásobí proud.",
        ["learn.project.resistanceIntro.quiz.q1.c"] = "proud nezmění.",
        ["learn.project.resistanceIntro.quiz.q1.explain"] = "I = U / R, proud je nepřímo úměrný odporu.",
        ["learn.project.resistanceIntro.quiz.q2.prompt"] = "Baterie 5 V, LED s úbytkem 2 V a rezistor 220 Ω: proud LED je asi…",
        ["learn.project.resistanceIntro.quiz.q2.a"] = "23 mA.",
        ["learn.project.resistanceIntro.quiz.q2.b"] = "13,6 mA.",
        ["learn.project.resistanceIntro.quiz.q2.c"] = "2,3 mA.",
        ["learn.project.resistanceIntro.quiz.q2.explain"] = "Rezistor vidí 5 − 2 = 3 V; 3 V / 220 Ω ≈ 13,6 mA.",
        ["learn.project.resistanceIntro.quiz.q3.prompt"] = "Dva rezistory 220 Ω v sérii se chovají jako…",
        ["learn.project.resistanceIntro.quiz.q3.a"] = "110 Ω.",
        ["learn.project.resistanceIntro.quiz.q3.b"] = "220 Ω.",
        ["learn.project.resistanceIntro.quiz.q3.c"] = "440 Ω.",
        ["learn.project.resistanceIntro.quiz.q3.explain"] = "Sériové odpory se sčítají: 220 + 220 = 440 Ω.",
        ["learn.project.ohmsLaw.lesson1.title"] = "Jeden zákon, tři tvary",
        ["learn.project.ohmsLaw.lesson1.body"] = "U = I · R, I = U / R a R = U / I říkají to samé. Ohmické součástky kreslí přímku I–U; LED a diody se ohýbají, a proto potřebují sériový rezistor.",
        ["learn.project.ohmsLaw.lesson2.title"] = "Návrh a výkon",
        ["learn.project.ohmsLaw.lesson2.body"] = "Rezistor k LED spočítejte z R = (U_zdroj − U_LED) / I a zaokrouhlete nahoru na řadovou hodnotu; pak ověřte výkon P = U · I = I² · R proti zatížitelnosti.",
        ["learn.project.ohmsLaw.quiz.q1.prompt"] = "Zdroj 5 V, LED s úbytkem 2 V, cíl 15 mA. Rezistor má být asi…",
        ["learn.project.ohmsLaw.quiz.q1.a"] = "200 Ω (použijte 220 Ω).",
        ["learn.project.ohmsLaw.quiz.q1.b"] = "333 Ω.",
        ["learn.project.ohmsLaw.quiz.q1.c"] = "75 Ω.",
        ["learn.project.ohmsLaw.quiz.q1.explain"] = "R = (5 − 2) V / 0,015 A = 200 Ω; nejbližší řadová hodnota nahoru je 220 Ω.",
        ["learn.project.ohmsLaw.quiz.q2.prompt"] = "3 V na součástce a 6,4 mA skrz ni znamená R asi…",
        ["learn.project.ohmsLaw.quiz.q2.a"] = "19 Ω.",
        ["learn.project.ohmsLaw.quiz.q2.b"] = "470 Ω.",
        ["learn.project.ohmsLaw.quiz.q2.c"] = "2,1 kΩ.",
        ["learn.project.ohmsLaw.quiz.q2.explain"] = "R = U / I = 3 / 0,0064 ≈ 470 Ω.",
        ["learn.project.ohmsLaw.quiz.q3.prompt"] = "3 V děleno 2,2 kΩ je…",
        ["learn.project.ohmsLaw.quiz.q3.a"] = "1,36 A.",
        ["learn.project.ohmsLaw.quiz.q3.b"] = "0,68 mA.",
        ["learn.project.ohmsLaw.quiz.q3.c"] = "1,36 mA.",
        ["learn.project.ohmsLaw.quiz.q3.explain"] = "Volty dělené kiloohmy dávají miliampéry: 3 / 2,2 = 1,36 mA.",
        ["learn.project.circuitElements.lesson1.title"] = "Čtyři role",
        ["learn.project.circuitElements.lesson1.body"] = "Každý obvod má zdroj, zátěž, uzavřenou cestu a obvykle ovládání. Zdroje jsou baterie, střídavé a pulzní zdroje; pasivní prvky jsou rezistory, kondenzátory a cívky.",
        ["learn.project.circuitElements.lesson2.title"] = "Čtení značek",
        ["learn.project.circuitElements.lesson2.body"] = "Diody a LED jsou jednosměrné šipky, tranzistory řiditelné ventily, spínače a pojistky ovládají a chrání. Tečky spojují, křížení ne, a každá značka země je jeden uzel.",
        ["learn.project.circuitElements.quiz.q1.prompt"] = "Na značce baterie dlouhá čára označuje…",
        ["learn.project.circuitElements.quiz.q1.a"] = "svorku +.",
        ["learn.project.circuitElements.quiz.q1.b"] = "svorku −.",
        ["learn.project.circuitElements.quiz.q1.c"] = "zem.",
        ["learn.project.circuitElements.quiz.q1.explain"] = "Dlouhá čára +, krátká tlustá čára −.",
        ["learn.project.circuitElements.quiz.q2.prompt"] = "Kondenzátor…",
        ["learn.project.circuitElements.quiz.q2.a"] = "dodává do obvodu energii.",
        ["learn.project.circuitElements.quiz.q2.b"] = "ukládá náboj a blokuje stálé DC.",
        ["learn.project.circuitElements.quiz.q2.c"] = "jen omezuje proud.",
        ["learn.project.circuitElements.quiz.q2.explain"] = "Propouští měnící se signály a blokuje DC: vyhlazování, časování, filtrování.",
        ["learn.project.circuitElements.quiz.q3.prompt"] = "Dvě čáry ve schématu se kříží bez tečky. Jsou…",
        ["learn.project.circuitElements.quiz.q3.a"] = "spojené.",
        ["learn.project.circuitElements.quiz.q3.b"] = "spojené, jen pokud jsou obě vodiče.",
        ["learn.project.circuitElements.quiz.q3.c"] = "nespojené.",
        ["learn.project.circuitElements.quiz.q3.explain"] = "Elektrické spojení znamená jen tečka uzlu.",
        ["learn.project.seriesParallelCircuits.lesson1.title"] = "Sériově: jedna cesta",
        ["learn.project.seriesParallelCircuits.lesson1.body"] = "V sérii teče každou součástkou stejný proud, úbytky se sčítají na napětí zdroje a odpory se sčítají. Jedna vadná součástka zastaví všechno.",
        ["learn.project.seriesParallelCircuits.lesson2.title"] = "Paralelně: společné uzly",
        ["learn.project.seriesParallelCircuits.lesson2.body"] = "Paralelně vidí každá větev stejné napětí, proudy větví se u zdroje sčítají a celkový odpor je menší než kterákoli větev. Větve selhávají nezávisle.",
        ["learn.project.seriesParallelCircuits.quiz.q1.prompt"] = "Dva rezistory 220 Ω v sérii dají…",
        ["learn.project.seriesParallelCircuits.quiz.q1.a"] = "celkem 440 Ω.",
        ["learn.project.seriesParallelCircuits.quiz.q1.b"] = "celkem 110 Ω.",
        ["learn.project.seriesParallelCircuits.quiz.q1.c"] = "celkem 220 Ω.",
        ["learn.project.seriesParallelCircuits.quiz.q1.explain"] = "Sériové odpory se sčítají: 220 + 220 = 440 Ω.",
        ["learn.project.seriesParallelCircuits.quiz.q2.prompt"] = "Dvě stejné LED paralelně na 5 V: každá větev vidí…",
        ["learn.project.seriesParallelCircuits.quiz.q2.a"] = "2,5 V.",
        ["learn.project.seriesParallelCircuits.quiz.q2.b"] = "5 V.",
        ["learn.project.seriesParallelCircuits.quiz.q2.c"] = "10 V.",
        ["learn.project.seriesParallelCircuits.quiz.q2.explain"] = "Paralelní větve sdílejí stejné dva uzly, takže každá vidí plné napětí.",
        ["learn.project.seriesParallelCircuits.quiz.q3.prompt"] = "Jedna LED z paralelní dvojice shoří. Ta druhá…",
        ["learn.project.seriesParallelCircuits.quiz.q3.a"] = "zhasne taky.",
        ["learn.project.seriesParallelCircuits.quiz.q3.b"] = "dostane dvojnásobné napětí.",
        ["learn.project.seriesParallelCircuits.quiz.q3.c"] = "svítí dál jako předtím.",
        ["learn.project.seriesParallelCircuits.quiz.q3.explain"] = "Každá větev je vlastní smyčka; baterie jen dodává menší celkový proud.",
        ["learn.project.acDc.lesson1.title"] = "Stálý nebo střídavý",
        ["learn.project.acDc.lesson1.body"] = "DC teče jedním směrem se stálou hodnotou a má polaritu. AC se obrací v sinusovce; jedna perioda trvá T a frekvence je f = 1 / T, u sítě 50 nebo 60 Hz.",
        ["learn.project.acDc.lesson2.title"] = "Popis a přeměna AC",
        ["learn.project.acDc.lesson2.body"] = "Velikost AC udáváme špičkou, hodnotou špička–špička nebo efektivní hodnotou (U_ef = Û / √2 pro sinus). Transformátory fungují jen s AC, elektronika potřebuje DC, proto nabíječky usměrňují diodami a vyhlazují kondenzátory.",
        ["learn.project.acDc.quiz.q1.prompt"] = "Perioda sítě 50 Hz trvá…",
        ["learn.project.acDc.quiz.q1.a"] = "20 ms.",
        ["learn.project.acDc.quiz.q1.b"] = "50 ms.",
        ["learn.project.acDc.quiz.q1.c"] = "2 ms.",
        ["learn.project.acDc.quiz.q1.explain"] = "T = 1 / f = 1 / 50 Hz = 0,02 s = 20 ms.",
        ["learn.project.acDc.quiz.q2.prompt"] = "„Síť 230 V“ je…",
        ["learn.project.acDc.quiz.q2.a"] = "špičková hodnota.",
        ["learn.project.acDc.quiz.q2.b"] = "efektivní hodnota.",
        ["learn.project.acDc.quiz.q2.c"] = "hodnota špička–špička.",
        ["learn.project.acDc.quiz.q2.explain"] = "Efektivní hodnota je stejnosměrný ekvivalent podle ohřevu; špička je asi 325 V.",
        ["learn.project.acDc.quiz.q3.prompt"] = "Při AC kondenzátor…",
        ["learn.project.acDc.quiz.q3.a"] = "blokuje všechno.",
        ["learn.project.acDc.quiz.q3.b"] = "propouští DC a blokuje AC.",
        ["learn.project.acDc.quiz.q3.c"] = "propouští AC a blokuje DC.",
        ["learn.project.acDc.quiz.q3.explain"] = "Jen měnící se napětí přesouvá náboj na desky a z nich. Základ filtrů.",
        ["learn.project.voltageIntro.slide1.title"] = "Něco musí náboj tlačit",
        ["learn.project.voltageIntro.slide1.p1"] = "Elektrický náboj se sám od sebe nikam nerozběhne. Aby se ve vodiči dal do pohybu, musí ho něco tlačit, a právě tomuto „tlaku“ říkáme elektrické napětí.",
        ["learn.project.voltageIntro.slide1.p2"] = "Nejlépe si to představíte na vodě. Když spojíte trubkou dvě nádrže se stejnou hladinou, nic se nestane. Jakmile ale jednu nádrž zvednete, voda začne proudit do té nižší. Rozdíl hladin je to, co vodu pohání, a napětí hraje v obvodu úplně stejnou roli.",
        ["learn.project.voltageIntro.slide1.p3"] = "Všimněte si, že napětí samo o sobě neříká, kolik vody proteče. Vyjadřuje jen to, jak silně je voda tlačena. Skutečné množství závisí ještě na trubce, tedy na tom, jak snadno jí voda projde. O tom budou další dvě lekce, o proudu a o odporu.",
        ["learn.project.voltageIntro.slide1.caption"] = "Stejné hladiny, žádný tok. Rozdíl hladin vodu rozpohybuje. Napětí je tento rozdíl.",
        ["learn.project.voltageIntro.slide2.title"] = "Napětí je vždy mezi dvěma body",
        ["learn.project.voltageIntro.slide2.p1"] = "Samotný jeden bod v obvodu žádných „5 voltů“ nemá. Napětí je vždy porovnání dvou míst, rozdíl mezi nimi. Proto se voltmetr při měření musí dotýkat dvou bodů najednou.",
        ["learn.project.voltageIntro.slide2.p2"] = "Baterie s napětím 5 V udržuje svou kladnou svorku o 5 voltů výš než svorku zápornou, a to bez ohledu na to, co k ní připojíte. Jednotkou napětí je volt se značkou V. Ve vzorcích se napětí označuje písmenem U.",
        ["learn.project.voltageIntro.slide2.p3"] = "Když někdo řekne, že „tento uzel má 3 V“, myslí tím 3 volty vůči zemi. Ten druhý bod se prostě nevyslovuje, protože se předpokládá. Vždycky tam ale je.",
        ["learn.project.voltageIntro.slide2.caption"] = "Voltmetr se připojuje mezi dva body a ukazuje rozdíl jejich napětí.",
        ["learn.project.voltageIntro.slide2.callout"] = "Napětí měříme na součástce, mezi jejími vývody. Proud součástkou protéká.",
        ["learn.project.voltageIntro.slide3.title"] = "Odkud se napětí bere",
        ["learn.project.voltageIntro.slide3.p1"] = "V baterii odděluje náboje chemická reakce. Na jednom pólu se hromadí přebytek elektronů, na druhém elektrony chybějí. Tato uložená nerovnováha je zdrojem tlaku, který pak náboj v obvodu pohání.",
        ["learn.project.voltageIntro.slide3.p2"] = "Napětí různých zdrojů se od sebe hodně liší. Tužková baterie dává 1,5 V, port USB 5 V a autobaterie 12 V. V zásuvce je 230 V, což už je napětí, se kterým tyto lekce nikdy pracovat nebudou.",
        ["learn.project.voltageIntro.slide3.p3"] = "Chemie ale není jediná možnost. Solární článek vyrábí napětí ze světla, generátor z pohybu a nabíječka USB si ho odvodí ze sítě přes transformátor. Výsledek je pokaždé stejný: rozdíl potenciálů, který obvod dokáže využít.",
        ["learn.project.voltageIntro.slide3.caption"] = "Typická napětí od jednoho článku po zásuvku.",
        ["learn.project.voltageIntro.slide3.callout"] = "V těchto lekcích zůstáváme pod 24 V. Se síťovým napětím nikdy neexperimentujte.",
        ["learn.project.voltageIntro.slide4.title"] = "Zem je společná nula",
        ["learn.project.voltageIntro.slide4.p1"] = "Abychom mohli mluvit o napětí „v jednom uzlu“, potřebujeme společný vztažný bod, ke kterému všechna napětí vztáhneme. Tomuto bodu říkáme zem a podle dohody má napětí 0 V.",
        ["learn.project.voltageIntro.slide4.p2"] = "Každý popisek napětí, který v laboratoři uvidíte u uzlu, je měřený právě proti zemi. Zemí bývá nejčastěji záporný pól baterie. Není na ní nic zvláštního, je to jen místo, odkud měříme.",
        ["learn.project.voltageIntro.slide4.p3"] = "Za nulu bychom klidně mohli zvolit kterýkoli jiný uzel. Všechny rozdíly napětí mezi součástkami by zůstaly úplně stejné, jen by se posunula čísla u popisků. Zem je tedy jen dohoda, díky které se dají hodnoty v obvodu snadno porovnávat.",
        ["learn.project.voltageIntro.slide4.caption"] = "Napětí si můžete představit jako výšky na žebříku. Zem je příčka, které říkáme nula.",
        ["learn.project.voltageIntro.slide5.title"] = "Napětí může být i bez proudu",
        ["learn.project.voltageIntro.slide5.p1"] = "Rozepněte spínač a proud se v celém obvodu zastaví. Napětí baterie tím ale nikam nezmizí. Když připojíte voltmetr na rozepnutý spínač, ukáže plných 5 V.",
        ["learn.project.voltageIntro.slide5.p2"] = "Napětí je tedy připravenost tlačit, ne samotné tlačení. Teprve uzavřená cesta obvodem dovolí, aby se z této připravenosti stal pohyb náboje, tedy proud.",
        ["learn.project.voltageIntro.slide5.p3"] = "Tenhle příklad stojí za chvíli zamyšlení. Žádný náboj se nehýbe, a přesto je mezi kontakty rozepnutého spínače celé napětí baterie. Tlak tam čeká na okamžik, kdy se objeví cesta.",
        ["learn.project.voltageIntro.slide5.caption"] = "Rozepnutý spínač: nikde neteče proud, ale na kontaktech spínače je 5 V.",
        ["learn.project.voltageIntro.slide6.title"] = "Napětí se v obvodu rozdělí",
        ["learn.project.voltageIntro.slide6.p1"] = "Sepněte spínač a 5 V baterie se rozdělí mezi součástky. Na rezistoru bude přibližně 2,75 V a na LED 2,25 V. Když obě hodnoty sečtete, dostanete zase 5 V.",
        ["learn.project.voltageIntro.slide6.p2"] = "Tohle platí vždy: úbytky napětí na součástkách v uzavřené smyčce dají dohromady napětí zdroje. Co si nevezme LED, připadne rezistoru, a naopak.",
        ["learn.project.voltageIntro.slide6.p3"] = "Toto pravidlo je známé jako druhý Kirchhoffův zákon a je to hlavní nástroj, kterým se uvažuje o sériových obvodech. Stačí znát napětí zdroje a jeden úbytek, a ten druhý už dopočítáte.",
        ["learn.project.voltageIntro.slide6.caption"] = "2,75 V + 2,25 V = 5 V.",
        ["learn.project.voltageIntro.slide6.callout"] = "U_baterie = U_rezistor + U_LED",
        ["learn.project.voltageIntro.slide7.title"] = "Napětí: co si odnést",
        ["learn.project.voltageIntro.slide7.p1"] = "Na těchto čtyřech věcech stojí všechno, co přijde dál.",
        ["learn.project.voltageIntro.slide7.fact1"] = "Napětí je rozdíl potenciálů mezi dvěma body. Je to „tlak“, který pohání náboj.",
        ["learn.project.voltageIntro.slide7.fact2"] = "Měří se ve voltech, a to na součástce, voltmetrem připojeným paralelně.",
        ["learn.project.voltageIntro.slide7.fact3"] = "Zem je dohodnutá nula. Napětí uzlů se udávají vůči ní.",
        ["learn.project.voltageIntro.slide7.fact4"] = "Zdroj má napětí i tehdy, když neteče žádný proud. V uzavřené smyčce dají úbytky dohromady napětí zdroje.",
        ["learn.project.currentIntro.slide1.title"] = "Náboj v pohybu",
        ["learn.project.currentIntro.slide1.p1"] = "Kovy jsou plné elektronů, které se mohou volně pohybovat. Když na vodič přivedeme napětí, všechny se začnou posouvat jedním směrem. Tomuto uspořádanému pohybu náboje říkáme elektrický proud.",
        ["learn.project.currentIntro.slide1.p2"] = "Proud vyjadřuje, kolik náboje projde daným místem za jednu sekundu. Jednotkou je ampér (A): proud jednoho ampéru znamená, že místem projde jeden coulomb náboje každou sekundu. Ve vzorcích proud značíme písmenem I.",
        ["learn.project.currentIntro.slide1.p3"] = "Samotné elektrony se přitom pohybují překvapivě pomalu, ani ne milimetr za sekundu. Rychle se šíří jen tlak, který je pohání. Proto se po sepnutí spínače dají elektrony do pohybu po celé délce vodiče téměř okamžitě.",
        ["learn.project.currentIntro.slide1.caption"] = "Spočítejte, kolik náboje projde bránou za sekundu, a máte proud.",
        ["learn.project.currentIntro.slide1.callout"] = "I = Q / t",
        ["learn.project.currentIntro.slide2.title"] = "Kterým směrem proud teče",
        ["learn.project.currentIntro.slide2.p1"] = "Ve schématech se používá takzvaný dohodnutý směr proudu: od kladného pólu zdroje přes obvod k pólu zápornému. Tento směr sledují šipky ve schématech, značky diod i pohyb čárek na vodičích v laboratoři.",
        ["learn.project.currentIntro.slide2.p2"] = "Elektrony se ve skutečnosti pohybují opačně, od záporného pólu ke kladnému. Pro výpočty i pro pochopení obvodu to ale nehraje roli, obě představy vedou ke stejným výsledkům. Stará dohoda proto zůstala a každou šipku čtěte jako dohodnutý směr proudu.",
        ["learn.project.currentIntro.slide2.p3"] = "Tato dohoda je starší než objev elektronu. Benjamin Franklin určil, který náboj se bude nazývat kladný, dávno předtím, než kdokoli věděl, co náboj ve vodiči skutečně přenáší. Když se elektrony objevily, šipky už byly ve všech učebnicích.",
        ["learn.project.currentIntro.slide2.caption"] = "Dohodnutý směr proudu (nahoře) vede od + k −. Elektrony (dole) se pohybují opačně.",
        ["learn.project.currentIntro.slide3.title"] = "Jak velký je jeden ampér",
        ["learn.project.currentIntro.slide3.p1"] = "Pro malou elektroniku je jeden ampér hodně. Většina hodnot, se kterými se setkáte, se pohybuje v miliampérech: 1 A = 1000 mA.",
        ["learn.project.currentIntro.slide3.p2"] = "Vstup čidla odebírá jen mikroampéry, LED potřebuje 10 až 20 mA, nabíječka telefonu dodává až 2 A a rychlovarná konvice si bere kolem 10 A.",
        ["learn.project.currentIntro.slide3.p3"] = "Pro představu o měřítku: baterie telefonu má kapacitu asi 3000 mAh. To znamená, že může dodávat 3 A po dobu jedné hodiny, nebo 15 mA po dobu 200 hodin. Jedinou LED by tedy napájela déle než týden.",
        ["learn.project.currentIntro.slide3.caption"] = "Od čidel po topná tělesa.",
        ["learn.project.currentIntro.slide4.title"] = "Proud potřebuje uzavřený obvod",
        ["learn.project.currentIntro.slide4.p1"] = "Náboj se nemůže nikde hromadit ani se ztrácet. Aby mohl tekoucí proud existovat, musí mít celou cestu: ze zdroje ven, přes všechny součástky a zase zpátky do zdroje.",
        ["learn.project.currentIntro.slide4.p2"] = "Stačí obvod přerušit na jediném místě a proud klesne na nulu všude, ne jen u přerušení. Baterie má pořád své napětí, jenom nemá kudy tlačit.",
        ["learn.project.currentIntro.slide4.p3"] = "Přesně proto může pták klidně sedět na drátu vysokého napětí. Dotýká se jen jednoho vodiče, takže přes jeho tělo nevede žádná uzavřená cesta a neteče jím žádný proud.",
        ["learn.project.currentIntro.slide4.caption"] = "Baterie + → rezistor → LED → zem → baterie −.",
        ["learn.project.currentIntro.slide5.title"] = "Jedna smyčka, jeden proud",
        ["learn.project.currentIntro.slide5.p1"] = "V jednoduché smyčce teče jediný proud. Co vyteče z baterie, projde rezistorem, LED i zpětným vodičem, protože nemá kudy jinudy jít. Na každé součástce proto uvidíte stejnou hodnotu.",
        ["learn.project.currentIntro.slide5.p2"] = "Tam, kde se vodič rozvětví, se proud rozdělí do větví. Součet toho, co do uzlu přiteče, se ale vždy rovná součtu toho, co z něj odteče. To je základní pravidlo pro každý uzel v obvodu.",
        ["learn.project.currentIntro.slide5.p3"] = "Tomuto pravidlu se říká první Kirchhoffův zákon. Spolu se zákonem o napětí z předchozí lekce stačí na to, abyste vyřešili každý obvod, který v tomto kurzu potkáte.",
        ["learn.project.currentIntro.slide5.caption"] = "Do uzlu přitéká 30 mA, odtéká 18 + 12 mA.",
        ["learn.project.currentIntro.slide5.callout"] = "I_přítok = I_odtok1 + I_odtok2",
        ["learn.project.currentIntro.slide6.title"] = "Jak se proud měří",
        ["learn.project.currentIntro.slide6.p1"] = "Ampérmetr se zapojuje do série, tedy přímo do cesty proudu, aby jím měřený proud protékal. Kdybyste ho připojili paralelně k baterii, zkratoval by ji.",
        ["learn.project.currentIntro.slide6.p2"] = "V laboratoři ampérmetr většinou nepotřebujete. Po spuštění simulace se proud každé větve vypíše a rychlost čárek na vodiči odpovídá jeho velikosti.",
        ["learn.project.currentIntro.slide6.p3"] = "Se skutečným měřicím přístrojem je to pracnější: obvod musíte rozpojit a měřidlo vložit do vzniklé mezery. I proto se v praxi měří napětí mnohem častěji než proud, k měření napětí totiž není potřeba nic přepojovat.",
        ["learn.project.currentIntro.slide6.caption"] = "Ampérmetr zapojený do série v horním vodiči.",
        ["learn.project.currentIntro.slide7.title"] = "Když je proudu příliš",
        ["learn.project.currentIntro.slide7.p1"] = "Proud procházející odporem vytváří teplo. Malé množství nevadí, příliš velké ale roztaví izolaci, spálí rezistor a zničí LED.",
        ["learn.project.currentIntro.slide7.p2"] = "LED v laboratoři snese bez problémů přibližně 20 mA a při zhruba 35 mA se spálí. Omezit proud na bezpečnou hodnotu je právě úkol rezistoru zapojeného v sérii s LED.",
        ["learn.project.currentIntro.slide7.p3"] = "Své meze mají i vodiče. Tenký drát, kterým teče příliš velký proud, se zahřívá. Na tom je založená pojistka: je to úmyslně slabý kousek drátu, který se má přepálit jako první.",
        ["learn.project.currentIntro.slide7.caption"] = "Pásma proudu LED v laboratoři.",
        ["learn.project.currentIntro.slide7.callout"] = "LED nikdy nepřipojujte přímo na baterii bez rezistoru.",
        ["learn.project.currentIntro.slide8.title"] = "Proud: co si odnést",
        ["learn.project.currentIntro.slide8.p1"] = "Těchto pět bodů mějte při ruce.",
        ["learn.project.currentIntro.slide8.fact1"] = "Proud je množství náboje za sekundu a měří se v ampérech. Malé obvody pracují v miliampérech.",
        ["learn.project.currentIntro.slide8.fact2"] = "Dohodnutý směr proudu vede od + k −. Šipky i značky LED ho respektují.",
        ["learn.project.currentIntro.slide8.fact3"] = "Proud potřebuje uzavřený obvod. Přerušte ho kdekoli a zastaví se všude.",
        ["learn.project.currentIntro.slide8.fact4"] = "V jedné smyčce teče jeden proud. V uzlu se přítok rovná odtoku.",
        ["learn.project.currentIntro.slide8.fact5"] = "Měří se do série. Příliš velký proud znamená teplo a zničené součástky.",
        ["learn.project.resistanceIntro.slide1.title"] = "Odpor klade proudu překážku",
        ["learn.project.resistanceIntro.slide1.p1"] = "Širokou trubkou protéká voda snadno. Úzkou trubkou jí při stejném tlaku proteče mnohem méně. Elektrický odpor je přesně tato „úzkost“ cesty, kterou musí proud projít.",
        ["learn.project.resistanceIntro.slide1.p2"] = "Měděný drát klade proudu jen nepatrný odpor. Uhlík nebo tenká kovová vrstva ho naopak kladou hodně. Jednotkou odporu je ohm se značkou Ω.",
        ["learn.project.resistanceIntro.slide1.p3"] = "Odpor závisí na materiálu, délce a tloušťce vodiče. Delší vodič má odpor větší, tlustší menší. Proto vede ke sporáku tlustý kabel, zatímco domovnímu zvonku stačí tenký drátek.",
        ["learn.project.resistanceIntro.slide1.caption"] = "Stejný tlak, různé trubky. Úzká trubka znamená velký odpor.",
        ["learn.project.resistanceIntro.slide2.title"] = "Rezistor",
        ["learn.project.resistanceIntro.slide2.p1"] = "Rezistor je součástka vyrobená tak, aby měla přesně danou hodnotu odporu. Hodnotu vyjadřují barevné proužky na jeho těle. Rezistor nemá polaritu, takže je jedno, kterým směrem ho do obvodu zapojíte.",
        ["learn.project.resistanceIntro.slide2.p2"] = "Proužky se čtou jako číslice. Červená, červená a hnědá znamenají 2, 2 a násobek 10, tedy 220 Ω. Zlatý proužek udává toleranci 5 %.",
        ["learn.project.resistanceIntro.slide2.p3"] = "Barevný kód se nemusíte učit nazpaměť. Laboratoř hodnotu zobrazuje přímo u značky a multimetr ji změří za vás. Přesto je příjemné poznat rezistor 220 Ω na první pohled.",
        ["learn.project.resistanceIntro.slide2.caption"] = "Rezistor s odporem 220 Ω.",
        ["learn.project.resistanceIntro.slide3.title"] = "Ohmův zákon",
        ["learn.project.resistanceIntro.slide3.p1"] = "U rezistoru je proud přímo úměrný napětí. Konstantou úměrnosti je právě odpor a vztah mezi nimi zapisujeme jako U = I · R.",
        ["learn.project.resistanceIntro.slide3.p2"] = "Příklad: zdroj má 5 V a LED si z něj vezme 2 V, takže na rezistor zbývají 3 V. Při odporu 220 Ω pak rezistorem, a tedy i celou smyčkou, poteče proud 3 / 220 ≈ 13,6 mA.",
        ["learn.project.resistanceIntro.slide3.p3"] = "Pomáhá říkat si při počítání jednotky nahlas: volty na součástce, ampéry skrz ni, ohmy mezi nimi. Když výsledek vyjde nesmyslně, třeba 3000 A přes LED, někde se určitě ztratila předpona.",
        ["learn.project.resistanceIntro.slide3.caption"] = "Zakryjte veličinu, kterou hledáte. Zbylé dvě ukážou, jak ji spočítat.",
        ["learn.project.resistanceIntro.slide3.callout"] = "U = I · R\nI = U / R\nR = U / I",
        ["learn.project.resistanceIntro.slide4.title"] = "Větší odpor, menší proud",
        ["learn.project.resistanceIntro.slide4.p1"] = "Nechte napětí stejné a měňte jen rezistor. Ze 3 V protlačí odpor 100 Ω proud 30 mA, odpor 220 Ω už jen 13,6 mA a 1 kΩ pouhé 3 mA.",
        ["learn.project.resistanceIntro.slide4.p2"] = "Právě proto rezistor funguje jako omezovač proudu. Volbou odporu R volíte zároveň proud I, který obvodem poteče.",
        ["learn.project.resistanceIntro.slide4.p3"] = "Tato tabulka je vlastně celý postup návrhu jednoduchého obvodu. Rozhodnete, kolik proudu má zátěž dostat, a Ohmův zákon vám řekne, jaký rezistor k tomu potřebujete.",
        ["learn.project.resistanceIntro.slide4.caption"] = "Proud ze 3 V pro čtyři různé rezistory.",
        ["learn.project.resistanceIntro.slide5.title"] = "Sériové odpory se sčítají",
        ["learn.project.resistanceIntro.slide5.p1"] = "Zapojte dva rezistory za sebou a proud se musí protlačit oběma. Jejich odpory se proto sčítají: 220 + 220 = 440 Ω.",
        ["learn.project.resistanceIntro.slide5.p2"] = "Paralelní zapojení funguje opačně. Druhá „trubka“ vedle první celkový odpor sníží, protože proud má víc cest. Podrobněji se tomu věnuje lekce o sériovém a paralelním zapojení.",
        ["learn.project.resistanceIntro.slide5.p3"] = "Sčítání se hodí, když potřebnou hodnotu nemáte po ruce. Chybí vám 440 Ω? Dva rezistory 220 Ω zapojené za sebou udělají stejnou službu.",
        ["learn.project.resistanceIntro.slide5.caption"] = "Odpory v sérii se sčítají.",
        ["learn.project.resistanceIntro.slide5.callout"] = "R_sériové = R1 + R2",
        ["learn.project.resistanceIntro.slide6.title"] = "Odpor má všechno",
        ["learn.project.resistanceIntro.slide6.p1"] = "Krátký vodič má odpor jen několik miliohmů, proto laboratoř s vodiči počítá jako s dokonalými. Lidská pokožka má odpor desítky kiloohmů i více, a právě díky tomu jsou malá napětí neškodná.",
        ["learn.project.resistanceIntro.slide6.p2"] = "Některé součástky mění odpor záměrně: potenciometr otočením, fotorezistor podle množství světla a termistor podle teploty.",
        ["learn.project.resistanceIntro.slide6.p3"] = "Výjimkou jsou dlouhé tenké vodiče. Stometrový prodlužovací kabel má několik ohmů a motor s odběrem 10 A na něm ztratí i několik voltů. Proto nářadí na konci dlouhého kabelu běží slaběji.",
        ["learn.project.resistanceIntro.slide6.caption"] = "Od měděného drátu po skleněnou izolaci.",
        ["learn.project.resistanceIntro.slide7.title"] = "Odpor vytváří teplo",
        ["learn.project.resistanceIntro.slide7.p1"] = "Protlačit náboj odporem stojí energii a ta energie se mění v teplo. Výkon, který se v součástce ztrácí, spočítáme jako P = U · I nebo také I² · R.",
        ["learn.project.resistanceIntro.slide7.p2"] = "Náš rezistor 220 Ω při proudu 13,6 mA vydává asi 0,04 W, což je pro běžný čtvrtwattový rezistor bez problémů. Kdybyste jím ale protlačili 100 mA, ztrácel by 2,2 W a začal by se pálit.",
        ["learn.project.resistanceIntro.slide7.p3"] = "Někdy je teplo přímo účelem. Varná konvice, toustovač i stará žárovka jsou v podstatě jen rezistory navržené tak, aby byly horké. Ve všech ostatních případech jde o ztrátu, která omezuje, kolik výkonu malá součástka vydrží.",
        ["learn.project.resistanceIntro.slide7.caption"] = "Držte se pod povoleným výkonem součástky.",
        ["learn.project.resistanceIntro.slide7.callout"] = "P = U · I = I² · R",
        ["learn.project.resistanceIntro.slide8.title"] = "Odpor: co si odnést",
        ["learn.project.resistanceIntro.slide8.p1"] = "Třetí strana trojúhelníku.",
        ["learn.project.resistanceIntro.slide8.fact1"] = "Odpor brání průchodu proudu a měří se v ohmech. Vodiče mají odpor téměř nulový, izolanty obrovský.",
        ["learn.project.resistanceIntro.slide8.fact2"] = "U = I · R. Při stálém napětí znamená větší odpor menší proud.",
        ["learn.project.resistanceIntro.slide8.fact3"] = "Rezistor omezuje proud a nemá polaritu. Jeho hodnotu udávají barevné proužky.",
        ["learn.project.resistanceIntro.slide8.fact4"] = "Odpory v sérii se sčítají. Paralelní zapojení celkový odpor snižuje.",
        ["learn.project.resistanceIntro.slide8.fact5"] = "Proud procházející odporem vytváří teplo: P = I² · R.",
        ["learn.project.ohmsLaw.slide1.title"] = "Jeden zákon, tři veličiny",
        ["learn.project.ohmsLaw.slide1.p1"] = "Napětí tlačí, proud teče a odpor ho brzdí. Ohmův zákon spojuje všechny tři veličiny do jediného vztahu: U = I · R.",
        ["learn.project.ohmsLaw.slide1.p2"] = "Jakmile znáte dvě z těchto veličin, třetí je tím dána. Trojúhelník na obrázku je pomůcka pro zapamatování: zakryjte veličinu, kterou hledáte, a zbylé dvě vám ukážou, zda máte násobit, nebo dělit.",
        ["learn.project.ohmsLaw.slide1.p3"] = "Zákon platí pro každou jednotlivou ohmickou součástku i pro celý jejich řetězec, pokud dosadíte celkové napětí a celkový odpor. Jediný háček je udržet si přehled, které napětí patří ke kterému odporu.",
        ["learn.project.ohmsLaw.slide1.caption"] = "U nahoře, I a R dole.",
        ["learn.project.ohmsLaw.slide1.callout"] = "U = I · R",
        ["learn.project.ohmsLaw.slide2.title"] = "Přímka",
        ["learn.project.ohmsLaw.slide2.p1"] = "Když vynesete do grafu proud rezistorem v závislosti na napětí, dostanete přímku procházející počátkem. Zdvojnásobíte napětí a proud se zdvojnásobí také.",
        ["learn.project.ohmsLaw.slide2.p2"] = "Větší odpor dává plošší přímku, protože stejné napětí vyvolá menší proud. Součástky, jejichž graf je takováto přímka, nazýváme ohmické nebo lineární.",
        ["learn.project.ohmsLaw.slide2.p3"] = "Sklon přímky je 1 / R. Vezměte na ní libovolné dva body a odpor z nich přečtete. Přesně to dělá i multimetr v rozsahu ohmů: pošle součástkou známý proud a změří napětí.",
        ["learn.project.ohmsLaw.slide2.caption"] = "Strmější přímka znamená menší odpor.",
        ["learn.project.ohmsLaw.slide3.title"] = "Řešený příklad: rezistor k LED",
        ["learn.project.ohmsLaw.slide3.p1"] = "Zdroj má 5 V, červená LED potřebuje 2 V a chceme, aby jí protékalo přibližně 15 mA. Rezistor musí převzít zbytek napětí, tedy 5 − 2 = 3 V.",
        ["learn.project.ohmsLaw.slide3.p2"] = "Z Ohmova zákona R = U / I = 3 V / 0,015 A = 200 Ω. Rezistory se vyrábějí jen v normalizovaných hodnotách, takže zaokrouhlíme nahoru na 220 Ω. Rychlá kontrola: 3 / 220 ≈ 13,6 mA, což je v pořádku.",
        ["learn.project.ohmsLaw.slide3.p3"] = "Zaokrouhlení nahoru je záměrné. O něco větší rezistor znamená o něco menší proud, a to je na bezpečné straně. Zaokrouhlením dolů bychom LED zatížili víc, než jsme plánovali.",
        ["learn.project.ohmsLaw.slide3.caption"] = "R1 převezme napětí, které LED nepotřebuje.",
        ["learn.project.ohmsLaw.slide3.callout"] = "R = (U_zdroj − U_LED) / I\n= 3 V / 0,015 A = 200 Ω → 220 Ω",
        ["learn.project.ohmsLaw.slide4.title"] = "Řešený příklad: neznámý rezistor",
        ["learn.project.ohmsLaw.slide4.p1"] = "Změřte napětí na rezistoru a proud, který jím protéká, a Ohmův zákon vám dá jeho odpor: R = U / I.",
        ["learn.project.ohmsLaw.slide4.p2"] = "Když na součástce naměříte 3,0 V a protéká jí 6,4 mA, je odpor 3,0 / 0,0064 ≈ 470 Ω. Multimetr v rozsahu ohmů dělá přesně tento výpočet za vás.",
        ["learn.project.ohmsLaw.slide4.p3"] = "Postup funguje pro cokoli, co se chová jako rezistor: topné tělísko, dlouhý kabel, žárovku při stálém jasu. Dvě měření a jedno dělení.",
        ["learn.project.ohmsLaw.slide4.caption"] = "Ampérmetr do série, voltmetr na součástku. Dvě měření, jedno dělení.",
        ["learn.project.ohmsLaw.slide5.title"] = "Předpony jednotek",
        ["learn.project.ohmsLaw.slide5.p1"] = "Předpona k znamená ×1000, M znamená ×1 000 000, m znamená ÷1000 a µ znamená ÷1 000 000. Většina chyb při počítání s Ohmovým zákonem jsou ve skutečnosti chyby v předponách.",
        ["learn.project.ohmsLaw.slide5.p2"] = "Nejbezpečnější zvyk je převést všechno nejdřív na základní jednotky. Například 3 V / 2,2 kΩ = 3 / 2200 = 0,00136 A, tedy 1,36 mA.",
        ["learn.project.ohmsLaw.slide5.p3"] = "Pomáhá i rychlá kontrola smyslu. Proudy LED jsou miliampéry, rezistory mají stovky ohmů až kiloohmy a napětí v bastlení jsou jednotky voltů. Když výsledek vyjde daleko mimo tyto meze, hledejte ujetou předponu.",
        ["learn.project.ohmsLaw.slide5.caption"] = "Každý krok je násobek 1000.",
        ["learn.project.ohmsLaw.slide5.callout"] = "V ÷ kΩ = mA\nV ÷ MΩ = µA\nmA × kΩ = V",
        ["learn.project.ohmsLaw.slide6.title"] = "Kde zákon přestává platit",
        ["learn.project.ohmsLaw.slide6.p1"] = "LED žádnou přímku nekreslí. Pod přibližně 2 V neteče téměř nic a potom proud prudce roste. Její „odpor“ se mění s napětím, takže ho nelze popsat jediným číslem.",
        ["learn.project.ohmsLaw.slide6.p2"] = "Přesně proto LED potřebuje rezistor. Rezistor je ta ohmická součástka, která proud určuje; LED si jen vezme své 2 V a zbytek smyčky za ni obstará počítání.",
        ["learn.project.ohmsLaw.slide6.p3"] = "Takto se zakřivuje řada součástek: diody, tranzistory nebo žárovka, když se rozžhaví. Ohmův zákon platí v každém jednotlivém pracovním bodě, jen odpor není pevná hodnota. Katalogové listy proto místo čísla uvádějí křivku.",
        ["learn.project.ohmsLaw.slide6.caption"] = "Rezistor: přímka. LED: křivka.",
        ["learn.project.ohmsLaw.slide7.title"] = "Výkon",
        ["learn.project.ohmsLaw.slide7.p1"] = "Výkon je napětí krát proud, P = U · I. Ve spojení s Ohmovým zákonem ho můžeme zapsat také jako I² · R nebo U² / R.",
        ["learn.project.ohmsLaw.slide7.p2"] = "Rezistor k LED z našeho příkladu ztrácí 2,75 V × 13,6 mA ≈ 0,037 W, což je pro čtvrtwattovou součástku zanedbatelné. Naproti tomu rezistor 10 Ω připojený přímo na 5 V by musel zvládnout 2,5 W a shořel by.",
        ["learn.project.ohmsLaw.slide7.p3"] = "Tři vzorce pro výkon jsou jeden a tentýž zákon jen přeskládaný. Použijte tu dvojici veličin, kterou už znáte. U rezistoru to bývá R spolu s U nebo s I.",
        ["learn.project.ohmsLaw.slide7.caption"] = "Vždy si položte dvě otázky: kolik ohmů a kolik wattů.",
        ["learn.project.ohmsLaw.slide7.callout"] = "P = U · I = I² · R = U² / R",
        ["learn.project.ohmsLaw.slide8.title"] = "Ohmův zákon: co si odnést",
        ["learn.project.ohmsLaw.slide8.p1"] = "Pracovní pravidla.",
        ["learn.project.ohmsLaw.slide8.fact1"] = "U = I · R platí pro každou ohmickou součástku.",
        ["learn.project.ohmsLaw.slide8.fact2"] = "Rezistor k LED: R = (U_zdroj − U_LED) / I, potom zaokrouhlit nahoru na normalizovanou hodnotu.",
        ["learn.project.ohmsLaw.slide8.fact3"] = "Neznámý rezistor: R = U / I ze dvou měření.",
        ["learn.project.ohmsLaw.slide8.fact4"] = "Nejdřív převeďte předpony. V ÷ kΩ dává mA.",
        ["learn.project.ohmsLaw.slide8.fact5"] = "LED nejsou ohmické, proto potřebují rezistor. Kontrolujte watty stejně jako ohmy.",
        ["learn.project.circuitElements.slide1.title"] = "Čtyři role",
        ["learn.project.circuitElements.slide1.p1"] = "Každý obvod se skládá ze stejných čtyř rolí: zdroj, který tlačí, zátěž, která energii využívá, vodiče, které uzavírají smyčku, a obvykle také ovládací prvek, který rozhoduje, kdy obvod běží.",
        ["learn.project.circuitElements.slide1.p2"] = "V příkladu s LED je zdrojem baterie, zátěží LED se svým rezistorem, smyčku uzavírají vodiče a zem a ovládacím prvkem je spínač.",
        ["learn.project.circuitElements.slide1.p3"] = "Když obvod nefunguje, projděte role právě v tomto pořadí. Je tam zdroj? Je smyčka uzavřená? Pouští ovládací prvek proud dál? Teprve potom se začněte dívat na samotnou zátěž.",
        ["learn.project.circuitElements.slide1.caption"] = "Zdroj V1, ovládání S1, zátěž R1 + D1, návrat přes zem.",
        ["learn.project.circuitElements.slide2.title"] = "Zdroje",
        ["learn.project.circuitElements.slide2.p1"] = "Baterie dává stálé stejnosměrné napětí; delší čárka na její značce označuje kladný pól. Střídavý zdroj kmitá sem a tam jako síť. Pulzní zdroj skáče mezi dvěma úrovněmi, podobně jako výstupní pin mikrokontroléru.",
        ["learn.project.circuitElements.slide2.p2"] = "Každý zdroj má dva vývody. Proud, který jedním z nich odejde, se musí druhým vrátit zpět.",
        ["learn.project.circuitElements.slide2.p3"] = "Skutečný zdroj má své meze. Baterie nedodá neomezený proud a při velké zátěži jí napětí klesá. Baterie v laboratoři má přesně pro tento jev nastavení vnitřního odporu.",
        ["learn.project.circuitElements.slide2.caption"] = "Tři zdroje, které máte v laboratoři k dispozici.",
        ["learn.project.circuitElements.slide2.fig.l1"] = "Baterie",
        ["learn.project.circuitElements.slide2.fig.l2"] = "Střídavý zdroj",
        ["learn.project.circuitElements.slide2.fig.l3"] = "Pulzní zdroj",
        ["learn.project.circuitElements.slide3.title"] = "Pasivní součástky",
        ["learn.project.circuitElements.slide3.p1"] = "Rezistor omezuje proud. Kondenzátor ukládá náboj a nepropouští stálý stejnosměrný proud. Cívka ukládá energii do magnetického pole a brání se každé změně proudu.",
        ["learn.project.circuitElements.slide3.p2"] = "Žádná z těchto součástek do obvodu energii nepřidává. Pouze určují, jak se energie ze zdroje využije.",
        ["learn.project.circuitElements.slide3.p3"] = "Kondenzátory a cívky hrají roli jen tehdy, když se něco mění. V ustáleném stejnosměrném obvodu se kondenzátor chová jako přerušený vodič a cívka jako obyčejný drát. Jejich skutečný význam se ukáže v lekcích o RC obvodech a o střídavém proudu.",
        ["learn.project.circuitElements.slide3.caption"] = "Ohmy, farady a henry.",
        ["learn.project.circuitElements.slide3.fig.l1"] = "Rezistor",
        ["learn.project.circuitElements.slide3.fig.l2"] = "Kondenzátor",
        ["learn.project.circuitElements.slide3.fig.l3"] = "Cívka",
        ["learn.project.circuitElements.slide4.title"] = "Polovodiče",
        ["learn.project.circuitElements.slide4.p1"] = "Dioda je jednosměrný ventil. Proud teče od anody ke katodě, tedy ke straně s čárkou, a dioda si za otevření vezme přibližně 0,7 V. LED je dioda, která přitom svítí, a její úbytek je asi 2 V.",
        ["learn.project.circuitElements.slide4.p2"] = "Tranzistory jsou řiditelné ventily. Malý signál na jednom vývodu spíná mnohem větší proud mezi zbývajícími dvěma. S bipolárním tranzistorem i s MOSFETem se v kurzu setkáte později.",
        ["learn.project.circuitElements.slide4.p3"] = "Tranzistor je důvod, proč elektronika vůbec existuje. Každý čip v telefonu obsahuje miliardy tranzistorů a každý z nich pracuje jako drobný spínač. Tady začnete s jediným, který spíná LED.",
        ["learn.project.circuitElements.slide4.caption"] = "Jednosměrné součástky a elektronické spínače.",
        ["learn.project.circuitElements.slide4.callout"] = "Značky diody a LED jsou šipky. Proud teče ve směru, kam šipka ukazuje.",
        ["learn.project.circuitElements.slide4.fig.l1"] = "Dioda",
        ["learn.project.circuitElements.slide4.fig.l2"] = "LED",
        ["learn.project.circuitElements.slide4.fig.l3"] = "NPN tranzistor",
        ["learn.project.circuitElements.slide4.fig.l4"] = "N-MOSFET",
        ["learn.project.circuitElements.slide5.title"] = "Ovládání a ochrana",
        ["learn.project.circuitElements.slide5.p1"] = "Spínač cestu rozpojí nebo spojí. Tlačítko dělá to samé, ale jen po dobu, kdy je stisknuté. V laboratoři spínač přepnete kliknutím.",
        ["learn.project.circuitElements.slide5.p2"] = "Potenciometr je rezistor s posuvnou odbočkou, takže jeho odpor lze plynule měnit. Pojistka je úmyslně slabé místo, které se přepálí, když proud příliš vzroste.",
        ["learn.project.circuitElements.slide5.p3"] = "Relé je spínač ovládaný cívkou. Díky němu může malý obvod zapínat a vypínat mnohem větší. Používají ho pozdější lekce a tranzistor dělá tu samou práci bez pohyblivých částí.",
        ["learn.project.circuitElements.slide5.caption"] = "Rozhodují, kdy proud teče a kolik ho teče.",
        ["learn.project.circuitElements.slide5.fig.l1"] = "Spínač",
        ["learn.project.circuitElements.slide5.fig.l2"] = "Tlačítko",
        ["learn.project.circuitElements.slide5.fig.l3"] = "Potenciometr",
        ["learn.project.circuitElements.slide5.fig.l4"] = "Pojistka",
        ["learn.project.circuitElements.slide6.title"] = "Vodiče, uzly, zem a měřidla",
        ["learn.project.circuitElements.slide6.p1"] = "Vodiče jsou v laboratoři dokonalé. Tečka v místě, kde se čáry setkávají, znamená spojení. Čáry, které se křiží bez tečky, spojené nejsou.",
        ["learn.project.circuitElements.slide6.p2"] = "Značka země označuje 0 V a každá značka země ve schématu je jeden a tentýž uzel. Voltmetr se připojuje mezi dva body, ampérmetr se vkládá do cesty proudu.",
        ["learn.project.circuitElements.slide6.p3"] = "Dvě značky země na opačných stranách výkresu jsou spojené, i když mezi nimi není nakreslený žádný vodič. Schéma je díky tomu přehlednější, začátečníky to ale často zmate. Pamatujte: každá zem je jeden a tentýž uzel.",
        ["learn.project.circuitElements.slide6.caption"] = "Pojivo schématu a dvě měřidla.",
        ["learn.project.circuitElements.slide6.fig.l1"] = "Uzel",
        ["learn.project.circuitElements.slide6.fig.l2"] = "Zem",
        ["learn.project.circuitElements.slide6.fig.l3"] = "Voltmetr",
        ["learn.project.circuitElements.slide6.fig.l4"] = "Ampérmetr",
        ["learn.project.circuitElements.slide7.title"] = "Jak číst schéma",
        ["learn.project.circuitElements.slide7.p1"] = "Schéma je mapa propojení, ne obrázek desky plošných spojů. Jediné, na čem záleží, je, který vývod je spojený s kterým.",
        ["learn.project.circuitElements.slide7.p2"] = "Součástky dostávají označení jako R1, D1 nebo C1 a vedle nich se zapisují hodnoty. Schéma čtěte tak, jak jím teče proud: začněte u kladného pólu, sledujte cestu a ujistěte se, že dorazíte zpátky k pólu zápornému.",
        ["learn.project.circuitElements.slide7.p3"] = "Dobrý zvyk: než cokoli spustíte, projeďte smyčku prstem. Pokud se od + zpátky k − nedostanete, aniž byste prst zvedli, obvod fungovat nebude.",
        ["learn.project.circuitElements.slide7.caption"] = "Označení a hodnoty se píší vedle značek.",
        ["learn.project.circuitElements.slide8.title"] = "Prvky obvodu: co si odnést",
        ["learn.project.circuitElements.slide8.p1"] = "Vaše slovní zásoba součástek.",
        ["learn.project.circuitElements.slide8.fact1"] = "Každý obvod má zdroj, zátěž, uzavřenou cestu a obvykle i ovládací prvek.",
        ["learn.project.circuitElements.slide8.fact2"] = "Zdroje: baterie, střídavý zdroj, pulzní zdroj. Delší čárka na baterii je +.",
        ["learn.project.circuitElements.slide8.fact3"] = "Rezistor omezuje, kondenzátor ukládá náboj a nepropouští DC, cívka se brání změnám.",
        ["learn.project.circuitElements.slide8.fact4"] = "Diody a LED jsou šipky. Tranzistory jsou řízené ventily.",
        ["learn.project.circuitElements.slide8.fact5"] = "Tečky spojují, křížení bez tečky ne. Všechny země jsou jeden uzel.",
        ["learn.project.seriesParallelCircuits.slide1.title"] = "Dva způsoby zapojení",
        ["learn.project.seriesParallelCircuits.slide1.p1"] = "Zapojte dvě součástky za sebou a proud má jen jednu cestu, která vede oběma. Takové zapojení je sériové.",
        ["learn.project.seriesParallelCircuits.slide1.p2"] = "Dejte každé součástce vlastní cestu od + k − a proud si může vybrat. Takové zapojení je paralelní. Většina skutečných obvodů oba způsoby kombinuje.",
        ["learn.project.seriesParallelCircuits.slide1.p3"] = "Tato slova popisují, jak jsou součástky propojené, ne kde leží na papíře. Dva rezistory nakreslené vedle sebe jsou pořád v sérii, pokud proud nemá jinou možnost než projít oběma.",
        ["learn.project.seriesParallelCircuits.slide1.caption"] = "Sériové zapojení: jedna cesta, jeden proud.",
        ["learn.project.seriesParallelCircuits.slide2.title"] = "Pravidla pro sériové zapojení",
        ["learn.project.seriesParallelCircuits.slide2.p1"] = "V sériovém obvodu teče všemi součástkami jeden proud. Napětí se mezi součástky rozdělí a jednotlivé úbytky dají dohromady napětí zdroje. Odpory se sčítají.",
        ["learn.project.seriesParallelCircuits.slide2.p2"] = "Dva rezistory 220 Ω v sérii se chovají jako jeden rezistor 440 Ω, takže proud je poloviční oproti tomu, co by propustil jediný rezistor.",
        ["learn.project.seriesParallelCircuits.slide2.p3"] = "Napětí se dělí v poměru odporů: větší rezistor dostane větší díl. Rezistory 220 Ω a 440 Ω zapojené v sérii na 6 V dostanou 2 V a 4 V.",
        ["learn.project.seriesParallelCircuits.slide2.caption"] = "Dva stejné rezistory si každý vezmou polovinu napětí.",
        ["learn.project.seriesParallelCircuits.slide2.callout"] = "R_sériové = R1 + R2\nU_zdroj = U1 + U2\nvšude stejný proud I",
        ["learn.project.seriesParallelCircuits.slide3.title"] = "Pravidla pro paralelní zapojení",
        ["learn.project.seriesParallelCircuits.slide3.p1"] = "V paralelním obvodu vidí každá větev plné napětí zdroje. Každá větev odebírá svůj vlastní proud a zdroj musí dodat jejich součet.",
        ["learn.project.seriesParallelCircuits.slide3.p2"] = "Celkový odpor je menší než odpor kterékoli jednotlivé větve. Dva stejné rezistory paralelně mají poloviční odpor než jeden.",
        ["learn.project.seriesParallelCircuits.slide3.p3"] = "Přidání větve nikdy nesníží proud odebíraný ze zdroje, jen ho zvýší. Proto příliš mnoho topidel v jedné zásuvce vyhodí jistič: každé topidlo je další paralelní cesta.",
        ["learn.project.seriesParallelCircuits.slide3.caption"] = "Stejné napětí na každé větvi; proudy se sčítají.",
        ["learn.project.seriesParallelCircuits.slide3.callout"] = "1 / R_paralelní = 1 / R1 + 1 / R2\nI_zdroj = I1 + I2\nstejné U na každé větvi",
        ["learn.project.seriesParallelCircuits.slide4.title"] = "Co se stane, když součástka selže",
        ["learn.project.seriesParallelCircuits.slide4.p1"] = "V sériovém obvodu jediná vadná součástka přeruší jedinou cestu a všechno se zastaví. Staré vánoční řetězy zhasly naráz přesně z tohoto důvodu.",
        ["learn.project.seriesParallelCircuits.slide4.p2"] = "V paralelním obvodu je každá větev samostatná smyčka. Jedna LED může selhat a druhá svítí dál, jako by se nic nestalo.",
        ["learn.project.seriesParallelCircuits.slide4.p3"] = "Proto je domovní elektroinstalace paralelní. Každá lampa i zásuvka dostane plných 230 V a funguje nezávisle na ostatních. Moderní LED řetězy používají paralelní skupiny ze stejného důvodu.",
        ["learn.project.seriesParallelCircuits.slide4.caption"] = "Paralelně zapojené LED svítí nezávisle na sobě.",
        ["learn.project.seriesParallelCircuits.slide5.title"] = "Kombinace obou zapojení",
        ["learn.project.seriesParallelCircuits.slide5.p1"] = "Příklad v laboratoři zapojuje ke každé LED sériově rezistor a obě dvojice potom spojuje paralelně.",
        ["learn.project.seriesParallelCircuits.slide5.p2"] = "Uvnitř větve použijete pravidla pro sériové zapojení, mezi větvemi pravidla pro paralelní. Kombinovaný obvod zjednodušujte zevnitř ven.",
        ["learn.project.seriesParallelCircuits.slide5.p3"] = "Každá větev tu odebírá asi 13 mA, takže baterie dodává přibližně 26 mA. Přidejte třetí stejnou větev a celkem to bude 39 mA. LEDky si jedna druhé nevšimnou; baterie ano.",
        ["learn.project.seriesParallelCircuits.slide5.caption"] = "Každá větev je sériová dvojice.",
        ["learn.project.seriesParallelCircuits.slide6.title"] = "Rychlý test",
        ["learn.project.seriesParallelCircuits.slide6.p1"] = "Sériově: jediná cesta od jedné součástky k druhé je jeden vodič, na kterém není připojené nic dalšího.",
        ["learn.project.seriesParallelCircuits.slide6.p2"] = "Paralelně: oba konce obou součástek leží na stejných dvou uzlech. Poznávacím znamením je tečka uzlu.",
        ["learn.project.seriesParallelCircuits.slide6.p3"] = "Když si nejste jistí, sledujte proud od + a v každém bodě se zeptejte: má na výběr? Bez výběru je zapojení sériové. S výběrem tu začínají paralelní větve.",
        ["learn.project.seriesParallelCircuits.slide6.caption"] = "Uzel znamená větve.",
        ["learn.project.seriesParallelCircuits.slide6.callout"] = "Stejný proud: sériové. Stejné napětí: paralelní.",
        ["learn.project.seriesParallelCircuits.slide7.title"] = "Sériové a paralelní: co si odnést",
        ["learn.project.seriesParallelCircuits.slide7.p1"] = "Dvě sady pravidel.",
        ["learn.project.seriesParallelCircuits.slide7.fact1"] = "Sériové: stejný proud, napětí se sčítají, odpory se sčítají.",
        ["learn.project.seriesParallelCircuits.slide7.fact2"] = "Paralelní: stejné napětí, proudy se sčítají, celkový odpor klesá.",
        ["learn.project.seriesParallelCircuits.slide7.fact3"] = "Vadná součástka v sérii zastaví všechno. Paralelní větve jsou nezávislé.",
        ["learn.project.seriesParallelCircuits.slide7.fact4"] = "Kombinované obvody zjednodušujte zevnitř ven.",
        ["learn.project.acDc.slide1.title"] = "Dva druhy proudu",
        ["learn.project.acDc.slide1.p1"] = "Stejnosměrný proud, zkráceně DC, teče stále stejným směrem a má stálou hodnotu. Dodávají ho baterie, porty USB i solární články.",
        ["learn.project.acDc.slide1.p2"] = "Střídavý proud, AC, mění směr mnohokrát za sekundu a má průběh sinusovky. Přesně takový proud teče ze zásuvky.",
        ["learn.project.acDc.slide1.p3"] = "Energii přenášejí oba druhy stejně dobře. Rozdíl je v tom, co k nim můžete připojit: LED a čipy potřebují stejnosměrný proud, topení a mnoho motorů snesou oba a transformátory pracují jen se střídavým.",
        ["learn.project.acDc.slide1.caption"] = "Stejnosměrný proud je rovná čára. Střídavý prochází nulou dvakrát za periodu.",
        ["learn.project.acDc.slide2.title"] = "Stejnosměrný proud",
        ["learn.project.acDc.slide2.p1"] = "Stejnosměrný proud má polaritu. Otočte baterii a LED zhasne, motor se roztočí opačným směrem. Záleží na tom, který pól je který.",
        ["learn.project.acDc.slide2.p2"] = "Stejnosměrná analýza v laboratoři předpokládá, že se všechno už ustálilo. Dá vám jedno napětí pro každý uzel a jeden proud pro každou součástku, nic se v čase nemění.",
        ["learn.project.acDc.slide2.p3"] = "Ani stejnosměrné napětí není skoro nikdy dokonale rovné. Výstup nabíječky má malé zvlnění a napětí baterie s vybíjením klesá. „Stejnosměrný“ znamená, že se nikdy neobrátí směr, ne že se hodnota nikdy nepohne.",
        ["learn.project.acDc.slide2.caption"] = "Zdroj 5 V, v každém okamžiku stejný.",
        ["learn.project.acDc.slide3.title"] = "Střídavý proud",
        ["learn.project.acDc.slide3.p1"] = "Jeden úplný kmit vlny je perioda a její trvání označujeme T. Počet period za sekundu je frekvence f = 1 / T a měří se v hertzích.",
        ["learn.project.acDc.slide3.p2"] = "Evropská síť má 50 Hz, takže jedna perioda trvá 20 ms. Zvukové signály zabírají přibližně rozsah 20 Hz až 20 kHz.",
        ["learn.project.acDc.slide3.p3"] = "Frekvence je to, co ucho vnímá jako výšku tónu a na co se ladí rádio. Brum, který občas slyšíte z transformátoru nebo levného zesilovače, je právě 50 Hz sítě.",
        ["learn.project.acDc.slide3.caption"] = "Perioda T a amplituda Û.",
        ["learn.project.acDc.slide3.callout"] = "f = 1 / T\n50 Hz → T = 20 ms",
        ["learn.project.acDc.slide4.title"] = "Špičková a efektivní hodnota",
        ["learn.project.acDc.slide4.p1"] = "Špičková hodnota Û je vrchol vlny. Hodnota špička–špička je celý rozkmit od spodku k vrcholu, tedy dvojnásobek.",
        ["learn.project.acDc.slide4.p2"] = "Efektivní hodnota je takové stejnosměrné napětí, které by rezistor zahřálo stejně. Pro sinusovku platí U_ef = Û / √2. Když říkáme „230 V“, myslíme efektivní hodnotu; špička je přibližně 325 V.",
        ["learn.project.acDc.slide4.p3"] = "Efektivní hodnota je číslo, které rozhoduje o výkonu i o bezpečnosti. Údaj „12 V AC“ je efektivní hodnota a špička je asi 17 V. Součástky musí vydržet špičku, nejen efektivní hodnotu.",
        ["learn.project.acDc.slide4.caption"] = "Špička, efektivní hodnota na 0,707 špičky a celý rozkmit.",
        ["learn.project.acDc.slide4.callout"] = "U_ef = Û / √2",
        ["learn.project.acDc.slide5.title"] = "Proč je síť střídavá a spotřebiče stejnosměrné",
        ["learn.project.acDc.slide5.p1"] = "Transformátor dokáže střídavé napětí zvýšit nebo snížit téměř beze ztrát, funguje ale jen s měnícím se proudem. Proto elektřina cestuje přes zemi při velmi vysokém napětí a teprve u vás v ulici klesne na 230 V.",
        ["learn.project.acDc.slide5.p2"] = "Čipy a LED potřebují stálé stejnosměrné napětí, takže každá nabíječka i každý zdroj musí střídavé napětí ze zásuvky převést na stejnosměrné.",
        ["learn.project.acDc.slide5.p3"] = "Ztráta v kabelu je I² · R. Desetkrát vyšší napětí znamená při stejném výkonu desetinu proudu, a tedy setinu ztrát. To je celý důvod, proč existují vedení vysokého napětí.",
        ["learn.project.acDc.slide5.caption"] = "Střídavý proud na přenos, stejnosměrný u spotřebiče.",
        ["learn.project.acDc.slide6.title"] = "Ze střídavého na stejnosměrný",
        ["learn.project.acDc.slide6.p1"] = "Dioda propustí jen jednu polovinu každé periody. Čtyři diody zapojené do můstku překlopí nahoru i záporné půlvlny. Tomu se říká usměrnění.",
        ["learn.project.acDc.slide6.p2"] = "Výsledek je pořád hrbolatý. Kondenzátor vyplní mezery mezi hrboly a nechá mnohem hladší napětí s malým zvlněním. Stabilizátor pak výstup udrží na pevné hodnotě, například 5 V.",
        ["learn.project.acDc.slide6.p3"] = "Otevřete jakoukoli USB nabíječku a najdete přesně tyto stupně: usměrňovač, kondenzátor a stabilizátor, obvykle spínaný. V modulu o napájení si každý z nich postavíte.",
        ["learn.project.acDc.slide6.caption"] = "Usměrněné hrboly a vyhlazený výstup.",
        ["learn.project.acDc.slide7.title"] = "Střídavý proud v laboratoři",
        ["learn.project.acDc.slide7.p1"] = "Umístěte střídavý zdroj, nastavte jeho frekvenci a spusťte analýzu AC. Každý uzel pak místo jediného napětí dostane velikost a fázi.",
        ["learn.project.acDc.slide7.p2"] = "Kondenzátory stejnosměrný proud nepropouštějí, střídavý ale ano, a čím vyšší frekvence, tím snáz. Na tomto chování jsou postavené filtry a modul o filtrech ho rozvíjí dál.",
        ["learn.project.acDc.slide7.p3"] = "Analýza AC předpokládá čistou sinusovku o jedné frekvenci a říká, jak na ni obvod reaguje. Když chcete vidět skutečný tvar vlny v čase, použijte místo ní analýzu Transient.",
        ["learn.project.acDc.slide7.caption"] = "Příklad střídavého RC obvodu.",
        ["learn.project.acDc.slide7.fig.l1"] = "Střídavý zdroj",
        ["learn.project.acDc.slide7.fig.l2"] = "Rezistor",
        ["learn.project.acDc.slide7.fig.l3"] = "Kondenzátor",
        ["learn.project.acDc.slide7.fig.l4"] = "Zem",
        ["learn.project.acDc.slide8.title"] = "Střídavý a stejnosměrný: co si odnést",
        ["learn.project.acDc.slide8.p1"] = "To nejdůležitější.",
        ["learn.project.acDc.slide8.fact1"] = "Stejnosměrný proud teče jedním směrem se stálou hodnotou a má polaritu.",
        ["learn.project.acDc.slide8.fact2"] = "Střídavý proud je sinusovka. f = 1 / T. Síť má 50 nebo 60 Hz.",
        ["learn.project.acDc.slide8.fact3"] = "Střídavé napětí popisuje špičková nebo efektivní hodnota. U_ef = Û / √2 a „230 V“ je efektivní hodnota.",
        ["learn.project.acDc.slide8.fact4"] = "Síť je střídavá kvůli transformátorům. Elektronika běží na stejnosměrný proud.",
        ["learn.project.acDc.slide8.fact5"] = "Diody usměrňují, kondenzátory vyhlazují, stabilizátory drží hodnotu.",
        ["learn.project.fundamentalsLoop.slide1.title"] = "Jedna cesta tam, jedna zpátky",
        ["learn.project.fundamentalsLoop.slide1.p1"] = "Tohle je nejmenší užitečný obvod: baterie, rezistor, LED a návrat do země. Proud odchází z kladného pólu, prochází postupně každou součástkou a vrací se k pólu zápornému.",
        ["learn.project.fundamentalsLoop.slide1.p2"] = "Každá součástka leží na této jediné cestě. Odeberte kteroukoli z nich a žádný obvod už nezbude.",
        ["learn.project.fundamentalsLoop.slide1.p3"] = "Na pořadí součástek na cestě nezáleží. Dejte rezistor před LED nebo za ni, stejných 12,5 mA poteče v obou případech.",
        ["learn.project.fundamentalsLoop.slide1.caption"] = "Pohybující se čárky ukazují jediný proud, který obíhá smyčkou.",
        ["learn.project.fundamentalsLoop.slide2.title"] = "Přerušte ji kdekoli",
        ["learn.project.fundamentalsLoop.slide2.p1"] = "Rozepněte spínač, vytáhněte vodič nebo spalte LED a proud se zastaví všude ve stejném okamžiku, ne jen v místě přerušení.",
        ["learn.project.fundamentalsLoop.slide2.p2"] = "Součástí smyčky je i zem. Bez zpětného vodiče nic nesvítí, i když baterie zůstává na svém místě.",
        ["learn.project.fundamentalsLoop.slide2.p3"] = "Přerušení je vlastně jen velmi velký odpor. Ohmův zákon s obrovským R dává proud prakticky nulový, a přesně to vidíte na každém vodiči.",
        ["learn.project.fundamentalsLoop.slide2.caption"] = "Jedna mezera, nulový proud.",
        ["learn.project.fundamentalsLoop.slide3.title"] = "Čtení popisků",
        ["learn.project.fundamentalsLoop.slide3.p1"] = "Po spuštění stejnosměrné analýzy ukáže každý uzel své napětí vůči zemi a každá součástka proud, který jí protéká.",
        ["learn.project.fundamentalsLoop.slide3.p2"] = "Baterie, rezistor i LED ukazují stejný proud, protože existuje jen jedna cesta. Napětí uzlů klesají po smyčce od 5 V k 0 V.",
        ["learn.project.fundamentalsLoop.slide3.p3"] = "Popisky napětí mají smysl jen vůči zemi. Když značka země chybí, laboratoř nemá nulu, od které by měřila, a dá vám to vědět.",
        ["learn.project.fundamentalsLoop.slide3.caption"] = "5 V na vstupu, 2,75 V na R1, 2,25 V na D1, 0 V na zemi.",
        ["learn.project.fundamentalsLoop.slide4.title"] = "Teď to postavte",
        ["learn.project.fundamentalsLoop.slide4.p1"] = "V laboratoři:",
        ["learn.project.fundamentalsLoop.slide4.fact1"] = "Umístěte baterii, rezistor, LED a značku země. Propojte + → R → LED → zem a zem zpátky k −.",
        ["learn.project.fundamentalsLoop.slide4.fact2"] = "Spusťte stejnosměrnou analýzu. LED by měla svítit a ukazovat asi 12,5 mA.",
        ["learn.project.fundamentalsLoop.slide4.fact3"] = "Změřte uzel mezi rezistorem a LED. Leží blízko 2,25 V.",
        ["learn.project.fundamentalsLoop.slide4.fact4"] = "Smažte jeden vodič a spusťte znovu. Všechno se zastaví.",
        ["learn.project.led.slide1.title"] = "Proč rezistor?",
        ["learn.project.led.slide1.p1"] = "LED připojená přímo na baterii nemá nic, co by omezilo proud. Odebírá mnohem víc, než vydrží, a během okamžiku shoří.",
        ["learn.project.led.slide1.p2"] = "Rezistor v sérii promění pevné napětí na bezpečný a předvídatelný proud. To je tady jeho jediný úkol, ale zásadní.",
        ["learn.project.led.slide1.p3"] = "Berte LED jako součástku, která určuje napětí, a rezistor jako součástku, která určuje proud. Ani jeden z nich nemůže dělat práci toho druhého.",
        ["learn.project.led.slide1.caption"] = "Příliš malý odpor: 40 mA a zničená LED.",
        ["learn.project.led.slide1.callout"] = "LED nikdy nepřipojujte přímo na zdroj.",
        ["learn.project.led.slide2.title"] = "LED si vezme 2 V",
        ["learn.project.led.slide2.p1"] = "Svítící LED si na sobě drží přibližně 2 V téměř bez ohledu na proud. Rezistor převezme zbytek napájecího napětí.",
        ["learn.project.led.slide2.p2"] = "Při napájení 5 V zůstávají rezistoru 3 V. Tyto 3 V spolu s odporem R určují proud.",
        ["learn.project.led.slide2.p3"] = "Přesné napětí LED závisí na barvě. Červená má kolem 1,8 až 2 V, zelená a modrá kolem 3 V. Modrá LED na 5 V nechá rezistoru jen 2 V, takže pro stejný proud potřebuje menší rezistor.",
        ["learn.project.led.slide2.caption"] = "Asi 2 V na LED, zbytek na R1.",
        ["learn.project.led.slide3.title"] = "Volba hodnoty",
        ["learn.project.led.slide3.p1"] = "Zvolte proud, řekněme 15 mA. Potom R = (5 − 2) V / 0,015 A = 200 Ω. Zaokrouhlete nahoru na normalizovanou hodnotu 220 Ω.",
        ["learn.project.led.slide3.p2"] = "Menší rezistor znamená jasnější LED, až do chvíle, kdy se LED upeče. Větší rezistor dá LED slabší, ale delší život.",
        ["learn.project.led.slide3.p3"] = "Rezistory se vyrábějí v řadách: 100, 150, 220, 330, 470, 680 Ω a tak dále. Vyberte nejbližší hodnotu nad tou, kterou jste spočítali.",
        ["learn.project.led.slide3.caption"] = "R = U / I s napětím, které připadá na rezistor.",
        ["learn.project.led.slide3.callout"] = "R = (U_zdroj − U_LED) / I",
        ["learn.project.led.slide4.title"] = "Postavte to",
        ["learn.project.led.slide4.p1"] = "V laboratoři:",
        ["learn.project.led.slide4.fact1"] = "Baterie, rezistor, LED, zem. Nejméně čtyři vodiče.",
        ["learn.project.led.slide4.fact2"] = "Spusťte stejnosměrnou analýzu. LED vede a zůstává v pořádku.",
        ["learn.project.led.slide4.fact3"] = "Snižujte R1 krok za krokem. Sledujte, jak jas roste a jak se LED při asi 35 mA spálí.",
        ["learn.project.led.slide4.fact4"] = "Vyměňte LED a vraťte R1 na 220 Ω.",
        ["learn.project.diodeDirection.slide1.title"] = "Jednosměrný ventil",
        ["learn.project.diodeDirection.slide1.p1"] = "Dioda propouští proud jedním směrem a druhým ho blokuje. Její značka je šipka: proud teče tam, kam šipka ukazuje, od anody ke katodě, což je strana s čárkou.",
        ["learn.project.diodeDirection.slide1.p2"] = "LED je také dioda, takže na její orientaci záleží úplně stejně.",
        ["learn.project.diodeDirection.slide1.p3"] = "Na skutečné součástce je katoda označená: proužkem na diodě, kratší nožičkou nebo plochou hranou na LED. V laboratoři značku otáčejte, dokud čárka nemíří tam, kde má proud skončit.",
        ["learn.project.diodeDirection.slide1.caption"] = "Anoda na ploché straně, katoda u čárky.",
        ["learn.project.diodeDirection.slide1.fig.l1"] = "Dioda",
        ["learn.project.diodeDirection.slide1.fig.l2"] = "LED",
        ["learn.project.diodeDirection.slide2.title"] = "Propustný směr: dioda vede",
        ["learn.project.diodeDirection.slide2.p1"] = "S anodou směrem ke kladnému pólu se dioda otevře. Udržet ji otevřenou stojí přibližně 0,7 V u běžné diody a asi 2 V u LED.",
        ["learn.project.diodeDirection.slide2.p2"] = "Zbytek smyčky se chová jako obvykle a LED svítí.",
        ["learn.project.diodeDirection.slide2.p3"] = "Těch 0,7 V nebo 2 V se v součástce ztratí jako teplo. Není to mnoho, ale musíte je od napájení odečíst, než začnete počítat rezistor.",
        ["learn.project.diodeDirection.slide2.caption"] = "Propustný směr. Proud teče a LED svítí.",
        ["learn.project.diodeDirection.slide3.title"] = "Závěrný směr: dioda blokuje",
        ["learn.project.diodeDirection.slide3.p1"] = "Otočte diodu a neteče skoro nic. Celé napájecí napětí teď leží na diodě a LED zůstává zhasnutá.",
        ["learn.project.diodeDirection.slide3.p2"] = "To není porucha. Dioda dělá přesně to, k čemu je určená.",
        ["learn.project.diodeDirection.slide3.p3"] = "Závěrný směr má svou mez. Když na skutečnou diodu zatlačíte obráceně dost silně, prorazí. Malé signálové diody vydrží desítky voltů a nic v tomto kurzu se k tomu ani nepřiblíží.",
        ["learn.project.diodeDirection.slide3.caption"] = "Závěrný směr. Nikde neteče proud.",
        ["learn.project.diodeDirection.slide4.title"] = "Vyzkoušejte oba směry",
        ["learn.project.diodeDirection.slide4.p1"] = "V laboratoři:",
        ["learn.project.diodeDirection.slide4.fact1"] = "Spusťte příklad s diodou tak, jak je. LED svítí.",
        ["learn.project.diodeDirection.slide4.fact2"] = "Vyberte D1 a dvakrát ji otočte (o 180°). Spusťte znovu. Tma.",
        ["learn.project.diodeDirection.slide4.fact3"] = "Změřte uzel před diodou: čeká tam plné napětí.",
        ["learn.project.diodeDirection.slide4.fact4"] = "Otočte ji zpátky. Zase to funguje.",
        ["learn.project.seriesLeds.slide1.title"] = "Jeden řetěz",
        ["learn.project.seriesLeds.slide1.p1"] = "Dvě LED a rezistor v jedné řadě. Existuje jediná cesta, takže všemi součástkami teče jeden a tentýž proud.",
        ["learn.project.seriesLeds.slide1.p2"] = "Stejný proud znamená, že LED svítí stejně jasně.",
        ["learn.project.seriesLeds.slide1.p3"] = "Sériový řetěz je obvyklý způsob, jak napájet několik LED z jediného rezistoru. Jeden rezistor, jeden proud a každá LED v řetězu svítí stejně.",
        ["learn.project.seriesLeds.slide1.caption"] = "LED v sérii: jeden proud.",
        ["learn.project.seriesLeds.slide2.title"] = "Úbytky se sčítají",
        ["learn.project.seriesLeds.slide2.p1"] = "Každá LED si vezme přibližně 2 V. Dvě LED tedy spotřebují 4 V dřív, než na rezistor zbude vůbec něco.",
        ["learn.project.seriesLeds.slide2.p2"] = "Proto tento příklad používá baterii 9 V. S 5 V by na rezistor zbyl jediný volt a tekl by jen velmi malý proud.",
        ["learn.project.seriesLeds.slide2.p3"] = "Napájení musí být větší než součet napětí LED, a to s rezervou pro rezistor. Tři LED po 2 V chtějí přinejmenším kolem 8 V, aby zůstal pohodlný odstup.",
        ["learn.project.seriesLeds.slide2.caption"] = "9 V = 2 V + 2 V + 5 V na rezistoru.",
        ["learn.project.seriesLeds.slide2.callout"] = "I = (9 − 2 − 2) V / 470 Ω ≈ 10,6 mA",
        ["learn.project.seriesLeds.slide3.title"] = "Vyzkoušejte",
        ["learn.project.seriesLeds.slide3.p1"] = "V laboratoři:",
        ["learn.project.seriesLeds.slide3.fact1"] = "Spusťte příklad se sériovými LED. Obě LED ukazují stejný proud.",
        ["learn.project.seriesLeds.slide3.fact2"] = "Změňte baterii na 5 V a spusťte znovu. Sledujte, jak se proud zhroutí.",
        ["learn.project.seriesLeds.slide3.fact3"] = "Zpět na 9 V. Přidejte třetí LED a sledujte, jak proud znovu klesne.",
        ["learn.project.ledBurnLimit.slide1.title"] = "Co znamená „příliš“",
        ["learn.project.ledBurnLimit.slide1.p1"] = "Do přibližně 20 mA je LED v laboratoři jasná a v naprostém pořádku. Nad touto hodnotou je přetížená. Nad zhruba 35 mA shoří a zůstane zničená, dokud ji nevyměníte.",
        ["learn.project.ledBurnLimit.slide1.p2"] = "Skutečné LED se chovají stejně, jen o něco méně dramaticky.",
        ["learn.project.ledBurnLimit.slide1.p3"] = "Katalogové listy nazývají bezpečnou hodnotu trvalým propustným proudem, u malých LED obvykle 20 mA. Absolutní maximum uvedené nad ní je určené pro krátké pulzy, ne pro běžný provoz.",
        ["learn.project.ledBurnLimit.slide1.caption"] = "Zelená je pohoda, červená je konec.",
        ["learn.project.ledBurnLimit.slide2.title"] = "Jak vypadá 40 mA",
        ["learn.project.ledBurnLimit.slide2.p1"] = "S příliš malým rezistorem LED krátce zazáří a pak se přeruší. Celá smyčka s ní zhasne.",
        ["learn.project.ledBurnLimit.slide2.p2"] = "V laboratoři se součástka změní na spálenou značku. Novou získáte volbou Vyměnit LED.",
        ["learn.project.ledBurnLimit.slide2.p3"] = "Spálená LED se přeruší, takže s ní zhasne celá sériová smyčka. To je jediná výhoda této poruchy: rezistor i baterie zůstanou bez úhony.",
        ["learn.project.ledBurnLimit.slide2.caption"] = "Přetížená LED při 40 mA.",
        ["learn.project.ledBurnLimit.slide3.title"] = "Zabíjí teplo",
        ["learn.project.ledBurnLimit.slide3.p1"] = "Výkon je napětí krát proud. Zdvojnásobte proud a teplo vznikající v čipu LED se zhruba zdvojnásobí také.",
        ["learn.project.ledBurnLimit.slide3.p2"] = "Bezpečný návrh drží LED na 10 až 20 mA a rezistor nechává hluboko pod jeho povoleným výkonem.",
        ["learn.project.ledBurnLimit.slide3.p3"] = "LED také rychleji stárnou, když běží horké. Svítidlo navržené na 15 mA vydrží mnohem déle než stejná LED hnaná na 25 mA, i když první den fungují obě stejně dobře.",
        ["learn.project.ledBurnLimit.slide3.caption"] = "Udržujte v chladu LED i rezistor.",
        ["learn.project.ledBurnLimit.slide4.title"] = "Vyzkoušejte a napravte",
        ["learn.project.ledBurnLimit.slide4.p1"] = "V laboratoři:",
        ["learn.project.ledBurnLimit.slide4.fact1"] = "Snižujte R1, dokud LED neshoří. Poznamenejte si proud, při kterém k tomu došlo.",
        ["learn.project.ledBurnLimit.slide4.fact2"] = "Vyměňte LED.",
        ["learn.project.ledBurnLimit.slide4.fact3"] = "Zvolte rezistor, který udrží proud pod 25 mA, a spusťte znovu.",
        ["learn.project.rc.slide1.title"] = "Kondenzátor ukládá náboj",
        ["learn.project.rc.slide1.p1"] = "Kondenzátor jsou dvě desky s mezerou mezi nimi. Přiveďte napětí a na deskách se začne hromadit náboj. Čím víc náboje drží, tím vyšší je napětí mezi nimi.",
        ["learn.project.rc.slide1.p2"] = "Kapacita, měřená ve faradech, říká, kolik náboje kondenzátor uloží na jeden volt. Hodnota 1 µF je pro malé obvody typická.",
        ["learn.project.rc.slide1.p3"] = "Kondenzátory sahají od pikofaradů v rádiích po tisíce mikrofaradů ve zdrojích. Větší hodnota znamená víc náboje při stejném napětí a víc času na naplnění přes stejný rezistor.",
        ["learn.project.rc.slide1.caption"] = "Součástky RC příkladu.",
        ["learn.project.rc.slide1.fig.l1"] = "Baterie",
        ["learn.project.rc.slide1.fig.l2"] = "Rezistor",
        ["learn.project.rc.slide1.fig.l3"] = "Kondenzátor",
        ["learn.project.rc.slide2.title"] = "Nabíjení přes rezistor",
        ["learn.project.rc.slide2.p1"] = "Připojte baterii přes rezistor a kondenzátor se začne plnit. Na začátku je proud velký. Jak napětí kondenzátoru roste, zbývá na rezistor méně napětí, a proud se proto zmenšuje.",
        ["learn.project.rc.slide2.p2"] = "Plnění se tedy postupně zpomaluje. Poslední část nárůstu trvá mnohem déle než ta první.",
        ["learn.project.rc.slide2.p3"] = "Proud tu není jedno pevné číslo. Začíná na U / R, jako by byl kondenzátor zkratem, a klesá k nule, jak se napětí kondenzátoru blíží napětí baterie.",
        ["learn.project.rc.slide2.caption"] = "Proud teče jen po dobu, kdy se kondenzátor ještě nabíjí.",
        ["learn.project.rc.slide3.title"] = "Časová konstanta",
        ["learn.project.rc.slide3.p1"] = "Časová konstanta je τ = R · C. S 1 kΩ a 1 µF vychází τ = 1 ms. Po jednom τ dosáhne kondenzátor 63 % konečného napětí a po 5τ je prakticky plný.",
        ["learn.project.rc.slide3.p2"] = "Větší rezistor nebo větší kondenzátor znamená pomalejší nabíjení, protože obojí τ prodlužuje.",
        ["learn.project.rc.slide3.p3"] = "τ je pravidlo, které použijete i bez kalkulačky. Zdvojnásobte R nebo C a celá křivka se roztáhne na dvojnásobnou šířku. Řídí každé RC zpoždění, filtr i časovač v dalších lekcích.",
        ["learn.project.rc.slide3.caption"] = "Nabíjecí křivka. 63 % při τ, hotovo do 5τ.",
        ["learn.project.rc.slide3.callout"] = "τ = R · C\n1 kΩ · 1 µF = 1 ms",
        ["learn.project.rc.slide4.title"] = "Odečtení τ z osciloskopu",
        ["learn.project.rc.slide4.p1"] = "Najděte místo, kde napětí kondenzátoru dosáhne 63 % konečné hodnoty. Čas, který k tomu potřeboval, je jedno τ. Při napájení 5 V je to bod 3,15 V.",
        ["learn.project.rc.slide4.p2"] = "Po 3τ je napětí na 95 %, po 5τ na 99 %. Inženýři považují 5τ za plné nabití.",
        ["learn.project.rc.slide4.p3"] = "Vybíjení se řídí stejným pravidlem obráceně. Po jednom τ kondenzátor ztratil 63 % napětí a stále drží 37 %. Tvar je zrcadlovým obrazem nabíjecí křivky.",
        ["learn.project.rc.slide4.caption"] = "Každé τ uzavře 63 % zbývající mezery.",
        ["learn.project.rc.slide4.callout"] = "1τ → 63 %\n3τ → 95 %\n5τ → 99 %",
        ["learn.project.rc.slide5.title"] = "Sledujte to naživo",
        ["learn.project.rc.slide5.p1"] = "V laboratoři:",
        ["learn.project.rc.slide5.fact1"] = "Nejdřív si z hodnot součástek spočítejte τ = R · C.",
        ["learn.project.rc.slide5.fact2"] = "Otevřete RC příklad. Přepněte na Transient a spusťte.",
        ["learn.project.rc.slide5.fact3"] = "Najeďte na osciloskopu poblíž 63 % konečného napětí a porovnejte čas se svým odhadem.",
        ["learn.project.rc.slide5.fact4"] = "Změňte C na 10 µF a spusťte znovu. Desetkrát pomalejší.",
        ["learn.project.ledFade.slide1.title"] = "Nejdřív uložit",
        ["learn.project.ledFade.slide1.p1"] = "Se sepnutým spínačem baterie nabíjí velký kondenzátor. LED přitom svítí ze stejného zdroje.",
        ["learn.project.ledFade.slide1.p2"] = "Nabitý kondenzátor je malá zásobárna energie sedící hned vedle LED.",
        ["learn.project.ledFade.slide1.p3"] = "Kondenzátor o několika stovkách mikrofaradů drží při 5 V znatelnou energii. Dost na to, aby LED chvíli dosvítila, málo na to, aby něco běželo dlouho.",
        ["learn.project.ledFade.slide1.caption"] = "Nabíjení: kondenzátor se plní, dokud je spínač sepnutý.",
        ["learn.project.ledFade.slide2.title"] = "Potom uvolnit",
        ["learn.project.ledFade.slide2.p1"] = "Rozepněte spínač. Baterie je ze hry, ale kondenzátor si pořád drží své napětí a dál tlačí proud přes rezistor a LED.",
        ["learn.project.ledFade.slide2.p2"] = "Jeho napětí klesá po vybíjecí křivce se stejnou časovou konstantou τ = R · C jako předtím.",
        ["learn.project.ledFade.slide2.p3"] = "Vybíjecím rezistorem je tu rezistor LED. Menší R kondenzátor vyprázdní rychleji a dosvit se zkrátí; větší R ho natáhne.",
        ["learn.project.ledFade.slide2.caption"] = "Vybíjení: po jednom τ na 37 %.",
        ["learn.project.ledFade.slide3.title"] = "Proč LED pohasíná",
        ["learn.project.ledFade.slide3.p1"] = "Proud LED sleduje napětí kondenzátoru zmenšené o 2 V, které si LED bere. Jak napětí klesá, proud se zmenšuje a LED slábne.",
        ["learn.project.ledFade.slide3.p2"] = "Jakmile kondenzátor klesne pod přibližně 2 V, LED úplně zhasne, i když v něm ještě nějaký náboj zbývá.",
        ["learn.project.ledFade.slide3.p3"] = "Proto v některých přístrojích LED po vypnutí ještě chvíli dosvítí. Někde uvnitř se přes ně pořád vybíjí kondenzátor.",
        ["learn.project.ledFade.slide3.caption"] = "Proud sjíždí po stupnici dolů, jak se kondenzátor vyprazdňuje.",
        ["learn.project.ledFade.slide4.title"] = "Vyzkoušejte",
        ["learn.project.ledFade.slide4.p1"] = "V laboratoři:",
        ["learn.project.ledFade.slide4.fact1"] = "Spusťte se sepnutým spínačem. Kondenzátor se nabije.",
        ["learn.project.ledFade.slide4.fact2"] = "Zrušte zaškrtnutí Sepnuto a spusťte znovu. Sledujte, jak LED pohasíná.",
        ["learn.project.ledFade.slide4.fact3"] = "Změňte C na 470 µF. Dosvit se výrazně zkrátí.",
        ["learn.project.pulseRc.slide1.title"] = "Hrany se zaoblí",
        ["learn.project.pulseRc.slide1.p1"] = "Pulzní zdroj skáče mezi 0 a 5 V. Přiveďte to na rezistor s kondenzátorem a výstup s ním skákat nedokáže. Místo toho se nabíjí a vybíjí po RC křivkách.",
        ["learn.project.pulseRc.slide1.p2"] = "Dovnitř jdou ostré hrany, ven vychází zaoblené.",
        ["learn.project.pulseRc.slide1.p3"] = "Výstup se řídí stejným τ = R · C jako ve stejnosměrném RC příkladu. Jediný rozdíl je, že se vstup změní dřív, než kondenzátor stihne doběhnout.",
        ["learn.project.pulseRc.slide1.caption"] = "Obdélníkový pulz na vstupu, zaoblená odezva na výstupu.",
        ["learn.project.pulseRc.slide2.title"] = "Šířka pulzu proti τ",
        ["learn.project.pulseRc.slide2.p1"] = "Když pulz trvá mnohem déle než τ, výstup dosáhne vrcholu ještě před koncem pulzu. Když je pulz kratší než τ, výstup se tam nikdy nedostane.",
        ["learn.project.pulseRc.slide2.p2"] = "Přesně na tom stojí RC zpoždění i jednoduché filtry.",
        ["learn.project.pulseRc.slide2.p3"] = "Filtry pracují na stejném principu. Signál, který se mění mnohem rychleji než τ, skoro neprojde, zatímco pomalý projde téměř beze změny.",
        ["learn.project.pulseRc.slide2.caption"] = "Pulz 4 ms s τ = 1 ms se dostane asi na 98 %.",
        ["learn.project.pulseRc.slide2.callout"] = "τ = 1 kΩ · 1 µF = 1 ms",
        ["learn.project.pulseRc.slide3.title"] = "Vyzkoušejte",
        ["learn.project.pulseRc.slide3.p1"] = "V laboratoři:",
        ["learn.project.pulseRc.slide3.fact1"] = "Spusťte příklad s pulzem v Transientu. Porovnejte průběh na vstupu a na výstupu.",
        ["learn.project.pulseRc.slide3.fact2"] = "Zkraťte šířku pulzu na 0,5 ms a spusťte znovu. Výstup zůstane dole.",
        ["learn.project.pulseRc.slide3.fact3"] = "Změňte C na 0,1 µF. Hrany budou zase ostré.",
        ["learn.project.basicsFinal.slide1.title"] = "Co tato skupina probrala",
        ["learn.project.basicsFinal.slide1.p1"] = "Krátké shrnutí před otázkami.",
        ["learn.project.basicsFinal.slide1.fact1"] = "Napětí je tlak, měří se mezi dvěma body. Zem má 0 V.",
        ["learn.project.basicsFinal.slide1.fact2"] = "Proud je tok, měří se v cestě. Potřebuje uzavřenou smyčku.",
        ["learn.project.basicsFinal.slide1.fact3"] = "Odpor proud omezuje. U = I · R.",
        ["learn.project.basicsFinal.slide1.fact4"] = "Sériově: jeden proud, úbytky se sčítají. Paralelně: jedno napětí, proudy se sčítají.",
        ["learn.project.basicsFinal.slide1.fact5"] = "Stejnosměrný proud je stálý a má polaritu. Střídavý kmitá a „230 V“ je efektivní hodnota.",
        ["learn.project.basicsFinal.slide1.fact6"] = "LED si vezme asi 2 V a potřebuje rezistor. RC obvod se nabíjí s τ = R · C.",
        ["learn.project.basicsFinal.slide2.title"] = "Jak závěrečný kvíz funguje",
        ["learn.project.basicsFinal.slide2.p1"] = "Deset otázek ze všeho, co jste výše probrali. Ke splnění potřebujete osm správných odpovědí.",
        ["learn.project.basicsFinal.slide2.p2"] = "Po každém pokusu uvidíte, které odpovědi byly špatně a proč. Opakovat můžete, jak často chcete.",
        ["learn.project.basicsFinal.slide2.callout"] = "Zasekli jste se na otázce? Vraťte se k dané lekci. Stránky jsou krátké.",
        ["diag.empty_circuit"] = "Umístěte součástky z palety, propojte je a přidejte Zem.",
        ["diag.no_ground"] = "Přidejte značku Zem a připojte ji ke zpětné cestě obvodu.",
        ["diag.ground_disconnected"] = "Zem není připojená. Propojte Zem s obvodem.",
        ["diag.floating_component"] = "Nezapojené součástky: {ids}. Připojte každý potřebný pin, nebo nepoužité součástky smažte.",
