        ["learn.project.halfWave.title"] = "Jednocestný usměrňovač",
        ["learn.project.halfWave.summary"] = "Podívejte se, jak jediná dioda mění střídavé napětí na pulzující stejnosměrné. Základ každého síťového zdroje.",
