        ["learn.project.bridge.title"] = "Můstkový usměrňovač",
        ["learn.project.bridge.summary"] = "Čtyři diody vedou obě půlperiody střídavého napětí do zátěže. Hustší pulzující DC než u jednocestného.",
        ["learn.project.bridge.step1"] = "Otevřete příklad v Laboratoři a spusťte Transient.",
