        ["learn.project.bridge.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.filterCap.title"] = "Filtrační kondenzátor",
        ["learn.project.filterCap.summary"] = "Zásobní kondenzátor za usměrňovačem drží náboj mezi špičkami a vyhlazuje stejnosměrné napětí.",
        ["learn.project.filterCap.step1"] = "Otevřete příklad v Laboratoři a spusťte Transient.",
        ["learn.project.filterCap.step2"] = "Změřte napětí na C1. Špičky kondenzátor nabíjejí, zátěž ho mezi špičkami vybíjí.",
        ["learn.project.filterCap.step3"] = "Zmenšete C1 na polovinu (nebo snižte R1) a spusťte znovu. Zvlnění vzroste.",
        ["learn.project.filterCap.step4"] = "Větší C nebo menší zátěž znamená hladší DC (než se v praxi ozve ESR a nabíjecí proud).",
        ["learn.project.filterCap.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.zener.title"] = "Zenerův paralelní stabilizátor",
        ["learn.project.zener.summary"] = "Zenerova dioda v závěrném směru drží uzel blízko Vz, když je napájená přes sériový rezistor.",
        ["learn.project.zener.step1"] = "Otevřete příklad v Laboratoři a spusťte DC.",
        ["learn.project.zener.step2"] = "Změřte JM. Napětí by mělo sedět kolem 5,1 V při napájení 12 V.",
        ["learn.project.zener.step3"] = "Změňte RL a spusťte znovu. Lehká zátěž zůstane stabilizovaná, příliš těžká může Vz zhroutit.",
        ["learn.project.zener.step4"] = "Pamatujte: katoda na stabilizovaný uzel, anoda na zem.",
        ["learn.project.zener.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.vreg7805.title"] = "Lineární stabilizátor 7805",
        ["learn.project.vreg7805.summary"] = "Sériový stabilizátor drží na výstupu asi 5 V, pokud vstup zůstane nad úbytkem potřebným k regulaci.",
        ["learn.project.vreg7805.step1"] = "Otevřete příklad v Laboratoři a spusťte DC. OUT by měl mít asi 5 V.",
        ["learn.project.vreg7805.step2"] = "Změřte IN a OUT. Rozdíl se ve skutečném 7805 mění na teplo.",
        ["learn.project.vreg7805.step3"] = "Snižte VB k asi 6 V a spusťte. U hranice úbytku regulace selže.",
        ["learn.project.vreg7805.step4"] = "Porovnejte se Zenerovým příkladem: sériový obvod proti paralelní diodě.",
        ["learn.project.vreg7805.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.reversePolarity.title"] = "Ochrana proti přepólování",
        ["learn.project.reversePolarity.summary"] = "Sériová dioda zablokuje proud, když je baterie připojená obráceně. Levná ochrana zátěže.",
        ["learn.project.reversePolarity.step1"] = "Otevřete příklad v Laboratoři a spusťte DC. LED by měla svítit.",
        ["learn.project.reversePolarity.step2"] = "Všimněte si úbytku asi 0,7 V na Dprot (výuková křemíková dioda).",
        ["learn.project.reversePolarity.step3"] = "Představte si baterii obráceně. Dioda blokuje, LED zůstane zhasnutá.",
        ["learn.project.reversePolarity.step4"] = "Cena za ochranu: z napájení ztratíte Vf.",
        ["learn.project.reversePolarity.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.fuseProtect.title"] = "Pojistka a ochrana proti zkratu",
        ["learn.project.fuseProtect.summary"] = "Výuková pojistka se přeruší, když proud překročí iMax. Vyzkoušejte, co zkrat udělá s napájecí cestou.",
        ["learn.project.fuseProtect.step1"] = "Otevřete příklad v Laboratoři. S1 začíná rozepnutý (bezpečná cesta přes RL). Sepnutím S1 zkratujete RL.",
        ["learn.project.fuseProtect.step2"] = "Se sepnutým S1 spusťte DC. F1 se přeruší; RL je obejitý, takže selže jen pojistka.",
        ["learn.project.fuseProtect.step3"] = "Vyměňte F1. S1 se automaticky rozepne. Spusťte znovu a proud bezpečně poteče přes RL.",
        ["learn.project.fuseProtect.step4"] = "Ve skutečném obvodu nikdy nepřemosťujte pojistku drátem.",
        ["learn.project.fuseProtect.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.ripple.title"] = "Měření zvlnění",
        ["learn.project.ripple.summary"] = "Zbytkové střídavé napětí na vyhlazeném DC je zvlnění. Podívejte se na ně na osciloskopu za usměrňovačem s kondenzátorem.",
        ["learn.project.ripple.step1"] = "Otevřete příklad v Laboratoři a spusťte Transient.",
        ["learn.project.ripple.step2"] = "Změřte JT a přibližte si plochou část mezi špičkami.",
        ["learn.project.ripple.step3"] = "Zmenšete C1 nebo R1 a spusťte znovu. Zvlnění špička–špička vzroste.",
        ["learn.project.ripple.step4"] = "Ve skutečných zdrojích určuje požadované zvlnění velikost kondenzátoru a povolený proud zátěže.",
        ["learn.project.ripple.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.buck.title"] = "Základní snižující měnič",
        ["learn.project.buck.summary"] = "PWM, cívka, dioda a kondenzátor snižují vyšší stejnosměrné napětí. Diskrétní výuková topologie.",
        ["learn.project.buck.step1"] = "Otevřete příklad v Laboratoři a spusťte Transient (asi 10 ms).",
        ["learn.project.buck.step2"] = "Změřte JO. Střední hodnota by měla být pod Vin (ideálně střída × Vin).",
        ["learn.project.buck.step3"] = "Prodlužte šířku pulzu (pw) směrem k periodě. Střední hodnota výstupu vzroste.",
        ["learn.project.buck.step4"] = "Řízení hradla je vztažené k LX, takže horní NMOS vidí skutečné Vgs.",
        ["learn.project.buck.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.boost.title"] = "Základní zvyšující měnič",
        ["learn.project.boost.summary"] = "PWM, cívka, dioda a kondenzátor zvyšují nižší stejnosměrné napětí. Energie se každý cyklus ukládá do L.",
        ["learn.project.boost.step1"] = "Otevřete příklad v Laboratoři a spusťte Transient (asi 10 ms).",
        ["learn.project.boost.step2"] = "Změřte JO. Střední hodnota by měla po několika cyklech vystoupit nad vstupních 5 V.",
        ["learn.project.boost.step3"] = "Opatrně prodlužte dobu sepnutí (pw). Víc energie za cyklus, vyšší Vout.",
        ["learn.project.boost.step4"] = "Porovnejte se snižujícím měničem: spínač dole proti spínači nahoře.",
        ["learn.project.boost.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.bc547.title"] = "Spínání LED tranzistorem BC547",
        ["learn.project.bc547.summary"] = "Použijte BC547 (výukový NPN) k zapínání a vypínání LED spínačem v bázi. Stejná myšlenka jako skutečný spínací obvod v pouzdru TO-92, se zjednodušeným modelem tranzistoru.",
        ["learn.project.bc547.step1"] = "Otevřete příklad v Laboratoři a spusťte DC. LED by měla svítit.",
        ["learn.project.bc547.step2"] = "Vyberte spínač S1, zrušte zaškrtnutí Sepnuto a spusťte znovu. LED by měla zhasnout.",
        ["learn.project.bc547.step3"] = "Změřte ampérmetr (AM1) nebo LED a přečtěte kolektorový proud při sepnutém spínači.",
        ["learn.project.bc547.step4"] = "Hodně snižte RB (zkuste asi 100 Ω nebo méně). Příliš velký bázový proud (asi 25 mA) tranzistor spálí; obnovíte ho volbou Vyměnit tranzistor.",
        ["learn.project.bc547.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.relay.title"] = "Relé s ochrannou diodou",
        ["learn.project.relay.summary"] = "Ovládejte cívku výukového relé spínačem, chraňte ji ochrannou diodou a kontakty spínejte LED.",
        ["learn.project.relay.step1"] = "Otevřete příklad v Laboratoři a spusťte DC. Se sepnutým S1 cívka přitáhne a LED svítí.",
        ["learn.project.relay.step2"] = "Vyberte S1, zrušte zaškrtnutí Sepnuto a spusťte znovu. Kontakty se rozepnou a LED zhasne.",
        ["learn.project.relay.step3"] = "Vyberte Dfly. Katoda míří ke kladnému konci cívky (ke spínači), anoda se vrací na zem. Klasická orientace ochranné diody.",
        ["learn.project.relay.step4"] = "Zvedněte přítahové napětí K1 nad 5 V (nebo rozepněte S1), aby cívka nemohla přitáhnout. LED zůstane zhasnutá.",
        ["learn.project.relay.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.nmos.title"] = "Spínání LED tranzistorem NMOS",
        ["learn.project.nmos.summary"] = "Použijte výukový NMOS ke spínání LED spínačem na hradle. Stejná myšlenka jako logický FET spínač, s jednoduchým prahovým modelem Vgs.",
        ["learn.project.nmos.step1"] = "Otevřete příklad v Laboratoři a spusťte DC. Se sepnutým S1 by LED měla svítit.",
        ["learn.project.nmos.step2"] = "Vyberte S1, zrušte zaškrtnutí Sepnuto a spusťte znovu. RPD stáhne hradlo k zemi a LED zhasne.",
        ["learn.project.nmos.step3"] = "Změřte AM1 nebo LED a přečtěte proud kolektoru (drain) při sepnutém spínači.",
        ["learn.project.nmos.step4"] = "Snižte RD velmi nízko nebo hodně zvedněte napájení. Příliš velký proud nebo |Vgs| spálí M1; obnovíte ho volbou Vyměnit MOSFET.",
        ["learn.project.nmos.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.ne555.title"] = "Blikač s NE555 (astabilní)",
        ["learn.project.ne555.summary"] = "Postavte klasický astabilní obvod s 555 a časováním Ra/Rb/C a sledujte v analýze Transient tři barevné LED, jak blikají společně.",
        ["learn.project.ne555.step1"] = "Otevřete příklad v Laboratoři a spusťte Transient (asi 100 ms). Červená, zelená a žlutá LED by měly blikat současně.",
        ["learn.project.ne555.step2"] = "Změřte OUT nebo CT a projíždějte osciloskop, abyste viděli obdélník a nabíjení kondenzátoru.",
        ["learn.project.ne555.step3"] = "Změňte RA/RB/CT a upravte periodu (výuková aproximace klasických vzorců).",
        ["learn.project.ne555.step4"] = "Snižte R1–R3 příliš nízko. Nadproud na výstupu časovač spálí; obnovíte ho volbou Vyměnit NE555.",
        ["learn.project.ne555.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.pushbutton.title"] = "LED s tlačítkem",
        ["learn.project.pushbutton.summary"] = "Stiskem tlačítka rozsvítíte LED. Stejná myšlenka jako čtení tlačítka na pinu Arduina.",
        ["learn.project.pushbutton.step1"] = "Otevřete příklad v Laboratoři. S nástrojem Výběr podržte BTN1 na plátně. LED svítí, dokud držíte.",
        ["learn.project.pushbutton.step2"] = "Tlačítko pusťte a LED zhasne. Ovládací prvek Podržet ke stisku v inspektoru dělá totéž.",
        ["learn.project.pushbutton.step3"] = "Změřte proud LED při stisknutém tlačítku.",
        ["learn.project.pushbutton.step4"] = "Jako výzvu zkuste tlačítko zapojit proti zemi (aktivní v nule).",
        ["learn.project.pushbutton.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.ldr.title"] = "Noční světlo s fotorezistorem",
        ["learn.project.ldr.summary"] = "Zvedací rezistor a fotorezistor na zem řídí NMOS, takže se LED ve tmě rozsvítí. Klasické cvičení se světelným čidlem.",
        ["learn.project.ldr.step1"] = "Otevřete příklad v Laboratoři a spusťte DC. S nízkou hodnotou Světlo by LED měla svítit.",
        ["learn.project.ldr.step2"] = "Vyberte LDR1, zvedněte Světlo k hodnotě 1 a spusťte znovu. LED by měla zhasnout.",
        ["learn.project.ldr.step3"] = "Změřte uzel hradla MOSFETu a sledujte, jak se napětí děliče mění se Světlem.",
        ["learn.project.ldr.step4"] = "Změňte rDark / rLight (nebo R1) a sledujte, jak se posouvá bod přepnutí.",
        ["learn.project.ldr.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.buzzer.title"] = "Bzučák s tlačítkem",
        ["learn.project.buzzer.summary"] = "Stiskem tlačítka rozezníte výukový piezo bzučák. Proud znamená, že „zní“.",
        ["learn.project.buzzer.step1"] = "Otevřete příklad v Laboratoři. Podržte BTN1 na plátně. BZ1 by měl ukázat proud.",
        ["learn.project.buzzer.step2"] = "Tlačítko pusťte. Proud by měl klesnout k nule.",
        ["learn.project.buzzer.step3"] = "Změřte BZ1 a porovnejte s příkladem s LED (stejné tlačítko, jiná zátěž).",
        ["learn.project.buzzer.step4"] = "Opatrně snižujte R1. Příliš velký proud skutečnému bzučáku nesvědčí.",
        ["learn.project.buzzer.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.motor.title"] = "Spínání motoru tranzistorem NMOS",
        ["learn.project.motor.summary"] = "Spínejte stejnosměrný motor pomocí NMOS a ochranné diody. Takhle Arduino ovládá větší zátěže.",
        ["learn.project.motor.step1"] = "Otevřete příklad v Laboratoři a spusťte DC se sepnutým S1. Motorem by měl téct proud.",
        ["learn.project.motor.step2"] = "Rozepněte S1 a spusťte znovu. Proud motoru se zastaví.",
        ["learn.project.motor.step3"] = "Všimněte si Dfly přes motor (katoda k +V) kvůli indukčnímu rázu.",
        ["learn.project.motor.step4"] = "Změřte proud MOT1; zkuste na motoru změnit ron / vStart.",
        ["learn.project.motor.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.arduino.title"] = "LED na pinu Arduina",
        ["learn.project.arduino.summary"] = "Výukový digitální pin Arduina řídí LED. digitalWrite HIGH/LOW bez plné simulace mikrokontroléru.",
        ["learn.project.arduino.step1"] = "Otevřete příklad v Laboratoři a spusťte DC. Output/HIGH by měl LED rozsvítit.",
        ["learn.project.arduino.step2"] = "Vyberte D2, nastavte Úroveň na LOW a spusťte znovu. LED zhasne.",
        ["learn.project.arduino.step3"] = "Nastavte Režim na Input. Pin přejde do vysoké impedance; přidejte stahovací rezistor, pokud chcete definovaný stav LED.",
        ["learn.project.arduino.step4"] = "Změňte vHigh na 3,3 V a napodobte 3,3 V desku.",
        ["learn.project.arduino.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.i2cOled.title"] = "I2C OLED (SSD1306)",
        ["learn.project.i2cOled.summary"] = "Zapojte Arduino jako I2C master k OLED SSD1306 se zvedacími rezistory. Jádro každé lekce o I2C ještě před softwarem.",
        ["learn.project.i2cOled.step1"] = "Otevřete příklad v Laboratoři a spusťte DC. SDA a SCL by měly sedět blízko 5 V (zvedací rezistory na 5 V Arduina).",
        ["learn.project.i2cOled.step2"] = "Změřte napájecí proud OLED1. Displej by měl ukázat „Hello“, když je VCC napájené. Adresa 0x3C je obvyklý výchozí stav SSD1306.",
        ["learn.project.i2cOled.step3"] = "Smažte jeden zvedací rezistor (RpuSDA nebo RpuSCL) a spusťte znovu. Ta linka už nemá definovanou klidovou úroveň (sběrnice s otevřeným kolektorem).",
        ["learn.project.i2cOled.step4"] = "Rezistor vraťte. Poznámka: tato Laboratoř učí zapojení a klidové úrovně, ne Wire.begin() ani ACK bity.",
        ["learn.project.i2cOled.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.opampFollower.title"] = "Napěťový sledovač",
        ["learn.project.opampFollower.summary"] = "Oddělovač s jednotkovým zesílením: výstup sleduje vstup, aniž by zatěžoval zdroj.",
        ["learn.project.opampFollower.step1"] = "Otevřete příklad. U1 je zapojený jako sledovač (OUT vede zpět na −in).",
        ["learn.project.opampFollower.step2"] = "Spusťte DC a změřte VIN a JO. Napětí by se měla téměř shodovat.",
        ["learn.project.opampFollower.step3"] = "Změňte napětí VIN v inspektoru; výstup ho sleduje.",
        ["learn.project.opampFollower.step4"] = "Vyměňte RL za lehčí nebo těžší zátěž. Oddělovač pořád drží Vout ≈ Vin.",
        ["learn.project.opampFollower.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.opamp.title"] = "Invertující zesilovač",
        ["learn.project.opamp.summary"] = "Klasické zesílení −Rf/Rin s virtuální zemí v součtovém uzlu.",
        ["learn.project.opamp.step1"] = "Otevřete invertující příklad. Rin do −in, Rf z OUT zpět na −in, +in na zemi.",
        ["learn.project.opamp.step2"] = "Spusťte DC: s Vin=1 V, Rin=1 kΩ, Rf=10 kΩ čekejte Vout ≈ −10 V.",
        ["learn.project.opamp.step3"] = "Změřte součtový uzel JS. Sedí blízko 0 V (virtuální zem).",
        ["learn.project.opamp.step4"] = "Změňte Rf nebo Rin a ověřte, že zesílení ≈ −Rf/Rin, dokud nezasáhne omezení napájením.",
        ["learn.project.opamp.openLab"] = "Otevřít v Laboratoři",
        ["learn.project.opampNonInv.title"] = "Neinvertující zesilovač",
