        ["learn.project.opampNonInv.lesson1.body"] = "Zpětná vazba nastaví V− = Vin. Dělič Rf/Rg dává Vout = Vin·(1 + Rf/Rg).",
        ["learn.project.opampNonInv.lesson2.title"] = "Stejná polarita",
        ["learn.project.opampNonInv.lesson2.body"] = "Na rozdíl od invertujícího zapojení se výstup pohybuje stejným směrem jako vstup.",
        ["learn.project.opampNonInv.quiz.q1.prompt"] = "Ideální neinvertující zesílení je…",
        ["learn.project.opampNonInv.quiz.q1.a"] = "−Rf / Rg",
        ["learn.project.opampNonInv.quiz.q1.b"] = "1 + Rf / Rg",
        ["learn.project.opampNonInv.quiz.q1.c"] = "Rf − Rg",
        ["learn.project.opampNonInv.quiz.q1.explain"] = "Zesílení uzavřené smyčky neinvertujícího zapojení.",
        ["learn.project.opampNonInv.quiz.q2.prompt"] = "Vstupní signál se připojuje na…",
        ["learn.project.opampNonInv.quiz.q2.a"] = "jen −in",
        ["learn.project.opampNonInv.quiz.q2.b"] = "+in",
        ["learn.project.opampNonInv.quiz.q2.c"] = "OUT",
        ["learn.project.opampNonInv.quiz.q2.explain"] = "Vin budí neinvertující vstup.",
        ["learn.project.opampNonInv.quiz.q3.prompt"] = "Ve srovnání s invertujícím zapojením je polarita…",
        ["learn.project.opampNonInv.quiz.q3.a"] = "vždy opačná",
        ["learn.project.opampNonInv.quiz.q3.b"] = "nedefinovaná",
        ["learn.project.opampNonInv.quiz.q3.c"] = "stejná jako Vin",
        ["learn.project.opampNonInv.quiz.q3.explain"] = "Neinvertující zapojení zachovává znaménko.",
        ["learn.project.opampComparator.lesson1.title"] = "Bez zpětné vazby",
        ["learn.project.opampComparator.lesson1.body"] = "Bez zpětné vazby je výukové zesílení obrovské, takže OUT se nasytí nahoře nebo dole podle toho, který vstup je větší.",
        ["learn.project.opampComparator.lesson2.title"] = "Práh",
        ["learn.project.opampComparator.lesson2.body"] = "Odporový dělič nastaví přepínací napětí. Potenciometr umožní přejet Vin přes tento práh.",
        ["learn.project.opampComparator.quiz.q1.prompt"] = "Komparátor obvykle používá…",
        ["learn.project.opampComparator.quiz.q1.a"] = "silnou zápornou zpětnou vazbu",
        ["learn.project.opampComparator.quiz.q1.b"] = "zesílení bez zpětné vazby (nebo s nepatrnou)",
        ["learn.project.opampComparator.quiz.q1.c"] = "jen cívku",
        ["learn.project.opampComparator.quiz.q1.explain"] = "Velké zesílení žene výstup na mez.",
        ["learn.project.opampComparator.quiz.q2.prompt"] = "Když je v tomto příkladu Vin > Vth, OUT jde…",
        ["learn.project.opampComparator.quiz.q2.a"] = "ke kladné mezi",
        ["learn.project.opampComparator.quiz.q2.b"] = "přesně na Vin",
        ["learn.project.opampComparator.quiz.q2.c"] = "vždy na 0 V",
        ["learn.project.opampComparator.quiz.q2.explain"] = "+in nad −in → výstup nahoře.",
        ["learn.project.opampComparator.quiz.q3.prompt"] = "Posun běžce potenciometru…",
        ["learn.project.opampComparator.quiz.q3.a"] = "mění časovací kapacitu.",
        ["learn.project.opampComparator.quiz.q3.b"] = "nedělá nic.",
        ["learn.project.opampComparator.quiz.q3.c"] = "přejíždí Vin přes práh.",
        ["learn.project.opampComparator.quiz.q3.explain"] = "Běžec je proměnný vstup.",
        ["learn.project.opampSchmitt.lesson1.title"] = "Hystereze",
        ["learn.project.opampSchmitt.lesson1.body"] = "Kladná zpětná vazba přičte k prahu část OUT, takže se práh pro náběh a pro pokles liší. Šum kolem prahu pak výstupem necuká.",
        ["learn.project.opampSchmitt.lesson2.title"] = "Proti obyčejnému komparátoru",
        ["learn.project.opampSchmitt.lesson2.body"] = "Obyčejný komparátor přepíná v jednom napětí oběma směry; Schmitt potřebuje k přepnutí zpět větší výchylku.",
        ["learn.project.opampSchmitt.quiz.q1.prompt"] = "Schmittův klopný obvod přidává…",
        ["learn.project.opampSchmitt.quiz.q1.a"] = "hysterezi kladnou zpětnou vazbou",
        ["learn.project.opampSchmitt.quiz.q1.b"] = "jen sériovou indukčnost",
        ["learn.project.opampSchmitt.quiz.q1.c"] = "oddělení s jednotkovým zesílením",
        ["learn.project.opampSchmitt.quiz.q1.explain"] = "Zpětná vazba posouvá práh podle stavu výstupu.",
        ["learn.project.opampSchmitt.quiz.q2.prompt"] = "Přepínací body pro náběh a pokles jsou…",
        ["learn.project.opampSchmitt.quiz.q2.a"] = "vždy stejné",
        ["learn.project.opampSchmitt.quiz.q2.b"] = "různé (pásmo hystereze)",
        ["learn.project.opampSchmitt.quiz.q2.c"] = "při každém spuštění náhodné",
        ["learn.project.opampSchmitt.quiz.q2.explain"] = "Dva prahy jsou záměr.",
        ["learn.project.opampSchmitt.quiz.q3.prompt"] = "Hystereze pomáhá proti…",
        ["learn.project.opampSchmitt.quiz.q3.a"] = "napájecímu napětí",
        ["learn.project.opampSchmitt.quiz.q3.b"] = "barvě LED",
        ["learn.project.opampSchmitt.quiz.q3.c"] = "cukání od šumu kolem prahu",
        ["learn.project.opampSchmitt.quiz.q3.explain"] = "Malý šum nemůže stav přepnout, dokud nepřekročí druhý práh.",
        ["learn.project.opampSumming.lesson1.title"] = "Vážený součet",
        ["learn.project.opampSumming.lesson1.body"] = "Každý vstupní proud Vin/Rn se sčítá v součtovém uzlu. Se stejnými R a Rf je Vout = −(V1 + V2).",
        ["learn.project.opampSumming.lesson2.title"] = "Intuice pro audio a DAC",
        ["learn.project.opampSumming.lesson2.body"] = "Součtové zesilovače míchají signály nebo binárně vážené proudy ve výukových převodnících DAC.",
        ["learn.project.opampSumming.quiz.q1.prompt"] = "Se stejnými Rin a Rf je Vout…",
        ["learn.project.opampSumming.quiz.q1.a"] = "−(V1 + V2)",
        ["learn.project.opampSumming.quiz.q1.b"] = "V1 − V2",
        ["learn.project.opampSumming.quiz.q1.c"] = "V1 × V2",
        ["learn.project.opampSumming.quiz.q1.explain"] = "Invertující sčítačka se stejnými váhami.",
        ["learn.project.opampSumming.quiz.q2.prompt"] = "Další vstupní kanály se připojují přes…",
        ["learn.project.opampSumming.quiz.q2.a"] = "další rezistory do součtového uzlu",
        ["learn.project.opampSumming.quiz.q2.b"] = "jen pin +in",
        ["learn.project.opampSumming.quiz.q2.c"] = "zkratování OUT na zem",
        ["learn.project.opampSumming.quiz.q2.explain"] = "Každý zdroj potřebuje vlastní vstupní rezistor.",
        ["learn.project.opampSumming.quiz.q3.prompt"] = "Součtový uzel je držený blízko…",
        ["learn.project.opampSumming.quiz.q3.a"] = "Vcc",
        ["learn.project.opampSumming.quiz.q3.b"] = "virtuální země",
        ["learn.project.opampSumming.quiz.q3.c"] = "jen V1",
        ["learn.project.opampSumming.quiz.q3.explain"] = "Stejně jako u invertujícího zesilovače.",
        ["learn.project.opampIntegrator.lesson1.title"] = "Rampa z proudu",
        ["learn.project.opampIntegrator.lesson1.body"] = "Proud zpětné vazby nabíjí Cf. Ideální Vout invertujícího integrátoru klesá jako −(1/Rin·Cf)·∫Vin dt.",
        ["learn.project.opampIntegrator.lesson2.title"] = "Meze výukového modelu",
        ["learn.project.opampIntegrator.lesson2.body"] = "Skutečné integrátory potřebují velký stejnosměrný zpětnovazební rezistor proti driftu; tento příklad ukazuje ideální rampu.",
        ["learn.project.opampIntegrator.quiz.q1.prompt"] = "Zpětnovazebním prvkem v tomto integrátoru je…",
        ["learn.project.opampIntegrator.quiz.q1.a"] = "kondenzátor",
        ["learn.project.opampIntegrator.quiz.q1.b"] = "jen drát",
        ["learn.project.opampIntegrator.quiz.q1.c"] = "cívka",
        ["learn.project.opampIntegrator.quiz.q1.explain"] = "Cf ukládá integrovaný náboj.",
        ["learn.project.opampIntegrator.quiz.q2.prompt"] = "Stálé kladné Vin udělá z ideálního Vout…",
        ["learn.project.opampIntegrator.quiz.q2.a"] = "hodnotu Vin",
        ["learn.project.opampIntegrator.quiz.q2.b"] = "rampu (u invertujícího zapojení do záporných hodnot)",
        ["learn.project.opampIntegrator.quiz.q2.c"] = "věčné kmitání",
        ["learn.project.opampIntegrator.quiz.q2.explain"] = "Integrál konstanty je rampa.",
        ["learn.project.opampIntegrator.quiz.q3.prompt"] = "Nejlepší analýza je tady…",
        ["learn.project.opampIntegrator.quiz.q3.a"] = "jen DC",
        ["learn.project.opampIntegrator.quiz.q3.b"] = "jen AC na jedné frekvenci",
        ["learn.project.opampIntegrator.quiz.q3.c"] = "Transient",
        ["learn.project.opampIntegrator.quiz.q3.explain"] = "Rampu uvidíte jen v čase.",
        ["learn.project.opampDifferentiator.lesson1.title"] = "Jen hrany",
        ["learn.project.opampDifferentiator.lesson1.body"] = "Proud kondenzátoru je C·dV/dt, takže rovné úrovně dají malý výstup a hrany dají špičky.",
        ["learn.project.opampDifferentiator.lesson2.title"] = "Pozor na šum",
        ["learn.project.opampDifferentiator.lesson2.body"] = "Derivátory zdůrazňují rychlé změny. Výukové modely zůstávají klidné; skutečné obvody často přidávají sériový R, aby omezily zesílení na vysokých frekvencích.",
        ["learn.project.opampDifferentiator.quiz.q1.prompt"] = "Sériovým vstupním prvkem je tady…",
        ["learn.project.opampDifferentiator.quiz.q1.a"] = "kondenzátor",
        ["learn.project.opampDifferentiator.quiz.q1.b"] = "jen baterie",
        ["learn.project.opampDifferentiator.quiz.q1.c"] = "pojistka",
        ["learn.project.opampDifferentiator.quiz.q1.explain"] = "Cin přenáší dV/dt do zesilovače.",
        ["learn.project.opampDifferentiator.quiz.q2.prompt"] = "Rovný stejnosměrný vstup ideálně dá…",
        ["learn.project.opampDifferentiator.quiz.q2.a"] = "obrovské stejnosměrné zesílení",
        ["learn.project.opampDifferentiator.quiz.q2.b"] = "výstup blízko nuly",
        ["learn.project.opampDifferentiator.quiz.q2.c"] = "trojúhelníkový průběh",
        ["learn.project.opampDifferentiator.quiz.q2.explain"] = "Na rovné úrovni je dV/dt ≈ 0.",
        ["learn.project.opampDifferentiator.quiz.q3.prompt"] = "Sledujete hlavně…",
        ["learn.project.opampDifferentiator.quiz.q3.a"] = "jen stejnosměrný pracovní bod",
        ["learn.project.opampDifferentiator.quiz.q3.b"] = "nic",
        ["learn.project.opampDifferentiator.quiz.q3.c"] = "špičky na hranách v Transientu",
        ["learn.project.opampDifferentiator.quiz.q3.explain"] = "Hrany jsou výukový signál.",
        ["learn.project.opampActiveFilter.lesson1.title"] = "Dolní propust prvního řádu",
        ["learn.project.opampActiveFilter.lesson1.body"] = "Na nízkých f je C rozpojený a zesílení ≈ −Rf/Rin. Na vysokých f C přemostí Rf a zesílení klesá.",
        ["learn.project.opampActiveFilter.lesson2.title"] = "Proč aktivní?",
        ["learn.project.opampActiveFilter.lesson2.body"] = "Operační zesilovač filtr odděluje a může dodat zesílení; samotný pasivní RC zesílit neumí.",
        ["learn.project.opampActiveFilter.quiz.q1.prompt"] = "Zvýšení frekvence daleko nad mezní…",
        ["learn.project.opampActiveFilter.quiz.q1.a"] = "zvýší |Vout|.",
        ["learn.project.opampActiveFilter.quiz.q1.b"] = "zesílení nezmění.",
        ["learn.project.opampActiveFilter.quiz.q1.c"] = "výstup utlumí.",
        ["learn.project.opampActiveFilter.quiz.q1.explain"] = "Chování dolní propusti.",
        ["learn.project.opampActiveFilter.quiz.q2.prompt"] = "Zpětnovazební kondenzátor ovlivňuje hlavně…",
        ["learn.project.opampActiveFilter.quiz.q2.a"] = "jen barvu LED",
        ["learn.project.opampActiveFilter.quiz.q2.b"] = "zesílení na vysokých frekvencích (přemosťuje Rf)",
        ["learn.project.opampActiveFilter.quiz.q2.c"] = "jen ESR baterie",
        ["learn.project.opampActiveFilter.quiz.q2.explain"] = "S rostoucí f C zkracuje Rf.",
        ["learn.project.opampActiveFilter.quiz.q3.prompt"] = "Nejlepší analýza pro tento příklad je…",
        ["learn.project.opampActiveFilter.quiz.q3.a"] = "AC",
        ["learn.project.opampActiveFilter.quiz.q3.b"] = "jen DC",
        ["learn.project.opampActiveFilter.quiz.q3.c"] = "žádná simulace",
        ["learn.project.opampActiveFilter.quiz.q3.explain"] = "Frekvenční odezva je věc AC.",
        ["learn.project.rcLowPass.lesson1.title"] = "Dolní propust prvního řádu",
