        ["learn.project.bc547.lesson1.title"] = "Tranzistor jako spínač",
        ["learn.project.bc547.lesson1.body"] = "Malý bázový proud umožní větší kolektorový proud. Když je BJT buzený, vede proud LED.",
        ["learn.project.bc547.lesson2.title"] = "Rozpojená proti buzené bázi",
        ["learn.project.bc547.lesson2.body"] = "Rozpojená báze (spínač vypnutý) → LED nesvítí. Buzená báze přes sériový RB → LED svítí, pokud je tranzistor v saturaci.",
        ["learn.project.bc547.quiz.q1.prompt"] = "S rozepnutým S1 by LED měla…",
        ["learn.project.bc547.quiz.q1.a"] = "jasně svítit.",
        ["learn.project.bc547.quiz.q1.b"] = "nesvítit.",
        ["learn.project.bc547.quiz.q1.c"] = "svítit náhodně.",
        ["learn.project.bc547.quiz.q1.explain"] = "Bez buzení báze → tranzistor vypnutý → LED zhasnutá.",
        ["learn.project.bc547.quiz.q2.prompt"] = "RB slouží k…",
        ["learn.project.bc547.quiz.q2.a"] = "omezení bázového proudu.",
        ["learn.project.bc547.quiz.q2.b"] = "zvýšení napájecího napětí.",
        ["learn.project.bc547.quiz.q2.c"] = "časování LED.",
        ["learn.project.bc547.quiz.q2.explain"] = "Chrání výukový BJT před nadměrným bázovým proudem.",
        ["learn.project.bc547.quiz.q3.prompt"] = "Příliš malý RB může…",
        ["learn.project.bc547.quiz.q3.a"] = "tranzistor spálit.",
        ["learn.project.bc547.quiz.q3.b"] = "jen rychleji nabít kondenzátor.",
        ["learn.project.bc547.quiz.q3.c"] = "v tomto modelu nic.",
        ["learn.project.bc547.quiz.q3.explain"] = "Nadměrný bázový proud je výukový způsob poruchy.",
        ["learn.project.relay.lesson1.title"] = "Cívka a kontakty",
        ["learn.project.relay.lesson1.body"] = "Nabuzení cívky přitáhne kontakty a sepne oddělenou zátěž (tady LED).",
        ["learn.project.relay.lesson2.title"] = "Ochranná dioda",
        ["learn.project.relay.lesson2.body"] = "Dioda dá proudu cívky bezpečnou cestu, když se spínač rozepne. Jinak indukční ráz vystřelí napětí.",
        ["learn.project.relay.quiz.q1.prompt"] = "Orientace ochranné diody…",
        ["learn.project.relay.quiz.q1.a"] = "vede, když se pole cívky hroutí.",
        ["learn.project.relay.quiz.q1.b"] = "blokuje veškeré DC navždy.",
        ["learn.project.relay.quiz.q1.c"] = "nahrazuje cívku.",
        ["learn.project.relay.quiz.q1.explain"] = "Musí odvést zpětnou energii pryč od uzlu spínače.",
        ["learn.project.relay.quiz.q2.prompt"] = "S rozepnutým S1 by LED na kontaktech měla…",
        ["learn.project.relay.quiz.q2.a"] = "svítit.",
        ["learn.project.relay.quiz.q2.b"] = "nesvítit.",
        ["learn.project.relay.quiz.q2.c"] = "stále blikat.",
        ["learn.project.relay.quiz.q2.explain"] = "Bez proudu cívky → kontakty rozepnuté.",
        ["learn.project.relay.quiz.q3.prompt"] = "Cívka relé je buzená z…",
        ["learn.project.relay.quiz.q3.a"] = "stejné cesty se spínačem jako v předloze.",
        ["learn.project.relay.quiz.q3.b"] = "jen analýzy AC.",
        ["learn.project.relay.quiz.q3.c"] = "sondy osciloskopu.",
        ["learn.project.relay.quiz.q3.explain"] = "Držte se zapojení předlohy v Laboratoři.",
        ["learn.project.nmos.lesson1.title"] = "Hradlo řídí kanál",
        ["learn.project.nmos.lesson1.body"] = "NMOS se sepne, když je napětí hradla proti sourcu dost vysoké. Tady hradlo nastavuje spínač a stahovací rezistor.",
        ["learn.project.nmos.lesson2.title"] = "Stahovací rezistor",
        ["learn.project.nmos.lesson2.body"] = "Když se spínač rozepne, RPD drží hradlo dole, takže LED spolehlivě zhasne.",
        ["learn.project.nmos.quiz.q1.prompt"] = "S rozepnutým S1 je hradlo staženo…",
        ["learn.project.nmos.quiz.q1.a"] = "dolů rezistorem RPD.",
        ["learn.project.nmos.quiz.q1.b"] = "automaticky nahoru.",
        ["learn.project.nmos.quiz.q1.c"] = "nikam, plave navždy.",
        ["learn.project.nmos.quiz.q1.explain"] = "Stahovací rezistor definuje vypnutý stav.",
        ["learn.project.nmos.quiz.q2.prompt"] = "Proud LED teče, když…",
        ["learn.project.nmos.quiz.q2.a"] = "je MOSFET sepnutý.",
        ["learn.project.nmos.quiz.q2.b"] = "je hradlo jen pod prahem.",
        ["learn.project.nmos.quiz.q2.c"] = "je odstraněná zem.",
        ["learn.project.nmos.quiz.q2.explain"] = "Kanál musí vést proud drainu.",
        ["learn.project.nmos.quiz.q3.prompt"] = "Nadměrný proud drainu může…",
        ["learn.project.nmos.quiz.q3.a"] = "ve výukovém modelu spálit M1.",
        ["learn.project.nmos.quiz.q3.b"] = "jen nabít kondenzátor.",
        ["learn.project.nmos.quiz.q3.c"] = "nic.",
        ["learn.project.nmos.quiz.q3.explain"] = "Respektujte sériový odpor a meze napájení.",
        ["learn.project.motor.lesson1.title"] = "Spínač na spodní straně",
        ["learn.project.motor.lesson1.body"] = "NMOS na zemní straně spíná motor jako zátěž. Ve výukových zapojeních běžné.",
        ["learn.project.motor.lesson2.title"] = "Motor jako zátěž",
