        ["learn.project.motor.quiz.q3.explain"] = "DC ukáže ustálené chování zapnuto/vypnuto.",
        ["learn.project.ne555.lesson1.title"] = "Astabilní multivibrátor",
        ["learn.project.ne555.lesson1.body"] = "555 střídavě nabíjí a vybíjí časovací kondenzátor. Výstup se přepíná.",
        ["learn.project.ne555.lesson2.title"] = "Časovací síť",
        ["learn.project.ne555.lesson2.body"] = "RA, RB a CT nastavují periodu ve výukové aproximaci. Změňte je a blikání zrychlíte nebo zpomalíte.",
        ["learn.project.ne555.quiz.q1.prompt"] = "Blikající LED v čase uvidíte v…",
        ["learn.project.ne555.quiz.q1.a"] = "Transientu.",
        ["learn.project.ne555.quiz.q1.b"] = "jen DC.",
        ["learn.project.ne555.quiz.q1.c"] = "AC v jednom bodě.",
        ["learn.project.ne555.quiz.q1.explain"] = "Výstup měnící se v čase potřebuje Transient.",
        ["learn.project.ne555.quiz.q2.prompt"] = "Větší časovací kondenzátor obecně…",
        ["learn.project.ne555.quiz.q2.a"] = "kmitání zpomalí.",
        ["learn.project.ne555.quiz.q2.b"] = "ho vždy zrychlí.",
        ["learn.project.ne555.quiz.q2.c"] = "odstraní zem.",
        ["learn.project.ne555.quiz.q2.explain"] = "Větší τ → delší půlperiody.",
        ["learn.project.ne555.quiz.q3.prompt"] = "Tři LED na OUT v této předloze…",
        ["learn.project.ne555.quiz.q3.a"] = "blikají společně.",
        ["learn.project.ne555.quiz.q3.b"] = "nikdy nesvítí.",
        ["learn.project.ne555.quiz.q3.c"] = "potřebují I2C.",
        ["learn.project.ne555.quiz.q3.explain"] = "V příkladu sledují výstup 555.",
        ["learn.project.pushbutton.lesson1.title"] = "Okamžikový vstup",
        ["learn.project.pushbutton.lesson1.body"] = "Tlačítko spojuje jen po dobu stisku. Stejná myšlenka jako čtení digitálního vstupu na mikrokontroléru.",
        ["learn.project.pushbutton.lesson2.title"] = "Cesta aktivní v jedničce",
        ["learn.project.pushbutton.lesson2.body"] = "Tlačítko mezi napájením a rezistorem s LED: stisknuto = sepnutý spínač = teče proud.",
        ["learn.project.pushbutton.quiz.q1.prompt"] = "Puštěné tlačítko znamená…",
        ["learn.project.pushbutton.quiz.q1.a"] = "rozpojený obvod (žádný proud LED).",
        ["learn.project.pushbutton.quiz.q1.b"] = "zkratované napájení.",
        ["learn.project.pushbutton.quiz.q1.c"] = "vždy plně nabitý kondenzátor.",
        ["learn.project.pushbutton.quiz.q1.explain"] = "Okamžikový spínač se bez stisku rozepne.",
        ["learn.project.pushbutton.quiz.q2.prompt"] = "Abyste LED rozsvítili, musíte…",
        ["learn.project.pushbutton.quiz.q2.a"] = "stisknout BTN1 (nebo Podržet ke stisku).",
        ["learn.project.pushbutton.quiz.q2.b"] = "odstranit zem.",
        ["learn.project.pushbutton.quiz.q2.c"] = "spustit jen AC.",
        ["learn.project.pushbutton.quiz.q2.explain"] = "Sepnuté tlačítko uzavře cestu.",
        ["learn.project.pushbutton.quiz.q3.prompt"] = "Později se to na Arduinu promítne do…",
