        ["learn.project.pushbutton.quiz.q3.c"] = "navždy jen analogu.",
        ["learn.project.pushbutton.quiz.q3.explain"] = "Digitální vstup je zapnuto/vypnuto jako tlačítko.",
        ["learn.project.ldr.lesson1.title"] = "Fotorezistor",
        ["learn.project.ldr.lesson1.body"] = "Odpor fotorezistoru na světle klesá a ve tmě roste. Tady nastavuje napětí hradla NMOS nočního světla.",
        ["learn.project.ldr.lesson2.title"] = "Intuice děliče",
        ["learn.project.ldr.lesson2.body"] = "Zvedací rezistor a fotorezistor na zem: tma → vysoké napětí uzlu → tranzistor sepnutý → LED svítí.",
        ["learn.project.ldr.quiz.q1.prompt"] = "Ve tmě je odpor fotorezistoru…",
        ["learn.project.ldr.quiz.q1.a"] = "vyšší.",
        ["learn.project.ldr.quiz.q1.b"] = "vždy blízko nuly.",
        ["learn.project.ldr.quiz.q1.c"] = "na světle nezávislý.",
        ["learn.project.ldr.quiz.q1.explain"] = "Tma → vysoký R → uzel stoupá.",
        ["learn.project.ldr.quiz.q2.prompt"] = "Snížení parametru Světlo simuluje…",
        ["learn.project.ldr.quiz.q2.a"] = "jasnější okolí.",
        ["learn.project.ldr.quiz.q2.b"] = "tmavší okolí.",
        ["learn.project.ldr.quiz.q2.c"] = "vyšší napájení.",
        ["learn.project.ldr.quiz.q2.explain"] = "Ovládání Světlo modeluje osvětlení fotorezistoru.",
        ["learn.project.ldr.quiz.q3.prompt"] = "Noční světlo znamená LED svítí, když…",
        ["learn.project.ldr.quiz.q3.a"] = "je tma.",
        ["learn.project.ldr.quiz.q3.b"] = "slunce svítí nejvíc.",
        ["learn.project.ldr.quiz.q3.c"] = "je odstraněná zem.",
        ["learn.project.ldr.quiz.q3.explain"] = "Opačně než čidlo slunečného dne.",
        ["learn.project.buzzer.lesson1.title"] = "Zvuk z proudu",
        ["learn.project.buzzer.lesson1.body"] = "Výukový bzučák potřebuje dostatečný stejnosměrný proud. Vždy přidejte sériové omezení.",
        ["learn.project.buzzer.lesson2.title"] = "Ovládání spínačem",
        ["learn.project.buzzer.lesson2.body"] = "Stejný vzor jako u LED: spínač v sérii rozhoduje, zda proud dosáhne zátěže.",
        ["learn.project.buzzer.quiz.q1.prompt"] = "Sériový rezistor pomáhá…",
        ["learn.project.buzzer.quiz.q1.a"] = "omezit proud bzučáku.",
        ["learn.project.buzzer.quiz.q1.b"] = "zvýšit napájecí napětí.",
        ["learn.project.buzzer.quiz.q1.c"] = "odstranit zem.",
