        ["learn.project.buzzer.quiz.q2.explain"] = "Rozpojená cesta → žádný proud.",
        ["learn.project.buzzer.quiz.q3.prompt"] = "Kterou analýzu použít?",
        ["learn.project.buzzer.quiz.q3.a"] = "DC",
        ["learn.project.buzzer.quiz.q3.b"] = "jen Transient",
        ["learn.project.buzzer.quiz.q3.c"] = "rozmítání AC",
        ["learn.project.buzzer.quiz.q3.explain"] = "Ustálené zapnuto/vypnuto je DC.",
        ["learn.project.motorControl.lesson1.title"] = "Motor jako aktuátor",
        ["learn.project.motorControl.lesson1.body"] = "Stejnosměrný motor je zátěž, kterou budíte. Tady ho spínač NMOS na spodní straně zapne, když je hradlo buzené.",
        ["learn.project.motorControl.lesson2.title"] = "Chraňte spínač",
        ["learn.project.motorControl.lesson2.body"] = "Ochrannou diodu přes motor nechte na místě. Rozpojení cesty bez ní hrozí indukčním rázem ve skutečném hardwaru (a výukovými špičkami v Laboratoři).",
        ["learn.project.motorControl.quiz.q1.prompt"] = "Tento příklad bere motor hlavně jako…",
        ["learn.project.motorControl.quiz.q1.a"] = "zátěž aktuátoru ke spínání.",
        ["learn.project.motorControl.quiz.q1.b"] = "čidlo I2C.",
        ["learn.project.motorControl.quiz.q1.c"] = "krystalový oscilátor.",
        ["learn.project.motorControl.quiz.q1.explain"] = "Ženete proud vinutím motoru.",
        ["learn.project.motorControl.quiz.q2.prompt"] = "S rozepnutým spínačem hradla by motor měl…",
        ["learn.project.motorControl.quiz.q2.a"] = "točit se dál z ničeho.",
        ["learn.project.motorControl.quiz.q2.b"] = "zastavit (žádný budicí proud).",
        ["learn.project.motorControl.quiz.q2.c"] = "stát se baterií.",
        ["learn.project.motorControl.quiz.q2.explain"] = "Rozpojená cesta → žádný proud motoru.",
        ["learn.project.motorControl.quiz.q3.prompt"] = "Ochranná dioda je tam proto, aby…",
        ["learn.project.motorControl.quiz.q3.a"] = "zdobila schéma.",
        ["learn.project.motorControl.quiz.q3.b"] = "zvýšila Vf LED.",
        ["learn.project.motorControl.quiz.q3.c"] = "dala indukčnímu proudu bezpečnou cestu při vypnutí.",
        ["learn.project.motorControl.quiz.q3.explain"] = "Chrání spínací součástku.",
        ["learn.project.arduino.lesson1.title"] = "Digitální výstup",
        ["learn.project.arduino.lesson1.body"] = "Pin D13 Arduina budí LED přes rezistor. HIGH dodává proud, LOW ne.",
        ["learn.project.arduino.lesson2.title"] = "Meze výukového modelu",
        ["learn.project.arduino.lesson2.body"] = "Piny mají v modelu prahy pro jedničku a nulu. Není to plný emulátor mikrokontroléru, ale na trénink zapojení stačí.",
        ["learn.project.arduino.quiz.q1.prompt"] = "OUTPUT HIGH na D13 by měl…",
