        ["learn.project.arduino.quiz.q3.c"] = "návrh VF plošných spojů.",
        ["learn.project.arduino.quiz.q3.explain"] = "Nejdřív zapojení a logické úrovně.",
        ["learn.project.i2cOled.lesson1.title"] = "Zapojení sběrnice I2C",
        ["learn.project.i2cOled.lesson1.body"] = "SDA a SCL potřebují zvedací rezistory k logickému napájení. Podřízená zařízení sdílejí sběrnici se signalizací s otevřeným kolektorem.",
        ["learn.project.i2cOled.lesson2.title"] = "Adresa a napájení",
        ["learn.project.i2cOled.lesson2.body"] = "Modul OLED sdílí zem i napájení; I2C je dvouvodičové rozhraní s daty a hodinami.",
        ["learn.project.i2cOled.quiz.q1.prompt"] = "I2C potřebuje zvedací rezistory, protože…",
