        ["learn.project.i2cOled.quiz.q1.b"] = "je potřebují LED.",
        ["learn.project.i2cOled.quiz.q1.c"] = "zem je nepovinná.",
        ["learn.project.i2cOled.quiz.q1.explain"] = "Zvedací rezistory definují klidovou jedničku na SDA/SCL.",
        ["learn.project.i2cOled.quiz.q2.prompt"] = "Kolik vodičů má I2C pro data a hodiny (bez napájení)?",
