        ["learn.project.i2cOled.quiz.q2.c"] = "čtyři jen pro data",
        ["learn.project.i2cOled.quiz.q2.explain"] = "Klasické I2C jsou dvě signálové linky plus napájení a zem.",
        ["learn.project.i2cOled.quiz.q3.prompt"] = "Před spuštěním zkontrolujte…",
        ["learn.project.i2cOled.quiz.q3.a"] = "společnou zem a napájení.",
        ["learn.project.i2cOled.quiz.q3.b"] = "jen režim AC.",
        ["learn.project.i2cOled.quiz.q3.c"] = "odstranění rezistorů.",
        ["learn.project.i2cOled.quiz.q3.explain"] = "Všechny součástky sdílejí referenci a napájení.",
        ["learn.project.halfWave.lesson1.title"] = "Jedna dioda, jedna půlperioda",
        ["learn.project.halfWave.lesson1.body"] = "Dioda vede jen tehdy, když je anoda o asi Vf výš než katoda. K zátěži se tak dostanou jen kladné špičky střídavého napětí.",
        ["learn.project.halfWave.lesson2.title"] = "Pulzující DC",
        ["learn.project.halfWave.lesson2.body"] = "V blokované půlperiodě vidí zátěž nulu. Ta „chybějící“ energie je důvod, proč jednocestné usměrnění později potřebuje víc filtrování.",
        ["learn.project.halfWave.quiz.q1.prompt"] = "Jednocestný usměrňovač používá…",
        ["learn.project.halfWave.quiz.q1.a"] = "jednu sériovou diodu.",
