        ["learn.project.halfWave.quiz.q1.c"] = "jen kondenzátor.",
        ["learn.project.halfWave.quiz.q1.explain"] = "Jedna dioda propustí jednu polaritu.",
        ["learn.project.halfWave.quiz.q2.prompt"] = "V blokované půlperiodě je napětí na zátěži…",
        ["learn.project.halfWave.quiz.q2.a"] = "blízko nuly.",
        ["learn.project.halfWave.quiz.q2.b"] = "dvojnásobek špičky.",
        ["learn.project.halfWave.quiz.q2.c"] = "vždy záporné Vin.",
        ["learn.project.halfWave.quiz.q2.explain"] = "Dioda nevede → žádná cesta.",
        ["learn.project.halfWave.quiz.q3.prompt"] = "Nejlepší analýza tady?",
        ["learn.project.halfWave.quiz.q3.a"] = "Transient",
        ["learn.project.halfWave.quiz.q3.b"] = "jen DC",
        ["learn.project.halfWave.quiz.q3.c"] = "jen AC malý signál",
        ["learn.project.halfWave.quiz.q3.explain"] = "Průběh uvidíte jen v čase.",
        ["learn.project.bridge.lesson1.title"] = "Čtyři diody",
        ["learn.project.bridge.lesson1.body"] = "Můstek nasměruje obě půlperiody střídavého napětí do stejné stejnosměrné polarity na zátěži.",
        ["learn.project.bridge.lesson2.title"] = "Dvojnásobná frekvence pulzů",
        ["learn.project.bridge.lesson2.body"] = "Při 50 Hz AC dostanete pulzující DC o 100 Hz. Filtruje se snáz než jednocestné.",
        ["learn.project.bridge.quiz.q1.prompt"] = "Můstkové usměrňovače obvykle používají…",
        ["learn.project.bridge.quiz.q1.a"] = "čtyři diody.",
