        ["learn.project.bridge.quiz.q2.explain"] = "Přispívají obě polarity.",
        ["learn.project.bridge.quiz.q3.prompt"] = "Zpětná stejnosměrná svorka v tomto příkladu je…",
        ["learn.project.bridge.quiz.q3.a"] = "spojená se zemí kvůli měření.",
        ["learn.project.bridge.quiz.q3.b"] = "navždy plovoucí.",
        ["learn.project.bridge.quiz.q3.c"] = "jen AC.",
        ["learn.project.bridge.quiz.q3.explain"] = "Výukové zjednodušení.",
        ["learn.project.filterCap.lesson1.title"] = "Zásobní kondenzátor",
        ["learn.project.filterCap.lesson1.body"] = "Po usměrnění se C nabíjí blízko špiček a mezi špičkami napájí zátěž.",
        ["learn.project.filterCap.lesson2.title"] = "Kompromis se zvlněním",
        ["learn.project.filterCap.lesson2.body"] = "Menší C nebo těžší zátěž → větší pokles napětí mezi špičkami (zvlnění).",
        ["learn.project.filterCap.quiz.q1.prompt"] = "Mezi špičkami se kondenzátor hlavně…",
