        ["learn.project.filterCap.quiz.q3.a"] = "Transient",
        ["learn.project.filterCap.quiz.q3.b"] = "jen stejnosměrný pracovní bod",
        ["learn.project.filterCap.quiz.q3.c"] = "jen AC fázory",
        ["learn.project.filterCap.quiz.q3.explain"] = "Potřebujete průběh v čase.",
        ["learn.project.zener.lesson1.title"] = "Paralelní omezovač",
        ["learn.project.zener.lesson1.body"] = "Sériový Rs sráží přebytečné napětí; Zenerova dioda vede v závěrném směru blízko Vz a drží uzel zátěže.",
        ["learn.project.zener.lesson2.title"] = "Orientace",
        ["learn.project.zener.lesson2.body"] = "Katoda na stabilizovaný uzel, anoda na zem. Regulace probíhá v závěrném průrazu.",
        ["learn.project.zener.quiz.q1.prompt"] = "Zenerova stabilizace využívá…",
        ["learn.project.zener.quiz.q1.a"] = "závěrný průraz blízko Vz.",
