        ["learn.project.fuseProtect.lesson1.title"] = "Vybavení při nadproudu",
        ["learn.project.fuseProtect.lesson1.body"] = "Výuková pojistka má malý odpor, dokud |I| nepřekročí iMax. Pak se přeruší jako spálená součástka.",
        ["learn.project.fuseProtect.lesson2.title"] = "Po vybavení",
        ["learn.project.fuseProtect.lesson2.body"] = "Pojistku vyměňte. Laboratoř rozepne sepnuté spínače, aby nová pojistka nebyla hned přetížená. Než zkrat znovu sepnete, opravte závadu.",
        ["learn.project.fuseProtect.quiz.q1.prompt"] = "Pojistka se přeruší, když…",
