        ["learn.project.fuseProtect.quiz.q3.a"] = "zkrat, který přetíží pojistku.",
        ["learn.project.fuseProtect.quiz.q3.b"] = "navždy bezpečnou běžnou zátěž.",
        ["learn.project.fuseProtect.quiz.q3.c"] = "jen analýzu AC.",
        ["learn.project.fuseProtect.quiz.q3.explain"] = "Obtoková cesta nažene proud do F1.",
        ["learn.project.ripple.lesson1.title"] = "Co je zvlnění",
        ["learn.project.ripple.lesson1.body"] = "Zbytkové střídavé napětí na vyfiltrovaném DC. Pokles mezi špičkami usměrňovače.",
        ["learn.project.ripple.lesson2.title"] = "Jak ho uvidět",
        ["learn.project.ripple.lesson2.body"] = "Transient a sonda na uzlu filtru. Menší C nebo těžší zátěž zvlnění zvýrazní.",
        ["learn.project.ripple.quiz.q1.prompt"] = "Zvlnění je…",
        ["learn.project.ripple.quiz.q1.a"] = "zbytek AC na DC.",
        ["learn.project.ripple.quiz.q1.b"] = "jen stejnosměrný posun.",
        ["learn.project.ripple.quiz.q1.c"] = "práh hradla.",
        ["learn.project.ripple.quiz.q1.explain"] = "Zbytek špička–špička.",
        ["learn.project.ripple.quiz.q2.prompt"] = "Těžší zátěž obvykle…",
        ["learn.project.ripple.quiz.q2.a"] = "zvlnění zvětší.",
