        ["learn.project.ripple.quiz.q3.c"] = "nikdy sondu.",
        ["learn.project.ripple.quiz.q3.explain"] = "Pohled v časové oblasti.",
        ["learn.project.buck.lesson1.title"] = "Myšlenka snižování",
        ["learn.project.buck.lesson1.body"] = "Horní spínač seká Vin; L a C průměrují pulzy na nižší stejnosměrné napětí.",
        ["learn.project.buck.lesson2.title"] = "Střída",
        ["learn.project.buck.lesson2.body"] = "Delší doba sepnutí (vyšší střída) zvedá střední výstup směrem k Vin.",
        ["learn.project.buck.quiz.q1.prompt"] = "Snižující měnič ideálně…",
        ["learn.project.buck.quiz.q1.a"] = "napětí snižuje.",
        ["learn.project.buck.quiz.q1.b"] = "vždy zvyšuje.",
        ["learn.project.buck.quiz.q1.c"] = "odstraňuje cívky.",
        ["learn.project.buck.quiz.q1.explain"] = "Typicky Vout < Vin.",
        ["learn.project.buck.quiz.q2.prompt"] = "Vyšší střída obvykle…",
        ["learn.project.buck.quiz.q2.a"] = "zvedne střední Vout.",
