        ["learn.project.buck.quiz.q3.prompt"] = "Tento příklad potřebuje…",
        ["learn.project.buck.quiz.q3.a"] = "Transient (PWM).",
        ["learn.project.buck.quiz.q3.b"] = "jen DC.",
        ["learn.project.buck.quiz.q3.c"] = "jen AC fázory.",
        ["learn.project.buck.quiz.q3.explain"] = "Spínání je věc časové oblasti.",
        ["learn.project.boost.lesson1.title"] = "Myšlenka zvyšování",
        ["learn.project.boost.lesson1.body"] = "Spodní spínač ukládá energii do L, pak ji dioda předá kondenzátoru s vyšším Vout.",
        ["learn.project.boost.lesson2.title"] = "Energie za cyklus",
        ["learn.project.boost.lesson2.body"] = "Delší doba sepnutí uloží do cívky víc energie. Vout může vystoupit nad Vin.",
        ["learn.project.boost.quiz.q1.prompt"] = "Zvyšující měnič ideálně…",
        ["learn.project.boost.quiz.q1.a"] = "napětí zvyšuje.",
        ["learn.project.boost.quiz.q1.b"] = "vždy snižuje.",
        ["learn.project.boost.quiz.q1.c"] = "nepotřebuje diodu.",
        ["learn.project.boost.quiz.q1.explain"] = "Typicky Vout > Vin.",
        ["learn.project.boost.quiz.q2.prompt"] = "Energie cívky se ukládá hlavně, když…",
        ["learn.project.boost.quiz.q2.a"] = "je spínač sepnutý.",
        ["learn.project.boost.quiz.q2.b"] = "se přeruší pojistka.",
        ["learn.project.boost.quiz.q2.c"] = "zem plave.",
        ["learn.project.boost.quiz.q2.explain"] = "L se nabíjí proti zemi.",
        ["learn.project.boost.quiz.q3.prompt"] = "Režim analýzy?",
        ["learn.project.boost.quiz.q3.a"] = "Transient",
        ["learn.project.boost.quiz.q3.b"] = "jen DC",
        ["learn.project.boost.quiz.q3.c"] = "jen AC malý signál",
        ["learn.project.boost.quiz.q3.explain"] = "PWM potřebuje čas.",
        ["learn.project.rcLowPass.lesson1.body"] = "Na nízkých f je kondenzátor rozpojený, takže Vout ≈ Vin. Nad fc ≈ 1/(2πRC) paralelní C zkracuje střídavý signál k zemi a |Vout| klesá asi 20 dB na dekádu.",
        ["learn.project.rcLowPass.lesson2.body"] = "Vyhlazování čidel, antialiasing před ADC i jednoduchá regulace tónu vycházejí z této topologie.",
        ["learn.project.rcLowPass.quiz.q1.prompt"] = "RC dolní propust má kondenzátor…",
        ["learn.project.rcLowPass.quiz.q1.a"] = "přes výstup (paralelně k zemi).",
        ["learn.project.rcLowPass.quiz.q1.b"] = "jen v sérii se zdrojem.",
        ["learn.project.rcLowPass.quiz.q1.c"] = "plovoucí bez země.",
        ["learn.project.rcLowPass.quiz.q1.explain"] = "Sériový R a paralelní C je klasická dolní propust.",
        ["learn.project.rcLowPass.quiz.q2.prompt"] = "Mezní frekvence se mění jako…",
        ["learn.project.rcLowPass.quiz.q2.a"] = "RC",
        ["learn.project.rcLowPass.quiz.q2.b"] = "1 / (2πRC)",
        ["learn.project.rcLowPass.quiz.q2.c"] = "2πRC",
        ["learn.project.rcLowPass.quiz.q2.explain"] = "fc = 1/(2πRC) pro RC dolní propust prvního řádu.",
        ["learn.project.rcLowPass.quiz.q3.prompt"] = "Daleko nad mezní frekvencí |Vout|…",
        ["learn.project.rcLowPass.quiz.q3.a"] = "se rovná Vin.",
        ["learn.project.rcLowPass.quiz.q3.b"] = "roste bez omezení.",
        ["learn.project.rcLowPass.quiz.q3.c"] = "klesá s rostoucí frekvencí.",
        ["learn.project.rcLowPass.quiz.q3.explain"] = "Paralelní C odebírá s rostoucím f víc střídavého proudu.",
        ["learn.project.rcHighPass.lesson1.body"] = "Na vysokých f je kondenzátor zkrat, takže Vout ≈ Vin na R. Blízko DC C blokuje a |Vout| klesá k nule.",
        ["learn.project.rcHighPass.lesson2.body"] = "Střídavá vazba mezi stupni, odstranění stejnosměrného posunu a jednoduché výškové propusti.",
        ["learn.project.rcHighPass.quiz.q1.prompt"] = "RC horní propust má kondenzátor…",
        ["learn.project.rcHighPass.quiz.q1.a"] = "v sérii se signálovou cestou.",
        ["learn.project.rcHighPass.quiz.q1.b"] = "jen paralelně k zemi.",
        ["learn.project.rcHighPass.quiz.q1.c"] = "přes baterii.",
        ["learn.project.rcHighPass.quiz.q1.explain"] = "Sériový C a paralelní R je klasická horní propust.",
        ["learn.project.rcHighPass.quiz.q2.prompt"] = "Blízko DC je výstup ideální horní propusti…",
        ["learn.project.rcHighPass.quiz.q2.a"] = "rovný Vin.",
        ["learn.project.rcHighPass.quiz.q2.b"] = "blíží se nule.",
        ["learn.project.rcHighPass.quiz.q2.c"] = "kmitá.",
        ["learn.project.rcHighPass.quiz.q2.explain"] = "Sériový C blokuje DC.",
        ["learn.project.rcHighPass.quiz.q3.prompt"] = "Zvětšení C (při stejném R) posune fc…",
        ["learn.project.rcHighPass.quiz.q3.a"] = "výš.",
        ["learn.project.rcHighPass.quiz.q3.b"] = "nikam.",
        ["learn.project.rcHighPass.quiz.q3.c"] = "níž.",
        ["learn.project.rcHighPass.quiz.q3.explain"] = "fc = 1/(2πRC). Větší C zlom snižuje.",
        ["learn.project.rlcSeries.lesson1.body"] = "Při fr se induktivní a kapacitní reaktance vyruší. Sériová impedance je blízko R, takže proud je při daném buzení největší.",
        ["learn.project.rlcSeries.lesson2.body"] = "Filtry a laděné obvody jsou jen RLC s různými odběrovými body. Začněte tím, že si osaháte rezonanční špičku.",
        ["learn.project.rlcSeries.quiz.q1.prompt"] = "Sériová rezonance nastává, když…",
        ["learn.project.rlcSeries.quiz.q1.a"] = "XL ≈ XC.",
        ["learn.project.rlcSeries.quiz.q1.b"] = "jen R = 0.",
        ["learn.project.rlcSeries.quiz.q1.c"] = "L = C číselně.",
        ["learn.project.rlcSeries.quiz.q1.explain"] = "Reaktance se vyruší; impedance ≈ R.",
        ["learn.project.rlcSeries.quiz.q2.prompt"] = "Rezonanční frekvence se mění jako…",
        ["learn.project.rlcSeries.quiz.q2.a"] = "LC",
        ["learn.project.rlcSeries.quiz.q2.b"] = "1 / (2π√(LC))",
        ["learn.project.rlcSeries.quiz.q2.c"] = "2πLC",
        ["learn.project.rlcSeries.quiz.q2.explain"] = "fr = 1/(2π√(LC)).",
        ["learn.project.rlcSeries.quiz.q3.prompt"] = "Při rezonanci je sériová impedance nejblíž…",
        ["learn.project.rlcSeries.quiz.q3.a"] = "∞",
        ["learn.project.rlcSeries.quiz.q3.b"] = "jen jωL",
        ["learn.project.rlcSeries.quiz.q3.c"] = "R",
        ["learn.project.rlcSeries.quiz.q3.explain"] = "L a C se vyruší; zůstane R.",
        ["learn.project.bandPass.lesson1.body"] = "Kolem rezonance síť signál přenáší; daleko od rezonance ho reaktanční nesoulad tlumí. Šířka pásma závisí na Q (R proti √(L/C)).",
        ["learn.project.bandPass.lesson2.body"] = "Pásmová propust potřebuje pokles nahoře i dole. RLC (nebo kaskáda RC) takový tvar dá.",
        ["learn.project.bandPass.quiz.q1.prompt"] = "Pásmová propust ideálně…",
        ["learn.project.bandPass.quiz.q1.a"] = "propouští střední pásmo a tlumí okraje.",
        ["learn.project.bandPass.quiz.q1.b"] = "jen blokuje DC.",
        ["learn.project.bandPass.quiz.q1.c"] = "zesiluje všechny frekvence stejně.",
        ["learn.project.bandPass.quiz.q1.explain"] = "To je definice pásmové propusti.",
        ["learn.project.bandPass.quiz.q2.prompt"] = "Střední frekvenci určuje hlavně…",
        ["learn.project.bandPass.quiz.q2.a"] = "jen R.",
        ["learn.project.bandPass.quiz.q2.b"] = "L a C (rezonance).",
        ["learn.project.bandPass.quiz.q2.c"] = "jen délka drátu.",
        ["learn.project.bandPass.quiz.q2.explain"] = "fr sleduje součin LC.",
        ["learn.project.bandPass.quiz.q3.prompt"] = "Vyšší Q obvykle znamená…",
        ["learn.project.bandPass.quiz.q3.a"] = "širší propustné pásmo.",
        ["learn.project.bandPass.quiz.q3.b"] = "žádnou rezonanci.",
        ["learn.project.bandPass.quiz.q3.c"] = "užší špičku kolem fr.",
        ["learn.project.bandPass.quiz.q3.explain"] = "Q rezonanční špičku zostřuje.",
        ["learn.project.notchFilter.lesson1.body"] = "Na frekvenci zádrže síť vytvoří cestu, která přenos do zátěže vyruší. |Vout| v úzkém pásmu prudce klesne.",
        ["learn.project.notchFilter.lesson2.body"] = "Potlačení síťového brumu, odstranění pískání nebo vyčištění jednoho rušení před zesílením.",
        ["learn.project.notchFilter.quiz.q1.prompt"] = "Pásmová zádrž…",
        ["learn.project.notchFilter.quiz.q1.a"] = "potlačuje úzké pásmo.",
        ["learn.project.notchFilter.quiz.q1.b"] = "propouští jen DC.",
        ["learn.project.notchFilter.quiz.q1.c"] = "vždy zesiluje.",
        ["learn.project.notchFilter.quiz.q1.explain"] = "Zádrž = potlačení pásma kolem jedné frekvence.",
        ["learn.project.notchFilter.quiz.q2.prompt"] = "Daleko od frekvence zádrže |Vout|…",
        ["learn.project.notchFilter.quiz.q2.a"] = "je vždy nula.",
        ["learn.project.notchFilter.quiz.q2.b"] = "se vrací k propustné úrovni.",
        ["learn.project.notchFilter.quiz.q2.c"] = "musí kmitat.",
        ["learn.project.notchFilter.quiz.q2.explain"] = "Potlačení je omezené na okolí zádrže.",
        ["learn.project.notchFilter.quiz.q3.prompt"] = "Ladění zádrže znamená hlavně změnit…",
        ["learn.project.notchFilter.quiz.q3.a"] = "jen ESR baterie.",
        ["learn.project.notchFilter.quiz.q3.b"] = "barvu drátu.",
        ["learn.project.notchFilter.quiz.q3.c"] = "L a/nebo C.",
        ["learn.project.notchFilter.quiz.q3.explain"] = "Potlačovaná frekvence sleduje rezonanci LC.",
        ["learn.project.voltageDivider.lesson1.body"] = "Bez zátěže je Vmid = Vzdroj · Rdolní / (Rhorní + Rdolní). Proud je V / (R1+R2).",
        ["learn.project.voltageDivider.lesson2.body"] = "Cokoli připojené na střední uzel je další paralelní cesta. Sníží účinný Rdolní a Vmid klesne.",
        ["learn.project.voltageDivider.quiz.q1.prompt"] = "Střední napětí nezatíženého děliče je…",
        ["learn.project.voltageDivider.quiz.q1.a"] = "V · R2 / (R1 + R2)",
        ["learn.project.voltageDivider.quiz.q1.b"] = "jen V · R1",
        ["learn.project.voltageDivider.quiz.q1.c"] = "vždy V/2 bez ohledu na R",
        ["learn.project.voltageDivider.quiz.q1.explain"] = "Ohmův zákon na sériovém řetězci.",
        ["learn.project.voltageDivider.quiz.q2.prompt"] = "Stejné rezistory dají…",
        ["learn.project.voltageDivider.quiz.q2.a"] = "nula voltů.",
        ["learn.project.voltageDivider.quiz.q2.b"] = "polovinu zdroje (ideálně).",
        ["learn.project.voltageDivider.quiz.q2.c"] = "dvojnásobek zdroje.",
        ["learn.project.voltageDivider.quiz.q2.explain"] = "R2/(R1+R2) = 1/2.",
        ["learn.project.voltageDivider.quiz.q3.prompt"] = "Těžká zátěž na středním uzlu…",
        ["learn.project.voltageDivider.quiz.q3.a"] = "Vmid zvedne.",
        ["learn.project.voltageDivider.quiz.q3.b"] = "nedělá nic.",
        ["learn.project.voltageDivider.quiz.q3.c"] = "Vmid stáhne dolů.",
        ["learn.project.voltageDivider.quiz.q3.explain"] = "Zátěž je paralelně k Rdolní.",
        ["learn.project.dividerDesign.lesson1.title"] = "Navrhněte poměr",
        ["learn.project.dividerDesign.lesson1.body"] = "Zvolte R1 a R2 tak, aby Vmid vyšlo, kam potřebujete. Stejné rezistory → polovina napájení; větší Rdolní → vyšší střed.",
        ["learn.project.dividerDesign.lesson2.title"] = "Ověřte sondou",
        ["learn.project.dividerDesign.lesson2.body"] = "Po nastavení hodnot spusťte DC a změřte střední uzel. Nejdřív předpověď, potom měření.",
