        ["learn.project.measureAc.lesson1.body"] = "Režim AC hlásí velikost a fázi fázoru na analyzované frekvenci. Ptejte se: „jak velký je tady tento tón?“",
        ["learn.project.measureAc.lesson2.body"] = "Vyberte jednu frekvenci, změřte jeden uzel, změňte jeden parametr. Tak si budujete intuici, aniž byste se utopili v grafech.",
