        ["learn.project.bodeIntuition.lesson1.title"] = "Velikost proti frekvenci",
        ["learn.project.bodeIntuition.lesson1.body"] = "Změňte frekvenci analýzy AC a změřte tentýž uzel. To je zárodek Bodeho uvažování, ještě bez celého grafu.",
        ["learn.project.bodeIntuition.lesson2.title"] = "Jeden knoflík naráz",
