        ["learn.project.motorMosfet.lesson1.body"] = "NMOS mezi motorem (−) a zemí umožní logickému hradlu řídit cestu s větším proudem z napájení přes motor.",
        ["learn.project.motorMosfet.lesson2.body"] = "Motory jsou indukční. Když se FET rozepne, proud potřebuje volnoběžnou cestu (ochrannou diodu).",
