        ["learn.project.motorPwm.lesson1.body"] = "PWM spíná plně zapnuto/vypnuto. Indukčnost a mechanika motoru pulzy průměrují. Vyšší střída ≈ vyšší účinné napětí.",
        ["learn.project.motorPwm.lesson2.body"] = "Spínání drží FET ve stavech s malými ztrátami místo toho, aby topil jako sériový reostat.",
