        ["learn.project.hBridge.lesson1.body"] = "Vpřed: levý horní a pravý dolní. Vzad: druhá diagonála. Oba horní nebo oba dolní na jedné straně zkratují napájení.",
        ["learn.project.hBridge.lesson2.body"] = "Ideální spínače zastupují MOSFETové půlmůstky. Soustřeďte se na cestu proudu, ne zatím na budicí obvody hradel.",
