        ["learn.project.debounce.lesson1.body"] = "Mechanické kontakty po milisekundy kmitají. Logika, která vzorkuje surové hrany, může vidět mnoho falešných přechodů.",
        ["learn.project.debounce.lesson2.body"] = "Kondenzátor na zem (se zvedacím rezistorem) uzel spínače filtruje jako dolní propust. Ošetření ve firmwaru je digitální dvojče této myšlenky.",
        ["learn.project.debounce.quiz.q1.prompt"] = "Zákmity spínače způsobují…",
