        ["learn.project.debounce.quiz.q3.explain"] = "Prospěje každému mechanickému kontaktu.",
        ["learn.project.debounceIdea.lesson1.title"] = "Proč ošetření zákmitů existuje",
        ["learn.project.debounceIdea.lesson1.body"] = "Jeden fyzický stisk není jedna čistá hrana. Kontakty kmitají. Logika i vstupy mikrokontroléru potřebují klidné rozhodnutí.",
        ["learn.project.debounceIdea.lesson2.title"] = "Hardware proti firmwaru",
        ["learn.project.debounceIdea.lesson2.body"] = "RC filtr je analogová verze; čekání několik milisekund v kódu je digitální dvojče. Stejný problém, dva nástroje.",
        ["learn.project.debounceIdea.quiz.q1.prompt"] = "Ošetření zákmitů řeší…",
        ["learn.project.debounceIdea.quiz.q1.a"] = "falešné vícenásobné hrany z jednoho stisku.",
        ["learn.project.debounceIdea.quiz.q1.b"] = "zdvojnásobení napětí baterie.",
        ["learn.project.debounceIdea.quiz.q1.c"] = "jen chybějící značky země.",
        ["learn.project.debounceIdea.quiz.q1.explain"] = "Zákmity vytvářejí kmitající hrany.",
        ["learn.project.debounceIdea.quiz.q2.prompt"] = "Ošetření ve firmwaru obvykle…",
        ["learn.project.debounceIdea.quiz.q2.a"] = "po krátkou dobu ustálení hrany ignoruje.",
        ["learn.project.debounceIdea.quiz.q2.b"] = "smaže spínač.",
        ["learn.project.debounceIdea.quiz.q2.c"] = "zvedne napájení na 100 V.",
        ["learn.project.debounceIdea.quiz.q2.explain"] = "Počkejte, až je kontakt stabilní.",
        ["learn.project.debounceIdea.quiz.q3.prompt"] = "RC ošetření a ošetření v kódu…",
        ["learn.project.debounceIdea.quiz.q3.a"] = "navždy nesouvisí.",
        ["learn.project.debounceIdea.quiz.q3.b"] = "fungují jen na motorech.",
        ["learn.project.debounceIdea.quiz.q3.c"] = "útočí na stejný problém zákmitů různě.",
        ["learn.project.debounceIdea.quiz.q3.explain"] = "Hardware filtruje, software čeká. Stejný cíl.",
        ["learn.project.sensorLdr.lesson1.title"] = "Z odporu na napětí",
        ["learn.project.sensorLdr.lesson1.body"] = "Většina čidel sama o sobě čistý volt nevydá. Fotorezistor je proměnný R; pevný rezistor doplní dělič a dostanete napětí, které sleduje světlo.",
        ["learn.project.sensorLdr.lesson2.title"] = "Použitelný signál",
        ["learn.project.sensorLdr.lesson2.body"] = "Napětí středního uzlu může budit FET, komparátor nebo (později) pin ADC. Stejná myšlenka pro mnoho odporových čidel.",
        ["learn.project.sensorLdr.quiz.q1.prompt"] = "Fotorezistor mění hlavně…",
        ["learn.project.sensorLdr.quiz.q1.a"] = "odpor se světlem.",
        ["learn.project.sensorLdr.quiz.q1.b"] = "jen ESR baterie.",
        ["learn.project.sensorLdr.quiz.q1.c"] = "barvu drátu.",
        ["learn.project.sensorLdr.quiz.q1.explain"] = "Fotoodpor se mění s osvětlením.",
        ["learn.project.sensorLdr.quiz.q2.prompt"] = "Sériový rezistor s fotorezistorem tvoří…",
        ["learn.project.sensorLdr.quiz.q2.a"] = "zkrat přes VCC.",
        ["learn.project.sensorLdr.quiz.q2.b"] = "napěťový dělič (použitelný signál).",
        ["learn.project.sensorLdr.quiz.q2.c"] = "anténu.",
        ["learn.project.sensorLdr.quiz.q2.explain"] = "Střední uzel děliče je napětí čidla.",
        ["learn.project.sensorLdr.quiz.q3.prompt"] = "Víc světla (nižší R fotorezistoru k zemi) obvykle…",
        ["learn.project.sensorLdr.quiz.q3.a"] = "zvedá střední uzel navždy.",
        ["learn.project.sensorLdr.quiz.q3.b"] = "odpojí zem.",
        ["learn.project.sensorLdr.quiz.q3.c"] = "stáhne střední uzel k zemi.",
        ["learn.project.sensorLdr.quiz.q3.explain"] = "Nižší dolní R snižuje poměr děliče.",
        ["learn.project.sensorPot.lesson1.title"] = "Z polohy na napětí",
        ["learn.project.sensorPot.lesson1.body"] = "Mechanický pohyb mění poměr děliče. Běžec už je použitelný analogový signál.",
        ["learn.project.sensorPot.lesson2.title"] = "Zatížení",
        ["learn.project.sensorPot.lesson2.body"] = "Cokoli připojíte na běžec (ADC, zesilovač, FET) nesmí napětí stáhnout, pokud chcete přesnost. Pomůže oddělovač nebo vysoká impedance.",
        ["learn.project.sensorPot.quiz.q1.prompt"] = "Potenciometr jako čidlo dává…",
        ["learn.project.sensorPot.quiz.q1.a"] = "napětí odbočky mezi napájecími úrovněmi.",
        ["learn.project.sensorPot.quiz.q1.b"] = "jen digitální pulzy.",
        ["learn.project.sensorPot.quiz.q1.c"] = "jen VF.",
        ["learn.project.sensorPot.quiz.q1.explain"] = "Běžec je analogový signál.",
        ["learn.project.sensorPot.quiz.q2.prompt"] = "Posun běžce mění…",
        ["learn.project.sensorPot.quiz.q2.a"] = "nic elektrického.",
        ["learn.project.sensorPot.quiz.q2.b"] = "poměr děliče (a Vwiper).",
        ["learn.project.sensorPot.quiz.q2.c"] = "jen barvu LED.",
        ["learn.project.sensorPot.quiz.q2.explain"] = "Poloha nastavuje odporové rozdělení.",
        ["learn.project.sensorPot.quiz.q3.prompt"] = "Těžká zátěž na běžci…",
        ["learn.project.sensorPot.quiz.q3.a"] = "nikdy nevadí.",
        ["learn.project.sensorPot.quiz.q3.b"] = "zvedne VCC.",
        ["learn.project.sensorPot.quiz.q3.c"] = "může pokřivit očekávané napětí.",
        ["learn.project.sensorPot.quiz.q3.explain"] = "Zatížení je paralelně k dolnímu rameni.",
        ["learn.project.ntcDivider.lesson1.title"] = "Myšlenka termistoru",
        ["learn.project.ntcDivider.lesson1.body"] = "NTC s teplotou snižuje odpor. V děliči to posune střední napětí. To je váš teplotní signál.",
        ["learn.project.ntcDivider.lesson2.title"] = "Proč náhrada",
        ["learn.project.ntcDivider.lesson2.body"] = "Laboratoř v1 zatím nemá vlastní model NTC. Potenciometr vám dá osahat matematiku děliče, než přijde budoucí model čidla.",
        ["learn.project.ntcDivider.quiz.q1.prompt"] = "NTC v děliči dává hlavně…",
        ["learn.project.ntcDivider.quiz.q1.a"] = "napětí, které sleduje teplotu.",
        ["learn.project.ntcDivider.quiz.q1.b"] = "jen PWM.",
        ["learn.project.ntcDivider.quiz.q1.c"] = "galvanické oddělení.",
        ["learn.project.ntcDivider.quiz.q1.explain"] = "R(T) → Vmid.",
        ["learn.project.ntcDivider.quiz.q2.prompt"] = "Když odpor NTC v dolním rameni klesne (tepleji)…",
        ["learn.project.ntcDivider.quiz.q2.a"] = "Vmid obvykle klesne.",
        ["learn.project.ntcDivider.quiz.q2.b"] = "Vmid musí vystoupit na VCC.",
        ["learn.project.ntcDivider.quiz.q2.c"] = "baterie se zkratuje.",
        ["learn.project.ntcDivider.quiz.q2.explain"] = "Nižší dolní R snižuje poměr.",
        ["learn.project.ntcDivider.quiz.q3.prompt"] = "Tento příklad používá potenciometr, protože…",
        ["learn.project.ntcDivider.quiz.q3.a"] = "potenciometry jsou NTC.",
        ["learn.project.ntcDivider.quiz.q3.b"] = "je to výuková náhrada proměnného R.",
        ["learn.project.ntcDivider.quiz.q3.c"] = "to vyžaduje analýza AC.",
        ["learn.project.ntcDivider.quiz.q3.explain"] = "Interaktivní R bez vlastního modelu NTC.",
        ["learn.project.sensorThreshold.lesson1.title"] = "Rozhodnutí prahem",
        ["learn.project.sensorThreshold.lesson1.body"] = "Mnoho aplikací čidel potřebuje bod přepnutí, ne spojité číslo. Komparátor (nebo digitální čtení mikrokontroléru po úpravě signálu) změní analog na zapnuto/vypnuto.",
        ["learn.project.sensorThreshold.lesson2.title"] = "Dál hystereze",
        ["learn.project.sensorThreshold.lesson2.body"] = "Skutečné systémy přidávají Schmittovu zpětnou vazbu, aby šum kolem prahu necukal. Viz lekci o Schmittově obvodu.",
        ["learn.project.sensorThreshold.quiz.q1.prompt"] = "Komparátor na napětí čidla…",
        ["learn.project.sensorThreshold.quiz.q1.a"] = "ho porovnává s prahem.",
        ["learn.project.sensorThreshold.quiz.q1.b"] = "vždy integruje.",
        ["learn.project.sensorThreshold.quiz.q1.c"] = "odstraní potřebu země.",
        ["learn.project.sensorThreshold.quiz.q1.explain"] = "Zesilovač bez zpětné vazby jde nahoru nebo dolů podle −in.",
        ["learn.project.sensorThreshold.quiz.q2.prompt"] = "Překročení prahu…",
        ["learn.project.sensorThreshold.quiz.q2.a"] = "nechá OUT beze změny.",
        ["learn.project.sensorThreshold.quiz.q2.b"] = "překlopí OUT k mezi.",
        ["learn.project.sensorThreshold.quiz.q2.c"] = "vždy spálí potenciometr.",
        ["learn.project.sensorThreshold.quiz.q2.explain"] = "To je rozhodovací hrana.",
        ["learn.project.sensorThreshold.quiz.q3.prompt"] = "Děliče čidel napájejí komparátory, protože…",
        ["learn.project.sensorThreshold.quiz.q3.a"] = "už vydávají USB.",
        ["learn.project.sensorThreshold.quiz.q3.b"] = "fungují jen na 24 V.",
        ["learn.project.sensorThreshold.quiz.q3.c"] = "dávají napětí, které lze porovnat.",
        ["learn.project.sensorThreshold.quiz.q3.explain"] = "Analogový střední uzel → rozhodnutí.",
        ["learn.project.commsI2c.lesson1.title"] = "Sběrnice s otevřeným kolektorem",
        ["learn.project.commsI2c.lesson1.body"] = "Linky I²C jsou v klidu nahoře díky zvedacím rezistorům; zařízení jen stahují dolů. Chybějící zvedací rezistory = zamrzlá nebo nespolehlivá sběrnice.",
        ["learn.project.commsI2c.lesson2.title"] = "Proč na tom záleží",
        ["learn.project.commsI2c.lesson2.body"] = "Čidla, paměti EEPROM i displeje sdílejí tento vzor. UART, SPI a RS-485 potřebují vlastní příběhy o zapojení (pozdější lekce).",
        ["learn.project.commsI2c.quiz.q1.prompt"] = "Klidový stav SDA/SCL u I²C spoléhá na…",
        ["learn.project.commsI2c.quiz.q1.a"] = "zvedací rezistory k VCC.",
        ["learn.project.commsI2c.quiz.q1.b"] = "jen sériové cívky.",
        ["learn.project.commsI2c.quiz.q1.c"] = "plovoucí piny.",
        ["learn.project.commsI2c.quiz.q1.explain"] = "Otevřený kolektor potřebuje zvedací rezistory.",
        ["learn.project.commsI2c.quiz.q2.prompt"] = "Dvě zařízení na jedné sběrnici I²C sdílejí…",
        ["learn.project.commsI2c.quiz.q2.a"] = "SDA a SCL (a zem).",
        ["learn.project.commsI2c.quiz.q2.b"] = "jen TX.",
        ["learn.project.commsI2c.quiz.q2.c"] = "jen CAN_H.",
        ["learn.project.commsI2c.quiz.q2.explain"] = "Více zařízení na dvou vodičích a zemi.",
        ["learn.project.commsI2c.quiz.q3.prompt"] = "UART / SPI / RS-485 v této Laboratoři…",
        ["learn.project.commsI2c.quiz.q3.a"] = "jsou dnes plně simulované.",
        ["learn.project.commsI2c.quiz.q3.b"] = "potřebují budoucí modely (zdokumentované mezery).",
        ["learn.project.commsI2c.quiz.q3.c"] = "nahrazují zvedací rezistory I²C.",
        ["learn.project.commsI2c.quiz.q3.explain"] = "V Laboratoři v1 je hotové jen zapojení I²C.",
        ["learn.project.adcFrontEnd.lesson1.title"] = "Vzorkovat napětí",
        ["learn.project.adcFrontEnd.lesson1.body"] = "ADC převádí Vin na celé číslo pomocí Vref a počtu bitů. Úkolem vstupní části je dodat čisté Vin v rozsahu.",
        ["learn.project.adcFrontEnd.lesson2.title"] = "Z čidel do ADC",
        ["learn.project.adcFrontEnd.lesson2.body"] = "Děliče, zesilovače a filtry upraví signál čidla tak, aby pin mikrokontroléru viděl přátelské napětí, ne surové miliampérové smyčky.",
        ["learn.project.adcFrontEnd.quiz.q1.prompt"] = "ADC především převádí…",
        ["learn.project.adcFrontEnd.quiz.q1.a"] = "napětí na číslo.",
        ["learn.project.adcFrontEnd.quiz.q1.b"] = "jen odpor na světlo.",
        ["learn.project.adcFrontEnd.quiz.q1.c"] = "UART na SPI.",
        ["learn.project.adcFrontEnd.quiz.q1.explain"] = "Kvantování Vin vůči Vref.",
        ["learn.project.adcFrontEnd.quiz.q2.prompt"] = "Napětí běžce tu zastupuje…",
        ["learn.project.adcFrontEnd.quiz.q2.a"] = "Vin na analogovém pinu.",
        ["learn.project.adcFrontEnd.quiz.q2.b"] = "krystalový oscilátor.",
        ["learn.project.adcFrontEnd.quiz.q2.c"] = "jen diferenciální CAN.",
        ["learn.project.adcFrontEnd.quiz.q2.explain"] = "Napětí vstupní části před digitalizací.",
        ["learn.project.adcFrontEnd.quiz.q3.prompt"] = "Když Vin přesáhne Vref…",
        ["learn.project.adcFrontEnd.quiz.q3.a"] = "kódy rostou donekonečna.",
        ["learn.project.adcFrontEnd.quiz.q3.b"] = "nic se nestane.",
        ["learn.project.adcFrontEnd.quiz.q3.c"] = "údaj se nasytí nebo ořeže.",
        ["learn.project.adcFrontEnd.quiz.q3.explain"] = "Plný rozsah je Vref.",
        ["learn.project.adcReference.lesson1.title"] = "Vref nastavuje pravítko",
        ["learn.project.adcReference.lesson1.body"] = "Rozlišení je Vref / 2^N na jeden krok (ideálně). Zašuměné nebo špatné Vref přeškáluje každé měření.",
        ["learn.project.adcReference.lesson2.title"] = "Vzorkování",
        ["learn.project.adcReference.lesson2.body"] = "Jak často převádíte (vzorkovací frekvence) je jiná věc než počet bitů. Pro věrnou rekonstrukci záleží na obojím.",
        ["learn.project.adcReference.quiz.q1.prompt"] = "Plný rozsah ADC určuje…",
        ["learn.project.adcReference.quiz.q1.a"] = "referenční napětí (Vref).",
        ["learn.project.adcReference.quiz.q1.b"] = "jen průřez drátu.",
        ["learn.project.adcReference.quiz.q1.c"] = "barva LED.",
        ["learn.project.adcReference.quiz.q1.explain"] = "Kódy pokrývají 0…Vref.",
        ["learn.project.adcReference.quiz.q2.prompt"] = "Víc bitů (stejné Vref) znamená…",
        ["learn.project.adcReference.quiz.q2.a"] = "hrubší kroky.",
        ["learn.project.adcReference.quiz.q2.b"] = "jemnější napěťové kroky.",
        ["learn.project.adcReference.quiz.q2.c"] = "žádnou změnu.",
        ["learn.project.adcReference.quiz.q2.explain"] = "Krok ≈ Vref/2^N.",
        ["learn.project.adcReference.quiz.q3.prompt"] = "Odporový dělič pomáhá učit…",
        ["learn.project.adcReference.quiz.q3.a"] = "známé zlomky napájení.",
        ["learn.project.adcReference.quiz.q3.b"] = "adresování I²C.",
        ["learn.project.adcReference.quiz.q3.c"] = "arbitráž CAN.",
        ["learn.project.adcReference.quiz.q3.explain"] = "Poměr → předvídatelné střední napětí.",
        ["learn.project.pwmFilter.lesson1.title"] = "Střední hodnota je ten „analog“",
        ["learn.project.pwmFilter.lesson1.body"] = "PWM jsou pořád digitální hrany. RC (nebo vlastní filtrace zátěže) je zprůměruje na přibližně stejnosměrné napětí.",
        ["learn.project.pwmFilter.lesson2.title"] = "Proti skutečnému DAC",
        ["learn.project.pwmFilter.lesson2.body"] = "Skutečný DAC vydá drženou úroveň s lepší linearitou a menším šumem. PWM s filtrem je výuková náhrada a běžný trik mikrokontrolérů.",
        ["learn.project.pwmFilter.quiz.q1.prompt"] = "PWM jako DAC mění hlavně…",
        ["learn.project.pwmFilter.quiz.q1.a"] = "střídu.",
        ["learn.project.pwmFilter.quiz.q1.b"] = "jen ppm krystalu.",
        ["learn.project.pwmFilter.quiz.q1.c"] = "barvu drátu.",
        ["learn.project.pwmFilter.quiz.q1.explain"] = "Střední hodnota sleduje střídu.",
        ["learn.project.pwmFilter.quiz.q2.prompt"] = "RC za PWM…",
        ["learn.project.pwmFilter.quiz.q2.a"] = "pulzy filtruje dolní propustí a průměruje.",
        ["learn.project.pwmFilter.quiz.q2.b"] = "vytváří adresy I²C.",
        ["learn.project.pwmFilter.quiz.q2.c"] = "odstraní zem.",
        ["learn.project.pwmFilter.quiz.q2.explain"] = "To je pseudoanalogový stupeň.",
        ["learn.project.pwmFilter.quiz.q3.prompt"] = "Vyšší střída obvykle…",
        ["learn.project.pwmFilter.quiz.q3.a"] = "sníží střední napětí.",
        ["learn.project.pwmFilter.quiz.q3.b"] = "zastaví pulzní zdroj.",
        ["learn.project.pwmFilter.quiz.q3.c"] = "zvedne filtrovanou střední hodnotu.",
        ["learn.project.pwmFilter.quiz.q3.explain"] = "Delší doba nahoře → vyšší průměr.",
        ["learn.project.relayBjt.lesson1.title"] = "Proč budič",
        ["learn.project.relayBjt.lesson1.body"] = "Cívky relé berou desítky mA. Tranzistor (nebo MOSFET) umožní malému bázovému či hradlovému proudu tu cívku ovládat.",
        ["learn.project.relayBjt.lesson2.title"] = "Dioda pořád nutná",
        ["learn.project.relayBjt.lesson2.body"] = "Vypnutí cívky uvolní indukční energii. Dfly chrání tranzistor.",
        ["learn.project.relayBjt.quiz.q1.prompt"] = "BJT v tomto příkladu…",
        ["learn.project.relayBjt.quiz.q1.a"] = "spíná proud cívky relé.",
        ["learn.project.relayBjt.quiz.q1.b"] = "je zátěž kontaktů.",
        ["learn.project.relayBjt.quiz.q1.c"] = "nahrazuje ochrannou diodu.",
        ["learn.project.relayBjt.quiz.q1.explain"] = "Budič cívky na spodní straně.",
        ["learn.project.relayBjt.quiz.q2.prompt"] = "Ochranná dioda patří…",
        ["learn.project.relayBjt.quiz.q2.a"] = "přes cívku.",
        ["learn.project.relayBjt.quiz.q2.b"] = "jen přes LED.",
        ["learn.project.relayBjt.quiz.q2.c"] = "navždy do série s VCC.",
        ["learn.project.relayBjt.quiz.q2.explain"] = "Nechá indukční ráz volně doběhnout.",
        ["learn.project.relayBjt.quiz.q3.prompt"] = "Kontakty slouží…",
        ["learn.project.relayBjt.quiz.q3.a"] = "obvodu zátěže.",
        ["learn.project.relayBjt.quiz.q3.b"] = "jen předpětí báze.",
        ["learn.project.relayBjt.quiz.q3.c"] = "buzení krystalu.",
        ["learn.project.relayBjt.quiz.q3.explain"] = "Galvanicky oddělená spínací cesta.",
        ["learn.project.mosfetDriver.lesson1.title"] = "Hradlo je řízení",
        ["learn.project.mosfetDriver.lesson1.body"] = "Obohacený NMOS vede, když je Vgs dost vysoké. Téměř žádný stejnosměrný proud hradla, na rozdíl od bázového proudu BJT.",
        ["learn.project.mosfetDriver.lesson2.title"] = "Průmyslový příbuzný",
        ["learn.project.mosfetDriver.lesson2.body"] = "Budiče MOSFETů a vstupy polovodičových relé jsou tahle myšlenka ve větším. Pořád je tu řídicí a zátěžová strana.",
        ["learn.project.mosfetDriver.quiz.q1.prompt"] = "NMOS spínač na spodní straně potřebuje…",
        ["learn.project.mosfetDriver.quiz.q1.a"] = "dostatečné napětí hradla.",
        ["learn.project.mosfetDriver.quiz.q1.b"] = "jen plovoucí hradlo.",
        ["learn.project.mosfetDriver.quiz.q1.c"] = "žádnou zpětnou cestu k zemi.",
        ["learn.project.mosfetDriver.quiz.q1.explain"] = "Vgs nad prahem.",
        ["learn.project.mosfetDriver.quiz.q2.prompt"] = "Rezistor hradla hlavně…",
        ["learn.project.mosfetDriver.quiz.q2.a"] = "omezuje nabíjecí proud hradla a změkčuje hrany.",
        ["learn.project.mosfetDriver.quiz.q2.b"] = "nastavuje barvu LED.",
        ["learn.project.mosfetDriver.quiz.q2.c"] = "vytváří zvedací rezistory I²C.",
        ["learn.project.mosfetDriver.quiz.q2.explain"] = "Sériový RG je běžná praxe.",
        ["learn.project.mosfetDriver.quiz.q3.prompt"] = "Stahovací rezistor na hradle…",
        ["learn.project.mosfetDriver.quiz.q3.a"] = "drží vypnuto, když je buzení rozpojené.",
        ["learn.project.mosfetDriver.quiz.q3.b"] = "FET vždy sepne.",
        ["learn.project.mosfetDriver.quiz.q3.c"] = "odstraní potřebu zátěže.",
        ["learn.project.mosfetDriver.quiz.q3.explain"] = "Definovaná klidová úroveň.",
