        ["learn.project.industrial24v.lesson1.title"] = "Ovládací napětí",
        ["learn.project.industrial24v.lesson1.body"] = "24 V DC je běžné pro průmyslové vstupy/výstupy a cívky relé. Logika může být pořád 3,3/5 V za budiči a oddělením.",
