    public static async Task SeedEnglishAsync(LearningDbContext db, CancellationToken ct = default)
    {
        await SeedLocaleAsync(db, "en", English, ct);
        await SeedLocaleAsync(db, "cs", Czech, ct);
    }

    private static async Task SeedLocaleAsync(
        LearningDbContext db,
        string locale,
        IReadOnlyDictionary<string, string> dictionary,
        CancellationToken ct)
    {
        foreach (var (key, value) in dictionary)
        {
            var existing = await db.Translations.FindAsync([ locale, key ], ct);
            if (existing is null)
            {
                db.Translations.Add(new TranslationRow
                {
                    Locale = locale,
                    Key = key,
                    Value = value
                });
            }
            else if (existing.Value != value)
            {
                // Catalog in code is the source of truth — refresh stale rows.
                existing.Value = value;
            }
        }

        // Rows for keys no longer in the dictionary (renamed / removed) are dropped.
        var keys = dictionary.Keys.ToHashSet();
        var stale = await db.Translations.Where(t => t.Locale == locale).ToListAsync(ct);
        db.Translations.RemoveRange(stale.Where(t => !keys.Contains(t.Key)));

        await db.SaveChangesAsync(ct);
    }
}
